/**
 * Stage for fixture/work coordinate system changes (G54-G59, G54.1 P#)
 */

import { LogCategory, Logger } from '../../utils/Logger';
import { FixtureLibrary } from '../Common/FixtureLibrary';
import { JobStage, StageStatus, StageType } from '../JobStage';
import { MachineStateData } from '../MachineStateData';

export class FixtureChangeStage extends JobStage {
    public fixtureCode: string; // e.g., "G54", "G55", "G54.1 P001", "E7"
    public lineNumber: number;
    public gcodeLine: string;

    constructor(stageNumber: number, fixtureCode: string, lineNumber: number, gcodeLine: string) {
        super(stageNumber, StageType.FixtureChange, lineNumber - 1, lineNumber - 1);
        this.fixtureCode = fixtureCode;
        this.lineNumber = lineNumber;
        this.gcodeLine = gcodeLine;
    }

    protected async executeStage(callback?: import('../JobStage').StageCallback): Promise<void> {
        // Look up the fixture by its code
        const fixture = FixtureLibrary.getFixtureByNumber(this.fixtureCode);

        if (!fixture) {
            const errorMsg = `Fixture ${this.fixtureCode} not found in library`;
            Logger.Instance.logError(LogCategory.System, `Fixture not found: ${this.fixtureCode}`);

            this.status = StageStatus.Error;
            this.endTime = new Date();
            this.errorMessage = errorMsg;

            if (callback) {
                await callback.onError(errorMsg);
            }
            return;
        }

        // Update the current work zero home from the fixture
        MachineStateData.Instance.setWorkZeroFromFixture(fixture, true);
        MachineStateData.Instance.currentFixtureNumber = this.fixtureCode;

        // Mark as completed
        this.status = StageStatus.Completed;
        this.endTime = new Date();

        // Fixture changes continue automatically
        if (callback) {
            await callback.onComplete();
        }
    }

    public getStageName(): string {
        return 'Fixture Change';
    }

    public getDisplayName(): string {
        const fixture = FixtureLibrary.getFixtureByNumber(this.fixtureCode);
        const fixtureName = fixture ? fixture.name : this.fixtureCode;
        return `Fixture → ${this.fixtureCode}${fixtureName !== this.fixtureCode ? ` (${fixtureName})` : ''}`;
    }

    public getDescription(): string {
        const fixture = FixtureLibrary.getFixtureByNumber(this.fixtureCode);
        const fixtureName = fixture ? fixture.name : 'Unknown';
        return `Change to work coordinate system ${this.fixtureCode} - ${fixtureName} (Line ${this.lineNumber})`;
    }

    public getStageDisplayData(): string[] {
        const fixture = FixtureLibrary.getFixtureByNumber(this.fixtureCode);
        const data = [
            `Fixture: ${this.fixtureCode}`,
            `(Line ${this.lineNumber})`
        ];

        if (fixture) {
            data.splice(1, 0, `Name: ${fixture.name}`);
            if (!fixture.isComputed) {
                data.push(`Offsets: X${fixture.xOffset.toFixed(4)} Y${fixture.yOffset.toFixed(4)} Z${fixture.zOffset.toFixed(4)}`);
            }
        }

        return data;
    }
}
