import { Clear as ClearIcon, ExpandMore as ExpandMoreIcon } from '@mui/icons-material';
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Box,
    Checkbox,
    Divider,
    FormControlLabel,
    IconButton,
    MenuItem,
    Paper,
    Select,
    TextField,
    ToggleButton,
    ToggleButtonGroup,
    Tooltip,
    Typography
} from '@mui/material';
import React, { useState } from 'react';
import { NumberInput } from '../../../../components/Common/NumberInput';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { SpindleConfig } from '../../../../data/Machine/SpindleConfig';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';

interface SpindleConfigPanelProps {
    spindleConfig: SpindleConfig;
    spindleName: string;
    spindleNumber: number;
    encoderPort: number;
}

export function SpindleConfigPanel({ spindleConfig, spindleName, spindleNumber, encoderPort }: SpindleConfigPanelProps): React.ReactElement {
    const [expandedPanel, setExpandedPanel] = useState<string>('');

    const handleAccordionChange = (panel: string) => (_event: React.SyntheticEvent, isExpanded: boolean) => {
        setExpandedPanel(isExpanded ? panel : '');
    };

    const ClearButton = ({ onClear }: { onClear: () => void }) => (
        <Tooltip title="Clear value">
            <IconButton size="small" onClick={onClear} sx={{ ml: 1 }}>
                <ClearIcon fontSize="small" />
            </IconButton>
        </Tooltip>
    );

    return (
        <Paper sx={{ p: 3, maxWidth: 800 }}>
            <Typography variant="h5" gutterBottom sx={{ mb: 3 }}>
                Spindle {spindleNumber} Setup
            </Typography>

            <ObserveState
                key={`spindle-config-${spindleName}`}
                listenTo={spindleConfig}
                properties={[
                    'encoderCounts', 'spindleAxis', 'lowGearRatio', 'mediumGearRatio', 'highGearRatio',
                    'maxSpeed', 'minSpeed', 'analogRange', 'okDelay', 'fanDelay', 'encoderEnabled',
                    'rigidTappingEnabled', 'rtgDisplay', 'spindleScalingEnabled', 'decelTime',
                    'rigidTappingSlowSpeed', 'rigidTappingSlowTime', 'threadingTappingAccelDecelDistance',
                    'minimumRigidTappingRPM', 'durationForMinRigidTappingRPM', 'spindleDrift',
                    'spindleAccelDecelTime', 'rigidTappingZAxisSyncDistance', 'allowSpindleOverride',
                    'doNotWaitForIndexPulse', 'ssvCycleTime', 'ssvAmount', 'frvCycleTime',
                    'mFuncBottomHoleG84', 'mFuncTopHoleG74Counter', 'mFuncBottomHoleG74LeftHand', 'mFuncTopHoleG84Counter'
                ]}
                control={() => (
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                        {/* Spindle Encoder */}
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                            <Typography sx={{ width: 250 }}>Spindle Encoder (Encoder port #{encoderPort})</Typography>
                            <Box sx={{ width: 330 }}>
                                <ToggleButtonGroup
                                    value={spindleConfig.encoderEnabled ? 'yes' : 'no'}
                                    exclusive
                                    onChange={(_, value) => {
                                        if (value !== null) {
                                            spindleConfig.encoderEnabled = value === 'yes';
                                        }
                                    }}
                                    size="small"
                                >
                                    <ToggleButton value="yes" sx={{ px: 3, '&.Mui-selected': { backgroundColor: ConfigurationDataColors.Instance.successColor, color: ConfigurationDataColors.Instance.lightTextColor, '&:hover': { backgroundColor: ConfigurationDataColors.Instance.successColor } } }}>Yes</ToggleButton>
                                    <ToggleButton value="no" sx={{ px: 3, '&.Mui-selected': { backgroundColor: ConfigurationDataColors.Instance.errorColor, color: ConfigurationDataColors.Instance.lightTextColor, '&:hover': { backgroundColor: ConfigurationDataColors.Instance.errorColor } } }}>No</ToggleButton>
                                </ToggleButtonGroup>
                            </Box>
                        </Box>

                        {/* Only render remaining fields if encoder is enabled */}
                        {spindleConfig.encoderEnabled && (
                            <>
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Spindle Encoder counts</Typography>
                                    <Box sx={{ width: 330 }}>
                                        <TextField
                                            type="number"
                                            value={spindleConfig.encoderCounts ?? ''}
                                            onChange={(e) => (spindleConfig.encoderCounts = e.target.value ? parseInt(e.target.value) : null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                        />
                                    </Box>
                                </Box>

                                {/* Spindle max speed in high range */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Spindle max speed in high range</Typography>
                                    <Box sx={{ width: 330 }}>
                                        <NumberInput
                                            value={spindleConfig.maxSpeed ?? 0}
                                            onChange={(value) => (spindleConfig.maxSpeed = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={2}
                                        />
                                    </Box>
                                </Box>

                                {/* Spindle min speed in high range */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Spindle min speed in high range</Typography>
                                    <Box sx={{ width: 330 }}>
                                        <NumberInput
                                            value={spindleConfig.minSpeed ?? 0}
                                            onChange={(value) => (spindleConfig.minSpeed = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={2}
                                        />
                                    </Box>
                                </Box>

                                {/* Medium range Spindle Speed ratio */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Medium range Spindle Speed ratio</Typography>
                                    <Box sx={{ width: 330 }}>
                                        <NumberInput
                                            value={spindleConfig.mediumGearRatio ?? 0}
                                            onChange={(value) => (spindleConfig.mediumGearRatio = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={3}
                                        />
                                    </Box>
                                </Box>

                                {/* Low range Spindle Speed ratio */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Low range Spindle Speed ratio</Typography>
                                    <Box sx={{ width: 330 }}>
                                        <NumberInput
                                            value={spindleConfig.lowGearRatio ?? 0}
                                            onChange={(value) => (spindleConfig.lowGearRatio = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={3}
                                        />
                                    </Box>
                                </Box>

                                {/* Limit Spindle Analog Output to 0-5 volts */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Limit Spindle Analog Output to 0-5 volts</Typography>
                                    <Box sx={{ width: 330 }}>
                                        <ToggleButtonGroup
                                            value={spindleConfig.analogRange !== null && spindleConfig.analogRange <= 5 ? 'yes' : 'no'}
                                            exclusive
                                            onChange={(_, value) => {
                                                if (value !== null) {
                                                    spindleConfig.analogRange = value === 'yes' ? 5 : 10;
                                                }
                                            }}
                                            size="small"
                                        >
                                            <ToggleButton value="yes" sx={{ px: 3, '&.Mui-selected': { backgroundColor: ConfigurationDataColors.Instance.successColor, color: ConfigurationDataColors.Instance.lightTextColor, '&:hover': { backgroundColor: ConfigurationDataColors.Instance.successColor } } }}>Yes</ToggleButton>
                                            <ToggleButton value="no" sx={{ px: 3, '&.Mui-selected': { backgroundColor: ConfigurationDataColors.Instance.errorColor, color: ConfigurationDataColors.Instance.lightTextColor, '&:hover': { backgroundColor: ConfigurationDataColors.Instance.errorColor } } }}>No</ToggleButton>
                                        </ToggleButtonGroup>
                                    </Box>
                                </Box>

                                {/* RTG Sindle Speed RPM display */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>RTG Sindle Speed RPM display</Typography>
                                    <Box sx={{ width: 330 }}>
                                        <Select
                                            value={spindleConfig.rtgDisplay === null ? 'gcode' : (spindleConfig.rtgDisplay ? 'sensor' : 'gcode')}
                                            onChange={(e) => {
                                                const val = e.target.value;
                                                spindleConfig.rtgDisplay = val === 'sensor' ? true : false;
                                            }}
                                            size="small"
                                            fullWidth
                                        >
                                            <MenuItem value="gcode">G-code program or RPM sensor Spindle Speed</MenuItem>
                                            <MenuItem value="sensor">RPM sensor Spindle Speed only</MenuItem>
                                        </Select>
                                    </Box>
                                </Box>

                                {/* SpindleOk delay timer */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>SpindleOk delay timer</Typography>
                                    <Box sx={{ width: 330, display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <NumberInput
                                            value={spindleConfig.okDelay ?? 0}
                                            onChange={(value) => (spindleConfig.okDelay = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={0}
                                            afterText="milliseconds"
                                        />
                                    </Box>
                                </Box>

                                {/* Spindle cooling fan delay timer */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Spindle cooling fan delay timer</Typography>
                                    <Box sx={{ width: 330, display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <NumberInput
                                            value={spindleConfig.fanDelay ?? 0}
                                            onChange={(value) => (spindleConfig.fanDelay = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={1}
                                            afterText="seconds"
                                        />
                                    </Box>
                                </Box>

                                {/* Spindle Scaling Enabled */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Spindle Scaling Enabled</Typography>
                                    <Box sx={{ width: 330 }}>
                                        <ToggleButtonGroup
                                            value={spindleConfig.spindleScalingEnabled ? 'yes' : 'no'}
                                            exclusive
                                            onChange={(_, value) => {
                                                if (value !== null) {
                                                    spindleConfig.spindleScalingEnabled = value === 'yes';
                                                }
                                            }}
                                            size="small"
                                        >
                                            <ToggleButton value="yes" sx={{ px: 3, '&.Mui-selected': { backgroundColor: ConfigurationDataColors.Instance.successColor, color: ConfigurationDataColors.Instance.lightTextColor, '&:hover': { backgroundColor: ConfigurationDataColors.Instance.successColor } } }}>Yes</ToggleButton>
                                            <ToggleButton value="no" sx={{ px: 3, '&.Mui-selected': { backgroundColor: ConfigurationDataColors.Instance.errorColor, color: ConfigurationDataColors.Instance.lightTextColor, '&:hover': { backgroundColor: ConfigurationDataColors.Instance.errorColor } } }}>No</ToggleButton>
                                        </ToggleButtonGroup>
                                    </Box>
                                </Box>

                                <Divider sx={{ my: 2 }} />
                                <Typography variant="subtitle1" gutterBottom>
                                    Spindle Speed Variation (SSV) Configuration (M94/70 ON, M95/70 OFF)
                                </Typography>

                                {/* Spindle Speed Variation Cycle Time */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Spindle Speed Variation Cycle Time</Typography>
                                    <Box sx={{ width: 330, display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <NumberInput
                                            value={spindleConfig.ssvCycleTime ?? 0}
                                            onChange={(value) => (spindleConfig.ssvCycleTime = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={2}
                                            afterText="seconds"
                                        />
                                    </Box>
                                </Box>

                                {/* Amount of Speed Variation */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Amount of Speed Variation</Typography>
                                    <Box sx={{ width: 330, display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <NumberInput
                                            value={spindleConfig.ssvAmount ?? 0}
                                            onChange={(value) => (spindleConfig.ssvAmount = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={1}
                                            afterText="rpm (+/-)"
                                        />
                                    </Box>
                                </Box>

                                <Divider sx={{ my: 2 }} />
                                <Typography variant="subtitle1" gutterBottom>
                                    Feed Rate Variation (FRV) Configuration (M94/71 ON, M95/71 OFF)
                                </Typography>

                                {/* Feed Rate Variation Cycle Time */}
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Typography sx={{ width: 250 }}>Feed Rate Variation Cycle Time</Typography>
                                    <Box sx={{ width: 330, display: 'flex', alignItems: 'center', gap: 1 }}>
                                        <NumberInput
                                            value={spindleConfig.frvCycleTime ?? 0}
                                            onChange={(value) => (spindleConfig.frvCycleTime = value || null)}
                                            size="small"
                                            sx={{ width: 150 }}
                                            allowNegative={false}
                                            precision={2}
                                        />
                                    </Box>
                                </Box>
                            </>
                        )}

                        {/* Advanced Configuration Accordion - Hidden for now */}
                        {/* Advanced Configuration Accordion - Hidden for now */}
                        {false && <Accordion expanded={expandedPanel === 'advanced'} onChange={handleAccordionChange('advanced')} sx={{ mt: 3 }}>
                            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                                <Typography>Advanced Configuration</Typography>
                            </AccordionSummary>
                            <AccordionDetails>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Spindle Axis"
                                            type="number"
                                            value={spindleConfig.spindleAxis ?? ''}
                                            onChange={(e) => (spindleConfig.spindleAxis = e.target.value ? parseInt(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.spindleAxis = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="High Gear Ratio"
                                            type="number"
                                            value={spindleConfig.highGearRatio ?? ''}
                                            onChange={(e) => (spindleConfig.highGearRatio = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.highGearRatio = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Decel Time (s)"
                                            type="number"
                                            value={spindleConfig.decelTime ?? ''}
                                            onChange={(e) => (spindleConfig.decelTime = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.decelTime = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Spindle Accel/Decel Time (s)"
                                            type="number"
                                            value={spindleConfig.spindleAccelDecelTime ?? ''}
                                            onChange={(e) => (spindleConfig.spindleAccelDecelTime = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.spindleAccelDecelTime = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Spindle Drift"
                                            type="number"
                                            value={spindleConfig.spindleDrift ?? ''}
                                            onChange={(e) => (spindleConfig.spindleDrift = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.spindleDrift = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <FormControlLabel
                                            control={
                                                <Checkbox
                                                    checked={spindleConfig.allowSpindleOverride ?? false}
                                                    onChange={(e) => (spindleConfig.allowSpindleOverride = e.target.checked ? true : null)}
                                                />
                                            }
                                            label="Allow Spindle Override"
                                            sx={{ flex: 1 }}
                                        />
                                        <ClearButton onClear={() => (spindleConfig.allowSpindleOverride = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <FormControlLabel
                                            control={
                                                <Checkbox
                                                    checked={spindleConfig.doNotWaitForIndexPulse ?? false}
                                                    onChange={(e) => (spindleConfig.doNotWaitForIndexPulse = e.target.checked ? true : null)}
                                                />
                                            }
                                            label="Do Not Wait For Index Pulse"
                                            sx={{ flex: 1 }}
                                        />
                                        <ClearButton onClear={() => (spindleConfig.doNotWaitForIndexPulse = null)} />
                                    </Box>
                                </Box>
                            </AccordionDetails>
                        </Accordion>}

                        {/* Rigid Tapping - Hidden for now */}
                        {false && <Accordion expanded={expandedPanel === 'tapping'} onChange={handleAccordionChange('tapping')}>
                            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                                <Typography>Rigid Tapping</Typography>
                            </AccordionSummary>
                            <AccordionDetails>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <FormControlLabel
                                            control={
                                                <Checkbox
                                                    checked={spindleConfig.rigidTappingEnabled ?? false}
                                                    onChange={(e) => (spindleConfig.rigidTappingEnabled = e.target.checked ? true : null)}
                                                />
                                            }
                                            label="Rigid Tapping Enabled"
                                            sx={{ flex: 1 }}
                                        />
                                        <ClearButton onClear={() => (spindleConfig.rigidTappingEnabled = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Rigid Tapping Slow Speed (RPM)"
                                            type="number"
                                            value={spindleConfig.rigidTappingSlowSpeed ?? ''}
                                            onChange={(e) => (spindleConfig.rigidTappingSlowSpeed = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.rigidTappingSlowSpeed = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Rigid Tapping Slow Time (s)"
                                            type="number"
                                            value={spindleConfig.rigidTappingSlowTime ?? ''}
                                            onChange={(e) => (spindleConfig.rigidTappingSlowTime = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.rigidTappingSlowTime = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Threading/Tapping Accel/Decel Distance"
                                            type="number"
                                            value={spindleConfig.threadingTappingAccelDecelDistance ?? ''}
                                            onChange={(e) => (spindleConfig.threadingTappingAccelDecelDistance = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.threadingTappingAccelDecelDistance = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Minimum Rigid Tapping RPM"
                                            type="number"
                                            value={spindleConfig.minimumRigidTappingRPM ?? ''}
                                            onChange={(e) => (spindleConfig.minimumRigidTappingRPM = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.minimumRigidTappingRPM = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Duration for Min Rigid Tapping RPM (s)"
                                            type="number"
                                            value={spindleConfig.durationForMinRigidTappingRPM ?? ''}
                                            onChange={(e) => (spindleConfig.durationForMinRigidTappingRPM = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.durationForMinRigidTappingRPM = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="Rigid Tapping Z Axis Sync Distance"
                                            type="number"
                                            value={spindleConfig.rigidTappingZAxisSyncDistance ?? ''}
                                            onChange={(e) => (spindleConfig.rigidTappingZAxisSyncDistance = e.target.value ? parseFloat(e.target.value) : null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.rigidTappingZAxisSyncDistance = null)} />
                                    </Box>
                                </Box>
                            </AccordionDetails>
                        </Accordion>}

                        {/* M Functions - Hidden for now */}
                        {false && <Accordion expanded={expandedPanel === 'mfunctions'} onChange={handleAccordionChange('mfunctions')}>
                            <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                                <Typography>M Functions</Typography>
                            </AccordionSummary>
                            <AccordionDetails>
                                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="M Func Bottom Hole G84"
                                            value={spindleConfig.mFuncBottomHoleG84 ?? ''}
                                            onChange={(e) => (spindleConfig.mFuncBottomHoleG84 = e.target.value || null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.mFuncBottomHoleG84 = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="M Func Top Hole G74 Counter"
                                            value={spindleConfig.mFuncTopHoleG74Counter ?? ''}
                                            onChange={(e) => (spindleConfig.mFuncTopHoleG74Counter = e.target.value || null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.mFuncTopHoleG74Counter = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="M Func Bottom Hole G74 Left Hand"
                                            value={spindleConfig.mFuncBottomHoleG74LeftHand ?? ''}
                                            onChange={(e) => (spindleConfig.mFuncBottomHoleG74LeftHand = e.target.value || null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.mFuncBottomHoleG74LeftHand = null)} />
                                    </Box>
                                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                                        <TextField
                                            label="M Func Top Hole G84 Counter"
                                            value={spindleConfig.mFuncTopHoleG84Counter ?? ''}
                                            onChange={(e) => (spindleConfig.mFuncTopHoleG84Counter = e.target.value || null)}
                                            fullWidth
                                            size="small"
                                        />
                                        <ClearButton onClear={() => (spindleConfig.mFuncTopHoleG84Counter = null)} />
                                    </Box>
                                </Box>
                            </AccordionDetails>
                        </Accordion>}
                    </Box>
                )}
            />
        </Paper>
    );
}
