import React from 'react';
import { OutputForceControlDialog } from '../components/Common/OutputForceControlDialog';
import { IOStateData } from '../data/IOStateData';
import { MachineData } from '../data/Machine/MachineData';
import { DefinedIO, ICNCIO } from '../machine/ICNCIO';
import { Machine } from '../machine/Machine';
import { CNCIOApi } from '../services/src/apis/CNCIOApi';
import { SystemInfo } from '../services/src/models/SystemInfo';
import { getAvailableIONumbers } from '../utils/IONumberCalculator';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';
import { ModalManager } from '../utils/ModalManager';
import { PLCInput } from './plc/data/io/PLCInput';
import { PLCOutput } from './plc/data/io/PLCOutput';
import { PLCProgram } from './plc/data/PLCProgram';
import { PLCProgramType } from './plc/data/PLCUtilities';

export class CentroidCNCIO implements ICNCIO {
  private readonly api: CNCIOApi;
  private readonly basePath: string;
  private definedInputsCache: DefinedIO[] | null = null;
  private definedOutputsCache: DefinedIO[] | null = null;

  constructor() {
    const config = MachineInterfaceManager.Instance.getServiceConfiguration();

    this.basePath = config?.basePath || '';
    this.api = new CNCIOApi(config || undefined);
  }

  async GetBulkIOStates(): Promise<{ inputs: Record<number, boolean>, outputs: Record<number, boolean>, readAt: Date }> {
    try {
      const response = await this.api.apiCNCIOGetBulkIOStatesGetRaw();
      const bulkStates = await response.value();

      const inputs: Record<number, boolean> = {};
      const outputs: Record<number, boolean> = {};

      bulkStates.inputs?.forEach(input => {
        if (input.number !== undefined && input.isOn !== undefined) {
          inputs[input.number] = input.isOn;
        }
      });

      bulkStates.outputs?.forEach(output => {
        if (output.number !== undefined && output.isOn !== undefined) {
          outputs[output.number] = output.isOn;
        }
      });

      const readAt = bulkStates.readAt || new Date();

      return { inputs, outputs, readAt };
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get bulk I/O states:', error);
      throw error;
    }
  }

  async GetCurrentInputs(): Promise<Record<number, boolean>> {
    try {
      // Get defined inputs which includes the current state
      const definedInputs = await this.GetDefinedInputs();

      const result: Record<number, boolean> = {};
      definedInputs.forEach(input => {
        if (input.number !== undefined && input.state !== undefined) {
          result[input.number] = input.state;
        }
      });

      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get current inputs:', error);
      throw error;
    }
  }

  async GetCurrentOutputs(): Promise<Record<number, boolean>> {
    try {
      // Get defined outputs which includes the current state
      const definedOutputs = await this.GetDefinedOutputs();

      const result: Record<number, boolean> = {};
      definedOutputs.forEach(output => {
        if (output.number !== undefined && output.state !== undefined) {
          result[output.number] = output.state;
        }
      });

      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get current outputs:', error);
      throw error;
    }
  }

  async GetDefinedInputs(): Promise<DefinedIO[]> {
    // Return cached result if available
    if (this.definedInputsCache !== null) {
      return this.definedInputsCache;
    }

    try {
      // Get inputs from System PLC program
      const systemProgram = PLCProgram.Instance(PLCProgramType.System);
      const plcInputs = systemProgram.inputs;

      // Filter inputs that have assigned numbers
      const inputsWithNumbers = plcInputs.filter((input: PLCInput) => input.number !== null);
      const inputNumbers = inputsWithNumbers.map((input: PLCInput) => input.number!);


      // Query backend for current state of these inputs
      const stateResponse = await this.api.apiCNCIOGetInputStatePost({ requestBody: inputNumbers });
      const inputStates = stateResponse || {};

      // Combine PLC definitions with backend state
      const result: DefinedIO[] = inputsWithNumbers.map(input => ({
        number: input.number!,
        name: input.centroidName,
        state: inputStates[input.number!.toString()] ?? false
      }));


      // Cache the result
      this.definedInputsCache = result;
      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get defined inputs:', error);
      throw error;
    }
  }

  async GetDefinedOutputs(): Promise<DefinedIO[]> {
    // Return cached result if available
    if (this.definedOutputsCache !== null) {
      return this.definedOutputsCache;
    }

    try {
      // Get outputs from System PLC program
      const systemProgram = PLCProgram.Instance(PLCProgramType.System);
      const plcOutputs = systemProgram.outputs;

      // Filter outputs that have assigned numbers
      const outputsWithNumbers = plcOutputs.filter((output: PLCOutput) => output.number !== null);
      const outputNumbers = outputsWithNumbers.map((output: PLCOutput) => output.number!);


      // Query backend for current state of these outputs
      const stateResponse = await this.api.apiCNCIOGetOutputStatePost({ requestBody: outputNumbers });
      const outputStates = stateResponse || {};

      // Combine PLC definitions with backend state
      const result: DefinedIO[] = outputsWithNumbers.map((output: PLCOutput) => ({
        number: output.number!,
        name: output.centroidName,
        state: outputStates[output.number!.toString()] ?? false
      }));


      // Cache the result
      this.definedOutputsCache = result;
      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get defined outputs:', error);
      throw error;
    }
  }

  async GetBoardConfiguration(): Promise<Record<string, any>> {
    try {
      const response = await this.api.apiCNCIOGetBoardConfigurationGetRaw();
      const config = await response.value();

      return config || {};
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get board configuration:', error);
      throw error;
    }
  }

  async GetSystemInfo(): Promise<SystemInfo> {
    try {
      const response = await this.api.apiCNCIOGetSystemInfoGetRaw();
      const systemInfo = await response.value();
      return systemInfo;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get system info:', error);
      throw error;
    }
  }

  async GetIOAvailability(): Promise<Record<string, boolean>> {
    const availableNumbers = getAvailableIONumbers(
      MachineData.Instance.boardType,
      MachineData.Instance.expansionBoardCount
    );

    const result: Record<string, boolean> = {};
    availableNumbers.forEach(num => {
      result[`input_${num}`] = true;
      result[`output_${num}`] = true;
    });

    return result;
  }

  async IsInputActive(inputNumber: number): Promise<boolean> {
    try {
      const response = await this.api.apiCNCIOIsInputActiveInputNumberGetRaw({ inputNumber });
      const isActive = await response.value();
      return isActive ?? false;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to check input status:', error);
      throw error;
    }
  }

  async IsOutputActive(outputNumber: number): Promise<boolean> {
    try {
      const response = await this.api.apiCNCIOIsOutputActiveOutputNumberGetRaw({ outputNumber });
      const isActive = await response.value();
      return isActive ?? false;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to check output status:', error);
      throw error;
    }
  }

  async SetOutputState(outputNumber: number, state: boolean): Promise<void> {
    try {
      // Find the output to get G-code commands
      const output = IOStateData.Instance.getOutputByNumber(outputNumber);
      if (!output) {
        Logger.Instance.logError(LogCategory.System, `Output ${outputNumber} not found in IOStateData`);
        throw new Error(`Output ${outputNumber} not found`);
      }

      // Check if a job is running - Machine already imported at top of file
      const machine = Machine.getInstance();
      const isJobRunning = await machine.program.IsJobRunning();

      if (isJobRunning) {
        // Job is running - show force control dialog
        this.showForceControlDialog(output);
        return;
      }

      // No job running - use output's configured G-code commands
      const gcode = state ? output.getOnGCode() : output.getOffGCode();

      await machine.program.RunGCode([gcode], true);

    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to set output state:', error);
      throw error;
    }
  }

  private showForceControlDialog(output: any): void {
    const modalId = 'output-force-control-dialog';

    ModalManager.Instance.showModal({
      id: modalId,
      render: () => {
        return React.createElement(OutputForceControlDialog, {
          open: true,
          output: output,
          onClose: () => ModalManager.Instance.closeModal(modalId)
        });
      }
    });
  }

  async ResetOutput(outputNumber: number): Promise<void> {
    try {
      await this.api.apiCNCIOResetOutputOutputNumberPost({ outputNumber });
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to reset output:', error);
      throw error;
    }
  }

  async GetForcedOutputs(): Promise<Record<number, string>> {
    try {
      // Get outputs from System PLC program
      const systemProgram = PLCProgram.Instance(PLCProgramType.System);
      const plcOutputs = systemProgram.outputs;

      // Filter outputs that have assigned numbers
      const outputsWithNumbers = plcOutputs.filter((output: PLCOutput) => output.number !== null);
      const outputNumbers = outputsWithNumbers.map((output: PLCOutput) => output.number!);

      // Query backend for forced outputs
      const response = await this.api.apiCNCIOGetForcedOutputsPost({ requestBody: outputNumbers });

      // Convert string keys to number keys
      const result: Record<number, string> = {};
      if (response && typeof response === 'object') {
        Object.entries(response).forEach(([key, value]) => {
          const numKey = parseInt(key, 10);
          if (!isNaN(numKey)) {
            result[numKey] = value;
          }
        });
      }

      return result;
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Failed to get forced outputs:', error);
      throw error;
    }
  }
}
