import { BuildCircle as ReplaceToolIcon } from '@mui/icons-material';
import { Box, Typography } from '@mui/material';
import React from 'react';
import { ChangeToolWizard } from '../../components/wizards/changetool/ChangeToolWizard';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { IUserAction } from './IUserAction';

export class ReplaceToolUserAction implements IUserAction {
    public readonly id = 'replace_tool_wizard';
    public readonly category = 'Machine Actions';

    public isAvailable(): boolean {
        const config = ConfigurationState.Instance;
        return config.isHomed && !config.isJobRunning;
    }

    public renderButton(asLink: boolean): React.ReactNode {
        if (asLink) {
            return (
                <React.Fragment>
                    <ReplaceToolIcon sx={{ fontSize: 18, color: 'primary.main' }} />
                    <Typography variant="body2" sx={{ color: 'inherit', fontWeight: 500 }}>
                        Replace Tool Bit
                    </Typography>
                </React.Fragment>
            );
        } else {
            return (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <ReplaceToolIcon />
                    <Typography>Replace Tool Bit</Typography>
                </Box>
            );
        }
    }

    public run(): void {
        const machineState = MachineStateData.Instance;
        const toolLibrary = ToolLibrary.Instance;
        const currentTool = toolLibrary.tools.find(t => t.toolNumber === machineState.currentToolNumber);

        ChangeToolWizard.show(currentTool || null);
    }
}
