import {
    Add as AddIcon,
    ContentCopy as ContentCopyIcon,
    Delete as DeleteIcon,
    Download as DownloadIcon,
    MoreVert as MoreVertIcon,
    DriveFileMove as MoveIcon,
    Refresh as RefreshIcon,
    RestartAlt as RestartAltIcon,
    Save as SaveIcon,
    Search as SearchIcon,
    Settings as SettingsIcon,
    Upload as UploadIcon,
    Warning as WarningIcon
} from '@mui/icons-material';
import {
    Alert,
    AlertTitle,
    Box,
    Button,
    Card,
    Collapse,
    IconButton,
    List,
    ListItem,
    ListItemText,
    Menu,
    MenuItem,
    Paper,
    Stack,
    Typography
} from '@mui/material';
import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { PLCValidationIndicator } from '../../../components/PLC/PLCValidationIndicator';
import { VariableSearchDialog } from '../../../components/PLC/VariableSearchDialog';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { DataFileConstants } from '../../../data/DataFileConstants';
import { DataManager } from '../../../data/DataManager';
import { MachineStateData } from '../../../data/MachineStateData';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { Machine } from '../../../machine/Machine';
import { ConfirmDialogManager } from '../../../utils/ConfirmDialogManager';
import { LogCategory, Logger } from '../../../utils/Logger';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { EditableComment } from '../components/EditableComment';
import { PLCRenderMode } from '../data/IPLCElement';
import { PLCBlock } from '../data/PLCBlock';
import { PLCProgram } from '../data/PLCProgram';
import { PLCStage, StageType } from '../data/PLCStage';
import { PLCProgramType } from '../data/PLCUtilities';
import { StatementType, StatementUtilities } from '../statements';
import { BasePLCStatement } from '../statements/BasePLCStatement';
import { BlockDialog } from './BlockDialog';
import { PLCMoveDialog } from './PLCMoveDialog';
import { StageDialog } from './StageDialog';
import { StatementDialog } from './StatementDialog';

/**
 * Props for PLCEditor component
 */
interface PLCEditorProps {
    /**
     * The type of PLC program being edited (SystemDefault or System)
     */
    programType: PLCProgramType;
}

/**
 * Reusable PLC Editor component with collapsible nested structure
 * Displays stages containing blocks where statements can be added
 */
export function PLCEditor({ programType }: PLCEditorProps) {
    const program = PLCProgram.Instance(programType);
    const colors = ConfigurationDataColors.Instance;
    const [statementMenuAnchor, setStatementMenuAnchor] = useState<null | HTMLElement>(null);
    const [statementMenuBlock, setStatementMenuBlock] = useState<PLCBlock | null>(null);
    const [advancedMenuAnchor, setAdvancedMenuAnchor] = useState<null | HTMLElement>(null);
    const [stageDialogOpen, setStageDialogOpen] = useState(false);
    const [editingStage, setEditingStage] = useState<PLCStage | undefined>(undefined);
    const [blockDialogOpen, setBlockDialogOpen] = useState(false);
    const [editingBlock, setEditingBlock] = useState<PLCBlock | undefined>(undefined);
    const [statementDialogOpen, setStatementDialogOpen] = useState(false);
    const [editingStatement, setEditingStatement] = useState<BasePLCStatement | undefined>(undefined);
    const [moveDialogOpen, setMoveDialogOpen] = useState(false);
    const [movingItem, setMovingItem] = useState<PLCBlock | BasePLCStatement | undefined>(undefined);
    const [searchDialogOpen, setSearchDialogOpen] = useState(false);

    // Refs for measuring stage group heights
    const initialGroupRef = useRef<HTMLDivElement>(null);
    const mainGroupRef = useRef<HTMLDivElement>(null);
    const finalGroupRef = useRef<HTMLDivElement>(null);

    const [groupHeights, setGroupHeights] = useState({
        initial: 0,
        main: 0,
        final: 0
    });

    // Measure heights after render using ResizeObserver
    useLayoutEffect(() => {
        const measureHeights = () => {
            const newHeights = {
                initial: initialGroupRef.current?.offsetHeight || 0,
                main: mainGroupRef.current?.offsetHeight || 0,
                final: finalGroupRef.current?.offsetHeight || 0
            };

            // Only update if heights actually changed
            setGroupHeights(prev => {
                if (prev.initial === newHeights.initial &&
                    prev.main === newHeights.main &&
                    prev.final === newHeights.final) {
                    return prev;
                }
                return newHeights;
            });
        };

        // Initial measurement
        measureHeights();

        // Create ResizeObserver to watch for size changes
        const resizeObserver = new ResizeObserver(() => {
            measureHeights();
        });

        // Observe all three group containers
        if (initialGroupRef.current) resizeObserver.observe(initialGroupRef.current);
        if (mainGroupRef.current) resizeObserver.observe(mainGroupRef.current);
        if (finalGroupRef.current) resizeObserver.observe(finalGroupRef.current);

        // Re-measure on window resize
        window.addEventListener('resize', measureHeights);

        return () => {
            resizeObserver.disconnect();
            window.removeEventListener('resize', measureHeights);
        };
    }, [program.stages]); // Re-run when stages array changes

    // Load default program if no stages exist, then collapse all on initial load
    useEffect(() => {
        const initializeProgram = async () => {
            // Collapse all stages and blocks on initial load
            program.stages.forEach(stage => {
                stage.collapsed = true;
                stage.getBlocksForRendering().forEach(block => {
                    block.collapsed = true;
                });
            });
        };

        initializeProgram();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []); // Empty dependency - run once on mount

    // Save program to JSON file
    const handleSaveProgramJSON = async () => {
        try {
            const programData = program.toJSON();

            const json = JSON.stringify(programData, null, 2);

            const blob = new Blob([json], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `${programType === PLCProgramType.SystemDefault ? 'system-default' : 'system'}-plc-program.json`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);

            // Also save MachineStateData and ConfigurationData
            await MachineStateData.Instance.manualSave();
            await ConfigurationData.Instance.manualSave();

        } catch (error) {
            console.error('Failed to save program to JSON:', error);
            const errorMsg = error instanceof Error ? error.message : String(error);
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to save program to JSON:', error);
            UserMessageQueue.Instance.addMessage(`❌ Failed to save JSON: ${errorMsg}`);
        }
    };

    // Load program from JSON file
    const handleLoadProgramJSON = () => {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.json';
        input.onchange = async (e: Event) => {
            try {
                const file = (e.target as HTMLInputElement).files?.[0];
                if (!file) return;

                const text = await file.text();
                const json = JSON.parse(text);

                // Replace the current program
                program.fromJSON(json);

                // Trigger state update to reload UI
                StateManager.propertyChanged(program, 'stages');

            } catch (error) {
                Logger.Instance.logError(LogCategory.DataManager, 'Failed to load program from JSON:', error);
                UserMessageQueue.Instance.addMessage('❌ Failed to load program from JSON');
            }
        };
        input.click();
    };

    // Copy program to clipboard as JSON
    const handleCopyProgramJSON = async () => {
        try {
            const programData = program.toJSON();
            const json = JSON.stringify(programData, null, 2);
            await navigator.clipboard.writeText(json);
        } catch (error) {
            console.error('handleCopyProgramJSON: Error:', error);
            const errorMsg = error instanceof Error ? error.message : String(error);
            Logger.Instance.logError(LogCategory.System, 'Failed to copy program JSON to clipboard:', error);
            UserMessageQueue.Instance.addMessage(`❌ Failed to copy JSON: ${errorMsg}`);
        }
    };

    // Navigate to a specific stage and block
    const handleNavigateToBlock = (stageName: string, blockName: string) => {
        // Find the stage
        const stage = program.stages.find(s => s.name === stageName);
        if (!stage) {
            Logger.Instance.logError(LogCategory.UserInterface, `Stage not found: ${stageName}`);
            return;
        }

        // Find the block (search in blocks and subBlocks recursively)
        const findBlockRecursive = (blocks: PLCBlock[]): PLCBlock | undefined => {
            for (const block of blocks) {
                if (block.name === blockName) {
                    return block;
                }
                // Search in subBlocks
                if (block.subBlocks && block.subBlocks.length > 0) {
                    const found = findBlockRecursive(block.subBlocks);
                    if (found) return found;
                }
            }
            return undefined;
        };

        const block = findBlockRecursive(stage.blocks);
        if (!block) {
            Logger.Instance.logError(LogCategory.UserInterface, `Block not found: ${blockName} in stage ${stageName}`);
            return;
        }

        // Collapse all stages and blocks first
        program.stages.forEach(s => {
            s.collapsed = true;
            // Recursively collapse all blocks
            const collapseBlocks = (blocks: PLCBlock[]) => {
                blocks.forEach(b => {
                    b.collapsed = true;
                    if (b.subBlocks && b.subBlocks.length > 0) {
                        collapseBlocks(b.subBlocks);
                    }
                });
            };
            collapseBlocks(s.blocks);
        });

        // Expand the target stage and block
        stage.collapsed = false;
        block.collapsed = false;

        // Expand parent blocks if this is a subBlock
        const expandParents = (blocks: PLCBlock[], targetBlock: PLCBlock): boolean => {
            for (const b of blocks) {
                if (b.subBlocks && b.subBlocks.length > 0) {
                    if (b.subBlocks.includes(targetBlock)) {
                        b.collapsed = false;
                        return true;
                    }
                    if (expandParents(b.subBlocks, targetBlock)) {
                        b.collapsed = false;
                        return true;
                    }
                }
            }
            return false;
        };

        expandParents(stage.blocks, block);

        // Trigger state update to reload UI
        StateManager.propertyChanged(program, 'stages');

        // Flash highlight effect on the block without scrolling
        setTimeout(() => {
            const blockId = `plc-block-${stageName}-${blockName}`;
            const element = document.getElementById(blockId);
            if (element) {
                // Flash highlight effect without scrolling
                element.style.transition = 'box-shadow 0.3s';
                element.style.boxShadow = `0 0 15px 5px ${ConfigurationDataColors.Instance.primaryColor}`;
                setTimeout(() => {
                    element.style.boxShadow = '';
                }, 1000);
            }
        }, 100);

        UserMessageQueue.Instance.addMessage(`✓ Navigated to ${stageName} › ${blockName}`);
    };

    // Load default program — delegates to DataManager based on program type:
    // SystemDefault → fetch from backend API (falls back to embedded file when offline)
    // System        → reset to a blank program (never fetches from API)
    const loadDefaultProgram = async () => {
        if (programType === PLCProgramType.SystemDefault) {
            await DataManager.Instance.resetPLCSystemDefaultOnly();
        } else {
            await DataManager.Instance.resetPLCSystemOnly();
        }
    };

    // Reset program to defaults
    const handleResetProgram = async () => {
        const programName = programType === PLCProgramType.SystemDefault ? 'System Default' : 'System';
        const confirmed = await ConfirmDialogManager.Instance.showConfirm({
            title: 'Reset Program',
            message: `Are you sure you want to reset the ${programName} PLC program to factory defaults? This will remove all your custom stages, blocks, and statements. This action cannot be undone.`,
            confirmText: 'Reset to Defaults',
            severity: 'warning'
        });

        if (confirmed) {
            try {
                await loadDefaultProgram();
            } catch (error) {
                Logger.Instance.logError(LogCategory.System, 'Failed to reset PLC program:', error);
                UserMessageQueue.Instance.addMessage('❌ Failed to reset PLC program');
            }
        }
    };

    // Save as default PLC (only for SystemDefault program)
    const handleSaveAsDefault = async () => {
        if (programType !== PLCProgramType.SystemDefault) {
            UserMessageQueue.Instance.addMessage('⚠ Only System Default PLC can be saved as default');
            return;
        }

        try {
            // Get current program JSON
            const jsonData = JSON.stringify(program.toJSON(), null, 2);

            // Store via Machine API with hardcoded values
            const machine = Machine.getInstance();
            await machine.setup.StoreAsDefaultPLC(
                'systemdefault', // Hardcoded version name
                jsonData,
                'System Default PLC Configuration', // Hardcoded description
                true, // Mark as latest
                'System' // System user
            );

            UserMessageQueue.Instance.addMessage(`✓ Saved as default PLC`);
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to save as default PLC:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to save as default PLC');
        }
    };

    // TODO: This function is not currently used but may be needed for future save functionality
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const handleSaveProgram = async () => {
        try {
            if (programType === PLCProgramType.SystemDefault) {
                await DataManager.Instance.savePLCSystemDefaultIndividual();
            } else {
                await DataManager.Instance.savePLCSystemIndividual();
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to save PLC program:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to save PLC program');
        }
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            <ObserveState
                key={`plc-editor-${programType}`}
                listenTo={program}
                properties={['stages', 'name', 'description']}
                control={() => (
                    <Box sx={{ display: 'flex', flexDirection: 'column', flex: 1, minHeight: 0 }}>
                        {/* Program Header - Fixed at top */}
                        <Paper sx={{ p: 2, flexShrink: 0 }}>
                            <Stack direction="row" spacing={2} alignItems="center" justifyContent="space-between">
                                <Box sx={{ flex: 1 }}>
                                    <Typography variant="h6" gutterBottom>
                                        {program.name}
                                    </Typography>
                                    {program.description && (
                                        <Typography variant="body2" color="textSecondary">
                                            {program.description}
                                        </Typography>
                                    )}
                                </Box>
                                <Stack direction="row" spacing={1}>
                                    <Button
                                        variant="outlined"
                                        startIcon={<SearchIcon />}
                                        onClick={() => setSearchDialogOpen(true)}
                                        sx={{ borderColor: colors.primaryColor, color: colors.primaryColor }}
                                    >
                                        Search Variables
                                    </Button>
                                    <Button
                                        variant="outlined"
                                        startIcon={<MoreVertIcon />}
                                        onClick={(e) => setAdvancedMenuAnchor(e.currentTarget)}
                                        sx={{ borderColor: colors.primaryColor, color: colors.primaryColor }}
                                    >
                                        Advanced
                                    </Button>
                                    <Menu
                                        anchorEl={advancedMenuAnchor}
                                        open={Boolean(advancedMenuAnchor)}
                                        onClose={() => setAdvancedMenuAnchor(null)}
                                    >
                                        <MenuItem
                                            onClick={() => {
                                                setAdvancedMenuAnchor(null);
                                                handleResetProgram();
                                            }}
                                        >
                                            <RestartAltIcon sx={{ mr: 1 }} fontSize="small" />
                                            Reset Program
                                        </MenuItem>
                                        {programType === PLCProgramType.SystemDefault && (
                                            <MenuItem
                                                onClick={() => {
                                                    setAdvancedMenuAnchor(null);
                                                    handleSaveAsDefault();
                                                }}
                                            >
                                                <SaveIcon sx={{ mr: 1 }} fontSize="small" />
                                                Save as Default
                                            </MenuItem>
                                        )}
                                        <MenuItem
                                            onClick={async (e) => {
                                                e.preventDefault();
                                                e.stopPropagation();
                                                await handleCopyProgramJSON();
                                                setAdvancedMenuAnchor(null);
                                            }}
                                        >
                                            <ContentCopyIcon sx={{ mr: 1 }} fontSize="small" />
                                            Copy JSON
                                        </MenuItem>
                                        <MenuItem
                                            onClick={async (e) => {
                                                e.preventDefault();
                                                e.stopPropagation();
                                                await handleSaveProgramJSON();
                                                setAdvancedMenuAnchor(null);
                                            }}
                                        >
                                            <DownloadIcon sx={{ mr: 1 }} fontSize="small" />
                                            Save JSON
                                        </MenuItem>
                                        <MenuItem
                                            onClick={() => {
                                                setAdvancedMenuAnchor(null);
                                                handleLoadProgramJSON();
                                            }}
                                        >
                                            <UploadIcon sx={{ mr: 1 }} fontSize="small" />
                                            Load JSON
                                        </MenuItem>
                                    </Menu>
                                    <Button
                                        variant="contained"
                                        startIcon={<AddIcon />}
                                        onClick={() => {
                                            setEditingStage(undefined);
                                            setStageDialogOpen(true);
                                        }}
                                        sx={{ backgroundColor: colors.primaryColor }}
                                    >
                                        Add Stage
                                    </Button>
                                </Stack>
                            </Stack>
                        </Paper>

                        {/* Stages List with Side Legend - Scrollable */}
                        <Box sx={{ flex: 1, overflow: 'auto', display: 'flex', gap: 2, minHeight: 0 }}>
                            {(() => {
                                const stages = program.getStagesForRendering();

                                // Get the filename for this program type
                                const filename = programType === PLCProgramType.SystemDefault
                                    ? DataFileConstants.PLC_SYSTEM_DEFAULT
                                    : DataFileConstants.PLC_SYSTEM;

                                // Check if this file failed to load
                                const loadError = DataManager.Instance.getPLCLoadError(filename);

                                // Show message if no stages exist
                                if (stages.length === 0) {
                                    // If there was a load error, show warning with retry options
                                    if (loadError) {
                                        return (
                                            <Box sx={{
                                                flex: 1,
                                                display: 'flex',
                                                alignItems: 'center',
                                                justifyContent: 'center',
                                                p: 4
                                            }}>
                                                <Alert
                                                    severity="warning"
                                                    icon={<WarningIcon />}
                                                    sx={{ maxWidth: 600 }}
                                                    action={
                                                        <Stack direction="row" spacing={1} sx={{ mt: 1 }}>
                                                            <Button
                                                                size="small"
                                                                startIcon={<RefreshIcon />}
                                                                onClick={async () => {
                                                                    // Try to reload the file
                                                                    const loaded = await DataManager.Instance.fetch(filename, program);
                                                                    if (loaded) {
                                                                        DataManager.Instance.clearPLCLoadError(filename);
                                                                    } else {
                                                                        UserMessageQueue.Instance.addMessage('❌ Failed to load - file not found');
                                                                    }
                                                                }}
                                                                sx={{
                                                                    color: colors.primaryColor,
                                                                    borderColor: colors.primaryColor,
                                                                    '&:hover': { borderColor: colors.secondaryColor }
                                                                }}
                                                            >
                                                                Try Again
                                                            </Button>
                                                            <Button
                                                                size="small"
                                                                startIcon={<AddIcon />}
                                                                onClick={() => {
                                                                    // Clear error and let user start fresh
                                                                    DataManager.Instance.clearPLCLoadError(filename);
                                                                    setEditingStage(undefined);
                                                                    setStageDialogOpen(true);
                                                                }}
                                                                variant="contained"
                                                                sx={{
                                                                    backgroundColor: colors.primaryColor,
                                                                    '&:hover': { backgroundColor: colors.secondaryColor }
                                                                }}
                                                            >
                                                                Start Fresh
                                                            </Button>
                                                        </Stack>
                                                    }
                                                >
                                                    <AlertTitle>Failed to Load PLC Program</AlertTitle>
                                                    <Typography variant="body2" sx={{ mb: 1 }}>
                                                        The file <strong>{filename}</strong> could not be loaded from the controller.
                                                    </Typography>
                                                    <Typography variant="body2" color="text.secondary">
                                                        <strong>Error:</strong> {loadError}
                                                    </Typography>
                                                    <Typography variant="body2" sx={{ mt: 2 }}>
                                                        You can retry loading the file, or start fresh by adding stages manually.
                                                    </Typography>
                                                </Alert>
                                            </Box>
                                        );
                                    }

                                    // No load error - just empty program
                                    return (
                                        <Box sx={{
                                            flex: 1,
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            p: 4
                                        }}>
                                            <Paper sx={{ p: 4, textAlign: 'center', maxWidth: 500 }}>
                                                <Typography variant="h6" color="text.secondary" gutterBottom>
                                                    No Stages Found
                                                </Typography>
                                                <Typography variant="body2" color="text.secondary">
                                                    Click the "+ Add Stage" button above to create your first stage.
                                                </Typography>
                                            </Paper>
                                        </Box>
                                    );
                                }

                                const stagesByType = {
                                    [StageType.Initial]: stages.filter((s: PLCStage) => s.type === StageType.Initial),
                                    [StageType.Main]: stages.filter((s: PLCStage) => s.type === StageType.Main),
                                    [StageType.Final]: stages.filter((s: PLCStage) => s.type === StageType.Final)
                                };

                                return (
                                    <>
                                        {/* Type Legend Sidebar */}
                                        <Box sx={{ width: '32px', flexShrink: 0 }}>
                                            <Stack spacing={2}>
                                                {/* Initial Label */}
                                                {stagesByType[StageType.Initial].length > 0 && (
                                                    <Paper
                                                        sx={{
                                                            height: groupHeights.initial > 0 ? `${groupHeights.initial}px` : 'auto',
                                                            minHeight: '60px',
                                                            backgroundColor: ConfigurationDataColors.Instance.plcContinuousStageColor,
                                                            color: ConfigurationDataColors.Instance.lightTextColor,
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            writingMode: 'vertical-rl',
                                                            textOrientation: 'mixed',
                                                            fontSize: '0.7rem',
                                                            fontWeight: 600,
                                                            letterSpacing: '1px'
                                                        }}
                                                    >
                                                        INITIAL
                                                    </Paper>
                                                )}

                                                {/* Main Label */}
                                                {stagesByType[StageType.Main].length > 0 && (
                                                    <Paper
                                                        sx={{
                                                            height: groupHeights.main > 0 ? `${groupHeights.main}px` : 'auto',
                                                            minHeight: '60px',
                                                            backgroundColor: ConfigurationDataColors.Instance.plcOneTimeStageColor,
                                                            color: ConfigurationDataColors.Instance.lightTextColor,
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            writingMode: 'vertical-rl',
                                                            textOrientation: 'upright',
                                                            fontSize: '0.7rem',
                                                            fontWeight: 600,
                                                            letterSpacing: '1px'
                                                        }}
                                                    >
                                                        MAIN
                                                    </Paper>
                                                )}

                                                {/* Final Label */}
                                                {stagesByType[StageType.Final].length > 0 && (
                                                    <Paper
                                                        sx={{
                                                            height: groupHeights.final > 0 ? `${groupHeights.final}px` : 'auto',
                                                            minHeight: '60px',
                                                            backgroundColor: ConfigurationDataColors.Instance.plcDisabledStageColor,
                                                            color: ConfigurationDataColors.Instance.lightTextColor,
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            writingMode: 'vertical-rl',
                                                            textOrientation: 'upright',
                                                            fontSize: '0.7rem',
                                                            fontWeight: 600,
                                                            letterSpacing: '1px'
                                                        }}
                                                    >
                                                        FINAL
                                                    </Paper>
                                                )}
                                            </Stack>
                                        </Box>

                                        {/* Stages */}
                                        <Box sx={{ flex: 1 }}>
                                            <Stack spacing={2}>
                                                {/* Initial Stages Group */}
                                                {stagesByType[StageType.Initial].length > 0 && (
                                                    <Box ref={initialGroupRef}>
                                                        <Stack spacing={2}>
                                                            {stagesByType[StageType.Initial].map((stage: PLCStage) => {
                                                                const stageIndex = stages.indexOf(stage);
                                                                return (
                                                                    <StageEditor
                                                                        key={stageIndex}
                                                                        stage={stage}
                                                                        stageIndex={stageIndex}
                                                                        program={program}
                                                                        onAddStatement={(block) => {
                                                                            setStatementMenuBlock(block);
                                                                        }}
                                                                        setStatementMenuAnchor={setStatementMenuAnchor}
                                                                        onEditStage={(stage) => {
                                                                            setEditingStage(stage);
                                                                            setStageDialogOpen(true);
                                                                        }}
                                                                        onEditBlock={(block) => {
                                                                            setEditingBlock(block);
                                                                            setBlockDialogOpen(true);
                                                                        }}
                                                                        onEditStatement={(statement) => {
                                                                            setEditingStatement(statement);
                                                                            setStatementDialogOpen(true);
                                                                        }}
                                                                        setMovingItem={setMovingItem}
                                                                        setMoveDialogOpen={setMoveDialogOpen}
                                                                    />
                                                                );
                                                            })}
                                                        </Stack>
                                                    </Box>
                                                )}

                                                {/* Main Stages Group */}
                                                {stagesByType[StageType.Main].length > 0 && (
                                                    <Box ref={mainGroupRef}>
                                                        <Stack spacing={2}>
                                                            {stagesByType[StageType.Main].map((stage: PLCStage) => {
                                                                const stageIndex = stages.indexOf(stage);
                                                                return (
                                                                    <StageEditor
                                                                        key={stageIndex}
                                                                        stage={stage}
                                                                        stageIndex={stageIndex}
                                                                        program={program}
                                                                        onAddStatement={(block) => {
                                                                            setStatementMenuBlock(block);
                                                                        }}
                                                                        setStatementMenuAnchor={setStatementMenuAnchor}
                                                                        onEditStage={(stage) => {
                                                                            setEditingStage(stage);
                                                                            setStageDialogOpen(true);
                                                                        }}
                                                                        onEditBlock={(block) => {
                                                                            setEditingBlock(block);
                                                                            setBlockDialogOpen(true);
                                                                        }}
                                                                        onEditStatement={(statement) => {
                                                                            setEditingStatement(statement);
                                                                            setStatementDialogOpen(true);
                                                                        }}
                                                                        setMovingItem={setMovingItem}
                                                                        setMoveDialogOpen={setMoveDialogOpen}
                                                                    />
                                                                );
                                                            })}
                                                        </Stack>
                                                    </Box>
                                                )}

                                                {/* Final Stages Group */}
                                                {stagesByType[StageType.Final].length > 0 && (
                                                    <Box ref={finalGroupRef}>
                                                        <Stack spacing={2}>
                                                            {stagesByType[StageType.Final].map((stage: PLCStage) => {
                                                                const stageIndex = stages.indexOf(stage);
                                                                return (
                                                                    <StageEditor
                                                                        key={stageIndex}
                                                                        stage={stage}
                                                                        stageIndex={stageIndex}
                                                                        program={program}
                                                                        onAddStatement={(block) => {
                                                                            setStatementMenuBlock(block);
                                                                        }}
                                                                        setStatementMenuAnchor={setStatementMenuAnchor}
                                                                        onEditStage={(stage) => {
                                                                            setEditingStage(stage);
                                                                            setStageDialogOpen(true);
                                                                        }}
                                                                        onEditBlock={(block) => {
                                                                            setEditingBlock(block);
                                                                            setBlockDialogOpen(true);
                                                                        }}
                                                                        onEditStatement={(statement) => {
                                                                            setEditingStatement(statement);
                                                                            setStatementDialogOpen(true);
                                                                        }}
                                                                        setMovingItem={setMovingItem}
                                                                        setMoveDialogOpen={setMoveDialogOpen}
                                                                    />
                                                                );
                                                            })}
                                                        </Stack>
                                                    </Box>
                                                )}
                                            </Stack>
                                        </Box>
                                    </>
                                );
                            })()}
                        </Box>
                    </Box>
                )}
            />

            {/* Statement Type Selection Menu */}
            <Menu
                anchorEl={statementMenuAnchor}
                open={Boolean(statementMenuAnchor)}
                onClose={() => {
                    setStatementMenuAnchor(null);
                    setStatementMenuBlock(null);
                }}
            >
                {StatementUtilities.getStatementTypes(programType).map((typeInfo) => (
                    <MenuItem
                        key={typeInfo.type}
                        onClick={() => {
                            if (statementMenuBlock) {
                                handleAddStatement(statementMenuBlock, typeInfo.type);
                                setStatementMenuAnchor(null);
                                setStatementMenuBlock(null);
                            }
                        }}
                        sx={typeInfo.systemOnly ? {
                            backgroundColor: ConfigurationDataColors.Instance.selectionColor,
                            '&:hover': {
                                backgroundColor: ConfigurationDataColors.Instance.selectionColor
                            }
                        } : undefined}
                    >
                        <Box>
                            <Typography variant="body2">{typeInfo.displayName}</Typography>
                            <Typography variant="caption" color="text.secondary">
                                {typeInfo.description}
                            </Typography>
                        </Box>
                    </MenuItem>
                ))}
            </Menu>

            {/* Stage Dialog for Add/Edit */}
            <StageDialog
                open={stageDialogOpen}
                stage={editingStage}
                program={program}
                onClose={() => {
                    setStageDialogOpen(false);
                    setEditingStage(undefined);
                }}
                onSave={(name: string, description: string, type: StageType, enabled: boolean, fast: boolean) => {
                    if (editingStage) {
                        // Update existing stage
                        editingStage.name = name;
                        editingStage.description = description;
                        editingStage.type = type;
                        editingStage.enabled = enabled;
                        editingStage.fast = fast;
                    } else {
                        // Create new stage
                        program.stages.forEach(s => s.collapsed = true);
                        const newStage = new PLCStage(name, type);
                        newStage.description = description;
                        newStage.enabled = enabled;
                        newStage.fast = fast;
                        newStage.collapsed = false;
                        program.addStage(newStage);
                    }
                    setStageDialogOpen(false);
                    setEditingStage(undefined);
                }}
                onMoveUp={editingStage ? () => {
                    const sortedStages = program.stages;
                    const stageIndex = sortedStages.indexOf(editingStage);
                    if (stageIndex > 0) {
                        program.moveStageUp(stageIndex);
                    }
                } : undefined}
                onMoveDown={editingStage ? () => {
                    const sortedStages = program.stages;
                    const stageIndex = sortedStages.indexOf(editingStage);
                    if (stageIndex >= 0 && stageIndex < sortedStages.length - 1) {
                        program.moveStageDown(stageIndex);
                    }
                } : undefined}
            />

            {/* Block Dialog for Edit */}
            {editingBlock && (
                <BlockDialog
                    open={blockDialogOpen}
                    block={editingBlock}
                    onClose={() => {
                        setBlockDialogOpen(false);
                        setEditingBlock(undefined);
                    }}
                    onSave={(name: string, description: string, enabled: boolean, requiredInputs: string[], requiredOutputs: string[], requiredBoardTypes: string[]) => {
                        if (editingBlock) {
                            editingBlock.name = name;
                            editingBlock.comment = description;
                            editingBlock.enabled = enabled;
                            editingBlock.requiredInputs = requiredInputs;
                            editingBlock.requiredOutputs = requiredOutputs;
                            editingBlock.requiredBoardTypes = requiredBoardTypes;
                        }
                        setBlockDialogOpen(false);
                        setEditingBlock(undefined);
                    }}
                />
            )}

            {/* Statement Dialog for Edit */}
            {editingStatement && (
                <StatementDialog
                    open={statementDialogOpen}
                    statement={editingStatement}
                    onClose={() => {
                        setStatementDialogOpen(false);
                        setEditingStatement(undefined);
                    }}
                    onSave={(description: string, enabled: boolean) => {
                        if (editingStatement) {
                            editingStatement.comment = description;
                            editingStatement.enabled = enabled;
                        }
                        setStatementDialogOpen(false);
                        setEditingStatement(undefined);
                    }}
                />
            )}

            {/* Move Dialog for blocks and statements */}
            {movingItem && (
                <PLCMoveDialog
                    open={moveDialogOpen}
                    program={program}
                    movingItem={movingItem}
                    setMovingItem={setMovingItem}
                    onClose={() => {
                        setMoveDialogOpen(false);
                        setMovingItem(undefined);
                    }}
                />
            )}

            {/* Variable Search Dialog */}
            <VariableSearchDialog
                open={searchDialogOpen}
                onClose={() => setSearchDialogOpen(false)}
                program={program}
                onNavigateTo={handleNavigateToBlock}
            />
        </Box>
    );
}

/**
 * Props for StageEditor component
 */
interface StageEditorProps {
    stage: PLCStage;
    stageIndex: number;
    program: PLCProgram;
    onAddStatement: (block: PLCBlock) => void;
    setStatementMenuAnchor: (anchor: HTMLElement | null) => void;
    onEditStage: (stage: PLCStage) => void;
    onEditBlock: (block: PLCBlock) => void;
    onEditStatement: (statement: BasePLCStatement) => void;
    setMovingItem: (item: PLCBlock | BasePLCStatement) => void;
    setMoveDialogOpen: (open: boolean) => void;
}

/**
 * Editor for a single PLC stage with collapsible blocks
 */
function StageEditor({ stage, stageIndex, program, onAddStatement, setStatementMenuAnchor, onEditStage, onEditBlock, onEditStatement, setMovingItem, setMoveDialogOpen }: StageEditorProps) {
    const colors = ConfigurationDataColors.Instance;

    // Stage type colors (muted/darker versions)
    const getStageTypeColor = (type: StageType) => {
        switch (type) {
            case StageType.Initial:
                return ConfigurationDataColors.Instance.plcContinuousStageColor; // Muted blue
            case StageType.Main:
                return ConfigurationDataColors.Instance.plcOneTimeStageColor; // Muted green
            case StageType.Final:
                return ConfigurationDataColors.Instance.plcDisabledStageColor; // Muted red
            default:
                return colors.primaryColor;
        }
    };

    const stageColor = stage.enabled ? getStageTypeColor(stage.type) : colors.borderColor;

    return (
        <ObserveState
            key={`stage-editor-${stageIndex}`}
            profilerName={`StageEditor-${stage.name}`}
            listenTo={stage}
            properties={['name', 'type', 'blocks', 'collapsed', 'enabled', 'description']}

            control={() => (
                <Card
                    sx={{
                        borderLeft: `6px solid ${stageColor}`,
                        opacity: stage.enabled ? 1 : 0.6
                    }}
                >
                    {/* Stage Header */}
                    <Box
                        sx={{
                            p: 2,
                            backgroundColor: ConfigurationDataColors.Instance.lightTextColor,
                            borderBottom: `1px solid ${colors.borderColor}`,
                            display: 'flex',
                            alignItems: 'center',
                            gap: 2,
                            cursor: 'pointer',
                            textDecoration: !stage.enabled ? 'line-through' : 'none'
                        }}
                        onClick={() => {
                            // Close all other stages, then toggle this one
                            const wasCollapsed = stage.collapsed;
                            program.stages.forEach(s => s.collapsed = true);
                            stage.collapsed = !wasCollapsed;
                        }}
                    >
                        <Box sx={{ flex: 1 }}>                            <Stack direction="row" spacing={2} alignItems="center">
                            <Typography variant="h6" sx={{ textDecoration: 'inherit' }}>
                                {stage.name || 'Unnamed Stage'}
                            </Typography>
                            {stage.IsMirroringSystemDefault() ? (
                                <Typography variant="caption" color="textSecondary" sx={{ textDecoration: 'inherit' }}>
                                    {(() => {
                                        const allBlocks = stage.getBlocksForRendering();
                                        const systemDefaultCount = allBlocks.filter(b => b.IsInheritedFromSystemDefault()).length;
                                        const definedCount = allBlocks.filter(b => !b.IsInheritedFromSystemDefault()).length;
                                        return `${systemDefaultCount} system default / ${definedCount} defined`;
                                    })()}
                                </Typography>
                            ) : (
                                <Typography variant="caption" color="textSecondary" sx={{ textDecoration: 'inherit' }}>
                                    {stage.blocks.length} block{stage.blocks.length !== 1 ? 's' : ''}
                                </Typography>
                            )}
                        </Stack>
                        </Box>
                        <Stack direction="row" spacing={0.5} alignItems="center">
                            <PLCValidationIndicator element={stage} showCount={true} />
                            {stage.IsMirroringSystemDefault() && (
                                <Typography
                                    variant="caption"
                                    sx={{
                                        backgroundColor: ConfigurationDataColors.Instance.selectionColor,
                                        color: ConfigurationDataColors.Instance.infoColor,
                                        px: 1,
                                        py: 0.5,
                                        borderRadius: 1,
                                        fontWeight: 600,
                                        fontSize: '0.65rem',
                                        mr: 1
                                    }}
                                >
                                    SYSTEM DEFAULT STAGE
                                </Typography>
                            )}
                            {!stage.IsMirroringSystemDefault() && (
                                <>
                                    <IconButton
                                        size="small"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            onEditStage(stage);
                                        }}
                                        title="Edit stage"
                                        sx={{ opacity: 1 }}
                                    >
                                        <SettingsIcon fontSize="small" />
                                    </IconButton>
                                    {stage.enabled && (
                                        <>
                                            <IconButton
                                                size="small"
                                                onClick={async (e) => {
                                                    e.stopPropagation();
                                                    const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(`stage "${stage.name}"`);
                                                    if (confirmed) {
                                                        handleDeleteStage(program, stage);
                                                    }
                                                }}
                                                sx={{ color: 'grey.600' }}
                                                title="Delete stage"
                                            >
                                                <DeleteIcon />
                                            </IconButton>
                                        </>
                                    )}
                                </>
                            )}
                        </Stack>
                    </Box>

                    {/* Stage Content - Collapsible */}
                    <Collapse in={!stage.collapsed} timeout="auto" unmountOnExit>
                        <Box sx={{ p: 2, backgroundColor: ConfigurationDataColors.Instance.lightTextColor }}>
                            {/* Stage Description */}
                            {stage.description && (
                                <Box sx={{ mb: 2 }}>
                                    <EditableComment
                                        comment={stage.description}
                                        onCommentChange={(comment) => {
                                            stage.description = comment;
                                        }}
                                        placeholder="Add stage description..."
                                        readOnly={stage.IsMirroringSystemDefault()}
                                    />
                                </Box>
                            )}
                            {/* Blocks List */}
                            <Stack spacing={1.5}>
                                {stage.getBlocksForRendering().map((block, blockIndex) => (
                                    <BlockEditor
                                        key={blockIndex}
                                        block={block}
                                        blockIndex={blockIndex}
                                        stage={stage}
                                        program={program}
                                        onAddStatement={onAddStatement}
                                        setStatementMenuAnchor={setStatementMenuAnchor}
                                        onEditBlock={onEditBlock}
                                        onEditStatement={onEditStatement}
                                        setMovingItem={setMovingItem}
                                        setMoveDialogOpen={setMoveDialogOpen}
                                    />
                                ))}
                            </Stack>

                            {/* Add Block Button - always visible for enabled stages, new blocks belong to current program */}
                            {stage.enabled && (
                                <Box sx={{ mt: 2 }}>
                                    <Button
                                        variant="outlined"
                                        size="small"
                                        startIcon={<AddIcon />}
                                        onClick={() => handleAddBlock(stage, program)}
                                        sx={{ borderColor: colors.borderColor }}
                                    >
                                        Add Block
                                    </Button>
                                </Box>
                            )}
                        </Box>
                    </Collapse>
                </Card>
            )}
        />
    );
}

/**
 * Props for BlockEditor component
 */
interface BlockEditorProps {
    block: PLCBlock;
    blockIndex: number;
    stage: PLCStage;
    program: PLCProgram;
    onAddStatement: (block: PLCBlock) => void;
    setStatementMenuAnchor: (anchor: HTMLElement | null) => void;
    onEditBlock: (block: PLCBlock) => void;
    onEditStatement: (statement: BasePLCStatement) => void;
    setMovingItem: (item: PLCBlock | BasePLCStatement) => void;
    setMoveDialogOpen: (open: boolean) => void;
}

/**
 * Editor for a single PLC block with collapsible actions/statements
 */
function BlockEditor({ block, blockIndex, stage, program, onAddStatement, setStatementMenuAnchor, onEditBlock, onEditStatement, setMovingItem, setMoveDialogOpen }: BlockEditorProps) {
    const colors = ConfigurationDataColors.Instance;

    // Block is read-only only if it's from SystemDefault AND we're editing System program
    const isFromSystemDefault = block.IsInheritedFromSystemDefault() &&
        program.getProgramType() === PLCProgramType.System;

    // Get the target program type for checking block enabled state
    // For mirrored blocks, use the program being edited, not the block's source
    const targetProgramType = program.getProgramType();

    return (
        <ObserveState
            key={`block-editor-${blockIndex}`}
            profilerName={`BlockEditor-${block.name}`}
            listenTo={block}
            properties={['name', 'type', 'actions', 'subBlocks', 'collapsed', 'enabled', 'comment']}

            control={() => (
                <Paper
                    id={`plc-block-${stage.name}-${block.name}`}
                    variant="outlined"
                    sx={{
                        borderLeft: `3px solid ${block.isEnabled(targetProgramType) ? colors.secondaryColor : colors.borderColor}`,
                        opacity: block.isEnabled(targetProgramType) ? 1 : 0.5,
                        backgroundColor: isFromSystemDefault ? ConfigurationDataColors.Instance.lightBackgroundColor : undefined
                    }}
                >
                    {/* Block Header */}
                    <Box
                        sx={{
                            p: 1.5,
                            backgroundColor: isFromSystemDefault ? ConfigurationDataColors.Instance.selectionColor : ConfigurationDataColors.Instance.lightBackgroundColor,
                            display: 'flex',
                            alignItems: 'center',
                            gap: 1,
                            cursor: 'pointer',
                            textDecoration: !block.isEnabled(targetProgramType) ? 'line-through' : 'none'
                        }}
                        onClick={(e) => {
                            // Stop propagation to prevent parent blocks from collapsing
                            e.stopPropagation();

                            // For sub-blocks, only toggle this block without affecting siblings
                            // For top-level blocks, close all other blocks in the stage
                            const wasCollapsed = block.collapsed;

                            // Check if this is a top-level block (parent is stage) or a sub-block (parent is block)
                            const parentElement = block.getParentElement();
                            const isTopLevelBlock = parentElement?.getElementType() === 'stage';

                            if (isTopLevelBlock) {
                                // Top-level block: close all other blocks in this stage
                                stage.getBlocksForRendering().forEach(b => b.collapsed = true);
                            } else {
                                // Sub-block: just close all sibling sub-blocks
                                const parentBlock = parentElement as PLCBlock;
                                if (parentBlock) {
                                    parentBlock.subBlocks.forEach(b => b.collapsed = true);
                                }
                            }

                            block.collapsed = !wasCollapsed;
                        }}
                    >
                        <Box sx={{ flex: 1 }}>
                            <Stack direction="row" spacing={1} alignItems="center">
                                <Typography variant="subtitle2" sx={{ textDecoration: 'inherit' }}>
                                    {block.name || 'Unnamed Block'}
                                </Typography>
                                <Typography variant="caption" color="textSecondary" sx={{ textDecoration: 'inherit' }}>
                                    {block.actions.length} statement{block.actions.length !== 1 ? 's' : ''}
                                    {block.subBlocks.length > 0 && `, ${block.subBlocks.length} sub-block${block.subBlocks.length !== 1 ? 's' : ''}`}
                                </Typography>
                            </Stack>
                        </Box>
                        <Stack direction="row" spacing={0.5} alignItems="center">
                            <PLCValidationIndicator element={block} showCount={true} />
                            {isFromSystemDefault && (
                                <Typography
                                    variant="caption"
                                    sx={{
                                        backgroundColor: ConfigurationDataColors.Instance.selectionColor,
                                        color: ConfigurationDataColors.Instance.infoColor,
                                        px: 1,
                                        py: 0.5,
                                        borderRadius: 1,
                                        fontWeight: 600,
                                        fontSize: '0.65rem',
                                        mr: 1
                                    }}
                                >
                                    SYSTEM DEFAULT
                                </Typography>
                            )}
                            {!isFromSystemDefault && (
                                <>
                                    <IconButton
                                        size="small"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            onEditBlock(block);
                                        }}
                                        title="Edit block"
                                        sx={{ opacity: 1 }}
                                    >
                                        <SettingsIcon fontSize="small" />
                                    </IconButton>
                                    <IconButton
                                        size="small"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            setMovingItem(block);
                                            setMoveDialogOpen(true);
                                        }}
                                        title="Move block"
                                        sx={{ opacity: 1 }}
                                    >
                                        <MoveIcon fontSize="small" />
                                    </IconButton>
                                    {block.isEnabled(targetProgramType) && (
                                        <>
                                            <IconButton
                                                size="small"
                                                onClick={async (e) => {
                                                    e.stopPropagation();
                                                    const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(`block "${block.name}"`);
                                                    if (confirmed) {
                                                        handleDeleteBlock(stage, block);
                                                    }
                                                }}
                                                sx={{ color: 'grey.600' }}
                                                title="Delete block"
                                            >
                                                <DeleteIcon fontSize="small" />
                                            </IconButton>
                                        </>
                                    )}
                                </>
                            )}
                        </Stack>
                    </Box>

                    {/* Block Content - Collapsible */}
                    <Collapse in={!block.collapsed} timeout="auto" unmountOnExit>
                        <Box sx={{ p: 1.5, pt: 1 }}>
                            {/* Block Comment */}
                            {block.comment && (
                                <Box sx={{ mb: 1.5 }}>
                                    <EditableComment
                                        comment={block.comment}
                                        onCommentChange={(comment) => {
                                            block.comment = comment;
                                        }}
                                        placeholder="Add block comment..."
                                        readOnly={isFromSystemDefault}
                                    />
                                </Box>
                            )}
                            {/* Items List (Statements and Sub-blocks sorted by ordinal) */}
                            <List dense sx={{ py: 0 }}>
                                {block.getItemsSorted().map((item, itemIndex) => {
                                    const isSubBlock = item instanceof PLCBlock;

                                    if (isSubBlock) {
                                        // Render sub-block recursively
                                        const subBlock = item as PLCBlock;
                                        return (
                                            <ListItem
                                                key={`subblock-${itemIndex}`}
                                                sx={{
                                                    mb: 0.5,
                                                    flexDirection: 'column',
                                                    alignItems: 'stretch',
                                                    p: 0
                                                }}
                                            >
                                                <BlockEditor
                                                    block={subBlock}
                                                    blockIndex={itemIndex}
                                                    stage={stage}
                                                    program={program}
                                                    onAddStatement={onAddStatement}
                                                    setStatementMenuAnchor={setStatementMenuAnchor}
                                                    onEditBlock={onEditBlock}
                                                    onEditStatement={onEditStatement}
                                                    setMovingItem={setMovingItem}
                                                    setMoveDialogOpen={setMoveDialogOpen}
                                                />
                                            </ListItem>
                                        );
                                    } else {
                                        // Render statement
                                        const action = item as BasePLCStatement;

                                        return (
                                            <ListItem
                                                key={`statement-${itemIndex}`}
                                                sx={{
                                                    border: `1px solid ${colors.borderColor}`,
                                                    borderRadius: 1,
                                                    mb: 0.5,
                                                    backgroundColor: ConfigurationDataColors.Instance.lightTextColor,
                                                    flexDirection: 'column',
                                                    alignItems: 'stretch'
                                                }}
                                            >
                                                {action.comment && (
                                                    <Box sx={{ width: '100%', mb: 1, pt: 1, px: 1 }}>
                                                        <EditableComment
                                                            comment={action.comment}
                                                            onCommentChange={(comment) => {
                                                                action.comment = comment;
                                                            }}
                                                            placeholder="Add statement comment..."
                                                            readOnly={isFromSystemDefault}
                                                        />
                                                    </Box>
                                                )}
                                                <Box sx={{ display: 'flex', width: '100%', alignItems: 'flex-start' }}>
                                                    <Box sx={{ flex: 1, pr: 2 }}>
                                                        <ListItemText
                                                            primary={action.render(
                                                                !block.isEnabled(targetProgramType) ? PLCRenderMode.Disabled :
                                                                    action.isDisabled(isFromSystemDefault ? PLCRenderMode.ReadOnly : PLCRenderMode.Edit, program.getProgramType()) ? PLCRenderMode.Disabled :
                                                                        isFromSystemDefault ? PLCRenderMode.ReadOnly :
                                                                            PLCRenderMode.Edit,
                                                                program.getProgramType()
                                                            )}
                                                        />
                                                    </Box>
                                                    <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 0.5 }}>
                                                        <PLCValidationIndicator element={action} />
                                                        <Typography variant="caption" color="text.secondary" sx={{ pt: 0.5, mr: 0.5 }}>
                                                            {action.constructor.name}
                                                        </Typography>
                                                        <IconButton
                                                            edge="end"
                                                            size="small"
                                                            disabled={isFromSystemDefault}
                                                            onClick={() => {
                                                                onEditStatement(action);
                                                            }}
                                                            sx={{ mt: -0.5, opacity: 1 }}
                                                            title={
                                                                isFromSystemDefault ? "Cannot edit statement from SystemDefault block" :
                                                                    "Edit statement"
                                                            }
                                                        >
                                                            <SettingsIcon fontSize="small" />
                                                        </IconButton>
                                                        <IconButton
                                                            edge="end"
                                                            size="small"
                                                            disabled={isFromSystemDefault}
                                                            onClick={() => {
                                                                setMovingItem(action);
                                                                setMoveDialogOpen(true);
                                                            }}
                                                            sx={{ mt: -0.5, opacity: 1 }}
                                                            title={
                                                                isFromSystemDefault ? "Cannot move statement from SystemDefault block" :
                                                                    "Move statement"
                                                            }
                                                        >
                                                            <MoveIcon fontSize="small" />
                                                        </IconButton>
                                                        <IconButton
                                                            edge="end"
                                                            size="small"
                                                            disabled={isFromSystemDefault || !block.isEnabled(targetProgramType)}
                                                            onClick={() => handleDeleteStatement(block, action)}
                                                            sx={{ color: 'grey.600', mt: -0.5 }}
                                                            title={
                                                                !block.isEnabled(targetProgramType) ? "Cannot delete statement in disabled block" :
                                                                    isFromSystemDefault ? "Cannot delete statement from SystemDefault block" :
                                                                        "Delete statement"
                                                            }
                                                        >
                                                            <DeleteIcon fontSize="small" />
                                                        </IconButton>
                                                    </Box>
                                                </Box>
                                            </ListItem>
                                        );
                                    }
                                })}
                            </List>

                            {/* Add Statement and Add Block Buttons - hidden for SystemDefault blocks and disabled blocks */}
                            {!isFromSystemDefault && block.isEnabled(targetProgramType) && (
                                <Box sx={{ mt: 1, display: 'flex', gap: 1 }}>
                                    <Button
                                        variant="text"
                                        size="small"
                                        startIcon={<AddIcon />}
                                        onClick={(e) => {
                                            setStatementMenuAnchor(e.currentTarget);
                                            onAddStatement(block);
                                        }}
                                        sx={{ textTransform: 'none' }}
                                    >
                                        Add Statement
                                    </Button>
                                    <Button
                                        variant="text"
                                        size="small"
                                        startIcon={<AddIcon />}
                                        onClick={() => {
                                            handleAddSubBlock(block);
                                        }}
                                        sx={{ textTransform: 'none', color: colors.primaryColor }}
                                    >
                                        Add Block
                                    </Button>
                                </Box>
                            )}
                        </Box>
                    </Collapse>
                </Paper>
            )}
        />
    );
}

// ============================================================================
// Handler Functions
// ============================================================================

function handleDeleteStage(program: PLCProgram, stage: PLCStage): void {
    program.removeStage(stage);
}

function handleAddBlock(stage: PLCStage, program: PLCProgram): void {
    // TODO: Show dialog to configure block properties
    // Collapse all existing blocks before adding new one
    stage.blocks.forEach(b => b.collapsed = true);

    // Determine block name prefix based on program type
    const isSystemDefault = program.getProgramType() === PLCProgramType.SystemDefault;
    const prefix = isSystemDefault ? 'System Default Block' : 'Block';
    const newBlock = new PLCBlock(`${prefix} ${stage.blocks.length + 1}`);
    // Block type is always Rung
    newBlock.comment = '';
    newBlock.collapsed = false; // New block is open
    // Note: plcSource will be resolved from parent chain (stage -> program)
    // This ensures new blocks get the correct program even when adding to
    // a SystemDefault stage being rendered in System program context
    stage.addBlock(newBlock);
}

function handleDeleteBlock(stage: PLCStage, block: PLCBlock): void {
    // Check if this is a sub-block (parent is PLCBlock) or top-level block (parent is PLCStage)
    const parentElement = block.getParentElement();

    if (parentElement?.getElementType() === 'block') {
        // Sub-block: remove from parent block
        const parentBlock = parentElement as PLCBlock;
        parentBlock.removeSubBlock(block);
    } else {
        // Top-level block: remove from stage
        stage.removeBlock(block);
    }
}

function handleAddStatement(block: PLCBlock, statementType: StatementType): void {
    // Create new statement using factory
    const newStatement = StatementUtilities.createStatement(statementType);

    // Add statement to block
    block.addAction(newStatement);
}

function handleDeleteStatement(block: PLCBlock, action: BasePLCStatement): void {
    block.removeAction(action);
}

function handleAddSubBlock(parentBlock: PLCBlock): void {
    // Collapse all existing items before adding new sub-block
    parentBlock.subBlocks.forEach(b => b.collapsed = true);

    const newSubBlock = new PLCBlock(`Sub-block ${parentBlock.subBlocks.length + 1}`);
    newSubBlock.comment = '';
    newSubBlock.collapsed = false; // New sub-block is open
    parentBlock.addSubBlock(newSubBlock);
}
