import { UserMessageQueue } from '../data/UserMessageQueue';
import { ICNCFeatures } from '../machine/ICNCFeatures';

export class SimulatorCNCFeatures implements ICNCFeatures {
  private pointerOn: boolean = false;
  private laserOn: boolean = false;
  private currentTool: number = 1;

  async IsToolLoaded(): Promise<boolean> {
    return true; // Simulator always has a tool loaded
  }

  async IsClampOpened(): Promise<boolean> {
    return false; // Simulator clamp is always closed
  }

  async DropTool(): Promise<void> {
    this.currentTool = 0;
    UserMessageQueue.Instance.addMessage('✓ Tool dropped');
  }

  async ChangeToTool(toolNumber: number, returnToCurrentPosition: boolean): Promise<void> {
    this.currentTool = toolNumber;
    const returnMsg = returnToCurrentPosition ? ' and returned to position' : '';
    UserMessageQueue.Instance.addMessage(`✓ Changed to tool ${toolNumber}${returnMsg}`);
  }

  async GetCurrentToolNumber(): Promise<number> {
    return this.currentTool;
  }

  async CheckTool(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Tool check completed');
  }

  async MeasureCurrentTool(): Promise<void> {
    UserMessageQueue.Instance.addMessage(`✓ Measured tool ${this.currentTool}`);
  }

  async MeasureAllTools(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ All tools measured');
  }

  async TouchOff(): Promise<void> {
    UserMessageQueue.Instance.addMessage('✓ Touch-off completed');
  }

  async StartPointer(): Promise<void> {
    this.pointerOn = true;
    UserMessageQueue.Instance.addMessage('✓ Pointer started');
  }

  async StopPointer(): Promise<void> {
    this.pointerOn = false;
    UserMessageQueue.Instance.addMessage('✓ Pointer stopped');
  }

  IsPointerOn(): boolean {
    return this.pointerOn;
  }

  async StartLaser(): Promise<void> {
    this.laserOn = true;
    UserMessageQueue.Instance.addMessage('✓ Laser started');
  }

  async StopLaser(): Promise<void> {
    this.laserOn = false;
    UserMessageQueue.Instance.addMessage('✓ Laser stopped');
  }

  IsLaserOn(): boolean {
    return this.laserOn;
  }
}
