import React from 'react';
import { Declaration } from './Declaration';
import { IPLCSource, PLCProgramType } from './PLCUtilities';

/**
 * Interface for PLC elements that have a name
 */
export interface INamedPLCElement {
    name: string;
}

/**
 * Interface for PLC elements that represent data (variables, inputs, outputs)
 * Used to distinguish data elements that can be read/written from other elements
 * This should be at the bottom of the IPLCElement chain (DataElement instances)
 */
export interface IDataPLCElement extends INamedPLCElement {
    /**
     * Whether this data element needs write access (can be assigned to)
     * If false, the element is read-only
     * Matches the needsWrite property on DataElement
     */
    needsWrite: boolean;
}

/**
 * Rendering mode for PLC elements
 */
export enum PLCRenderMode {
    /** Full editing capabilities (default) */
    Edit = 'edit',
    /** Read-only view with different background, no edit functions */
    ReadOnly = 'readonly',
    /** Disabled state with strikethrough text */
    Disabled = 'disabled'
}

/**
 * Output state for PLC elements - determines how element should be output
 */
export enum OutputState {
    /** Element should be output normally */
    Output = 'output',
    /** Element should be output but disabled/commented out */
    Disabled = 'disabled',
    /** Element should be excluded from output entirely */
    Exclude = 'exclude'
}

/**
 * Output type for determining output behavior
 */
export enum OutputType {
    /** Rendering to UI */
    Render = 'render',
    /** Generating PLC code output */
    PLCCode = 'plccode'
}

/**
 * Validation severity level
 */
export enum ValidationSeverity {
    /** Error - prevents compilation/execution */
    Error = 'error',
    /** Warning - should be addressed but doesn't prevent compilation */
    Warning = 'warning'
}

/**
 * Validation issue for a PLC element
 */
export class PLCValidationIssue {
    public element: IPLCElement;
    public message: string;
    public severity: ValidationSeverity;

    constructor(element: IPLCElement, message: string, severity: ValidationSeverity = ValidationSeverity.Error) {
        this.element = element;
        this.message = message;
        this.severity = severity;
    }
}

/**
 * Interface for PLC elements that can be rendered, output declarations, and generate logic
 * Implemented by PLCProgram, PLCStage, PLCBlock, and statements (BasePLCStatement)
 */
export interface IPLCElement {
    /**
     * Get the PLC source (program) that contains this element
     * Used for scoped declaration lookups
     */
    plcSource: IPLCSource | undefined;

    /**
     * Get the parent element that contains this element in the hierarchy
     * - For statements: returns the containing block
     * - For blocks: returns the containing stage
     * - For stages: returns the containing program
     * - For programs: returns undefined
     * - For other elements (DataElement, Condition, etc.): returns the containing statement or undefined
     * This enables O(1) scope resolution instead of O(n) tree searches
     */
    getParentElement(): IPLCElement | undefined;

    /**
     * Set the parent element that contains this element in the hierarchy
     * Called automatically when element is added to a container
     * Should NOT be serialized to storage
     */
    setParentElement(parent: IPLCElement | undefined): void;

    /**
     * Get the type of this PLC element
     * Used for identifying element types without circular dependencies
     * @returns Type identifier: 'program', 'stage', 'block', 'statement', 'condition', 'predicate', or 'other'
     */
    getElementType(): 'program' | 'stage' | 'block' | 'statement' | 'condition' | 'condition-group' | 'predicate' | 'other';

    /**
     * Reset any cached/generated state before rendering or code generation
     * Called before collecting declarations and generating logic to ensure consistent state
     * Elements that generate dynamic content (like IOStateChangesStatement) should clear their cache here
     */
    preRenderReset(): void;

    /**
     * Get a unique identifier for this element
     * - For stages: returns the stage name
     * - For blocks: returns a unique block ID (GUID)
     * - For statements: returns a unique statement ID (GUID)
     * - For programs: returns the program type name
     * @returns Unique identifier string
     */
    getElementId(): string;

    /**
     * Render the element to a visual representation (for UI display)
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled). Defaults to Edit.
     *             If Edit or not supplied, checks the element's enabled state.
     *             ReadOnly: different background, no edit functions
     *             Disabled: strikethrough text
     * @param targetProgramType The program type context this element is being rendered in
     *                          Used to determine if SystemDefault elements should be disabled in System context
     * @returns React component or HTML representation
     */
    render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode;

    /**
     * Get declarations that are used/referenced by this element and its children
     * @returns Array of Declaration objects that are referenced in the logic
     */
    getUsedDeclarations(): Declaration[];

    /**
     * Get declarations that are added/defined by this element and its children
     * @returns Array of Declaration objects that are defined at this level
     */
    getAddedDeclarations(): Declaration[];

    /**
     * Get the PLC logic code for this element
     * @param availableDeclarations Array of declaration names that are available/defined
     *                              Used to determine if logic should be commented out due to missing dependencies
     * @returns Generated PLC code as string array (e.g., ladder logic, structured text, etc.)
     */
    getPLCLogic(availableDeclarations: string[]): string[];

    /**
     * Get validation issues for this element and its children
     * @returns Array of validation issues with references to the element that has the issue
     */
    getValidationIssues(): PLCValidationIssue[];

    /**
     * Determine if this element should be output and how
     * Allows elements to control their own output behavior based on context,
     * dependencies, enabled state, etc.
     * @param outputType The type of output being generated (Render for UI, PLCCode for logic)
     * @param availableDeclarations Optional array of declaration names that are available/defined
     * @returns OutputState indicating whether to output normally, as disabled, or exclude entirely
     */
    shouldOutput(outputType: OutputType, availableDeclarations?: string[]): OutputState;

    /**
     * Determine if this element should be disabled in the given context
     * Disabled means the element is visible but cannot be edited (for UI) or is commented out (for PLC code)
     * @param mode The rendering mode being used
     * @param targetProgramType The program type context this element is being evaluated in
     *                          Used to determine if SystemDefault elements should be disabled in System context
     * @returns true if the element should be disabled, false otherwise
     */
    isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean;
}
