import { StateManager } from '../../utils/statemanager/StateManager';
import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for Movable Touch Plate Height configuration
 * Conditional validation - only validates when movable touch plate is enabled
 * Requires manual confirmation that height is properly configured
 */
export class MovableTouchPlateHeightChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Movable Touch Plate Height',
            'Configure the height/thickness of the movable touch plate'
        );

        // Listen to MachineData changes that affect this checklist item
        const machine = MachineData.Instance;
        StateManager.addObserver(machine, () => {
            // Trigger update on this item when relevant properties change
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['hasMovableTouchPlate', 'movableTouchPlateHeight']);
    }

    public shouldInclude(): boolean {
        return MachineData.Instance.hasMovableTouchPlate;
    }

    public needsManualConfirmation(): boolean {
        return false; // Auto-validation only
    }

    public completionCheck(): boolean {
        const machine = MachineData.Instance;

        // If movable touch plate is not enabled, this item is N/A (considered complete)
        if (!machine.hasMovableTouchPlate) {
            return true;
        }

        // If enabled, validate that height is configured (not 0)
        return machine.movableTouchPlateHeight !== 0;
    }

    public clone(): MovableTouchPlateHeightChecklistItem {
        const cloned = new MovableTouchPlateHeightChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
