import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { WizardStep } from '../../../Wizard/WizardStep';
import { WarmUpSpindleWizard } from '../WarmUpSpindleWizard';
import { WarmUpProgressStep } from './WarmUpProgressStep';

export class WarmUpInstructionsStep extends WizardStep {
    constructor(wizard: WarmUpSpindleWizard, priorStep: WizardStep | null = null) {
        super(wizard, priorStep);
    }

    getTitle(): string {
        return 'Spindle Warm-Up';
    }

    nextStep(): WizardStep | null {
        return new WarmUpProgressStep(this.wizard as WarmUpSpindleWizard, this);
    }

    backStep(): WizardStep | null {
        return null;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="warmup-instructions-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <WarmUpInstructionsStepComponent step={this} />}
            />
        );
    }
}

interface WarmUpInstructionsStepComponentProps {
    step: WarmUpInstructionsStep;
}

function WarmUpInstructionsStepComponent({ step }: WarmUpInstructionsStepComponentProps) {
    const colors = ConfigurationDataColors.Instance;
    const wizard = step.wizard as WarmUpSpindleWizard;

    const handleStartWarmup = () => {
        wizard.advanceToNextStep();
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Typography variant="h6" sx={{ color: colors.darkTextColor }}>
                    Spindle Warm-Up Procedure
                </Typography>

                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    This wizard will warm up the spindle through a series of progressive speed stages to ensure optimal performance and longevity.
                </Typography>

                <Box sx={{ mt: 2 }}>
                    <Typography variant="body2" sx={{ color: colors.mutedTextColor, mb: 1 }}>
                        The warm-up process includes:
                    </Typography>
                    <Box component="ul" sx={{ pl: 3, m: 0 }}>
                        <Typography component="li" variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                            Move to safe position
                        </Typography>
                        <Typography component="li" variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                            40% speed warm-up (30 seconds)
                        </Typography>
                        <Typography component="li" variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                            70% speed warm-up (45 seconds)
                        </Typography>
                        <Typography component="li" variant="body2" sx={{ color: colors.darkTextColor, mb: 0.5 }}>
                            90% speed warm-up (60 seconds)
                        </Typography>
                    </Box>
                </Box>

                <Typography variant="body2" sx={{ color: colors.mutedTextColor, mt: 2, fontStyle: 'italic' }}>
                    Total time: approximately 2-3 minutes
                </Typography>
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    variant="outlined"
                    onClick={() => wizard.cancelWizard()}
                >
                    Cancel
                </Button>
                <Button
                    variant="contained"
                    onClick={handleStartWarmup}
                >
                    Start Warm-Up
                </Button>
            </Box>
        </Box>
    );
}
