  /**
   * IStorable implementation - serialize to JSON
   */
  public toJSON(): object {
    return DataUtilities.getStorageData(this, ['_instance']);
  }

  /**
   * IStorable implementation - deserialize from JSON
   */
  public fromJSON(data: any): void {
    if (!data) return;
    DataUtilities.loadStorageData(this, data, ['_instance']);
  }

  /**
   * Convert 8-character hex colors (with alpha) to 6-character hex colors for THREE.js compatibility
   * THREE.js doesn't support alpha in hex colors, so we strip the alpha channel
   * @param color - The color string (e.g., '#c9caced2' becomes '#c9cace')
   * @returns Valid 6-character hex color for THREE.js
   */
  public static toThreeJsColor(color: string): string {
    if (!color || !color.startsWith('#')) {
      return color || '#ffffff'; // Default to white if invalid
    }

    // If it's an 8-character hex color, strip the alpha channel
    if (color.length === 9) {
      return color.substring(0, 7); // Take first 7 characters (#rrggbb)
    }

    // If it's already 6 characters or other format, return as-is
    return color;
  }

  /**
   * Reset all colors and transparency values to their default values
   */
  public async reset(): Promise<void> {
    // Create a new instance with default values
    const defaultColors = new ConfigurationDataColors();

    // Copy all default values from the new instance
    const defaultData = defaultColors.toJSON();
    this.fromJSON(defaultData);

    // Notify all listeners that everything has changed
    StateManager.propertyChanged(this, '');
  }

