import { SingletonRegistry } from '../../utils/SingletonRegistry';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { DataFileConstants } from '../DataFileConstants';
import { SaveableDataBase } from './SaveableDataBase';
import { CutterType, Tool } from "./Tool";

/**
 * Tool library (placeholder for now)
 * Direct conversion from C# ToolLibrary class
 * Implemented as singleton pattern
 */
export class ToolLibrary extends SaveableDataBase {
  // Add tool properties as needed based on your C# implementation
  public tools: Tool[] = []; // Array to hold tool definitions

  /**
   * Get the filename to use for saving/loading this data
   */
  protected get filename(): string {
    return DataFileConstants.TOOLS;
  }

  private constructor() {
    super(); // Call parent constructor first

    // Register this singleton - will throw if a duplicate is created
    SingletonRegistry.ToolLibrary = this;

    // Initialize default values
    // add the following bit as examples

    // manual tool. This is a placeholder for manual tool input
    const manualTool = new Tool();
    manualTool.toolNumber = 199; // Manual tool has no number
    manualTool.toolName = 'Manual Tool';
    manualTool.shankWidth = 0;
    manualTool.lengthBelowHolder = 0;
    manualTool.cuttingLength = 0;
    manualTool.cuttingDiameter = 0;
    manualTool.cutterType = CutterType.Manual; // Default type
    manualTool.toolOffsetX = 0;
    manualTool.toolOffsetY = 0;
    manualTool.measuredLength = 0;
    manualTool.systemLocked = true; // Manual tool cannot be edited
    this.tools.push(manualTool);

    // 1/4" flat end mill
    const bit1 = new Tool();
    bit1.toolNumber = 1;
    bit1.toolName = '1/4" Flat End Mill';
    bit1.shankWidth = 0.25;
    bit1.lengthBelowHolder = 2.5;
    bit1.cuttingLength = 1.5;
    bit1.cuttingDiameter = 0.25;
    bit1.cutterType = CutterType.FlatEndMill;
    bit1.toolOffsetX = 0;
    bit1.toolOffsetY = 0;
    bit1.lastMeasuredSessionNumber = 1;
    bit1.measuredLength = 2.492; // Close to but not exactly 2.5
    this.tools.push(bit1);

    // 1/8" ball end mill
    const bit2 = new Tool();
    bit2.toolNumber = 2;
    bit2.toolName = '1/8" Ball End Mill';
    bit2.shankWidth = 0.125;
    bit2.lengthBelowHolder = 2.0;
    bit2.cuttingLength = 0.125;
    bit2.cuttingDiameter = 0.125;
    bit2.cutterType = CutterType.BallEndMill;
    bit2.toolOffsetX = 0;
    bit2.toolOffsetY = 0;
    bit2.lastMeasuredSessionNumber = 1;
    bit2.measuredLength = 2.007; // Close to but not exactly 2.0
    this.tools.push(bit2);

    // 60 degree v-bit
    const bit3 = new Tool();
    bit3.toolNumber = 3;
    bit3.toolName = '60° V-Bit';
    bit3.shankWidth = 0.125;
    bit3.lengthBelowHolder = 2.0;
    bit3.cuttingLength = .5;
    bit3.cuttingDiameter = 0.25; // Flat width at tip
    bit3.vCuttingEdgeAngle = 60; // Angle in degrees
    bit3.cutterType = CutterType.VBit;
    bit3.toolOffsetX = 0;
    bit3.toolOffsetY = 0;
    bit3.lastMeasuredSessionNumber = 1;
    bit3.measuredLength = 1.995; // Close to but not exactly 2.0
    this.tools.push(bit3);

    // 1.5" spoil board surfacing bit
    const bit4 = new Tool();
    bit4.toolNumber = 4;
    bit4.toolName = '1.5" Spoil Board Surfacing Bit';
    bit4.shankWidth = .5;
    bit4.lengthBelowHolder = 2.0;
    bit4.cuttingLength = 1.0;
    bit4.cuttingDiameter = 1.5;
    bit4.cutterType = CutterType.FlatEndMill; // Assuming flat end mill for surfacing
    bit4.toolOffsetX = 0;
    bit4.toolOffsetY = 0;
    bit4.lastMeasuredSessionNumber = 1;
    bit4.measuredLength = 2.003; // Close to but not exactly 2.0
    this.tools.push(bit4);

    // 1/2" flat end mill
    const bit5 = new Tool();
    bit5.toolNumber = 5;
    bit5.toolName = '1/2" Flat End Mill';
    bit5.shankWidth = 0.5;
    bit5.lengthBelowHolder = 2.5;
    bit5.cuttingLength = 1.5;
    bit5.cuttingDiameter = 0.5;
    bit5.cutterType = CutterType.FlatEndMill;
    bit5.toolOffsetX = 0;
    bit5.toolOffsetY = 0;
    bit5.lastMeasuredSessionNumber = 1;
    bit5.measuredLength = 2.498; // Close to but not exactly 2.5
    this.tools.push(bit5);

    // add 90 degree v-bit with 1/2 shank and 1" cutting length
    const bit6 = new Tool();
    bit6.toolNumber = 6;
    bit6.toolName = '90° V-Bit';
    bit6.shankWidth = 0.5;
    bit6.lengthBelowHolder = 2.0;
    bit6.cuttingLength = 1.0;
    bit6.cuttingDiameter = 0.25; // Flat width at tip
    bit6.vCuttingEdgeAngle = 90; // Angle in degrees
    bit6.cutterType = CutterType.VBit;
    bit6.toolOffsetX = 0;
    bit6.toolOffsetY = 0;
    bit6.lastMeasuredSessionNumber = 1;
    bit6.measuredLength = 2.001; // Close to but not exactly 2.0
    this.tools.push(bit6);

    // add 45 degree v-bit with 1/4 shank and 1" cutting length
    const bit7 = new Tool();
    bit7.toolNumber = 7;
    bit7.toolName = '45° V-Bit';
    bit7.shankWidth = 0.25;
    bit7.lengthBelowHolder = 2.0;
    bit7.cuttingLength = .5;
    bit7.cuttingDiameter = 0.25; // Flat width at tip
    bit7.vCuttingEdgeAngle = 45; // Angle in degrees
    bit7.cutterType = CutterType.VBit;
    bit7.toolOffsetX = 0;
    bit7.toolOffsetY = 0;
    bit7.lastMeasuredSessionNumber = 1;
    bit7.measuredLength = 1.997; // Close to but not exactly 2.0
    this.tools.push(bit7);

    // Initialization is handled by DataManager.initializeOnStartup()
    // Note: setupAutoSave() will be called after instance creation to avoid constructor issues

    // Register listeners on all default tools
    this.registerSubObjectListeners();
  }

  /**
   * Register listener on a single tool
   */
  private registerToolListener(tool: Tool): void {
    StateManager.addObserver(
      tool,
      () => {
        // When any tool changes, notify that the library changed
        StateManager.changed(this);
      },
      [], // Listen to all properties
      `ToolLibrary-Tool-${tool.toolNumber}`
    );
  }

  /**
   * Unregister listener from a single tool
   */
  private unregisterToolListener(tool: Tool): void {
    StateManager.removeObserverByName(tool, `ToolLibrary-Tool-${tool.toolNumber}`);
  }

  /**
   * Register listeners on all sub-objects (tools)
   * Called during initialization and after fromJSON
   */
  protected registerSubObjectListeners(): void {
    for (const tool of this.tools) {
      this.registerToolListener(tool);
    }
  }

  /**
   * Unregister listeners from all sub-objects (tools)
   * Called before fromJSON to clean up old listeners
   */
  protected unregisterSubObjectListeners(): void {
    for (const tool of this.tools) {
      this.unregisterToolListener(tool);
    }
  }

  /**
   * Add a tool to the library
   */
  public addTool(tool: Tool): void {
    this.tools.push(tool);
    this.registerToolListener(tool); // Listen to tool changes
    StateManager.propertyChanged(this, 'tools');
  }

  /**
   * Remove a tool from the library
   */
  public removeTool(toolNumber: number | null): void {
    const index = this.tools.findIndex(tool => tool.toolNumber === toolNumber);
    if (index !== -1) {
      const tool = this.tools[index];
      this.unregisterToolListener(tool); // Stop listening to tool
      this.tools.splice(index, 1);
      StateManager.propertyChanged(this, 'tools');
    }
  }

  /**
   * Update a tool in the library
   */
  public updateTool(toolNumber: number | null, updatedTool: Tool): void {
    const index = this.tools.findIndex(tool => tool.toolNumber === toolNumber);
    if (index !== -1) {
      const oldTool = this.tools[index];
      this.unregisterToolListener(oldTool); // Stop listening to old tool
      this.tools[index] = updatedTool;
      this.registerToolListener(updatedTool); // Listen to new tool
      StateManager.propertyChanged(this, 'tools');
    }
  }

  /**
   * Get a tool by its tool number
   */
  public getToolByNumber(toolNumber: number | null): Tool | undefined {
    return this.tools.find(tool => tool.toolNumber === toolNumber);
  }

  /**
   * Update the entire tools array from loaded data
   * This preserves existing tool objects where possible by updating their properties
   * instead of replacing the entire array
   */
  public updateFromLoadedData(loadedTools: any[]): void {
    if (!Array.isArray(loadedTools)) return;

    // Unregister listeners from old tools
    this.unregisterSubObjectListeners();

    // Clear existing tools
    this.tools.length = 0;

    // Add loaded tools using DataUtilities for consistent deserialization
    for (const toolData of loadedTools) {
      const tool = new Tool();
      DataUtilities.loadStorageData(tool, toolData);
      this.tools.push(tool);
    }

    // Register listeners on new tools
    this.registerSubObjectListeners();

    StateManager.propertyChanged(this, 'tools');
  }

  /**
   * Get the singleton instance
   */
  public static get Instance(): ToolLibrary {
    if (!SingletonRegistry.ToolLibrary) {
      const instance = new ToolLibrary();
      // Setup auto-save after instance is fully created
      instance.setupAutoSave();
    }
    return SingletonRegistry.ToolLibrary!;
  }

  /**
   * Serialize to JSON - handle tools array explicitly
   */
  public toJSON(): any {
    const baseData = DataUtilities.getStorageData(this, ['tools']); // Exclude tools from auto-processing

    // Handle tools array explicitly with proper serialization
    return {
      ...baseData,
      tools: this.tools.map(tool => tool.toJSON())
    };
  }

  /**
   * Load from JSON - handle tools array explicitly using fromJSON
   */
  public fromJSON(data: any): void {
    // Use the helper method from SaveableDataBase to manage listeners
    this.loadWithListenerManagement(() => {
      // Load basic properties
      DataUtilities.loadStorageData(this, data, ['tools']); // Exclude tools from auto-processing

      // Handle tools array explicitly
      if (data.tools && Array.isArray(data.tools)) {
        this.tools = data.tools.map((toolData: any) => {
          const tool = new Tool();
          tool.fromJSON(toolData);
          return tool;
        });
      }
    });
  }
}
