import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import ClearIcon from '@mui/icons-material/Clear';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import PlayArrowIcon from '@mui/icons-material/PlayArrow';
import StopIcon from '@mui/icons-material/Stop';
import {
    Box,
    Button,
    ButtonGroup,
    Divider,
    IconButton,
    Paper,
    Tab,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Tabs,
    Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { Profiler } from '../../../utils/Profiler';

type SortBy = 'count' | 'total' | 'max';

export function ProfilerTab() {
    const colors = ConfigurationDataColors.Instance;
    const [activeTab, setActiveTab] = useState<'summary' | 'outline'>('summary');
    const [sortBy, setSortBy] = useState<SortBy>('total');
    const [isEnabled, setIsEnabled] = useState(Profiler.Instance.enabled);
    const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());

    const config = ConfigurationData.Instance;


    const handleToggle = () => {
        const newEnabled = !isEnabled;
        Profiler.Instance.enabled = newEnabled;
        setIsEnabled(newEnabled);
    };

    const handleClear = () => {
        Profiler.Instance.clear();
        setExpandedNodes(new Set());
    };

    const toggleNode = (nodePath: string) => {
        const newExpanded = new Set(expandedNodes);
        if (newExpanded.has(nodePath)) {
            newExpanded.delete(nodePath);
        } else {
            newExpanded.add(nodePath);
        }
        setExpandedNodes(newExpanded);
    };

    const getSortedSummaries = (): [string, any][] => {
        const summaries = Array.from(Profiler.Instance.flatSummaries.entries());

        switch (sortBy) {
            case 'count':
                return summaries.sort((a, b) => b[1].count - a[1].count);
            case 'total':
                return summaries.sort((a, b) => b[1].totalTime - a[1].totalTime);
            case 'max':
                return summaries.sort((a, b) => b[1].maxTime - a[1].maxTime);
            default:
                return summaries;
        }
    };

    const renderHierarchy = (nodes: Map<string, any>, depth: number = 0, parentPath: string = ''): React.ReactNode[] => {
        const sortedNodes = Array.from(nodes.entries()).sort((a, b) => {
            switch (sortBy) {
                case 'count':
                    return b[1].count - a[1].count;
                case 'total':
                    return b[1].totalTime - a[1].totalTime;
                case 'max':
                    return b[1].maxTime - a[1].maxTime;
                default:
                    return 0;
            }
        });

        const elements: React.ReactNode[] = [];

        for (const [name, node] of sortedNodes) {
            const nodePath = parentPath ? `${parentPath}/${name}` : name;
            const hasChildren = node.children && node.children.size > 0;
            const isExpanded = expandedNodes.has(nodePath);

            elements.push(
                <TableRow key={nodePath}>
                    <TableCell sx={{ pl: depth * 3 + 1 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            {hasChildren ? (
                                <IconButton
                                    size="small"
                                    onClick={() => toggleNode(nodePath)}
                                    sx={{ mr: 1, p: 0 }}
                                >
                                    {isExpanded ? <ExpandMoreIcon fontSize="small" /> : <ChevronRightIcon fontSize="small" />}
                                </IconButton>
                            ) : (
                                <Box sx={{ width: 32 }} />
                            )}
                            <Typography variant="body2">{name}</Typography>
                        </Box>
                    </TableCell>
                    <TableCell align="right">{node.count}</TableCell>
                    <TableCell align="right">{node.totalTime.toFixed(2)}ms</TableCell>
                    <TableCell align="right">{node.averageTime.toFixed(2)}ms</TableCell>
                    <TableCell align="right">{node.minTime.toFixed(2)}ms</TableCell>
                    <TableCell align="right">{node.maxTime.toFixed(2)}ms</TableCell>
                </TableRow>
            );

            if (hasChildren && isExpanded) {
                elements.push(...renderHierarchy(node.children, depth + 1, nodePath));
            }
        }

        return elements;
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', p: 2 }}>
            {/* Controls */}
            <Box sx={{ display: 'flex', gap: 2, mb: 2, alignItems: 'center' }}>
                <Button
                    variant="contained"
                    startIcon={isEnabled ? <StopIcon /> : <PlayArrowIcon />}
                    onClick={handleToggle}
                    sx={{
                        backgroundColor: isEnabled ? colors.primaryColor : 'grey.500',
                        '&:hover': {
                            backgroundColor: isEnabled ? colors.primaryColor : 'grey.600',
                            filter: 'brightness(0.9)'
                        }
                    }}
                >
                    {isEnabled ? 'Stop' : 'Start'}
                </Button>

                <Button
                    variant="outlined"
                    startIcon={<ClearIcon />}
                    onClick={handleClear}
                >
                    Clear
                </Button>

                <Divider orientation="vertical" flexItem />

                <Typography variant="body2" color="text.secondary">
                    Sort by:
                </Typography>

                <ButtonGroup size="small">
                    <Button
                        variant={sortBy === 'count' ? 'contained' : 'outlined'}
                        onClick={() => setSortBy('count')}
                    >
                        Count
                    </Button>
                    <Button
                        variant={sortBy === 'total' ? 'contained' : 'outlined'}
                        onClick={() => setSortBy('total')}
                    >
                        Total Time
                    </Button>
                    <Button
                        variant={sortBy === 'max' ? 'contained' : 'outlined'}
                        onClick={() => setSortBy('max')}
                    >
                        Max Time
                    </Button>
                </ButtonGroup>

                <Box sx={{ flex: 1 }} />

                <Typography variant="body2" color="text.secondary">
                    {Profiler.Instance.flatSummaries.size} operations tracked
                </Typography>
            </Box>

            {/* Tabs */}
            <Tabs value={activeTab} onChange={(_, value) => setActiveTab(value)} sx={{ mb: 2 }}>
                <Tab label="Summary (Flat View)" value="summary" />
                <Tab label="Outline (Hierarchy)" value="outline" />
            </Tabs>

            {/* Content */}
            <Box sx={{ flex: 1, overflow: 'auto' }}>
                {activeTab === 'summary' && (
                    <TableContainer component={Paper}>
                        <Table size="small" stickyHeader>
                            <TableHead>
                                <TableRow>
                                    <TableCell>Operation</TableCell>
                                    <TableCell align="right">Count</TableCell>
                                    <TableCell align="right">Total</TableCell>
                                    <TableCell align="right">Average</TableCell>
                                    <TableCell align="right">Min</TableCell>
                                    <TableCell align="right">Max</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {getSortedSummaries().map(([name, summary]) => (
                                    <TableRow key={name} hover>
                                        <TableCell>{name}</TableCell>
                                        <TableCell align="right">{summary.count}</TableCell>
                                        <TableCell align="right">{summary.totalTime.toFixed(2)}ms</TableCell>
                                        <TableCell align="right">{summary.averageTime.toFixed(2)}ms</TableCell>
                                        <TableCell align="right">{summary.minTime.toFixed(2)}ms</TableCell>
                                        <TableCell align="right">{summary.maxTime.toFixed(2)}ms</TableCell>
                                    </TableRow>
                                ))}
                                {getSortedSummaries().length === 0 && (
                                    <TableRow>
                                        <TableCell colSpan={6} align="center">
                                            <Typography variant="body2" color="text.secondary" sx={{ py: 2 }}>
                                                {isEnabled ? 'No data yet - perform some operations to see profiler data' : 'Start the profiler to begin tracking'}
                                            </Typography>
                                        </TableCell>
                                    </TableRow>
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>
                )}

                {activeTab === 'outline' && (
                    <TableContainer component={Paper}>
                        <Table size="small" stickyHeader>
                            <TableHead>
                                <TableRow>
                                    <TableCell>Operation</TableCell>
                                    <TableCell align="right">Count</TableCell>
                                    <TableCell align="right">Total</TableCell>
                                    <TableCell align="right">Average</TableCell>
                                    <TableCell align="right">Min</TableCell>
                                    <TableCell align="right">Max</TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {renderHierarchy(Profiler.Instance.hierarchyRoots)}
                                {Profiler.Instance.hierarchyRoots.size === 0 && (
                                    <TableRow>
                                        <TableCell colSpan={6} align="center">
                                            <Typography variant="body2" color="text.secondary" sx={{ py: 2 }}>
                                                {isEnabled ? 'No data yet - perform some operations to see profiler data' : 'Start the profiler to begin tracking'}
                                            </Typography>
                                        </TableCell>
                                    </TableRow>
                                )}
                            </TableBody>
                        </Table>
                    </TableContainer>
                )}
            </Box>
        </Box>
    );
}
