import { OrbitControls } from '@react-three/drei';
import { Canvas } from '@react-three/fiber';
import React, { Suspense } from 'react';
import { Tool as ToolData } from '../../data/Common/Tool';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { Tool as ToolComponent } from './components';

interface ToolViewerProps {
  tool: ToolData;
  width?: string | number;
  height?: string | number;
  showGrid?: boolean;
  enableControls?: boolean;
}

/**
 * Standalone 3D Tool Viewer Component
 * Displays a single tool in a contained 3D environment
 */
export const ToolViewer: React.FC<ToolViewerProps> = ({
  tool,
  width = 300,
  height = 300,
  showGrid = true,
  enableControls = true
}) => {
  const config = ConfigurationData.Instance;
  const colors = ConfigurationDataColors.Instance;

  // Calculate optimal camera position based on tool size
  // lengthBelowHolder is now negative, so use absolute value
  const toolSize = Math.max(Math.abs(tool.lengthBelowHolder), tool.cuttingDiameter);
  const cameraDistance = Math.max(toolSize * 3, 2); // Closer camera, minimum 2 units

  // //// console.log('ToolViewer camera setup:', {
  //   toolName: tool.toolName,
  //   toolSize,
  //   cameraDistance,
  //   lengthBelowHolder: tool.lengthBelowHolder,
  //   cuttingDiameter: tool.cuttingDiameter
  // });

  return (
    <div style={{ width, height, border: `1px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`, borderRadius: '4px' }}>
      <Canvas
        shadows
        dpr={[1, 2]}
        camera={{ position: [cameraDistance, cameraDistance, cameraDistance], fov: 50 }}
      >
        <Suspense fallback={null}>
          {/* Lighting */}
          <ambientLight intensity={1.6} />
          <directionalLight
            position={[10, 10, 5]}
            intensity={2.5}
            castShadow
            shadow-mapSize-width={1024}
            shadow-mapSize-height={1024}
          />
          <pointLight position={[-10, -10, -5]} intensity={2.0} />

          {/* Grid helper if enabled */}
          {showGrid && (
            <gridHelper
              args={[toolSize * 4, 20, colors.borderColor, colors.borderColor]}
              position={[0, tool.lengthBelowHolder / 2, 0]}
            />
          )}

          {/* Tool Component */}
          <ToolComponent
            tool={tool}
            position={[0, 0, 0]}
            visible={true}
          />

          {/* Camera Controls */}
          {enableControls && (
            <OrbitControls
              enablePan={true}
              enableZoom={true}
              enableRotate={true}
              maxPolarAngle={Math.PI}
              target={[0, tool.lengthBelowHolder / 4, 0]}
            />
          )}
        </Suspense>
      </Canvas>
    </div>
  );
};
