import CloseIcon from '@mui/icons-material/Close';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import {
    Box,
    Button,
    Card,
    Collapse,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    List,
    ListItem,
    Paper,
    Stack,
    Typography
} from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { PLCBlock } from '../data/PLCBlock';
import { PLCProgram } from '../data/PLCProgram';
import { PLCStage, StageType } from '../data/PLCStage';
import { PLCUtilities } from '../data/PLCUtilities';
import { BasePLCStatement } from '../statements/BasePLCStatement';

interface PLCMoveDialogProps {
    open: boolean;
    onClose: () => void;
    program: PLCProgram;
    movingItem: PLCBlock | BasePLCStatement;
    setMovingItem: (item: PLCBlock | BasePLCStatement) => void;
}

type TreeNode = {
    type: 'stage' | 'block' | 'statement';
    item: PLCStage | PLCBlock | BasePLCStatement;
    level: number;
    isExpanded?: boolean;
};

/**
 * Dialog for moving blocks and statements within the PLC program structure
 * Shows a tree view of the entire program with hover-to-insert functionality
 */
export function PLCMoveDialog({ open, onClose, program, movingItem, setMovingItem }: PLCMoveDialogProps) {
    const colors = ConfigurationDataColors.Instance;

    const [expandedStages, setExpandedStages] = useState<Set<string>>(new Set());
    const [expandedBlocks, setExpandedBlocks] = useState<Set<string>>(new Set());
    const [hoveredNode, setHoveredNode] = useState<TreeNode | null>(null);

    const movingItemType = (movingItem as any).getElementType ? (movingItem as any).getElementType() : 'unknown';
    const isMovingBlock = movingItemType === 'block';
    const isMovingStatement = movingItemType === 'statement';

    /**
     * Create a copy of the moving item and insert it below the original
     * Dialog stays open so user can continue moving items
     */
    const handleCreateCopy = () => {
        // Create deep copy using serialization
        const itemJson = movingItem.toJSON();
        let copiedItem: PLCBlock | BasePLCStatement;

        if (isMovingBlock) {
            copiedItem = new PLCBlock();
            copiedItem.fromJSON(itemJson);
        } else {
            // For statements, instantiate the correct type
            const StatementClass = (movingItem as any).constructor;
            copiedItem = new StatementClass();
            copiedItem.fromJSON(itemJson);
        }

        // Find the parent and insert the copy below the original
        const parent = movingItem.getParentElement();
        if (parent) {
            if (isMovingBlock) {
                // Find index of original block in parent's subBlocks
                const parentBlock = parent as PLCBlock;
                const originalIndex = parentBlock.subBlocks.findIndex((b: PLCBlock) => b === movingItem);
                if (originalIndex !== -1) {
                    // Insert copy right after original
                    parentBlock.subBlocks.splice(originalIndex + 1, 0, copiedItem as PLCBlock);
                    (copiedItem as PLCBlock).setParentElement(parentBlock);
                    StateManager.propertyChanged(parentBlock, 'subBlocks');
                }
            } else {
                // Find index of original statement in parent's actions
                const parentBlock = parent as PLCBlock;
                const originalIndex = parentBlock.actions.findIndex((s: BasePLCStatement) => s === movingItem);
                if (originalIndex !== -1) {
                    // Insert copy right after original
                    parentBlock.actions.splice(originalIndex + 1, 0, copiedItem as BasePLCStatement);
                    (copiedItem as BasePLCStatement).setParentElement(parentBlock);
                    StateManager.propertyChanged(parentBlock, 'actions');
                }
            }

            // Dialog stays open - user can continue moving if needed
        }
    };

    /**
     * Get left border color for a stage based on its type
     * Matches the color scheme used in PLCEditor
     */
    const getStageTypeColor = (stage: PLCStage): string => {
        if (!stage.enabled) {
            return colors.borderColor;
        }

        switch (stage.type) {
            case StageType.Initial:
                return colors.plcContinuousStageColor;
            case StageType.Main:
                return colors.plcOneTimeStageColor;
            case StageType.Final:
                return colors.plcDisabledStageColor;
            default:
                return colors.primaryColor;
        }
    };

    // Auto-expand tree to show current item when dialog opens
    useEffect(() => {
        if (!open) return;

        const newExpandedStages = new Set<string>();
        const newExpandedBlocks = new Set<string>();

        // Find parent elements to expand
        const parent = movingItem.getParentElement();
        if (parent) {
            const parentType = (parent as any).getElementType ? (parent as any).getElementType() : 'unknown';

            if (parentType === 'stage') {
                // Moving item is a top-level block, expand its stage
                newExpandedStages.add((parent as PLCStage).getElementId());
            } else if (parentType === 'block') {
                // Moving item is a statement or sub-block, expand its block and stage
                const block = parent as PLCBlock;
                newExpandedBlocks.add(block.getElementId());

                // Also expand the stage containing this block
                const grandparent = block.getParentElement();
                if (grandparent) {
                    const grandparentType = (grandparent as any).getElementType ? (grandparent as any).getElementType() : 'unknown';
                    if (grandparentType === 'stage') {
                        newExpandedStages.add((grandparent as PLCStage).getElementId());
                    }
                }
            }
        }

        setExpandedStages(newExpandedStages);
        setExpandedBlocks(newExpandedBlocks);
    }, [open, movingItem]);

    const toggleStageExpanded = (stageId: string) => {
        const newSet = new Set(expandedStages);
        if (newSet.has(stageId)) {
            newSet.delete(stageId);
        } else {
            newSet.add(stageId);
        }
        setExpandedStages(newSet);
    };

    const toggleBlockExpanded = (blockId: string) => {
        const newSet = new Set(expandedBlocks);
        if (newSet.has(blockId)) {
            newSet.delete(blockId);
        } else {
            newSet.add(blockId);
        }
        setExpandedBlocks(newSet);
    };

    const handleInsertClick = (node: TreeNode, position: 'above' | 'below') => {
        // Determine the target parent
        let targetParent: PLCBlock | PLCStage;
        let referenceItem: PLCBlock | BasePLCStatement | undefined;

        if (node.type === 'stage') {
            // Inserting relative to a stage - parent is the stage itself
            targetParent = node.item as PLCStage;
            referenceItem = undefined;
        } else if (node.type === 'block') {
            // Inserting relative to a block - need to find parent
            const block = node.item as PLCBlock;
            const parentElement = block.getParentElement();
            if (parentElement && (parentElement as any).getElementType() === 'stage') {
                targetParent = parentElement as PLCStage;
            } else if (parentElement && (parentElement as any).getElementType() === 'block') {
                targetParent = parentElement as PLCBlock;
            } else {
                console.error('Could not determine parent for block');
                return;
            }
            referenceItem = block;
        } else {
            // Inserting relative to a statement - parent is the containing block
            const statement = node.item as BasePLCStatement;
            const parentElement = statement.getParentElement();
            if (parentElement && (parentElement as any).getElementType() === 'block') {
                targetParent = parentElement as PLCBlock;
            } else {
                console.error('Could not determine parent for statement');
                return;
            }
            referenceItem = statement;
        }

        // Call utility function directly to perform the move
        PLCUtilities.moveItem(movingItem, targetParent, position, referenceItem, program.getProgramType());

        // Close the dialog after successful move
        onClose();
    };

    const expandToShowItem = (item: PLCBlock | BasePLCStatement) => {
        const newExpandedStages = new Set(expandedStages);
        const newExpandedBlocks = new Set(expandedBlocks);

        // Find parent elements to expand
        const parent = item.getParentElement();
        if (parent) {
            const parentType = (parent as any).getElementType ? (parent as any).getElementType() : 'unknown';

            if (parentType === 'stage') {
                // Item is a top-level block, expand its stage
                newExpandedStages.add((parent as PLCStage).getElementId());
            } else if (parentType === 'block') {
                // Item is a statement or sub-block, expand its block and stage
                const block = parent as PLCBlock;
                newExpandedBlocks.add(block.getElementId());

                // Also expand the stage containing this block
                const grandparent = block.getParentElement();
                if (grandparent) {
                    const grandparentType = (grandparent as any).getElementType ? (grandparent as any).getElementType() : 'unknown';
                    if (grandparentType === 'stage') {
                        newExpandedStages.add((grandparent as PLCStage).getElementId());
                    }
                }
            }
        }

        setExpandedStages(newExpandedStages);
        setExpandedBlocks(newExpandedBlocks);
    };

    const getMovingItemDescription = (): string => {
        if (isMovingBlock) {
            const block = movingItem as PLCBlock;
            return block.name || '(unnamed block)';
        } else {
            const statement = movingItem as BasePLCStatement;
            return statement.getShortDescription();
        }
    };

    const canInsertHere = (node: TreeNode, position: 'above' | 'below'): boolean => {
        // Can't insert at the same position as the moving item
        if (node.item === movingItem) {
            return false;
        }

        // If moving a block, prevent moving into its own descendants
        if (isMovingBlock) {
            const movingBlock = movingItem as PLCBlock;

            // Check if we're trying to position relative to our own child
            if (node.type === 'block' || node.type === 'statement') {
                let parent = node.item.getParentElement();
                while (parent) {
                    if (parent === movingBlock) {
                        return false; // Can't move a block relative to its own descendants
                    }
                    parent = (parent as any).getParentElement?.();
                }
            }
        }

        // If moving a block, can insert relative to:
        // - Other blocks (at same level - sibling blocks or into parent stage)
        // - Stages (for top-level blocks)
        // - Statements (sub-blocks can be positioned relative to statements since they share ordinal space)
        if (isMovingBlock) {
            // Check if this is a sub-block move (parent is another block)
            const movingBlockParent = movingItem.getParentElement();
            const isSubBlock = movingBlockParent && (movingBlockParent as any).getElementType?.() === 'block';

            if (isSubBlock) {
                // Sub-blocks can be positioned relative to blocks or statements in the same parent
                return node.type === 'block' || node.type === 'statement';
            } else {
                // Top-level blocks can only be positioned relative to other blocks or stages
                return node.type === 'block' || node.type === 'stage';
            }
        }

        // If moving a statement, can insert relative to statements or other sub-blocks (shared ordinal space)
        // BUT: statements cannot be siblings with top-level blocks (blocks in stages)
        // They can only be siblings with other statements or sub-blocks within the same parent block
        if (isMovingStatement) {
            // Statements can be positioned relative to other statements
            if (node.type === 'statement') {
                return true;
            }

            // Statements can be positioned relative to sub-blocks (blocks that are children of another block)
            if (node.type === 'block') {
                const targetBlock = node.item as PLCBlock;
                const targetBlockParent = targetBlock.getParentElement();
                // Only allow if the block's parent is also a block (i.e., it's a sub-block, not a top-level block)
                return !!(targetBlockParent && (targetBlockParent as any).getElementType?.() === 'block');
            }

            return false;
        }

        return false;
    };

    const canAddInside = (node: TreeNode): boolean => {
        // Can't add to the moving item itself
        if (node.item === movingItem) {
            return false;
        }

        // If moving a block, prevent adding into its own descendants
        if (isMovingBlock) {
            const movingBlock = movingItem as PLCBlock;

            // Check if target is the moving block itself or one of its descendants
            if (node.type === 'block') {
                const targetBlock = node.item as PLCBlock;
                if (targetBlock === movingBlock) {
                    return false;
                }

                // Check if target block is a descendant of moving block
                let parent = targetBlock.getParentElement();
                while (parent) {
                    if (parent === movingBlock) {
                        return false; // Can't add a block inside its own descendants
                    }
                    parent = (parent as any).getParentElement?.();
                }
            }
        }

        // Can add statements inside any block (expanded or not)
        if (isMovingStatement && node.type === 'block') {
            return true;
        }

        // Can add sub-blocks inside any block (expanded or not)
        if (isMovingBlock && node.type === 'block') {
            return true;
        }

        // Can add blocks inside any stage
        if (isMovingBlock && node.type === 'stage') {
            return true;
        }

        return false;
    };

    const handleAddInsideClick = (node: TreeNode) => {
        let targetParent: PLCBlock | PLCStage;

        if (node.type === 'stage') {
            targetParent = node.item as PLCStage;
        } else {
            targetParent = node.item as PLCBlock;
        }

        // Add to the end of the block/stage (no reference item)
        PLCUtilities.moveItem(movingItem, targetParent, 'below', undefined, program.getProgramType());

        // After moving, expand tree to show new location
        expandToShowItem(movingItem);
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
            <DialogTitle
                sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3,
                }}
            >
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                    <Typography variant="h6">
                        Move {isMovingBlock ? 'Block' : 'Statement'}
                    </Typography>
                    <Button
                        variant="contained"
                        size="small"
                        startIcon={<ContentCopyIcon />}
                        onClick={handleCreateCopy}
                        sx={{
                            backgroundColor: colors.lightTextColor,
                            color: colors.primaryColor,
                            '&:hover': {
                                backgroundColor: `${colors.lightTextColor}E6`,
                            },
                        }}
                    >
                        Create Copy
                    </Button>
                </Box>
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: `${colors.lightTextColor}1A`,
                        },
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ mt: 3 }}>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                        Hover over an item and click the arrow to move {isMovingBlock ? 'the block' : 'the statement'} above or below it. Use "Create Copy" to duplicate below the original.
                    </Typography>

                    <Typography variant="body2" sx={{ mb: 2, fontWeight: 'bold', fontFamily: 'monospace' }}>
                        Moving: {getMovingItemDescription()}
                    </Typography>

                    <Box sx={{ border: `1px solid ${colors.borderColor}`, borderRadius: 1, maxHeight: '400px', overflow: 'auto' }}>
                        <Stack spacing={2}>
                            {program.stages.map((stage, stageIndex) => {
                                const stageId = stage.getElementId();
                                const isStageExpanded = expandedStages.has(stageId);
                                const stageColor = getStageTypeColor(stage);
                                const isStageHovered = hoveredNode?.item === stage;

                                return (
                                    <Card
                                        key={stageIndex}
                                        sx={{
                                            borderLeft: `6px solid ${stageColor}`,
                                            opacity: stage.enabled ? 1 : 0.6,
                                        }}
                                    >
                                        {/* Stage Header */}
                                        <Box
                                            sx={{
                                                p: 2,
                                                backgroundColor: colors.lightTextColor,
                                                borderBottom: isStageExpanded ? `1px solid ${colors.borderColor}` : 'none',
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: 2,
                                                cursor: 'pointer',
                                                textDecoration: !stage.enabled ? 'line-through' : 'none',
                                            }}
                                            onClick={() => toggleStageExpanded(stageId)}
                                            onMouseEnter={() => setHoveredNode({ type: 'stage', item: stage, level: 0 })}
                                            onMouseLeave={() => setHoveredNode(null)}
                                        >
                                            <Typography variant="body2" sx={{ mr: 1 }}>📋</Typography>
                                            <Typography
                                                variant="body2"
                                                sx={{
                                                    flex: 1,
                                                    fontWeight: 600,
                                                    textDecoration: 'inherit',
                                                }}
                                            >
                                                {stage.name || 'Unnamed Stage'}
                                            </Typography>

                                            {/* Insert buttons for stage */}
                                            {isStageHovered && (canInsertHere({ type: 'stage', item: stage, level: 0 }, 'above') ||
                                                canInsertHere({ type: 'stage', item: stage, level: 0 }, 'below') ||
                                                canAddInside({ type: 'stage', item: stage, level: 0 })) && (
                                                    <Box sx={{ display: 'flex', gap: 1, ml: 'auto' }}>
                                                        {canInsertHere({ type: 'stage', item: stage, level: 0 }, 'above') && (
                                                            <Button size="small" variant="contained"
                                                                onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'stage', item: stage, level: 0 }, 'above'); }}
                                                                sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                Above
                                                            </Button>
                                                        )}
                                                        {canInsertHere({ type: 'stage', item: stage, level: 0 }, 'below') && (
                                                            <Button size="small" variant="contained"
                                                                onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'stage', item: stage, level: 0 }, 'below'); }}
                                                                sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                Below
                                                            </Button>
                                                        )}
                                                        {canAddInside({ type: 'stage', item: stage, level: 0 }) && (
                                                            <Button size="small" variant="contained"
                                                                onClick={(e) => { e.stopPropagation(); handleAddInsideClick({ type: 'stage', item: stage, level: 0 }); }}
                                                                sx={{ minWidth: '100px', backgroundColor: colors.infoColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                Add Inside
                                                            </Button>
                                                        )}
                                                    </Box>
                                                )}
                                        </Box>

                                        {/* Stage Content - Collapsible */}
                                        <Collapse in={isStageExpanded} timeout="auto" unmountOnExit>
                                            <Box sx={{ p: 2, backgroundColor: colors.lightTextColor }}>
                                                <Stack spacing={1.5}>
                                                    {stage.getDefinedBlocks().map((block, blockIndex) => {
                                                        const blockId = block.getElementId();
                                                        const isBlockExpanded = expandedBlocks.has(blockId);
                                                        const isBlockHovered = hoveredNode?.item === block;

                                                        return (
                                                            <Paper
                                                                key={blockIndex}
                                                                variant="outlined"
                                                                sx={{
                                                                    borderLeft: block === movingItem ? `6px solid ${colors.primaryColor}` :
                                                                        `3px solid ${block.enabled ? colors.secondaryColor : colors.borderColor}`,
                                                                    opacity: block.enabled ? 1 : 0.5,
                                                                }}
                                                            >
                                                                {/* Block Header */}
                                                                <Box
                                                                    sx={{
                                                                        p: 1.5,
                                                                        backgroundColor: block === movingItem ? `${colors.warningColor}33` : colors.lightBackgroundColor,
                                                                        display: 'flex',
                                                                        alignItems: 'center',
                                                                        gap: 1,
                                                                        cursor: 'pointer',
                                                                        textDecoration: !block.enabled ? 'line-through' : 'none',
                                                                    }}
                                                                    onClick={(e) => { e.stopPropagation(); toggleBlockExpanded(blockId); }}
                                                                    onMouseEnter={() => setHoveredNode({ type: 'block', item: block, level: 1 })}
                                                                    onMouseLeave={() => setHoveredNode(null)}
                                                                >
                                                                    <Typography variant="body2" sx={{ mr: 1 }}>📦</Typography>
                                                                    <Typography
                                                                        variant="body2"
                                                                        sx={{
                                                                            flex: 1,
                                                                            fontWeight: 500,
                                                                            textDecoration: 'inherit',
                                                                        }}
                                                                    >
                                                                        {block.name || 'Unnamed Block'}
                                                                    </Typography>

                                                                    {/* Insert buttons for block */}
                                                                    {isBlockHovered && (canInsertHere({ type: 'block', item: block, level: 1 }, 'above') ||
                                                                        canInsertHere({ type: 'block', item: block, level: 1 }, 'below') ||
                                                                        canAddInside({ type: 'block', item: block, level: 1 })) && (
                                                                            <Box sx={{ display: 'flex', gap: 1, ml: 'auto' }}>
                                                                                {canInsertHere({ type: 'block', item: block, level: 1 }, 'above') && (
                                                                                    <Button size="small" variant="contained"
                                                                                        onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'block', item: block, level: 1 }, 'above'); }}
                                                                                        sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                        Above
                                                                                    </Button>
                                                                                )}
                                                                                {canInsertHere({ type: 'block', item: block, level: 1 }, 'below') && (
                                                                                    <Button size="small" variant="contained"
                                                                                        onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'block', item: block, level: 1 }, 'below'); }}
                                                                                        sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                        Below
                                                                                    </Button>
                                                                                )}
                                                                                {canAddInside({ type: 'block', item: block, level: 1 }) && (
                                                                                    <Button size="small" variant="contained"
                                                                                        onClick={(e) => { e.stopPropagation(); handleAddInsideClick({ type: 'block', item: block, level: 1 }); }}
                                                                                        sx={{ minWidth: '100px', backgroundColor: colors.infoColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                        Add Inside
                                                                                    </Button>
                                                                                )}
                                                                            </Box>
                                                                        )}
                                                                </Box>

                                                                {/* Block Content - Collapsible */}
                                                                <Collapse in={isBlockExpanded} timeout="auto" unmountOnExit>
                                                                    <Box sx={{ p: 1.5, pt: 1 }}>
                                                                        <Stack spacing={1}>
                                                                            {block.getItemsSorted().map((item, itemIndex) => {
                                                                                const itemType = (item as any).getElementType?.();
                                                                                const isSubBlock = itemType === 'block';

                                                                                if (isSubBlock) {
                                                                                    // Render sub-block (nested block)
                                                                                    const subBlock = item as PLCBlock;
                                                                                    const subBlockId = subBlock.getElementId();
                                                                                    const isSubBlockExpanded = expandedBlocks.has(subBlockId);
                                                                                    const isSubBlockHovered = hoveredNode?.item === subBlock;

                                                                                    return (
                                                                                        <Paper
                                                                                            key={itemIndex}
                                                                                            variant="outlined"
                                                                                            sx={{
                                                                                                borderLeft: subBlock === movingItem ? `6px solid ${colors.primaryColor}` :
                                                                                                    `3px solid ${subBlock.enabled ? colors.secondaryColor : colors.borderColor}`,
                                                                                                opacity: subBlock.enabled ? 1 : 0.5,
                                                                                                ml: 2, // Indent sub-blocks
                                                                                            }}
                                                                                        >
                                                                                            {/* Sub-Block Header */}
                                                                                            <Box
                                                                                                sx={{
                                                                                                    p: 1.5,
                                                                                                    backgroundColor: subBlock === movingItem ? `${colors.warningColor}33` : colors.lightBackgroundColor,
                                                                                                    display: 'flex',
                                                                                                    alignItems: 'center',
                                                                                                    gap: 1,
                                                                                                    cursor: 'pointer',
                                                                                                    textDecoration: !subBlock.enabled ? 'line-through' : 'none',
                                                                                                }}
                                                                                                onClick={(e) => { e.stopPropagation(); toggleBlockExpanded(subBlockId); }}
                                                                                                onMouseEnter={() => setHoveredNode({ type: 'block', item: subBlock, level: 2 })}
                                                                                                onMouseLeave={() => setHoveredNode(null)}
                                                                                            >
                                                                                                <Typography variant="body2" sx={{ mr: 1 }}>📦</Typography>
                                                                                                <Typography
                                                                                                    variant="body2"
                                                                                                    sx={{
                                                                                                        flex: 1,
                                                                                                        fontWeight: 500,
                                                                                                        textDecoration: 'inherit',
                                                                                                    }}
                                                                                                >
                                                                                                    {subBlock.name || 'Unnamed Block'}
                                                                                                </Typography>

                                                                                                {/* Insert buttons for sub-block */}
                                                                                                {isSubBlockHovered && (canInsertHere({ type: 'block', item: subBlock, level: 2 }, 'above') ||
                                                                                                    canInsertHere({ type: 'block', item: subBlock, level: 2 }, 'below') ||
                                                                                                    canAddInside({ type: 'block', item: subBlock, level: 2 })) && (
                                                                                                        <Box sx={{ display: 'flex', gap: 1, ml: 'auto' }}>
                                                                                                            {canInsertHere({ type: 'block', item: subBlock, level: 2 }, 'above') && (
                                                                                                                <Button size="small" variant="contained"
                                                                                                                    onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'block', item: subBlock, level: 2 }, 'above'); }}
                                                                                                                    sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                                                    Above
                                                                                                                </Button>
                                                                                                            )}
                                                                                                            {canInsertHere({ type: 'block', item: subBlock, level: 2 }, 'below') && (
                                                                                                                <Button size="small" variant="contained"
                                                                                                                    onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'block', item: subBlock, level: 2 }, 'below'); }}
                                                                                                                    sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                                                    Below
                                                                                                                </Button>
                                                                                                            )}
                                                                                                            {canAddInside({ type: 'block', item: subBlock, level: 2 }) && (
                                                                                                                <Button size="small" variant="contained"
                                                                                                                    onClick={(e) => { e.stopPropagation(); handleAddInsideClick({ type: 'block', item: subBlock, level: 2 }); }}
                                                                                                                    sx={{ minWidth: '100px', backgroundColor: colors.infoColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                                                    Add Inside
                                                                                                                </Button>
                                                                                                            )}
                                                                                                        </Box>
                                                                                                    )}
                                                                                            </Box>

                                                                                            {/* Sub-Block Content - Collapsible */}
                                                                                            <Collapse in={isSubBlockExpanded} timeout="auto" unmountOnExit>
                                                                                                <Box sx={{ p: 1.5, pt: 1 }}>
                                                                                                    <List dense sx={{ py: 0 }}>
                                                                                                        {subBlock.getItemsSorted().map((subItem, subItemIndex) => {
                                                                                                            const subItemType = (subItem as any).getElementType?.();
                                                                                                            const isStatement = subItemType !== 'block';
                                                                                                            const isSubItemHovered = hoveredNode?.item === subItem;

                                                                                                            if (isStatement) {
                                                                                                                const statement = subItem as BasePLCStatement;
                                                                                                                return (
                                                                                                                    <ListItem
                                                                                                                        key={subItemIndex}
                                                                                                                        sx={{
                                                                                                                            border: statement === movingItem ? `4px solid ${colors.primaryColor}` : `1px solid ${colors.borderColor}`,
                                                                                                                            borderRadius: 1,
                                                                                                                            mb: 0.5,
                                                                                                                            backgroundColor: statement === movingItem ? `${colors.warningColor}33` : colors.lightTextColor,
                                                                                                                            flexDirection: 'column',
                                                                                                                            alignItems: 'stretch',
                                                                                                                        }}
                                                                                                                        onMouseEnter={() => setHoveredNode({ type: 'statement', item: statement, level: 3 })}
                                                                                                                        onMouseLeave={() => setHoveredNode(null)}
                                                                                                                    >
                                                                                                                        <Box sx={{ display: 'flex', width: '100%', alignItems: 'center' }}>
                                                                                                                            <Typography variant="body2" sx={{ mr: 1 }}>•</Typography>
                                                                                                                            <Typography variant="body2" sx={{ flex: 1, fontFamily: 'monospace', fontSize: '0.85rem' }}>
                                                                                                                                {statement.getShortDescription()}
                                                                                                                            </Typography>

                                                                                                                            {/* Insert buttons for statement in sub-block */}
                                                                                                                            {isSubItemHovered && (canInsertHere({ type: 'statement', item: statement, level: 3 }, 'above') ||
                                                                                                                                canInsertHere({ type: 'statement', item: statement, level: 3 }, 'below')) && (
                                                                                                                                    <Box sx={{ display: 'flex', gap: 1, ml: 'auto' }}>
                                                                                                                                        {canInsertHere({ type: 'statement', item: statement, level: 3 }, 'above') && (
                                                                                                                                            <Button size="small" variant="contained"
                                                                                                                                                onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'statement', item: statement, level: 3 }, 'above'); }}
                                                                                                                                                sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                                                                                Above
                                                                                                                                            </Button>
                                                                                                                                        )}
                                                                                                                                        {canInsertHere({ type: 'statement', item: statement, level: 3 }, 'below') && (
                                                                                                                                            <Button size="small" variant="contained"
                                                                                                                                                onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'statement', item: statement, level: 3 }, 'below'); }}
                                                                                                                                                sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                                                                                Below
                                                                                                                                            </Button>
                                                                                                                                        )}
                                                                                                                                    </Box>
                                                                                                                                )}
                                                                                                                        </Box>
                                                                                                                    </ListItem>
                                                                                                                );
                                                                                                            }
                                                                                                            return null;
                                                                                                        })}
                                                                                                    </List>
                                                                                                </Box>
                                                                                            </Collapse>
                                                                                        </Paper>
                                                                                    );
                                                                                } else {
                                                                                    // Render statement
                                                                                    const statement = item as BasePLCStatement;
                                                                                    const isItemHovered = hoveredNode?.item === statement;

                                                                                    return (
                                                                                        <ListItem
                                                                                            key={itemIndex}
                                                                                            sx={{
                                                                                                border: statement === movingItem ? `4px solid ${colors.primaryColor}` : `1px solid ${colors.borderColor}`,
                                                                                                borderRadius: 1,
                                                                                                backgroundColor: statement === movingItem ? `${colors.warningColor}33` : colors.lightTextColor,
                                                                                                flexDirection: 'column',
                                                                                                alignItems: 'stretch',
                                                                                            }}
                                                                                            onMouseEnter={() => setHoveredNode({ type: 'statement', item: statement, level: 2 })}
                                                                                            onMouseLeave={() => setHoveredNode(null)}
                                                                                        >
                                                                                            <Box sx={{ display: 'flex', width: '100%', alignItems: 'center' }}>
                                                                                                <Typography variant="body2" sx={{ mr: 1 }}>•</Typography>
                                                                                                <Typography variant="body2" sx={{ flex: 1, fontFamily: 'monospace', fontSize: '0.85rem' }}>
                                                                                                    {statement.getShortDescription()}
                                                                                                </Typography>

                                                                                                {/* Insert buttons for statement */}
                                                                                                {isItemHovered && (canInsertHere({ type: 'statement', item: statement, level: 2 }, 'above') ||
                                                                                                    canInsertHere({ type: 'statement', item: statement, level: 2 }, 'below')) && (
                                                                                                        <Box sx={{ display: 'flex', gap: 1, ml: 'auto' }}>
                                                                                                            {canInsertHere({ type: 'statement', item: statement, level: 2 }, 'above') && (
                                                                                                                <Button size="small" variant="contained"
                                                                                                                    onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'statement', item: statement, level: 2 }, 'above'); }}
                                                                                                                    sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                                                    Above
                                                                                                                </Button>
                                                                                                            )}
                                                                                                            {canInsertHere({ type: 'statement', item: statement, level: 2 }, 'below') && (
                                                                                                                <Button size="small" variant="contained"
                                                                                                                    onClick={(e) => { e.stopPropagation(); handleInsertClick({ type: 'statement', item: statement, level: 2 }, 'below'); }}
                                                                                                                    sx={{ minWidth: '80px', backgroundColor: colors.successColor, '&:hover': { backgroundColor: colors.primaryColor } }}>
                                                                                                                    Below
                                                                                                                </Button>
                                                                                                            )}
                                                                                                        </Box>
                                                                                                    )}
                                                                                            </Box>
                                                                                        </ListItem>
                                                                                    );
                                                                                }
                                                                            })}
                                                                        </Stack>
                                                                    </Box>
                                                                </Collapse>
                                                            </Paper>
                                                        );
                                                    })}
                                                </Stack>
                                            </Box>
                                        </Collapse>
                                    </Card>
                                );
                            })}
                        </Stack>
                    </Box>
                </Box>
            </DialogContent>

            <DialogActions
                sx={{
                    p: 2,
                    gap: 1,
                    justifyContent: 'flex-end',
                    borderTop: `1px solid ${colors.borderColor}`,
                }}
            >
                <Button onClick={onClose} variant="outlined">
                    Close
                </Button>
            </DialogActions>
        </Dialog>
    );
}
