import { Cancel as EmergencyStopIcon } from '@mui/icons-material';
import { Alert, Box, Button, CircularProgress, Typography } from '@mui/material';
import React, { useEffect, useState } from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MeasurementTarget, TouchPlateType } from '../../../../machine/ICNCSystem';
import { MachineInterfaceManager } from '../../../../utils/MachineInterfaceManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ToolMeasurementMethod, ToolMeasurementWizard } from '../ToolMeasurementWizard';

/**
 * Step to trigger the measurement with touchplate
 */
export class TriggerMeasureStep extends WizardStep {
    private tool: Tool;
    private method: ToolMeasurementMethod;

    constructor(wizard: ToolMeasurementWizard, tool: Tool, previousStep: WizardStep | null, method: ToolMeasurementMethod) {
        super(wizard, previousStep);
        this.tool = tool;
        this.method = method;
    }

    getTitle(): string {
        return 'Measure Tool';
    }

    nextStep(): WizardStep | null {
        // Final step - wizard will close after measurement
        return null;
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return <TriggerMeasureStepComponent step={this} />;
    }
}

interface TriggerMeasureStepComponentProps {
    step: TriggerMeasureStep;
}

function TriggerMeasureStepComponent({ step }: TriggerMeasureStepComponentProps) {
    const wizard = step.wizard as ToolMeasurementWizard;
    const colors = ConfigurationDataColors.Instance;
    const [isStarted, setIsStarted] = useState(false);

    useEffect(() => {
        if (!isStarted) {
            setIsStarted(true);
            handleMeasure();
        }
    }, [isStarted]);

    const handleMeasure = async () => {
        try {
            const machineInterface = MachineInterfaceManager.Instance.getMachineInterface();
            const method = (step as any).method as ToolMeasurementMethod;

            if (method === ToolMeasurementMethod.AutoFixedTouchPlate) {
                // Call measureCurrentTool which will use the fixed touch plate automatically
                await machineInterface.system.measureCurrentTool({
                    onComplete: async () => {
                        await wizard.callback?.onComplete?.();
                    },
                    onError: async (error: string | Error) => {
                        console.error('Tool measurement error:', error);
                        await wizard.callback?.onCancel?.();
                    }
                });
            } else {
                // Manual methods - map to MeasurementTarget for reference point
                let measurementTarget: MeasurementTarget;

                switch (method) {
                    case ToolMeasurementMethod.ManualFixedPoint:
                        measurementTarget = MeasurementTarget.FixedPosition;
                        break;
                    case ToolMeasurementMethod.ManualSpoilboard:
                        measurementTarget = MeasurementTarget.Spoilboard;
                        break;
                    case ToolMeasurementMethod.ManualMachineBed:
                        measurementTarget = MeasurementTarget.MachineBed;
                        break;
                    default:
                        measurementTarget = MeasurementTarget.FixedPosition;
                }

                // Call autoMeasureTool with Movable touch plate and measurement target
                await machineInterface.system.autoMeasureTool(TouchPlateType.Movable, measurementTarget, {
                    onComplete: async () => {
                        await wizard.callback?.onComplete?.();
                    },
                    onError: async (error: string | Error) => {
                        console.error('Tool measurement error:', error);
                        await wizard.callback?.onCancel?.();
                    }
                });
            }
        } catch (error) {
            console.error('Error measuring tool:', error);
            await wizard.callback?.onCancel?.();
        }
    };

    const handleEmergencyStop = async () => {
        try {
            const machineInterface = MachineInterfaceManager.Instance.getMachineInterface();
            await machineInterface.system.EStop();
            await wizard.callback?.onCancel?.();
        } catch (error) {
            console.error('Error triggering emergency stop:', error);
        }
    };

    return (
        <Box sx={{ p: 3, display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Alert severity="warning" sx={{ mb: 2 }}>
                <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                    ⚠️ MEASUREMENT IN PROGRESS
                </Typography>
                <Typography variant="body2">
                    The machine is automatically measuring the tool. Do not interfere with the process.
                </Typography>
            </Alert>

            <Box sx={{
                flex: 1,
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 3
            }}>
                <CircularProgress size={80} thickness={4} sx={{ color: colors.primaryColor }} />
                <Typography variant="h6" color="text.secondary">
                    Measuring tool with touchplate...
                </Typography>
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 3 }}>
                <Button
                    variant="contained"
                    color="error"
                    size="large"
                    startIcon={<EmergencyStopIcon sx={{ fontSize: '2rem !important' }} />}
                    onClick={handleEmergencyStop}
                    sx={{
                        fontWeight: 'bold',
                        fontSize: '1.25rem',
                        py: 2,
                        px: 6,
                        minHeight: 60
                    }}
                >
                    EMERGENCY STOP
                </Button>
            </Box>
        </Box>
    );
}
