import {
    Box,
    CircularProgress,
    Paper,
    Typography
} from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../data/ConfigurationDataColors';
import { SignalRStateData } from '../data/SignalRStateData';
import { Machine } from '../machine/Machine';
import { LogCategory, Logger } from '../utils/Logger';

interface ConnectionSplashScreenProps {
    onConnected: () => void;
}

/**
 * ConnectionSplashScreen displays while waiting for server connection
 * Continuously polls IsConnectedToServer until connection is established
 */
export function ConnectionSplashScreen({ onConnected }: ConnectionSplashScreenProps) {
    const colors = ConfigurationDataColors.Instance;
    const [attempts, setAttempts] = React.useState(0);
    const [apiStatus, setApiStatus] = React.useState<string>('Checking...');
    const [signalRStatus, setSignalRStatus] = React.useState<string>('Checking...');
    const [errorMessage, setErrorMessage] = React.useState<string>('');
    const [debugInfo, setDebugInfo] = React.useState<string>('');
    const checkIntervalRef = React.useRef<NodeJS.Timeout | null>(null);

    React.useEffect(() => {
        let isMounted = true;

        const checkConnection = async () => {
            try {
                setAttempts(prev => {
                    const attemptNumber = prev + 1;
                    Logger.Instance.log(LogCategory.System, `Connection check attempt #${attemptNumber}`);
                    return attemptNumber;
                });

                const machine = Machine.getInstance();

                // Try to get detailed status by checking the connection
                let signalRConnected = false;
                let isConnected = false;

                try {
                    isConnected = await machine.system.IsConnectedToServer();

                    setDebugInfo(`isConnected=${JSON.stringify(isConnected)} (type: ${typeof isConnected}), isMounted=${isMounted}`);

                    // If we got here without error, we can check SignalR separately
                    // If we got here without error, we can check SignalR separately
                    const signalRData = SignalRStateData.Instance;
                    signalRConnected = signalRData.isConnected;

                    // Infer API status - if overall connected, API must be working
                    // If not connected but no error, check individual components
                    if (isConnected) {
                        signalRConnected = true;
                        setApiStatus('✓ Connected');
                        setSignalRStatus('✓ Connected');
                    } else {
                        // Not fully connected - figure out which part failed
                        setApiStatus('✓ API Responding');
                        setSignalRStatus(signalRConnected ? '✓ Connected' : `✗ Not Connected (State: ${signalRData.connectionState})`);
                    }
                } catch (innerError) {
                    // If error occurs, it's likely API related
                    setApiStatus(`✗ Error: ${(innerError as any).message || 'API call failed'}`);
                    setErrorMessage(`Connection Error: ${(innerError as any).message || 'Unknown error'}`);

                    // Still try to check SignalR
                    try {
                        const signalRData = SignalRStateData.Instance;
                        signalRConnected = signalRData.isConnected;
                        setSignalRStatus(signalRConnected ? '✓ Connected' : `✗ Not Connected (State: ${signalRData.connectionState})`);
                    } catch (signalRError) {
                        setSignalRStatus('✗ Unable to check');
                    }
                }


                if (isConnected && isMounted) {
                    Logger.Instance.log(LogCategory.System, 'Server connection established');
                    // Clear interval and notify parent
                    if (checkIntervalRef.current) {
                        clearInterval(checkIntervalRef.current);
                        checkIntervalRef.current = null;
                    }
                    onConnected();
                }
            } catch (error) {
                console.error('[ConnectionSplashScreen] ❌ Error during connection check:', error);
                Logger.Instance.logError(LogCategory.System, 'Error checking server connection:', error);
            }
        };

        // Initial check
        checkConnection();

        // Set up polling interval (check every 2 seconds)
        checkIntervalRef.current = setInterval(checkConnection, 2000);

        // Cleanup
        return () => {
            isMounted = false;
            if (checkIntervalRef.current) {
                clearInterval(checkIntervalRef.current);
                checkIntervalRef.current = null;
            }
        };
    }, [onConnected]); // Removed attempts from dependency array

    return (
        <Box
            sx={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                height: '100vh',
                backgroundColor: colors.lightBackgroundColor,
                padding: 3
            }}
        >
            <Paper
                elevation={8}
                sx={{
                    padding: 6,
                    borderRadius: 4,
                    textAlign: 'center',
                    maxWidth: 500,
                    width: '100%',
                    backgroundColor: colors.darkBackgroundColor,
                    color: colors.lightTextColor
                }}
            >
                {/* App Title */}
                <Typography
                    variant="h3"
                    component="h1"
                    gutterBottom
                    sx={{
                        color: colors.primaryColor,
                        fontWeight: 'bold',
                        marginBottom: 3
                    }}
                >
                    HavenCNC
                </Typography>

                {/* Loading Spinner */}
                <CircularProgress
                    size={60}
                    sx={{
                        color: colors.primaryColor,
                        marginBottom: 3
                    }}
                />

                {/* Connection Status Details */}
                <Box
                    sx={{
                        backgroundColor: `${colors.lightTextColor}0D`,
                        borderRadius: 2,
                        padding: 2,
                        marginTop: 3,
                        textAlign: 'left'
                    }}
                >
                    <Typography
                        variant="body2"
                        sx={{
                            color: colors.lightTextColor,
                            marginBottom: 1,
                            fontWeight: 'bold'
                        }}
                    >
                        Connection Status:
                    </Typography>

                    <Typography
                        variant="body2"
                        sx={{
                            color: apiStatus.includes('✓') ? colors.successColor : colors.errorColor,
                            marginBottom: 0.5,
                            fontFamily: 'monospace'
                        }}
                    >
                        API: {apiStatus}
                    </Typography>

                    <Typography
                        variant="body2"
                        sx={{
                            color: signalRStatus.includes('✓') ? colors.successColor : colors.errorColor,
                            fontFamily: 'monospace'
                        }}
                    >
                        SignalR: {signalRStatus}
                    </Typography>

                    {errorMessage && (
                        <Typography
                            variant="caption"
                            sx={{
                                color: colors.errorColor,
                                marginTop: 1,
                                display: 'block',
                                fontStyle: 'italic'
                            }}
                        >
                            {errorMessage}
                        </Typography>
                    )}

                    {debugInfo && (
                        <Typography
                            variant="caption"
                            sx={{
                                color: colors.warningColor,
                                marginTop: 1,
                                display: 'block',
                                fontFamily: 'monospace',
                                fontSize: '0.7rem'
                            }}
                        >
                            DEBUG: {debugInfo}
                        </Typography>
                    )}
                </Box>

                {/* Attempt Counter */}
                <Typography
                    variant="caption"
                    sx={{
                        color: colors.mutedTextColor,
                        fontStyle: 'italic',
                        marginTop: 2,
                        display: 'block'
                    }}
                >
                    Connection attempts: {attempts}
                </Typography>
            </Paper>

            {/* Version Info */}
            <Typography
                variant="caption"
                sx={{
                    color: colors.mutedTextColor,
                    marginTop: 3,
                    textAlign: 'center'
                }}
            >
                CNC Machine Control Interface
                <br />
                Waiting for server connection...
            </Typography>
        </Box>
    );
}
