import { Workspaces as MachineBedIcon, Layers as MaterialIcon, ViewInAr as SpoilboardIcon, CropDin as WorkZeroIcon } from '@mui/icons-material';
import { Box, Card, CardActionArea, CardContent, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { TouchOffTarget } from '../../../../machine/ICNCSystem';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { TouchOffWizard } from '../TouchOffWizard';
import { SelectMethodStep } from './SelectMethodStep';

/**
 * Step to select which surface to touch off to
 */
export class SelectTargetStep extends WizardStep {

    getTitle(): string {
        return 'Select Touch Off Target';
    }

    nextStep(): WizardStep | null {
        // Skip this step if target was already specified when wizard was launched
        const wizard = this.wizard as TouchOffWizard;
        if (wizard.state.target !== undefined) {
            return new SelectMethodStep(wizard, this);
        }
        return new SelectMethodStep(this.wizard as TouchOffWizard, this);
    }

    backStep(): WizardStep | null {
        return null; // First step, no back
    }

    render(): React.ReactNode {
        // Skip this step if target was already specified when wizard was launched
        const wizard = this.wizard as TouchOffWizard;
        if (wizard.state.target !== undefined) {
            // Auto-advance to next step
            setTimeout(() => wizard.advanceToNextStep(), 0);
            return null;
        }

        return (
            <ObserveState
                key="select-target-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <SelectTargetStepComponent step={this} />}
            />
        );
    }
}

interface SelectTargetStepComponentProps {
    step: SelectTargetStep;
}

function SelectTargetStepComponent({ step }: SelectTargetStepComponentProps) {
    const wizard = step.wizard as TouchOffWizard;
    const colors = ConfigurationDataColors.Instance;

    const handleSelectTarget = (target: TouchOffTarget) => {
        wizard.state = {
            ...wizard.state,
            target
        };
        StateManager.propertyChanged(wizard, 'state');
        wizard.advanceToNextStep();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column', gap: 3, p: 3 }}>
            {/* Header */}
            <Box>
                <Typography variant="h5" gutterBottom sx={{ color: colors.primaryColor, fontWeight: 'bold' }}>
                    Select Touch-Off Target
                </Typography>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Choose which surface you want to set as Z zero.
                </Typography>
            </Box>

            {/* Target selection cards - 2x2 grid */}
            <Box sx={{
                flex: 1,
                display: 'grid',
                gridTemplateColumns: 'repeat(2, 1fr)',
                gridTemplateRows: 'repeat(2, 1fr)',
                gap: 3,
                minHeight: 0
            }}>
                {/* Machine Bed Card */}
                <Card
                    sx={{
                        border: `1px solid ${colors.borderColor}`,
                        transition: 'all 0.2s',
                        '&:hover': {
                            border: `2px solid ${colors.primaryColor}`,
                            transform: 'translateY(-4px)',
                            boxShadow: 3
                        }
                    }}
                >
                    <CardActionArea
                        onClick={() => handleSelectTarget(TouchOffTarget.MachineBed)}
                        sx={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'stretch', justifyContent: 'flex-start' }}
                    >
                        <CardContent sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2, p: 3 }}>
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                                <MachineBedIcon sx={{ fontSize: 64, color: colors.primaryColor }} />
                                <Typography variant="h5" sx={{ fontWeight: 'bold', textAlign: 'center' }}>
                                    Machine Bed
                                </Typography>
                            </Box>
                            <Typography variant="body2" sx={{ color: colors.darkTextColor, textAlign: 'center', mt: 2 }}>
                                Set Z zero to the machine bed (table) surface.
                            </Typography>
                            <Box sx={{ mt: 'auto', pt: 2 }}>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold', display: 'block', textAlign: 'center' }}>
                                    Absolute Reference
                                </Typography>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, display: 'block', textAlign: 'center' }}>
                                    Use for machine coordinate work
                                </Typography>
                            </Box>
                        </CardContent>
                    </CardActionArea>
                </Card>

                {/* Spoilboard Card */}
                <Card
                    sx={{
                        border: `1px solid ${colors.borderColor}`,
                        transition: 'all 0.2s',
                        '&:hover': {
                            border: `2px solid ${colors.primaryColor}`,
                            transform: 'translateY(-4px)',
                            boxShadow: 3
                        }
                    }}
                >
                    <CardActionArea
                        onClick={() => handleSelectTarget(TouchOffTarget.SpoilBoard)}
                        sx={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'stretch', justifyContent: 'flex-start' }}
                    >
                        <CardContent sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2, p: 3 }}>
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                                <SpoilboardIcon sx={{ fontSize: 64, color: colors.primaryColor }} />
                                <Typography variant="h5" sx={{ fontWeight: 'bold', textAlign: 'center' }}>
                                    Spoilboard
                                </Typography>
                            </Box>
                            <Typography variant="body2" sx={{ color: colors.darkTextColor, textAlign: 'center', mt: 2 }}>
                                Set Z zero to the spoilboard surface.
                            </Typography>
                            <Box sx={{ mt: 'auto', pt: 2 }}>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold', display: 'block', textAlign: 'center' }}>
                                    Reference Point
                                </Typography>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, display: 'block', textAlign: 'center' }}>
                                    Use for consistent fixture setup
                                </Typography>
                            </Box>
                        </CardContent>
                    </CardActionArea>
                </Card>

                {/* Material Top Card */}
                <Card
                    sx={{
                        border: `1px solid ${colors.borderColor}`,
                        transition: 'all 0.2s',
                        '&:hover': {
                            border: `2px solid ${colors.primaryColor}`,
                            transform: 'translateY(-4px)',
                            boxShadow: 3
                        }
                    }}
                >
                    <CardActionArea
                        onClick={() => handleSelectTarget(TouchOffTarget.MaterialTop)}
                        sx={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'stretch', justifyContent: 'flex-start' }}
                    >
                        <CardContent sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2, p: 3 }}>
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                                <MaterialIcon sx={{ fontSize: 64, color: colors.primaryColor }} />
                                <Typography variant="h5" sx={{ fontWeight: 'bold', textAlign: 'center' }}>
                                    Material Top
                                </Typography>
                            </Box>
                            <Typography variant="body2" sx={{ color: colors.darkTextColor, textAlign: 'center', mt: 2 }}>
                                Set Z zero to the top of your workpiece material.
                            </Typography>
                            <Box sx={{ mt: 'auto', pt: 2 }}>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold', display: 'block', textAlign: 'center' }}>
                                    Most Common
                                </Typography>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, display: 'block', textAlign: 'center' }}>
                                    Use for most machining operations
                                </Typography>
                            </Box>
                        </CardContent>
                    </CardActionArea>
                </Card>

                {/* Work Zero Card */}
                <Card
                    sx={{
                        border: `1px solid ${colors.borderColor}`,
                        transition: 'all 0.2s',
                        '&:hover': {
                            border: `2px solid ${colors.primaryColor}`,
                            transform: 'translateY(-4px)',
                            boxShadow: 3
                        }
                    }}
                >
                    <CardActionArea
                        onClick={() => handleSelectTarget(TouchOffTarget.WorkZero)}
                        sx={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'stretch', justifyContent: 'flex-start' }}
                    >
                        <CardContent sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2, p: 3 }}>
                            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                                <WorkZeroIcon sx={{ fontSize: 64, color: colors.primaryColor }} />
                                <Typography variant="h5" sx={{ fontWeight: 'bold', textAlign: 'center' }}>
                                    Work Zero
                                </Typography>
                            </Box>
                            <Typography variant="body2" sx={{ color: colors.darkTextColor, textAlign: 'center', mt: 2 }}>
                                Set Z zero with fixture offsets applied.
                            </Typography>
                            <Box sx={{ mt: 'auto', pt: 2 }}>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, fontWeight: 'bold', display: 'block', textAlign: 'center' }}>
                                    Fixture Work
                                </Typography>
                                <Typography variant="caption" sx={{ color: colors.mutedTextColor, display: 'block', textAlign: 'center' }}>
                                    Use with fixture coordinate system
                                </Typography>
                            </Box>
                        </CardContent>
                    </CardActionArea>
                </Card>
            </Box>
        </Box>
    );
}
