import {
    Box,
    FormControlLabel,
    Grid,
    Paper,
    Slider,
    Switch,
    Typography
} from '@mui/material';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';

export function PerformanceSection() {
    const config = ConfigurationData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <Paper sx={{ p: 3 }}>
                    <Typography variant="h6" gutterBottom>DRO Polling Mode</Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                        Alternative mode for systems where DRO position data from SignalR events is unreliable.
                    </Typography>

                    <ObserveState
                        key="performance-dro-polling"
                        listenTo={config}
                        properties={['enableDROPolling', 'droPollInterval']}
                        control={() => (
                            <Grid container spacing={3}>
                                <Grid item xs={12}>
                                    <Box sx={{ p: 2, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
                                        <FormControlLabel
                                            control={
                                                <Switch
                                                    checked={config.enableDROPolling}
                                                    onChange={(e) => config.enableDROPolling = e.target.checked}
                                                />
                                            }
                                            label="Enable DRO Polling Mode"
                                        />

                                        <Typography variant="body2" color="text.secondary" sx={{ mt: 1, mb: 2 }}>
                                            When enabled, DRO events trigger API polling for position instead of using event data directly.
                                            Polling stops automatically when no new DRO events are received.
                                        </Typography>

                                        {config.enableDROPolling && (
                                            <Box sx={{ mt: 2 }}>
                                                <Typography gutterBottom>
                                                    DRO Poll Interval: {config.droPollInterval}ms
                                                </Typography>
                                                <Slider
                                                    value={config.droPollInterval}
                                                    onChange={(_, value) => config.droPollInterval = value as number}
                                                    min={50}
                                                    max={500}
                                                    step={50}
                                                    valueLabelDisplay="auto"
                                                    valueLabelFormat={(value) => `${value}ms`}
                                                    marks={[
                                                        { value: 50, label: '50ms' },
                                                        { value: 200, label: '200ms' },
                                                        { value: 500, label: '500ms' }
                                                    ]}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Lower values = more responsive but higher CPU usage. Higher values = less CPU usage but slower updates.
                                                </Typography>
                                            </Box>
                                        )}
                                    </Box>
                                </Grid>
                            </Grid>
                        )}
                    />
                </Paper>
            </Grid>
        </Grid>
    );
}
