import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ChangeToolWizard, ChangeToolWizardState } from '../ChangeToolWizard';
import { MeasureNewToolStep } from './MeasureNewToolStep';
import { SelectNewToolStep } from './SelectNewToolStep';

export class SameSpecificationStep extends WizardStep {
    private currentTool: Tool | null;

    constructor(wizard: ChangeToolWizard, currentTool: Tool | null, previousStep: WizardStep | null) {
        super(wizard, previousStep);
        this.currentTool = currentTool;
    }

    public getTitle(): string {
        return 'Tool Specification';
    }

    public nextStep(): WizardStep | null {
        const wizardState = (this.wizard as ChangeToolWizard).state;

        if (wizardState.isSameSpecification === null) {
            return null; // User hasn't selected yet
        }

        if (wizardState.isSameSpecification) {
            // Same specification - use current tool and go to measure
            wizardState.newTool = this.currentTool;
            return new MeasureNewToolStep(this.wizard as ChangeToolWizard, this.currentTool, this);
        } else {
            // Different specification - initialize newTool with oldTool so we edit it directly
            wizardState.newTool = this.currentTool;
            return new SelectNewToolStep(this.wizard as ChangeToolWizard, this);
        }
    }

    public backStep(): WizardStep | null {
        return this.priorStep;
    }

    private handleResponse(isSame: boolean): void {
        const wizardState = (this.wizard as ChangeToolWizard).state;
        wizardState.isSameSpecification = isSame;

        // Automatically advance to next step
        const nextStep = this.nextStep();
        if (nextStep) {
            this.wizard.currentStep = nextStep;
            StateManager.propertyChanged(this.wizard, 'currentStep');
        }
    }

    public render(): React.ReactNode {
        const config = ConfigurationData.Instance;
        const colors = ConfigurationDataColors.Instance;
        const wizard = this.wizard as ChangeToolWizard;
        const wizardState = wizard.state as ChangeToolWizardState;

        return (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
                {/* Instructions */}
                <Box sx={{
                    p: 2,
                    backgroundColor: colors.primaryColor + '15',
                    borderRadius: 1,
                    borderLeft: `4px solid ${colors.primaryColor}`
                }}>
                    <Typography variant="h6" sx={{ mb: 1, fontWeight: 'bold' }}>
                        Tool Specification
                    </Typography>
                    <Typography variant="body1">
                        Does the new tool have the same specification (diameter, cutting length, etc.) as the previous tool?
                    </Typography>
                </Box>

                {/* Current Tool Info */}
                {this.currentTool ? (
                    <Box sx={{
                        p: 2,
                        border: `1px solid ${colors.borderColor}`,
                        borderRadius: 1
                    }}>
                        <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 1 }}>
                            Previous Tool
                        </Typography>
                        <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 1 }}>
                            T{(this.currentTool.toolNumber ?? 0).toString().padStart(2, '0')} - {this.currentTool.displayName}
                        </Typography>
                        <Box sx={{ display: 'flex', gap: 2, mt: 1 }}>
                            <Box>
                                <Typography variant="caption" sx={{ color: 'text.secondary' }}>Cutting Diameter</Typography>
                                <Typography variant="body2">{this.currentTool.cuttingDiameter?.toFixed(3) || '0.000'}"</Typography>
                            </Box>
                            <Box>
                                <Typography variant="caption" sx={{ color: 'text.secondary' }}>Cutting Length</Typography>
                                <Typography variant="body2">{this.currentTool.cuttingLength?.toFixed(3) || '0.000'}"</Typography>
                            </Box>
                            <Box>
                                <Typography variant="caption" sx={{ color: 'text.secondary' }}>Type</Typography>
                                <Typography variant="body2">{this.currentTool.cutterType}</Typography>
                            </Box>
                        </Box>
                    </Box>
                ) : (
                    <Box sx={{
                        p: 2,
                        border: `1px solid ${colors.borderColor}`,
                        borderRadius: 1,
                        textAlign: 'center'
                    }}>
                        <Typography variant="body1" sx={{ color: 'text.secondary' }}>
                            No previous tool loaded
                        </Typography>
                    </Box>
                )}

                {/* Selection Buttons */}
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                    <Button
                        variant={wizardState.isSameSpecification === true ? "contained" : "outlined"}
                        size="large"
                        onClick={() => this.handleResponse(true)}
                        sx={{
                            py: 2,
                            justifyContent: 'flex-start',
                            textAlign: 'left'
                        }}
                    >
                        <Box>
                            <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 0.5 }}>
                                Yes - Same Specification
                            </Typography>
                            <Typography variant="body2" sx={{ opacity: 0.8 }}>
                                The new tool is the same type (only length offset may differ)
                            </Typography>
                        </Box>
                    </Button>

                    <Button
                        variant={wizardState.isSameSpecification === false ? "contained" : "outlined"}
                        size="large"
                        onClick={() => this.handleResponse(false)}
                        sx={{
                            py: 2,
                            justifyContent: 'flex-start',
                            textAlign: 'left'
                        }}
                    >
                        <Box>
                            <Typography variant="h6" sx={{ fontWeight: 'bold', mb: 0.5 }}>
                                No - Different Specification
                            </Typography>
                            <Typography variant="body2" sx={{ opacity: 0.8 }}>
                                The new tool has different diameter, length, or other specifications
                            </Typography>
                        </Box>
                    </Button>
                </Box>
            </Box>
        );
    }
}
