import { Close as CloseIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    List,
    ListItemButton,
    ListItemText,
    TextField,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { Tool } from '../../data/Common/Tool';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { MachineStateData } from '../../data/MachineStateData';
import { ActionBus } from '../../utils/actions/ActionBus';
import { ToolChangeAction } from '../../utils/actions/ToolChangeAction';
import { ObserveState } from '../../utils/statemanager/ObserveState';

interface ToolSelectionDialogProps {
    open: boolean;
    onClose: () => void;
    onToolSelected?: (toolNumber: number) => void; // Optional callback - if provided, doesn't trigger tool change action
}

export function ToolSelectionDialog({ open, onClose, onToolSelected }: ToolSelectionDialogProps) {
    const [colors] = useState(() => ConfigurationDataColors.Instance);
    const [toolLibrary] = useState(() => ToolLibrary.Instance);
    const [machineState] = useState(() => MachineStateData.Instance);
    const [searchText, setSearchText] = useState('');
    const [selectedToolNumber, setSelectedToolNumber] = useState<number | null>(null);

    const handleSelectTool = () => {
        if (selectedToolNumber !== null) {
            if (onToolSelected) {
                // Use callback instead of triggering tool change action
                onToolSelected(selectedToolNumber);
            } else {
                // Create and add tool change action to the action bus
                const toolChangeAction = new ToolChangeAction(selectedToolNumber);
                ActionBus.Instance.addAction(toolChangeAction);
            }
            onClose();
        }
    };

    const handleClose = () => {
        setSearchText('');
        setSelectedToolNumber(null);
        onClose();
    };

    return (
        <Dialog
            open={open}
            onClose={handleClose}
            maxWidth="md"
            fullWidth
            sx={{
                zIndex: 1500 // Above wizards (1400)
            }}
        >
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3,
                fontWeight: 'bold'
            }}>
                Select Tool
                <IconButton
                    onClick={handleClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent sx={{ px: 2, pb: 2 }}>
                <ObserveState
                    key="tool-selection-dialog-content"
                    listenTo={machineState}
                    properties={['currentToolNumber']}
                    control={() => {
                        const currentToolNumber = machineState.currentToolNumber;
                        const availableTools: Tool[] = toolLibrary.tools;

                        // Filter tools based on search
                        const filteredTools = availableTools.filter(tool => {
                            if (!searchText) return true;
                            const searchLower = searchText.toLowerCase();
                            return (
                                (tool.toolNumber?.toString() || '').includes(searchText) ||
                                tool.displayName.toLowerCase().includes(searchLower)
                            );
                        });

                        return (
                            <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
                                {/* Search field */}
                                <TextField
                                    fullWidth
                                    label="Search Tools"
                                    value={searchText}
                                    onChange={(e) => setSearchText(e.target.value)}
                                    placeholder="Search by number, name, or description"
                                    autoFocus
                                    sx={{
                                        '& .MuiInputBase-root': {
                                            backgroundColor: colors.lightBackgroundColor
                                        }
                                    }}
                                />

                                {/* Tool list */}
                                <Box
                                    sx={{
                                        border: `1px solid ${colors.borderColor}`,
                                        borderRadius: 1,
                                        maxHeight: '400px',
                                        overflow: 'auto'
                                    }}
                                >
                                    <List sx={{ p: 0 }}>
                                        {filteredTools.length === 0 ? (
                                            <Box sx={{ p: 3, textAlign: 'center' }}>
                                                <Typography variant="body2" color="text.secondary">
                                                    No tools found
                                                </Typography>
                                            </Box>
                                        ) : (
                                            filteredTools.map((tool) => {
                                                const isSelected = selectedToolNumber === tool.toolNumber;
                                                const isCurrent = tool.toolNumber === currentToolNumber;

                                                return (
                                                    <ListItemButton
                                                        key={tool.toolNumber}
                                                        selected={isSelected}
                                                        onClick={() => setSelectedToolNumber(tool.toolNumber)}
                                                        sx={{
                                                            borderBottom: `1px solid ${colors.borderColor}`,
                                                            backgroundColor: isCurrent
                                                                ? `${colors.primaryColor}22`
                                                                : undefined,
                                                            '&.Mui-selected': {
                                                                backgroundColor: `${colors.primaryColor}44`,
                                                                '&:hover': {
                                                                    backgroundColor: `${colors.primaryColor}55`
                                                                }
                                                            }
                                                        }}
                                                    >
                                                        <ListItemText
                                                            primary={
                                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                                    <Typography
                                                                        variant="body1"
                                                                        sx={{
                                                                            fontWeight: 'bold',
                                                                            color: colors.primaryColor
                                                                        }}
                                                                    >
                                                                        T{(tool.toolNumber ?? 0).toString().padStart(2, '0')}
                                                                    </Typography>
                                                                    <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                                                        {tool.displayName}
                                                                    </Typography>
                                                                    {isCurrent && (
                                                                        <Typography
                                                                            variant="caption"
                                                                            sx={{
                                                                                color: colors.successColor,
                                                                                fontWeight: 'bold',
                                                                                ml: 1
                                                                            }}
                                                                        >
                                                                            (Current)
                                                                        </Typography>
                                                                    )}
                                                                </Box>
                                                            }
                                                            secondary={
                                                                <Typography variant="body2" color="text.secondary">
                                                                    {tool.cuttingDiameter.toFixed(3)}" Ø - {tool.cutterType}
                                                                </Typography>
                                                            }
                                                        />
                                                    </ListItemButton>
                                                );
                                            })
                                        )}
                                    </List>
                                </Box>
                            </Box>
                        );
                    }}
                />
            </DialogContent>

            <DialogActions sx={{ borderTop: `1px solid ${colors.borderColor}`, p: 2, gap: 1, justifyContent: 'flex-end' }}>
                <Button
                    onClick={handleClose}
                    variant="outlined"
                >
                    Cancel
                </Button>
                <Button
                    onClick={handleSelectTool}
                    variant="contained"
                    disabled={selectedToolNumber === null}
                    sx={{
                        fontWeight: 'bold',
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Select Tool
                </Button>
            </DialogActions>
        </Dialog>
    );
}
