import { StateManager } from '../../utils/statemanager/StateManager';
import { AxisConfig } from '../Machine/AxisConfig';
import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Axis Configuration Checklist Item
 * Automatic validation that X, Y, and Z axes are configured
 */
export class AxisConfigurationChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Axis Configuration',
            'Verify X, Y, and Z axes are configured with proper settings'
        );

        // Listen for changes to axis configuration
        const machine = MachineData.Instance;
        StateManager.addObserver(machine, () => {
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['axisConfigurations']);
    }

    /**
     * This is an auto-validation item
     */
    public needsManualConfirmation(): boolean {
        return false;
    }

    /**
     * Validation check: X, Y, and Z axes must be configured
     */
    public completionCheck(): boolean {
        const machine = MachineData.Instance;

        // Check that we have at least 3 axes
        if (machine.axisConfigurations.length < 3) {
            return false;
        }

        // Find X, Y, and Z axes
        const xAxis = machine.axisConfigurations.find((axis: AxisConfig) => axis.axisType === 'X');
        const yAxis = machine.axisConfigurations.find((axis: AxisConfig) => axis.axisType === 'Y');
        const zAxis = machine.axisConfigurations.find((axis: AxisConfig) => axis.axisType === 'Z');

        // All three must exist and be configured
        if (!xAxis || !yAxis || !zAxis) {
            return false;
        }

        // Basic validation: steps per revolution should be non-zero
        return xAxis.stepsPerRevolution > 0 &&
            yAxis.stepsPerRevolution > 0 &&
            zAxis.stepsPerRevolution > 0;
    }

    public clone(): AxisConfigurationChecklistItem {
        const cloned = new AxisConfigurationChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
