import { LogCategory, Logger } from './Logger';

/**
 * Event types for data reload notifications
 */
export enum DataReloadEvent {
    /** All data has been reloaded from server */
    AllDataReloaded = 'AllDataReloaded',
    /** User actions data has been updated */
    UserActionsUpdated = 'UserActionsUpdated',
    /** PLC programs have been reloaded */
    PLCDataReloaded = 'PLCDataReloaded',
    /** Configuration data has changed */
    ConfigurationUpdated = 'ConfigurationUpdated',
    /** Material/Tool/Clamp libraries have been updated */
    LibrariesUpdated = 'LibrariesUpdated'
}

/**
 * Callback type for data reload listeners
 */
export type DataReloadListener = (event: DataReloadEvent) => void | Promise<void>;

/**
 * Centralized notification system for data reload events
 * Allows different parts of the system to listen for and respond to data changes
 * 
 * Usage:
 * ```typescript
 * // Register a listener
 * DataReloadNotifier.Instance.addListener(DataReloadEvent.AllDataReloaded, async () => {
 *   await myComponent.refresh();
 * });
 * 
 * // Notify listeners when data is reloaded
 * DataReloadNotifier.Instance.notifyListeners(DataReloadEvent.AllDataReloaded);
 * ```
 */
export class DataReloadNotifier {
    private static _instance: DataReloadNotifier;
    private _listeners: Map<DataReloadEvent, Set<DataReloadListener>> = new Map();

    private constructor() {
        // Initialize listener sets for each event type
        Object.values(DataReloadEvent).forEach(eventType => {
            this._listeners.set(eventType as DataReloadEvent, new Set());
        });
    }

    /**
     * Get the singleton instance
     */
    public static get Instance(): DataReloadNotifier {
        if (!DataReloadNotifier._instance) {
            DataReloadNotifier._instance = new DataReloadNotifier();
        }
        return DataReloadNotifier._instance;
    }

    /**
     * Add a listener for a specific data reload event
     * @param event The event type to listen for
     * @param listener The callback to invoke when the event occurs
     */
    public addListener(event: DataReloadEvent, listener: DataReloadListener): void {
        const listeners = this._listeners.get(event);
        if (listeners) {
            listeners.add(listener);
            Logger.Instance.log(
                LogCategory.DataManager,
                `DataReloadNotifier: Added listener for ${event} (total: ${listeners.size})`
            );
        }
    }

    /**
     * Remove a listener for a specific event
     * @param event The event type
     * @param listener The callback to remove
     */
    public removeListener(event: DataReloadEvent, listener: DataReloadListener): void {
        const listeners = this._listeners.get(event);
        if (listeners) {
            listeners.delete(listener);
            Logger.Instance.log(
                LogCategory.DataManager,
                `DataReloadNotifier: Removed listener for ${event} (remaining: ${listeners.size})`
            );
        }
    }

    /**
     * Remove all listeners for a specific event
     * @param event The event type
     */
    public clearListeners(event: DataReloadEvent): void {
        const listeners = this._listeners.get(event);
        if (listeners) {
            listeners.clear();
            Logger.Instance.log(
                LogCategory.DataManager,
                `DataReloadNotifier: Cleared all listeners for ${event}`
            );
        }
    }

    /**
     * Notify all listeners of a data reload event
     * @param event The event type that occurred
     */
    public async notifyListeners(event: DataReloadEvent): Promise<void> {
        const listeners = this._listeners.get(event);
        if (!listeners || listeners.size === 0) {
            return;
        }

        Logger.Instance.log(
            LogCategory.DataManager,
            `DataReloadNotifier: Notifying ${listeners.size} listener(s) of ${event}`
        );

        // Execute all listeners (allow both sync and async)
        const promises: Promise<void>[] = [];
        for (const listener of listeners) {
            try {
                const result = listener(event);
                if (result instanceof Promise) {
                    promises.push(result);
                }
            } catch (error) {
                Logger.Instance.logError(
                    LogCategory.DataManager,
                    `DataReloadNotifier: Error in listener for ${event}:`,
                    error
                );
            }
        }

        // Wait for all async listeners to complete
        if (promises.length > 0) {
            await Promise.all(promises).catch(error => {
                Logger.Instance.logError(
                    LogCategory.DataManager,
                    `DataReloadNotifier: Error in async listener for ${event}:`,
                    error
                );
            });
        }
    }

    /**
     * Get the number of listeners for a specific event
     * @param event The event type
     * @returns The number of registered listeners
     */
    public getListenerCount(event: DataReloadEvent): number {
        return this._listeners.get(event)?.size || 0;
    }

    /**
     * Clear all listeners for all events (useful for testing)
     */
    public clearAll(): void {
        this._listeners.forEach(listeners => listeners.clear());
        Logger.Instance.log(LogCategory.DataManager, 'DataReloadNotifier: Cleared all listeners');
    }
}
