import { FormControl, Grid, InputLabel, MenuItem, Select, Typography } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { RotaryAxis } from '../../../../data/Machine/RotaryAxis';
import { RotaryAxisDirection } from '../../../../data/Machine/RotaryAxisDirection';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';

export function RotarySection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <FormControl fullWidth margin="normal">
                    <InputLabel>Rotary Axis Type</InputLabel>
                    <Select
                        value={machine.rotaryAxis}
                        onChange={(e) => machine.rotaryAxis = e.target.value as RotaryAxis}
                    >
                        <MenuItem value={RotaryAxis.None}>None</MenuItem>
                        <MenuItem value={RotaryAxis.Fixed}>Fixed</MenuItem>
                        <MenuItem value={RotaryAxis.Movable}>Movable</MenuItem>
                    </Select>
                </FormControl>

                <ObserveState
                    key="rotary-diameter"
                    listenTo={machine}
                    properties={['rotaryDiameter']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Diameter"
                            value={machine.rotaryDiameter}
                            onChange={(value) => machine.rotaryDiameter = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="rotary-length"
                    listenTo={machine}
                    properties={['rotaryLength']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Length"
                            value={machine.rotaryLength}
                            onChange={(value) => machine.rotaryLength = value}
                            margin="normal"
                            precision={1}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12}>
                <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Position</Typography>
            </Grid>

            <Grid item xs={12} md={4}>
                <ObserveState
                    key="rotary-x-position"
                    listenTo={machine}
                    properties={['rotaryZeroLocationX']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary X Position"
                            value={machine.rotaryZeroLocationX}
                            onChange={(value) => machine.rotaryZeroLocationX = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={4}>
                <ObserveState
                    key="rotary-y-position"
                    listenTo={machine}
                    properties={['rotaryZeroLocationY']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Y Position"
                            value={machine.rotaryZeroLocationY}
                            onChange={(value) => machine.rotaryZeroLocationY = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={4}>
                <ObserveState
                    key="rotary-z-position"
                    listenTo={machine}
                    properties={['rotaryZeroLocationZ']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Z Position"
                            value={machine.rotaryZeroLocationZ}
                            onChange={(value) => machine.rotaryZeroLocationZ = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <FormControl fullWidth margin="normal">
                    <InputLabel>Rotary Axis Direction</InputLabel>
                    <Select
                        value={machine.rotaryAxisDirection}
                        onChange={(e) => machine.rotaryAxisDirection = e.target.value as RotaryAxisDirection}
                    >
                        <MenuItem value={RotaryAxisDirection.X}>X-Axis</MenuItem>
                        <MenuItem value={RotaryAxisDirection.Y}>Y-Axis</MenuItem>
                    </Select>
                </FormControl>
            </Grid>

            <Grid item xs={12}>
                <Typography variant="subtitle1" sx={{ mt: 3, mb: 2 }}>Detailed Component Dimensions</Typography>
            </Grid>

            {/* Rotary Head */}
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="rotary-head-diameter"
                    listenTo={machine}
                    properties={['rotaryHeadDiameter']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Head Diameter"
                            value={machine.rotaryHeadDiameter}
                            onChange={(value) => machine.rotaryHeadDiameter = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="rotary-head-length"
                    listenTo={machine}
                    properties={['rotaryHeadLength']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Head Length"
                            value={machine.rotaryHeadLength}
                            onChange={(value) => machine.rotaryHeadLength = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            {/* Rotary Post */}
            <Grid item xs={12} md={4}>
                <ObserveState
                    key="rotary-post-height"
                    listenTo={machine}
                    properties={['rotaryPostHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Post Height"
                            value={machine.rotaryPostHeight}
                            onChange={(value) => machine.rotaryPostHeight = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={4}>
                <ObserveState
                    key="rotary-post-width"
                    listenTo={machine}
                    properties={['rotaryPostWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Post Width"
                            value={machine.rotaryPostWidth}
                            onChange={(value) => machine.rotaryPostWidth = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={4}>
                <ObserveState
                    key="rotary-post-length"
                    listenTo={machine}
                    properties={['rotaryPostLength']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Post Length"
                            value={machine.rotaryPostLength}
                            onChange={(value) => machine.rotaryPostLength = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            {/* Rotary Bed */}
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="rotary-bed-width"
                    listenTo={machine}
                    properties={['rotaryBedWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Bed Width"
                            value={machine.rotaryBedWidth}
                            onChange={(value) => machine.rotaryBedWidth = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="rotary-bed-height"
                    listenTo={machine}
                    properties={['rotaryBedHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Rotary Bed Height"
                            value={machine.rotaryBedHeight}
                            onChange={(value) => machine.rotaryBedHeight = value}
                            margin="normal"
                            precision={2}
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
