import { IStorable } from '../common/IStorable';
import { StateManager } from '../utils/statemanager/StateManager';
import { DataUtilities } from '../utils/storage/DataUtilities';
import { ConfigurationData } from './ConfigurationData';

/**
 * Toolpath mode for dry run
 */
export enum DryRunToolpathMode {
    NoChanges = 'noChanges',
    RemoveDuplicate = 'removeDuplicate',
    TraceOutline = 'traceOutline'
}

/**
 * Tool mode for dry run
 */
export enum DryRunToolMode {
    CurrentTool = 'currentTool',
    DoToolChanges = 'doToolChanges',
    LaserPointer = 'laserPointer'
}

/**
 * Settings for dry run execution
 * Controls how the machine executes a dry run of the job
 */
export class DryRunSettings implements IStorable {
    private static _instance: DryRunSettings;

    private _toolpathMode: DryRunToolpathMode = DryRunToolpathMode.NoChanges;
    private _toolMode: DryRunToolMode = DryRunToolMode.CurrentTool;
    private _runAtZ: number = 1;
    private _changeSpeed: boolean = false;
    private _overrideSpeed: number = 0; // Will be initialized to fastJogXY in constructor

    private constructor() {
        // Initialize overrideSpeed to fastJogXY from ConfigurationData
        this._overrideSpeed = ConfigurationData.Instance.fastJogXY;
    }

    public static get Instance(): DryRunSettings {
        if (!DryRunSettings._instance) {
            DryRunSettings._instance = new DryRunSettings();
        }
        return DryRunSettings._instance;
    }

    public get toolpathMode(): DryRunToolpathMode {
        return this._toolpathMode;
    }

    public set toolpathMode(value: DryRunToolpathMode) {
        this._toolpathMode = value;
        StateManager.propertyChanged(this, 'toolpathMode');
    }

    public get toolMode(): DryRunToolMode {
        return this._toolMode;
    }

    public set toolMode(value: DryRunToolMode) {
        this._toolMode = value;
        StateManager.propertyChanged(this, 'toolMode');
    }

    public get runAtZ(): number {
        return this._runAtZ;
    }

    public set runAtZ(value: number) {
        this._runAtZ = value;
        StateManager.propertyChanged(this, 'runAtZ');
    }

    public get changeSpeed(): boolean {
        return this._changeSpeed;
    }

    public set changeSpeed(value: boolean) {
        this._changeSpeed = value;
        StateManager.propertyChanged(this, 'changeSpeed');
    }

    public get overrideSpeed(): number {
        return this._overrideSpeed;
    }

    public set overrideSpeed(value: number) {
        this._overrideSpeed = value;
        StateManager.propertyChanged(this, 'overrideSpeed');
    }

    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
