/**
 * Base message structure from SignalR hub
 * Server sends PascalCase, we normalize to camelCase
 */
export interface CNCMessage {
    EventType?: string;      // PascalCase from server
    eventType?: string;      // camelCase normalized
    Timestamp?: string;      // PascalCase from server
    timestamp?: string;      // camelCase normalized
    Data?: any;              // PascalCase from server
    data?: any;              // camelCase normalized
}

/**
 * DRO (Digital Read Out) event data
 * Contains real-time machine position information
 */
export interface DROEventData {
    timestamp: string;
    messageType: string;
    message: string;      // Human-readable position summary
    axis1: number;        // X axis position
    axis2: number;        // Y axis position  
    axis3: number;        // Z axis position
    axis4: number;        // A axis position (rotary)
    axis5: number;        // B axis position
    axis6: number;        // C axis position
    axis7: number;        // Additional axis
    axis8: number;        // Additional axis
}

export class DROEvent {
    public readonly messageType: string = 'DROEvent';
    public readonly timestamp: Date;
    public readonly data: DROEventData;

    constructor(message: CNCMessage) {
        const rawData = message.Data || message.data;
        this.timestamp = new Date(rawData.Timestamp || rawData.timestamp);
        // Normalize PascalCase to camelCase
        this.data = {
            timestamp: rawData.Timestamp || rawData.timestamp,
            messageType: rawData.MessageType || rawData.messageType,
            message: rawData.Message || rawData.message,
            axis1: rawData.Axis1 !== undefined ? rawData.Axis1 : rawData.axis1,
            axis2: rawData.Axis2 !== undefined ? rawData.Axis2 : rawData.axis2,
            axis3: rawData.Axis3 !== undefined ? rawData.Axis3 : rawData.axis3,
            axis4: rawData.Axis4 !== undefined ? rawData.Axis4 : rawData.axis4,
            axis5: rawData.Axis5 !== undefined ? rawData.Axis5 : rawData.axis5,
            axis6: rawData.Axis6 !== undefined ? rawData.Axis6 : rawData.axis6,
            axis7: rawData.Axis7 !== undefined ? rawData.Axis7 : rawData.axis7,
            axis8: rawData.Axis8 !== undefined ? rawData.Axis8 : rawData.axis8
        };
    }
}

/**
 * General message event from the CNC system
 */
export interface MessageEventData {
    timestamp: string;
    messageType: string;
    message: string;                // Error/status message text
    eventCode: number;              // Centroid error code (e.g., 306, 407)
    eventType: string;              // Classified message type
}

export class MessageEvent {
    public readonly messageType: string = 'MessageEvent';
    public readonly timestamp: Date;
    public readonly data: MessageEventData;

    constructor(message: CNCMessage) {
        const rawData = message.Data || message.data;
        this.timestamp = new Date(rawData.Timestamp || rawData.timestamp);
        // Normalize PascalCase to camelCase
        this.data = {
            timestamp: rawData.Timestamp || rawData.timestamp,
            messageType: rawData.MessageType || rawData.messageType,
            message: rawData.Message || rawData.message,
            eventCode: rawData.EventCode !== undefined ? rawData.EventCode : rawData.eventCode,
            eventType: rawData.EventType || rawData.eventType
        };
    }
}

