/**
 * Server Status event data (formerly called Heartbeat)
 * Sent every 2 seconds via ReceiveCNCMessage to provide connection status and position
 * Note: Server sends PascalCase, we normalize to camelCase
 */
export interface ServerStatusEventData {
    timestamp: string;          // UTC timestamp (ISO 8601)
    serverTime: string;         // Local server time
    isConnected: boolean;       // True if server is connected to CNC
    status: string;             // "Connected" or "Disconnected"
    messageType: string;        // Always "ServerStatus"
    isApiRestricted: boolean;   // True if API is in restricted mode
    isJobRunning: boolean;      // True if a job is currently running
    requiresReset: boolean;     // True if machine needs reset (SV_STOP)
    isIncrementalJogMode: boolean; // True if jog mode is incremental, false if continuous
    isFastJogging: boolean;     // True if fast jog mode is enabled (rabbit), false if slow (turtle)
    jogIncrementSpeed: number;  // Jog increment speed multiplier (1 = X1, 10 = X10, 100 = X100)
    isHomed: boolean;           // True if machine has been homed
    JogSettings?: {             // Optional: Nested jog settings from server
        IsIncremental: boolean; // True if jog mode is incremental, false if continuous
        IsSlowMode: boolean;    // True if slow jog mode (turtle), false if fast (rabbit)
        IncrementSpeed: string; // Jog increment speed as string ('X1', 'X10', 'X100')
    };
    plcVersion?: {              // Optional: Installed PLC version from controller
        major: number;
        minor: number;
        update: number;
    } | null;
    boardType?: string;         // Optional: Controller board type (Acorn, Acorn6, Hickory, Unknown)
    expansionBoardCount?: number; // Optional: Number of expansion boards connected
    position: {
        x: number;              // X-axis position (machine units)
        y: number;              // Y-axis position (machine units)
        z: number;              // Z-axis position (machine units)
        a: number;              // A-axis rotary position (degrees)
    } | null;                   // null if disconnected or unavailable
}

export class ServerStatusEvent {
    public readonly messageType: string = 'ServerStatus';
    public readonly timestamp: Date;
    public readonly data: ServerStatusEventData;

    constructor(message: CNCMessage) {
        // Handle both PascalCase (from server) and camelCase (normalized)
        const rawData = message.Data || message.data;

        this.timestamp = new Date(rawData.Timestamp || rawData.timestamp);

        // Normalize PascalCase to camelCase
        this.data = {
            timestamp: rawData.Timestamp || rawData.timestamp,
            serverTime: rawData.ServerTime || rawData.serverTime,
            isConnected: rawData.IsConnected !== undefined ? rawData.IsConnected : rawData.isConnected,
            status: rawData.Status || rawData.status,
            messageType: rawData.MessageType || rawData.messageType || 'ServerStatus',
            isApiRestricted: rawData.IsApiRestricted !== undefined ? rawData.IsApiRestricted : (rawData.isApiRestricted || false),
            isJobRunning: rawData.IsJobRunning !== undefined ? rawData.IsJobRunning : (rawData.isJobRunning || false),
            requiresReset: rawData.RequiresReset !== undefined ? rawData.RequiresReset : (rawData.requiresReset || false),
            isIncrementalJogMode: rawData.IsIncrementalJogMode !== undefined ? rawData.IsIncrementalJogMode : (rawData.isIncrementalJogMode || false),
            isFastJogging: rawData.IsFastJogging !== undefined ? rawData.IsFastJogging : (rawData.isFastJogging || false),
            jogIncrementSpeed: rawData.JogIncrementSpeed !== undefined ? rawData.JogIncrementSpeed : (rawData.jogIncrementSpeed || 1),
            isHomed: rawData.IsHomed !== undefined ? rawData.IsHomed : (rawData.isHomed || false),
            JogSettings: rawData.JogSettings ? {
                IsIncremental: rawData.JogSettings.IsIncremental,
                IsSlowMode: rawData.JogSettings.IsSlowMode,
                IncrementSpeed: rawData.JogSettings.IncrementSpeed
            } : undefined,
            plcVersion: rawData.PlcVersion || rawData.plcVersion ? {
                major: (rawData.PlcVersion?.Major ?? rawData.plcVersion?.major) || 0,
                minor: (rawData.PlcVersion?.Minor ?? rawData.plcVersion?.minor) || 0,
                update: (rawData.PlcVersion?.Update ?? rawData.plcVersion?.update) || 0
            } : null,
            boardType: rawData.BoardType || rawData.boardType,
            expansionBoardCount: rawData.ExpansionBoardCount ?? rawData.expansionBoardCount,
            position: rawData.Position || rawData.position ? {
                x: (rawData.Position?.X !== undefined ? rawData.Position.X : rawData.position?.x) || 0,
                y: (rawData.Position?.Y !== undefined ? rawData.Position.Y : rawData.position?.y) || 0,
                z: (rawData.Position?.Z !== undefined ? rawData.Position.Z : rawData.position?.z) || 0,
                a: (rawData.Position?.A !== undefined ? rawData.Position.A : rawData.position?.a) || 0
            } : null
        };
    }
}

/**
 * Output state changed event data
 * Triggered when an output is forced on/off via API
 */
export interface OutputStateChangedEventData {
    timestamp: string;
    messageType: string;
    outputNumber: number;    // The output number
    state: boolean;          // true = on, false = off
    forceState: string;      // "ForcedOn", "ForcedOff", or "NotForced"
    isForced: boolean;       // true if output is forced (not controlled by PLC)
}

export class OutputStateChangedEvent {
    public readonly messageType: string = 'OutputStateChanged';
    public readonly timestamp: Date;
    public readonly data: OutputStateChangedEventData;

    constructor(message: CNCMessage) {
        const rawData = message.Data || message.data;
        this.timestamp = new Date(rawData.Timestamp || rawData.timestamp);

        // Normalize PascalCase to camelCase
        this.data = {
            timestamp: rawData.Timestamp || rawData.timestamp,
            messageType: rawData.MessageType || rawData.messageType || 'OutputStateChanged',
            outputNumber: rawData.OutputNumber !== undefined ? rawData.OutputNumber : rawData.outputNumber,
            state: rawData.State !== undefined ? rawData.State : rawData.state,
            forceState: rawData.ForceState || rawData.forceState,
            isForced: rawData.IsForced !== undefined ? rawData.IsForced : rawData.isForced
        };
    }
}

/**
 * Union type for all event types
 */
export type SignalREvent =
    | DROEvent
    | MessageEvent
    | JobInfoEvent
    | JobStartedEvent
    | JobCompletedEvent
    | StepExecutionEvent
    | ServerStatusEvent
    | OutputStateChangedEvent;

/**
 * Type guard functions
 */
export function isDROEvent(event: SignalREvent): event is DROEvent {
    return event.messageType === 'DROEvent';
}

export function isMessageEvent(event: SignalREvent): event is MessageEvent {
    return event.messageType === 'MessageEvent';
}

export function isJobInfoEvent(event: SignalREvent): event is JobInfoEvent {
    return event.messageType === 'JobInfoEvent';
}

export function isJobStartedEvent(event: SignalREvent): event is JobStartedEvent {
    return event.messageType === 'JobStartedEvent';
}

export function isJobCompletedEvent(event: SignalREvent): event is JobCompletedEvent {
    return event.messageType === 'JobCompletedEvent';
}

export function isStepExecutionEvent(event: SignalREvent): event is StepExecutionEvent {
    return event.messageType === 'StepExecutionEvent';
}

export function isServerStatusEvent(event: SignalREvent): event is ServerStatusEvent {
    return event.messageType === 'ServerStatus';
}

export function isOutputStateChangedEvent(event: SignalREvent): event is OutputStateChangedEvent {
    return event.messageType === 'OutputStateChanged';
}

// Legacy alias for backward compatibility
export function isHeartbeatEvent(event: SignalREvent): event is ServerStatusEvent {
    return event.messageType === 'ServerStatus';
}
