import { TouchApp as AutoIcon, Layers as MachineBedIcon, GpsFixed as ManualFixedIcon, ViewInAr as SpoilboardIcon } from '@mui/icons-material';
import { Box, Card, CardActionArea, CardContent, Grid, Typography } from '@mui/material';
import React from 'react';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ToolMeasurementMethod, ToolMeasurementWizard } from '../ToolMeasurementWizard';
import { MoveToPositionStep } from './MoveToPositionStep';

/**
 * Step to select measurement method
 */
export class SelectMethodStep extends WizardStep {
    public tool: Tool;

    constructor(wizard: ToolMeasurementWizard, tool: Tool, previousStep: WizardStep | null) {
        super(wizard, previousStep);
        this.tool = tool;
    }

    getTitle(): string {
        return `Measure Tool: ${this.tool.displayName}`;
    }

    nextStep(): WizardStep | null {
        // Check if only one method is configured and auto-select it
        const machineData = MachineData.Instance;
        const availableMethods: ToolMeasurementMethod[] = [];

        if (machineData.hasFixedTouchPlate) {
            availableMethods.push(ToolMeasurementMethod.AutoFixedTouchPlate);
        }
        if (machineData.fixedToolMeasurementPointEnabled) {
            availableMethods.push(ToolMeasurementMethod.ManualFixedPoint);
        }
        if (machineData.spoilboardToolMeasurementPointEnabled) {
            availableMethods.push(ToolMeasurementMethod.ManualSpoilboard);
        }
        if (machineData.machineBedToolMeasurementPointEnabled) {
            availableMethods.push(ToolMeasurementMethod.ManualMachineBed);
        }

        // If only one method is available, skip this step and go directly to it
        if (availableMethods.length === 1) {
            const method = availableMethods[0];
            if (method === ToolMeasurementMethod.AutoFixedTouchPlate) {
                // TODO: Create auto measurement step when implemented
                return null;
            } else {
                return new MoveToPositionStep(this.wizard as ToolMeasurementWizard, this.tool, this, method);
            }
        }

        // Multiple or zero methods available - show selection page
        return null;
    }

    backStep(): WizardStep | null {
        return null; // First step, no back
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="select-method-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <SelectMethodStepComponent step={this} />}
            />
        );
    }
}

interface SelectMethodStepComponentProps {
    step: SelectMethodStep;
}

function SelectMethodStepComponent({ step }: SelectMethodStepComponentProps) {
    const wizard = step.wizard as ToolMeasurementWizard;
    const colors = ConfigurationDataColors.Instance;

    const handleMethodSelect = (method: ToolMeasurementMethod) => {
        if (method === ToolMeasurementMethod.AutoFixedTouchPlate) {
            // TODO: Create auto measurement step
            // Auto measurement not yet implemented
        } else {
            // All manual methods use the same flow, just with different parameters
            const nextStep = new MoveToPositionStep(wizard, step.tool, step, method);
            wizard.currentStep = nextStep;
            StateManager.propertyChanged(wizard, 'currentStep');
        }
    };

    return (
        <ObserveState
            key="machine-config-observer"
            listenTo={MachineData.Instance}
            properties={['hasFixedTouchPlate', 'fixedToolMeasurementPointEnabled', 'spoilboardToolMeasurementPointEnabled', 'machineBedToolMeasurementPointEnabled']}
            control={() => {
                const machineData = MachineData.Instance;
                const hasFixedTouchPlate = machineData.hasFixedTouchPlate;
                const autoEnabled = hasFixedTouchPlate;
                const fixedPointEnabled = machineData.fixedToolMeasurementPointEnabled;
                const spoilboardEnabled = machineData.spoilboardToolMeasurementPointEnabled;
                const machineBedEnabled = machineData.machineBedToolMeasurementPointEnabled;

                // Count available methods
                const availableCount = [autoEnabled, fixedPointEnabled, spoilboardEnabled, machineBedEnabled].filter(Boolean).length;

                // If no methods are configured, show message
                if (availableCount === 0) {
                    return (
                        <Box sx={{ p: 3, textAlign: 'center' }}>
                            <Typography variant="h6" sx={{ mb: 2, color: 'warning.main' }}>
                                No Measurement Methods Configured
                            </Typography>
                            <Typography variant="body1" color="text.secondary">
                                Please configure at least one tool measurement method in the Setup tab before measuring tools.
                                You can configure touch plates or manual measurement reference points in the Speeds/Homing/Measuring section.
                            </Typography>
                        </Box>
                    );
                }

                return (
                    <Box sx={{ p: 3 }}>
                        <Typography variant="body1" sx={{ mb: 3, color: 'text.secondary' }}>
                            Select the measurement method for this tool:
                        </Typography>

                        <Grid container spacing={3}>
                            {/* Auto Measure - Touch Plate */}
                            {autoEnabled && (
                                <Grid item xs={12} sm={6}>
                                    <Card
                                        sx={{
                                            height: '100%',
                                            border: `1px solid ${colors.borderColor}`,
                                            transition: 'all 0.2s ease-in-out',
                                            '&:hover': {
                                                boxShadow: 3,
                                                borderColor: colors.primaryColor
                                            }
                                        }}
                                    >
                                        <CardActionArea
                                            onClick={() => handleMethodSelect(ToolMeasurementMethod.AutoFixedTouchPlate)}
                                            sx={{ height: '100%', p: 2 }}
                                        >
                                            <CardContent sx={{ textAlign: 'center' }}>
                                                <AutoIcon sx={{ fontSize: 64, color: colors.primaryColor, mb: 2 }} />
                                                <Typography variant="h6" gutterBottom>
                                                    Auto Measure
                                                </Typography>
                                                <Typography variant="body2" color="text.secondary">
                                                    Automatically measure using touch plate
                                                </Typography>
                                            </CardContent>
                                        </CardActionArea>
                                    </Card>
                                </Grid>
                            )}

                            {/* Manual Measure - Fixed Point */}
                            {fixedPointEnabled && (
                                <Grid item xs={12} sm={6}>
                                    <Card
                                        sx={{
                                            height: '100%',
                                            border: `1px solid ${colors.borderColor}`,
                                            transition: 'all 0.2s ease-in-out',
                                            '&:hover': {
                                                boxShadow: 3,
                                                borderColor: colors.primaryColor
                                            }
                                        }}
                                    >
                                        <CardActionArea
                                            onClick={() => handleMethodSelect(ToolMeasurementMethod.ManualFixedPoint)}
                                            sx={{ height: '100%', p: 2 }}
                                        >
                                            <CardContent sx={{ textAlign: 'center' }}>
                                                <ManualFixedIcon sx={{ fontSize: 64, color: colors.secondaryColor, mb: 2 }} />
                                                <Typography variant="h6" gutterBottom>
                                                    Fixed Point
                                                </Typography>
                                                <Typography variant="body2" color="text.secondary">
                                                    Measure against a known reference point
                                                </Typography>
                                            </CardContent>
                                        </CardActionArea>
                                    </Card>
                                </Grid>
                            )}

                            {/* Manual Measure - Spoilboard */}
                            {spoilboardEnabled && (
                                <Grid item xs={12} sm={6}>
                                    <Card
                                        sx={{
                                            height: '100%',
                                            border: `1px solid ${colors.borderColor}`,
                                            transition: 'all 0.2s ease-in-out',
                                            '&:hover': {
                                                boxShadow: 3,
                                                borderColor: colors.primaryColor
                                            }
                                        }}
                                    >
                                        <CardActionArea
                                            onClick={() => handleMethodSelect(ToolMeasurementMethod.ManualSpoilboard)}
                                            sx={{ height: '100%', p: 2 }}
                                        >
                                            <CardContent sx={{ textAlign: 'center' }}>
                                                <SpoilboardIcon sx={{ fontSize: 64, color: colors.secondaryColor, mb: 2 }} />
                                                <Typography variant="h6" gutterBottom>
                                                    Spoilboard
                                                </Typography>
                                                <Typography variant="body2" color="text.secondary">
                                                    Measure against spoilboard surface
                                                </Typography>
                                            </CardContent>
                                        </CardActionArea>
                                    </Card>
                                </Grid>
                            )}

                            {/* Manual Measure - Machine Bed */}
                            {machineBedEnabled && (
                                <Grid item xs={12} sm={6}>
                                    <Card
                                        sx={{
                                            height: '100%',
                                            border: `1px solid ${colors.borderColor}`,
                                            transition: 'all 0.2s ease-in-out',
                                            '&:hover': {
                                                boxShadow: 3,
                                                borderColor: colors.primaryColor
                                            }
                                        }}
                                    >
                                        <CardActionArea
                                            onClick={() => handleMethodSelect(ToolMeasurementMethod.ManualMachineBed)}
                                            sx={{ height: '100%', p: 2 }}
                                        >
                                            <CardContent sx={{ textAlign: 'center' }}>
                                                <MachineBedIcon sx={{ fontSize: 64, color: colors.secondaryColor, mb: 2 }} />
                                                <Typography variant="h6" gutterBottom>
                                                    Machine Bed
                                                </Typography>
                                                <Typography variant="body2" color="text.secondary">
                                                    Measure against machine bed surface
                                                </Typography>
                                            </CardContent>
                                        </CardActionArea>
                                    </Card>
                                </Grid>
                            )}
                        </Grid>
                    </Box>
                );
            }}
        />
    );
}
