import { CNCPoint } from '../data/CNCPoint';
import { ConfigurationData } from '../data/ConfigurationData';
import { ConfigurationState, JogIncrementSpeed } from '../data/ConfigurationState';
import { UserMessageQueue } from '../data/UserMessageQueue';
import { ICNCMovement, MovementCoordinateType } from '../machine/ICNCMovement';
import { IOEvent } from '../machine/IOEvent';
import { JogDirection } from '../machine/JogDirection';
import { MoveDirection } from '../machine/MoveDirection';
import { MoveStrategy } from '../machine/MoveStrategy';
import { MoveType } from '../machine/MoveType';
import { CoordinateUtil } from '../utils/CoordinateUtil';

export class SimulatorCNCMovement implements ICNCMovement {
  private moveType: MoveType = MoveType.Absolute;
  private feedRateFactor: number = 1.0;
  private jogInterval: NodeJS.Timeout | null = null;
  private currentJogDirection: JogDirection | null = null;
  private currentJogSpeed: number = 1;

  async SetMoveType(moveType: MoveType): Promise<void> {
    this.moveType = moveType;
    UserMessageQueue.Instance.addMessage(`✓ Set move type to ${moveType}`);
  }

  async GetMoveType(): Promise<MoveType> {
    return this.moveType;
  }

  async GetCurrentPosition(): Promise<CNCPoint> {
    return ConfigurationState.Instance.currentMachinePoint;
  }

  async MoveTo(point: CNCPoint, coordinateType: MovementCoordinateType, xySpeed?: number, zSpeed?: number, strategy?: MoveStrategy): Promise<void> {
    // Simulate movement delay
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Convert coordinates based on coordinateType
    let targetPoint: CNCPoint;
    if (coordinateType === MovementCoordinateType.WorkZero) {
      // WorkZero coordinates need to be converted to MachineZero first
      targetPoint = CoordinateUtil.toMachineZero(point);
    } else {
      // Machine coordinates - convert to MachineZero for consistency
      targetPoint = CoordinateUtil.toMachineZero(point);
    }

    const strategyText = strategy !== undefined ? ` using ${MoveStrategy[strategy]} strategy` : '';

    // Update the machine state with the new position
    ConfigurationState.Instance.currentMachinePoint = targetPoint;

    // Clear proposed spindle position since move is complete
    ConfigurationState.Instance.proposedSpindlePosition = null;

    const speedText = xySpeed || zSpeed ? ` (XY: ${xySpeed || 'default'}, Z: ${zSpeed || 'default'})` : '';
    UserMessageQueue.Instance.addMessage(`✓ Moved to X${point.x.toFixed(4)} Y${point.y.toFixed(4)} Z${point.z.toFixed(4)} (${coordinateType})${speedText}${strategyText}`);
  }

  async MoveToUntil(point: CNCPoint, coordinateType: MovementCoordinateType, event: IOEvent, xySpeed?: number, zSpeed?: number): Promise<void> {
    UserMessageQueue.Instance.addMessage(`✓ Moving to position until ${event} event (${coordinateType})`);
    await this.MoveTo(point, coordinateType, xySpeed, zSpeed);
  }

  async MoveDirectionUntil(
    direction: MoveDirection,
    event: IOEvent,
    maxDistance?: number,
    speed?: number
  ): Promise<void> {
    const currentPos = await this.GetCurrentPosition();
    let targetPos = new CNCPoint(currentPos.x, currentPos.y, currentPos.z, currentPos.coordinateType);

    const moveDistance = maxDistance || 1.0; // Default 1 inch

    switch (direction) {
      case MoveDirection.XPositive:
        targetPos.x += moveDistance;
        break;
      case MoveDirection.XNegative:
        targetPos.x -= moveDistance;
        break;
      case MoveDirection.YPositive:
        targetPos.y += moveDistance;
        break;
      case MoveDirection.YNegative:
        targetPos.y -= moveDistance;
        break;
      case MoveDirection.ZPositive:
        targetPos.z += moveDistance;
        break;
      case MoveDirection.ZNegative:
        targetPos.z -= moveDistance;
        break;
    }

    UserMessageQueue.Instance.addMessage(`✓ Moving ${direction} until ${event} event`);
    await this.MoveTo(targetPos, MovementCoordinateType.Machine, speed, speed);
  }

  async SetCurrentFixturePoint(): Promise<void> {
    // Use CoordinateUtil to calculate API fixture offset from current work zero
    // (calculated but not used in simulator - just for consistency with interface)
    CoordinateUtil.toAPIFixtureOffset();

    UserMessageQueue.Instance.addMessage(`✓ Set current fixture point`);
  }

  async AdjustFeedRate(factor: number): Promise<void> {
    this.feedRateFactor = factor;
    UserMessageQueue.Instance.addMessage(`✓ Adjusted feed rate by factor ${factor}`);
  }

  async GetCurrentFeedRateFactor(): Promise<number> {
    return this.feedRateFactor;
  }

  async ResetFeedRateFactor(): Promise<void> {
    this.feedRateFactor = 1.0;
    UserMessageQueue.Instance.addMessage(`✓ Reset feed rate factor to 1.0`);
  }

  async StartJog(direction: JogDirection): Promise<void> {
    // Stop any existing jog
    await this.StopJog();

    // Get current jog settings from ConfigurationState
    const config = ConfigurationState.Instance;
    const continuous = config.jogContinuousMode;

    // Convert JogIncrementSpeed to numeric multiplier
    const speed = config.jogIncrementSpeed === 'X1' ? 1 : config.jogIncrementSpeed === 'X10' ? 10 : 100;

    this.currentJogDirection = direction;
    this.currentJogSpeed = speed;

    if (continuous) {
      // Continuous jog - update position repeatedly
      this.jogInterval = setInterval(() => {
        this._updateJogPosition();
      }, 50); // Update every 50ms for smooth movement
    } else {
      // Incremental jog - single step
      this._updateJogPosition();
    }
  }

  async StopJog(): Promise<void> {
    if (this.jogInterval) {
      clearInterval(this.jogInterval);
      this.jogInterval = null;
    }
    this.currentJogDirection = null;
  }

  async KeepJogging(direction: JogDirection): Promise<void> {
    // Simulator doesn't need renewal - interval keeps running
    // This is a no-op for the simulator
  }

  private _updateJogPosition(): void {
    if (!this.currentJogDirection) return;

    const currentPos = ConfigurationState.Instance.currentMachinePoint;
    const config = ConfigurationState.Instance;

    // Get base increment from MachineData
    const baseIncrement = ConfigurationData.Instance.jogIncrement1x;

    // Apply speed multiplier (X1, X10, X100)
    const speedMultiplier = this.currentJogSpeed;

    // Apply fast jog multiplier if enabled (e.g., 2x for fast mode)
    const fastMultiplier = config.jogFastMode ? 2.0 : 1.0;

    // Calculate final increment
    const increment = baseIncrement * speedMultiplier * fastMultiplier;

    // Create new position based on direction
    let newPos = new CNCPoint(currentPos.x, currentPos.y, currentPos.z, currentPos.coordinateType);

    switch (this.currentJogDirection) {
      case JogDirection.XPlus:
        newPos.x += increment;
        break;
      case JogDirection.XMinus:
        newPos.x -= increment;
        break;
      case JogDirection.YPlus:
        newPos.y += increment;
        break;
      case JogDirection.YMinus:
        newPos.y -= increment;
        break;
      case JogDirection.ZPlus:
        newPos.z += increment;
        break;
      case JogDirection.ZMinus:
        newPos.z -= increment;
        break;
      case JogDirection.XPlusYPlus:
        newPos.x += increment;
        newPos.y += increment;
        break;
      case JogDirection.XPlusYMinus:
        newPos.x += increment;
        newPos.y -= increment;
        break;
      case JogDirection.XMinusYMinus:
        newPos.x -= increment;
        newPos.y -= increment;
        break;
      case JogDirection.XMinusYPlus:
        newPos.x -= increment;
        newPos.y += increment;
        break;
      case JogDirection.APlus:
        // A-axis not yet implemented
        return;
      case JogDirection.AMinus:
        // A-axis not yet implemented
        return;
    }

    // Update machine state
    ConfigurationState.Instance.currentMachinePoint = newPos;
  }

  async SetContinuousJog(isContinuous: boolean): Promise<void> {
    ConfigurationState.Instance.jogContinuousMode = isContinuous;
  }

  async SetFastJog(isFast: boolean): Promise<void> {
    ConfigurationState.Instance.jogFastMode = isFast;
  }

  async SetJogIncrementSpeed(speed: JogIncrementSpeed): Promise<void> {
    ConfigurationState.Instance.jogIncrementSpeed = speed;
  }
}
