import { Grid } from '@mui/material';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { OffsetEditor } from '../../../Common/OffsetEditor';

export function VerticalTableSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
                <ObserveState
                    key="vertical-table-width"
                    listenTo={machine}
                    properties={['verticalTableWidth']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Table Width"
                            value={machine.verticalTableWidth}
                            onChange={(value) => machine.verticalTableWidth = value}
                            margin="normal"
                            precision={1}
                            helperText="Width of the vertical table surface"
                        />
                    )}
                />

                <ObserveState
                    key="vertical-table-height"
                    listenTo={machine}
                    properties={['verticalTableHeight']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Table Height"
                            value={machine.verticalTableHeight}
                            onChange={(value) => machine.verticalTableHeight = value}
                            margin="normal"
                            precision={1}
                            helperText="Height of the vertical table surface"
                        />
                    )}
                />

                <ObserveState
                    key="vertical-table-thickness"
                    listenTo={machine}
                    properties={['verticalTableThickness']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Table Thickness"
                            value={machine.verticalTableThickness}
                            onChange={(value) => machine.verticalTableThickness = value}
                            margin="normal"
                            precision={1}
                            helperText="Thickness of the table material"
                        />
                    )}
                />
            </Grid>

            <Grid item xs={12} md={6}>
                <ObserveState
                    key="vertical-table-angle"
                    listenTo={machine}
                    properties={['verticalTableAngle']}
                    control={() => (
                        <NumberInput
                            fullWidth
                            label="Table Angle"
                            value={machine.verticalTableAngle}
                            onChange={(value) => machine.verticalTableAngle = value}
                            margin="normal"
                            precision={1}
                            helperText="Angle from horizontal (90° = vertical)"
                        />
                    )}
                />

                <ObserveState
                    key="vertical-table-offset"
                    listenTo={machine}
                    properties={['verticalTableOffset']}
                    control={() => (
                        <OffsetEditor
                            offset={machine.verticalTableOffset}
                            label="Position Offset from Bed Origin"
                            showLabel={true}
                            precision={1}
                            xLabel="X Offset"
                            yLabel="Y Offset"
                            zLabel="Z Offset"
                        />
                    )}
                />
            </Grid>
        </Grid>
    );
}
