import { IMachineInterface } from '../machine/IMachineInterface';
import { Configuration } from '../services/src/runtime';
import { LogCategory, Logger } from './Logger';

/**
 * Manages machine interface selection and configuration based on URL parameters
 */
export class MachineInterfaceManager {
  private static _instance: MachineInterfaceManager;
  private static _factories = new Map<string, () => IMachineInterface>();
  private _machineInterface: IMachineInterface | null = null;
  private _interfaceType: string = 'simulator';
  private _serverUrl: string | null = null;
  private _serviceConfiguration: Configuration | null = null;

  private constructor() { }

  public static get Instance(): MachineInterfaceManager {
    if (!MachineInterfaceManager._instance) {
      MachineInterfaceManager._instance = new MachineInterfaceManager();
    }
    return MachineInterfaceManager._instance;
  }

  /**
   * Register a factory for creating a machine interface implementation
   */
  public static registerFactory(name: string, factory: () => IMachineInterface): void {
    MachineInterfaceManager._factories.set(name, factory);
  }

  /**
   * Initialize the machine interface based on URL parameters and environment variables
   */
  public initialize(): void {
    try {
      // Parse URL parameters first (takes priority)
      const urlParams = new URLSearchParams(window.location.search);

      let serverUrl = urlParams.get('url_to_havencnc_server') || urlParams.get('havencnc_server_url');

      // If no URL parameter, check environment variable
      if (!serverUrl) {
        serverUrl = process.env.REACT_APP_HAVEN_CNC_SERVER_URL || null;
      }

      if (serverUrl) {
        // Clean up the server URL to ensure proper formatting
        serverUrl = serverUrl.trim(); // Remove whitespace

        // Validate the URL before using it
        try {
          const url = new URL(serverUrl); // This will throw if the URL is invalid

          // Ensure no trailing slash in the base path
          const cleanBasePath = url.origin + url.pathname.replace(/\/+$/, '');

          this._serverUrl = serverUrl;

          // Create service configuration with cleaned base URL
          this._serviceConfiguration = new Configuration({
            basePath: cleanBasePath,
          });

          // Use Centroid implementation
          const centroidFactory = MachineInterfaceManager._factories.get('centroid');
          if (centroidFactory) {
            this._machineInterface = centroidFactory();
            this._interfaceType = 'centroid';
          } else {
            Logger.Instance.logError(LogCategory.System, 'Centroid factory not registered, falling back to simulator');
            this._createSimulator();
          }
        } catch (urlError) {
          Logger.Instance.logError(LogCategory.System, `Invalid server URL "${serverUrl}":`, urlError);
          // Fall back to simulator
          this._createSimulator();
        }
      } else {
        // Use simulator implementation (default)
        this._createSimulator();
      }
    } catch (error) {
      Logger.Instance.logError(LogCategory.System, 'Error initializing machine interface:', error);
      // Fall back to simulator
      this._createSimulator();
    }
  }

  private _createSimulator(): void {
    const simulatorFactory = MachineInterfaceManager._factories.get('simulator');
    if (simulatorFactory) {
      this._machineInterface = simulatorFactory();
      this._interfaceType = 'simulator';
    } else {
      throw new Error('Simulator factory not registered');
    }
  }

  /**
   * Get the current machine interface instance
   */
  public getMachineInterface(): IMachineInterface {
    if (!this._machineInterface) {
      this.initialize();
    }
    return this._machineInterface!;
  }

  /**
   * Get the server URL if one was provided
   * Defaults to localhost:5000 if no URL is set
   */
  public getServerUrl(): string {
    if (!this._serverUrl) {
      // Default to localhost:5000 for development/local backend
      return 'http://localhost:5000';
    }
    return this._serverUrl;
  }

  /**
   * Get the service configuration for API calls
   * Defaults to localhost:5000 if no configuration is set
   */
  public getServiceConfiguration(): Configuration {
    if (!this._serviceConfiguration) {
      // Default to localhost:5000 for development/local backend
      return new Configuration({ basePath: 'http://localhost:5000' });
    }
    return this._serviceConfiguration;
  }

  /**
   * Check if we're using the Centroid implementation
   */
  public isUsingCentroid(): boolean {
    return this._interfaceType === 'centroid';
  }

  /**
   * Check if we're using the Simulator implementation
   */
  public isUsingSimulator(): boolean {
    return this._interfaceType === 'simulator';
  }

  /**
   * Get information about the current configuration
   */
  public getConfigurationInfo(): {
    usingCentroid: boolean;
    serverUrl: string | null;
    source: 'url_parameter' | 'environment' | 'none';
  } {
    const urlParams = new URLSearchParams(window.location.search);
    const urlServerUrl = urlParams.get('havencnc_server_url');
    const envServerUrl = process.env.REACT_APP_HAVEN_CNC_SERVER_URL;

    let source: 'url_parameter' | 'environment' | 'none' = 'none';

    if (urlServerUrl) {
      source = 'url_parameter';
    } else if (envServerUrl) {
      source = 'environment';
    }

    return {
      usingCentroid: this.isUsingCentroid(),
      serverUrl: this._serverUrl,
      source
    };
  }

  /**
   * Force reinitialization (useful for testing or configuration changes)
   */
  public reinitialize(): void {
    this._machineInterface = null;
    this._serverUrl = null;
    this._serviceConfiguration = null;
    this.initialize();
  }
}
