import { UserMessageQueue } from '../data/UserMessageQueue';
import { LogCategory, Logger } from '../utils/Logger';
import { ICNCProgramStorage, Storage } from './ICNCProgramStorage';

/**
 * Base class for CNC Program Storage implementations
 * Provides common export/import functionality that both Simulator and Centroid can use
 */
export abstract class BaseCNCProgramStorage implements ICNCProgramStorage {

    // Abstract methods that subclasses must implement
    abstract getMDIStorageNames(): Promise<string[]>;
    abstract getFlowStorageNames(): Promise<string[]>;
    abstract getStorageData(name: string): Promise<Storage | null>;
    abstract saveStorageData(storage: Storage): Promise<void>;
    abstract deleteStorageData(name: string): Promise<void>;

    // Default implementation for getAllStorageNames - can be overridden if needed
    async getAllStorageNames(): Promise<string[]> {
        const [flowNames, mdiNames] = await Promise.all([
            this.getFlowStorageNames(),
            this.getMDIStorageNames()
        ]);
        return [...flowNames, ...mdiNames].sort();
    }

    // Convenience method for subclasses that have a unified getStorageNames method
    protected async getStorageNames(): Promise<string[]> {
        return this.getAllStorageNames();
    }

    // Common implementation for action-related methods
    async getActionStorages(): Promise<Storage[]> {
        const names = await this.getStorageNames();
        const storages: Storage[] = [];

        for (const name of names) {
            const storage = await this.getStorageData(name);
            if (storage && storage.exposeAsAction) {
                storages.push(storage);
            }
        }

        return storages.sort((a, b) => a.categoryName.localeCompare(b.categoryName));
    }

    async getActionStorageNames(): Promise<string[]> {
        const storages = await this.getActionStorages();
        return storages.map(s => s.categoryName).sort();
    }

    // Common export functionality
    async exportAllAsJson(): Promise<string> {
        try {
            // Get all storage names
            const names = await this.getStorageNames();

            // Create a JSON export with all storage data
            const exportData: any = {
                version: '1.0',
                exportDate: new Date().toISOString(),
                storages: {}
            };

            // Fetch all storage data
            for (const name of names) {
                const storage = await this.getStorageData(name);
                if (storage) {
                    exportData.storages[name] = storage.toJSON();
                }
            }

            return JSON.stringify(exportData, null, 2);
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'Failed to export as JSON:', error);
            throw error;
        }
    }

    // Common import functionality
    async importFromJson(jsonData: string): Promise<void> {
        try {
            // Parse the JSON export data
            const exportData = JSON.parse(jsonData);

            // Import each storage from the export data
            if (exportData.storages) {
                for (const [name, storageData] of Object.entries(exportData.storages)) {
                    try {
                        const storage = new Storage();
                        storage.fromJSON(storageData);

                        await this.saveStorageData(storage);
                    } catch (error) {
                        Logger.Instance.logError(LogCategory.DataManager, `Failed to import storage '${name}':`, error);
                    }
                }
            }

        } catch (error) {
            const errorMessage = 'Failed to import JSON data';
            Logger.Instance.logError(LogCategory.DataManager, errorMessage, error);
            UserMessageQueue.Instance.addMessage(`❌ ${errorMessage}: ${error}`);
            throw error;
        }
    }
}