import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataElement } from '../data/DataElement';
import { Declaration } from '../data/Declaration';
import { IPLCElement, OutputState, OutputType, PLCRenderMode } from '../data/IPLCElement';
import { IPLCSource, PLCProgramType, PLCUtilities } from '../data/PLCUtilities';

/**
 * Base class for all PLC statement implementations
 * Implements IPLCElement to participate in the PLC element hierarchy
 */
export abstract class BasePLCStatement implements IPLCElement {
    protected _plcSource: IPLCSource | undefined;
    protected _parentElement: IPLCElement | undefined;  // Parent block that contains this statement
    protected _comment: string = '';       // Statement comment/description
    protected _enabled: boolean = true;     // Whether this statement is enabled/active
    protected _ordinal: number = 0;         // Sort order within parent block

    /**
     * Get the type of this PLC element
     */
    public getElementType(): 'statement' {
        return 'statement';
    }

    /**
     * Reset any cached/generated state before rendering or code generation
     * Default implementation does nothing - override in subclasses that need it
     */
    public preRenderReset(): void {
        // Default: no-op
    }

    /**
     * Get unique identifier for this statement
     * Subclasses can override to provide more specific IDs
     */
    public getElementId(): string {
        return `statement-${this.constructor.name}`;
    }

    /**
     * Get the parent element (block) that contains this statement
     */
    public getParentElement(): IPLCElement | undefined {
        return this._parentElement;
    }

    /**
     * Set the parent element (block) that contains this statement
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        this._parentElement = parent;
        // Clear cached plcSource so it gets resolved from new parent chain
        this._plcSource = undefined;
        // Subclasses should override this and cascade to their child elements
    }

    /**
     * Get the PLC source (root program) for this statement
     * Resolves by walking up parent chain
     */
    public get plcSource(): IPLCSource | undefined {
        const resolved = PLCUtilities.resolvePLCSource(this, false);
        return resolved !== null ? resolved : undefined;
    }

    /**
     * Get the statement comment/description
     */
    public get comment(): string {
        return this._comment;
    }

    /**
     * Set the statement comment/description
     */
    public set comment(value: string) {
        this._comment = value;
        StateManager.propertyChanged(this, 'comment');
    }

    /**
     * Get whether this statement is enabled
     */
    public get enabled(): boolean {
        return this._enabled;
    }

    /**
     * Set whether this statement is enabled
     */
    public set enabled(value: boolean) {
        this._enabled = value;
        StateManager.propertyChanged(this, 'enabled');
        this.notifyProgramValidationChanged();
    }

    /**
     * Get the ordinal (sort order) within parent block
     */
    public get ordinal(): number {
        return this._ordinal;
    }

    /**
     * Set the ordinal (sort order) within parent block
     */
    public set ordinal(value: number) {
        this._ordinal = value;
        StateManager.propertyChanged(this, 'ordinal');
    }

    /**
     * Notify the parent program that validation state may have changed
     * This propagates validation changes up to the program level so sidebar indicators update
     */
    protected notifyProgramValidationChanged(): void {
        // Walk up parent chain: Statement -> Block -> Stage -> Program
        let current: IPLCElement | undefined = this._parentElement;
        while (current) {
            if ('notifyValidationChanged' in current) {
                (current as any).notifyValidationChanged();
                break;
            }
            current = current.getParentElement();
        }
    }

    /**
     * Check if this statement is disabled
     * A statement is disabled if:
     * 1. Its enabled property is false, OR
     * 2. The parent is rendering it with Disabled mode, OR
     * 3. (For SystemDefault statements merged into System) It references inputs/outputs
     *    that are not available in the System PLC
     * 
     * Special handling for LogicStatement (IF-THEN):
     * - If a condition references unavailable declarations, that condition is disabled
     * - If a predicate references unavailable declarations, that predicate is disabled
     * - If a condition group has no enabled conditions, the condition group is disabled
     * - If ALL conditions are disabled OR ALL predicates are disabled, the entire statement is disabled
     * 
     * @param mode The render mode from parent
     * @param targetProgramType The target program type context (e.g., System when SystemDefault blocks are rendered in System)
     * @returns True if statement should be treated as disabled
     */
    public isDisabled(mode: PLCRenderMode, targetProgramType: PLCProgramType): boolean {

        // 1. Check parent render mode first - if parent is disabled, we are disabled
        if (mode === PLCRenderMode.Disabled) {
            return true;
        }

        // 2. Check enabled property
        if (!this._enabled) {
            return true;
        }

        // 3. Check if statement uses unavailable declarations (SystemDefault -> System merge)
        // Only applies when a SystemDefault statement is being used in System context
        if (!this.plcSource) {
            // Log parent chain to diagnose plcSource propagation issue
            console.error(`[BasePLCStatement.isDisabled] plcSource is null for statement ${this.constructor.name}`);
            console.error(`[BasePLCStatement.isDisabled] Parent chain:`);
            let current: IPLCElement | undefined = this._parentElement;
            let depth = 0;
            while (current && depth < 10) {
                const elementType = current.getElementType ? current.getElementType() : 'unknown';
                const elementId = current.getElementId ? current.getElementId() : 'unknown';
                const hasPlcSource = 'plcSource' in current;
                const plcSourceValue = hasPlcSource ? (current as any).plcSource?.getProgramType() : 'N/A';
                console.error(`  [${depth}] ${elementType} "${elementId}" - hasPlcSource=${hasPlcSource}, plcSource=${plcSourceValue}`);
                current = current.getParentElement ? current.getParentElement() : undefined;
                depth++;
            }
            throw new Error(`[BasePLCStatement.isDisabled] plcSource is null for statement ${this.constructor.name}. This should never happen - plcSource must be set during construction or addition to program.`);
        }

        if (this.plcSource && this.plcSource.getProgramType() === PLCProgramType.SystemDefault
            && targetProgramType === PLCProgramType.SystemDefault) {
            return false; // skip the data type checks for these
        }

        if (this.plcSource && this.plcSource.getProgramType() === PLCProgramType.System) {
            return false; // System statements skip validation checks - validation will catch issues
        }

        const parentProgramType = targetProgramType;

        if (!this.plcSource) {
            throw new Error(`[BasePLCStatement.isDisabled] plcSource is null when checking program type for statement ${this.constructor.name}`);
        }

        const currentProgramType = this.plcSource.getProgramType();

        // SystemDefault statement being used in System - check if inputs/outputs are defined in System
        const dataElements = this.getDataElements();

        for (const element of dataElements) {
            if (PLCUtilities.shouldBeDisabledDueToDeclarations(element, parentProgramType, currentProgramType)) {
                return true; // Missing declaration, disable statement
            }
        }

        return false;
    }

    /**
     * Determine if this statement should be output
     * Default implementation: disabled statements are output as disabled, enabled statements output normally
     */
    public shouldOutput(outputType: OutputType, availableDeclarations?: string[]): OutputState {
        if (!this.plcSource) {
            throw new Error(`[BasePLCStatement.shouldOutput] plcSource is null for statement ${this.constructor.name}. This should never happen - plcSource must be set before calling shouldOutput().`);
        }

        // TODO: Define proper output logic later
        return OutputState.Output;
    }

    /**
     * Validate the statement configuration
     * @returns Validation error message, or undefined if valid
     */
    public abstract validate(): string | undefined;

    /**
     * Serialize the statement to JSON
     */
    public abstract toJSON(): any;

    /**
     * Deserialize the statement from JSON
     */
    public abstract fromJSON(data: any): void;

    /**
     * Clone the statement
     */
    public abstract clone(): BasePLCStatement;

    /**
     * Render the statement (required by IPLCElement)
     * Returns JSX representation - must be implemented by subclasses
     * IMPORTANT: Implementations should throw an error if plcSource is null when accessed
     * @param mode Rendering mode (Edit, ReadOnly, or Disabled)
     * @param targetProgramType The program type context for rendering
     */
    public abstract render(mode: PLCRenderMode, targetProgramType: PLCProgramType): any;

    /**
     * Get declarations used by this statement - must be implemented by subclasses
     */
    public abstract getUsedDeclarations(): Declaration[];

    /**
     * Get declarations added by this statement - must be implemented by subclasses
     * Statements that need unique IDs should call StatementIdRegistry.getId(this) internally
     */
    public abstract getAddedDeclarations(): Declaration[];

    /**
     * Get PLC logic code - must be implemented by subclasses
     * Statements that need unique IDs should call StatementIdRegistry.getId(this) internally
     * @param availableDeclarations Array of declaration names that are available/defined
     */
    public abstract getPLCLogic(availableDeclarations: string[]): string[];

    /**
     * Get validation issues - must be implemented by subclasses
     */
    public abstract getValidationIssues(): any[];

    /**
     * Get all data elements used by this statement
     * MUST be implemented by each statement class to explicitly return its data elements
     * This prevents accidental traversal into React elements and other unintended objects
     * @returns Array of all DataElement instances in this statement
     */
    public abstract getDataElements(): DataElement[];

    /**
     * Get a short, single-line description of this statement for display in tree views
     * Example: "if (havenreset is set) then..." or "Set DustCollector output"
     * @returns A human-readable summary of the statement's action
     */
    public abstract getShortDescription(): string;
}
