import { Box, Button, CircularProgress, Typography } from '@mui/material';
import React from 'react';
import { CNCPoint } from '../../../../data/CNCPoint';
import { CoordinateType } from '../../../../data/Common/CoordinateType';
import { Tool } from '../../../../data/Common/Tool';
import { ConfigurationData } from '../../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { MovementCoordinateType } from '../../../../machine/ICNCMovement';
import { Machine } from '../../../../machine/Machine';
import { LogCategory, Logger } from '../../../../utils/Logger';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { ChangeToolWizard } from '../ChangeToolWizard';
import { SameSpecificationStep } from './SameSpecificationStep';

export class MoveToChangeLocationStep extends WizardStep {
    private currentTool: Tool | null;
    private isMoving: boolean = false;
    private hasMoved: boolean = false;

    constructor(wizard: ChangeToolWizard, currentTool: Tool | null, previousStep: WizardStep | null) {
        super(wizard, previousStep);
        this.currentTool = currentTool;
    }

    public getTitle(): string {
        return 'Move to Tool Change Location';
    }

    public nextStep(): WizardStep | null {
        if (this.hasMoved && !this.isMoving) {
            return new SameSpecificationStep(this.wizard as ChangeToolWizard, this.currentTool, this);
        }
        return null;
    }

    public backStep(): WizardStep | null {
        return null; // First step, no back
    }

    private async moveToChangeLocation(): Promise<void> {
        this.isMoving = true;
        StateManager.propertyChanged(this, 'isMoving');

        try {
            const machine = Machine.getInstance();
            const machineData = MachineData.Instance;
            const changeLocation = machineData.manualToolChangeLocationFromMZ;


            // Create point and move using machine coordinates
            const targetPoint = new CNCPoint(changeLocation.x, changeLocation.y, changeLocation.z, CoordinateType.MachineZero);
            await machine.movement.MoveTo(targetPoint, MovementCoordinateType.Machine, 200);

            this.hasMoved = true;
            this.isMoving = false;
            StateManager.propertyChanged(this, 'hasMoved');
            StateManager.propertyChanged(this, 'isMoving');

            // Automatically advance to next step after move completes
            setTimeout(() => {
                this.wizard.advanceToNextStep();
            }, 100);
        } catch (error) {
            Logger.Instance.logError(LogCategory.Tools, 'Error moving to tool change location:', error);
            this.isMoving = false;
            StateManager.propertyChanged(this, 'isMoving');
            throw error;
        }
    }

    public render(): React.ReactNode {
        return (
            <ObserveState
                key="move-to-change-location-step"
                listenTo={this}
                properties={['isMoving', 'hasMoved']}
                control={() => {
                    const config = ConfigurationData.Instance;
                    const colors = ConfigurationDataColors.Instance;
                    const machineData = MachineData.Instance;
                    const location = machineData.manualToolChangeLocationFromMZ;

                    return (
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
                            {/* Instructions */}
                            <Box sx={{
                                p: 2,
                                backgroundColor: colors.primaryColor + '15',
                                borderRadius: 1,
                                borderLeft: `4px solid ${colors.primaryColor}`
                            }}>
                                <Typography variant="h6" sx={{ mb: 1, fontWeight: 'bold' }}>
                                    Tool Change Instructions
                                </Typography>
                                <Typography variant="body1" sx={{ mb: 1 }}>
                                    1. Click "Move to Change Location" to move the spindle to the tool change position
                                </Typography>
                                <Typography variant="body1" sx={{ mb: 1 }}>
                                    2. Wait for the machine to complete the move
                                </Typography>
                                <Typography variant="body1">
                                    3. Change the tool manually, then click Continue
                                </Typography>
                            </Box>

                            {/* Current Tool Info */}
                            {this.currentTool && (
                                <Box sx={{
                                    p: 2,
                                    border: `1px solid ${colors.borderColor}`,
                                    borderRadius: 1
                                }}>
                                    <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 0.5 }}>
                                        Current Tool
                                    </Typography>
                                    <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
                                        T{(this.currentTool.toolNumber ?? 0).toString().padStart(2, '0')} - {this.currentTool.displayName}
                                    </Typography>
                                </Box>
                            )}

                            {/* Tool Change Location */}
                            <Box sx={{
                                p: 2,
                                border: `1px solid ${colors.borderColor}`,
                                borderRadius: 1
                            }}>
                                <Typography variant="subtitle2" sx={{ color: 'text.secondary', mb: 1 }}>
                                    Tool Change Location (Machine Coordinates)
                                </Typography>
                                <Box sx={{ display: 'flex', gap: 2 }}>
                                    <Box>
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>X</Typography>
                                        <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                            {location.x.toFixed(3)}"
                                        </Typography>
                                    </Box>
                                    <Box>
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>Y</Typography>
                                        <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                            {location.y.toFixed(3)}"
                                        </Typography>
                                    </Box>
                                    <Box>
                                        <Typography variant="caption" sx={{ color: 'text.secondary' }}>Z</Typography>
                                        <Typography variant="body1" sx={{ fontWeight: 'bold' }}>
                                            {location.z.toFixed(3)}"
                                        </Typography>
                                    </Box>
                                </Box>
                            </Box>

                            {/* Action Buttons */}
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 'auto' }}>
                                <Button
                                    variant="contained"
                                    size="large"
                                    onClick={() => this.moveToChangeLocation()}
                                    disabled={this.isMoving || this.hasMoved}
                                    startIcon={this.isMoving ? <CircularProgress size={20} color="inherit" /> : undefined}
                                    sx={{ py: 1.5 }}
                                >
                                    {this.isMoving ? 'Moving...' : this.hasMoved ? 'At Change Location' : 'Move to Change Location'}
                                </Button>
                            </Box>
                        </Box>
                    );
                }}
            />
        );
    }
}
