import { Close as CloseIcon } from '@mui/icons-material';
import { Box, Button, Dialog, DialogActions, DialogContent, DialogTitle, IconButton, Tab, Tabs } from '@mui/material';
import { useState } from 'react';
import { SimulatorViewData } from '../data/Common/SimulatorViewData';
import { ConfigurationDataColors } from '../data/ConfigurationDataColors';
import { ConfigurationState } from '../data/ConfigurationState';
import { Job } from '../data/Job';
import { MachineData } from '../data/Machine/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { FullSizeCNCViewer } from './MachineViewer/FullSizeCNCViewer';

interface SimulatorDialogProps {
    open: boolean;
    onClose: () => void;
    simulatorViewData: SimulatorViewData;
    maxWidth?: 'sm' | 'md' | 'lg' | 'xl';
    showDryRunGCode?: boolean;
}

export function SimulatorDialog({ open, onClose, simulatorViewData, maxWidth = 'xl', showDryRunGCode = false }: SimulatorDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const machineState = MachineStateData.Instance;
    const machineData = MachineData.Instance;
    const job = ConfigurationState.Instance.currentJob || new Job();
    const [activeTab, setActiveTab] = useState(0);

    // Get dry run G-code if needed
    const dryRunGCode = showDryRunGCode && job ? job.getDryRunGCode() : '';
    const hasOriginalGCode = job && job.gcode && job.gcode.length > 0;

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth={maxWidth}
            fullWidth
            PaperProps={{ sx: { height: '90vh' } }}
        >
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                Job Simulator
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: `${colors.lightTextColor}1A`
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>
            <DialogContent sx={{ p: 0, height: '100%', display: 'flex', flexDirection: 'column' }}>
                {showDryRunGCode && (
                    <Tabs
                        value={activeTab}
                        onChange={(_, newValue) => setActiveTab(newValue)}
                        sx={{
                            borderBottom: 1,
                            borderColor: 'divider',
                            backgroundColor: colors.lightBackgroundColor,
                            minHeight: 48
                        }}
                    >
                        <Tab label="3D View" />
                        <Tab label="Dry Run G-Code" />
                    </Tabs>
                )}

                {/* 3D View Tab */}
                {(!showDryRunGCode || activeTab === 0) && (
                    <Box sx={{ flex: 1, minHeight: 0 }}>
                        <FullSizeCNCViewer
                            simulatorViewData={simulatorViewData}
                            machineState={machineState}
                            machineData={machineData}
                            job={job}
                        />
                    </Box>
                )}

                {/* G-Code Tab */}
                {showDryRunGCode && activeTab === 1 && (
                    <Box
                        sx={{
                            flex: 1,
                            overflow: 'auto',
                            backgroundColor: colors.darkBackgroundColor,
                            color: colors.lightTextColor,
                            fontFamily: 'monospace',
                            fontSize: '14px',
                            p: 2
                        }}
                    >
                        {!hasOriginalGCode ? (
                            <Box sx={{ color: colors.errorColor, p: 2 }}>
                                <div>⚠️ No G-code loaded in job</div>
                                <div style={{ marginTop: '8px', fontSize: '12px', color: colors.mutedTextColor }}>
                                    Original G-code: {job.gcode ? `${job.gcode.length} characters` : 'empty'}
                                </div>
                            </Box>
                        ) : !dryRunGCode ? (
                            <Box sx={{ color: colors.errorColor, p: 2 }}>
                                <div>⚠️ Dry run G-code generation returned empty</div>
                                <div style={{ marginTop: '8px', fontSize: '12px', color: colors.mutedTextColor }}>
                                    <div>Original G-code: {job.gcode.length} characters</div>
                                    <div>Toolpath Mode: {String(job.dryRunToolpathMode)}</div>
                                    <div>Tool Mode: {String(job.dryRunToolMode)}</div>
                                    <div>Run at Z: {job.dryRunZ}</div>
                                    <div>Change Speed: {job.dryRunChangeSpeed ? 'Yes' : 'No'}</div>
                                    <div>Speed: {job.dryRunSpeed}</div>
                                </div>
                            </Box>
                        ) : (
                            <Box>
                                <Box sx={{ color: colors.infoColor, p: 1, borderBottom: `1px solid ${colors.darkTextColor}`, fontSize: '12px' }}>
                                    Dry Run G-code: {dryRunGCode.split('\n').length} lines, {dryRunGCode.length} characters
                                </Box>
                                <pre style={{ margin: 0, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
                                    {dryRunGCode}
                                </pre>
                            </Box>
                        )}
                    </Box>
                )}
            </DialogContent>
            <DialogActions sx={{ p: 2, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    onClick={onClose}
                    variant="contained"
                    sx={{
                        backgroundColor: colors.primaryColor,
                        '&:hover': {
                            backgroundColor: colors.primaryColor,
                            opacity: 0.9
                        }
                    }}
                >
                    Close
                </Button>
            </DialogActions>
        </Dialog>
    );
}
