import { Add as AddIcon, Close as CloseIcon, Delete as DeleteIcon } from '@mui/icons-material';
import { Autocomplete, Box, Button, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControl, IconButton, InputLabel, MenuItem, Select, SelectChangeEvent, TextField, Typography } from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { M94M95Trigger } from '../data/triggers/M94M95Trigger';

interface M94M95TriggerDialogProps {
    open: boolean;
    trigger: M94M95Trigger | null;
    program: PLCProgram;
    onClose: () => void;
    onSave: (trigger: M94M95Trigger) => void;
}

/**
 * Dialog for editing or creating an M94/M95 trigger
 */
export function M94M95TriggerDialog({ open, trigger, program, onClose, onSave }: M94M95TriggerDialogProps): React.ReactElement {
    const [workingTrigger, setWorkingTrigger] = useState<M94M95Trigger>(new M94M95Trigger());
    const [editingName, setEditingName] = useState('');
    const [outputInput, setOutputInput] = useState('');
    const [autoNamed, setAutoNamed] = useState(true);
    const colors = ConfigurationDataColors.Instance;

    // Get list of used trigger numbers (excluding the current one being edited)
    // If this is System program, also include numbers used in SystemDefault
    const usedNumbers = (() => {
        const currentProgramNumbers = program.m94m95Triggers
            .filter(t => trigger ? t.number !== trigger.number : true)
            .map(t => t.number);

        // If System program, also include SystemDefault's trigger numbers
        if (program.type === PLCProgramType.System) {
            const systemDefault = PLCProgram.Instance(PLCProgramType.SystemDefault);
            const systemDefaultNumbers = systemDefault.m94m95Triggers.map(t => t.number);
            return [...new Set([...currentProgramNumbers, ...systemDefaultNumbers])];
        }

        return currentProgramNumbers;
    })();

    // Reset form when dialog opens or trigger changes
    useEffect(() => {
        if (open) {
            if (trigger) {
                setWorkingTrigger(trigger.clone());
                // Remove _MM suffix for editing
                let name = trigger.name;
                if (name.endsWith('_MM')) {
                    name = name.slice(0, -3);
                }
                setEditingName(name);
                setAutoNamed(false);
            } else {
                const newTrigger = new M94M95Trigger();
                newTrigger.number = 1;
                newTrigger.outputs = [];
                setWorkingTrigger(newTrigger);
                setEditingName('');
                setAutoNamed(true);
            }
            setOutputInput('');
        }
    }, [open, trigger]);

    // Generate auto name when number changes
    useEffect(() => {
        if (autoNamed && workingTrigger.number) {
            setEditingName(`M${workingTrigger.number}`);
        }
    }, [workingTrigger.number, autoNamed]);

    // Get available output names from the program
    const availableOutputs = program.outputs.map(output => output.name).filter(name => name);

    const handleNameChange = (value: string) => {
        setEditingName(value);
        setAutoNamed(false); // Disable auto-naming once user manually edits
    };

    const handleNameFocus = () => {
        // Remove _MM suffix when focusing
        let name = editingName;
        if (name.endsWith('_MM')) {
            name = name.slice(0, -3);
        }
        setEditingName(name);
    };

    const handleNameBlur = () => {
        // For M## format, leave as-is; otherwise add _MM suffix and uppercase
        let name = editingName.trim();
        if (name) {
            const mNumberPattern = /^M\d+$/i;
            if (mNumberPattern.test(name)) {
                // Keep M## format as-is (just uppercase)
                name = name.toUpperCase();
            } else {
                // Custom name - add _MM suffix
                name = name.toUpperCase();
                if (!name.endsWith('_MM')) {
                    name = name + '_MM';
                }
            }
            workingTrigger.name = name;
            setEditingName(name);
        }
    };

    const handleNumberChange = (event: SelectChangeEvent<number>) => {
        const num = event.target.value as number;
        workingTrigger.number = num;
    };

    const handleAddOutput = (outputName: string) => {
        if (outputName && !workingTrigger.outputs.includes(outputName)) {
            workingTrigger.outputs = [...workingTrigger.outputs, outputName];
            setOutputInput('');
        }
    };

    const handleRemoveOutput = (outputName: string) => {
        workingTrigger.outputs = workingTrigger.outputs.filter(o => o !== outputName);
    };

    const handleSave = () => {
        // Check for duplicate trigger number
        const isDuplicate = program.isTriggerNumberUsed(workingTrigger.number, trigger || undefined);
        if (isDuplicate) {
            alert(`Trigger number ${workingTrigger.number} is already in use by another trigger.`);
            return;
        }

        // Ensure name has proper format/suffix
        let finalName = editingName.trim();
        const mNumberPattern = /^M\d+$/i;
        if (mNumberPattern.test(finalName)) {
            finalName = finalName.toUpperCase();
        } else {
            finalName = finalName.toUpperCase();
            if (!finalName.endsWith('_MM')) {
                finalName = finalName + '_MM';
            }
        }
        workingTrigger.name = finalName;

        onSave(workingTrigger);
    };

    const isValid = editingName.trim() !== '' && workingTrigger.number >= 1 && workingTrigger.number <= 128;

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="sm"
            fullWidth
        >
            <DialogTitle sx={{
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                backgroundColor: colors.primaryColor,
                color: colors.lightTextColor,
                py: 2,
                px: 3
            }}>
                {trigger ? 'Edit M94/M95 Trigger' : 'Add M94/M95 Trigger'}
                <IconButton
                    onClick={onClose}
                    size="small"
                    sx={{
                        color: colors.lightTextColor,
                        '&:hover': {
                            backgroundColor: colors.lightOverlay
                        }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <ObserveState
                key="m94m95-trigger-dialog-form"
                listenTo={workingTrigger}
                properties={['name', 'description', 'number', 'outputs', 'activeText', 'inactiveText', 'onCommand', 'offCommand']}
                control={() => (
                    <>
                        <DialogContent dividers sx={{ pt: 3 }}>
                            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5 }}>
                                <TextField
                                    label="Name"
                                    value={editingName}
                                    onChange={(e) => handleNameChange(e.target.value)}
                                    onFocus={handleNameFocus}
                                    onBlur={handleNameBlur}
                                    fullWidth
                                    placeholder="M1"
                                    helperText="Unique identifier for this trigger. _MM suffix will be added for custom names (M## format is left as-is)."
                                />

                                <FormControl fullWidth>
                                    <InputLabel>Trigger Number</InputLabel>
                                    <Select
                                        value={workingTrigger.number}
                                        onChange={handleNumberChange}
                                        label="Trigger Number"
                                    >
                                        {Array.from({ length: 128 }, (_, i) => i + 1).map(num => (
                                            <MenuItem
                                                key={num}
                                                value={num}
                                                disabled={usedNumbers.includes(num)}
                                            >
                                                {num} {usedNumbers.includes(num) ? '(In use)' : ''}
                                            </MenuItem>
                                        ))}
                                    </Select>
                                    <Typography variant="caption" color="textSecondary" sx={{ mt: 0.5, ml: 1.5 }}>
                                        Trigger number (1-128) used in M94/## and M95/## commands
                                    </Typography>
                                </FormControl>

                                <TextField
                                    label="Description"
                                    value={workingTrigger.description}
                                    onChange={(e) => workingTrigger.description = e.target.value}
                                    fullWidth
                                    multiline
                                    rows={2}
                                    placeholder="What does this trigger control?"
                                />

                                <TextField
                                    label="Active Text"
                                    value={workingTrigger.activeText}
                                    onChange={(e) => workingTrigger.activeText = e.target.value}
                                    fullWidth
                                    placeholder="Is Active"
                                    helperText="Text to display when M94 is triggered (e.g., 'Is Active', 'ON', 'enabled')"
                                />

                                <TextField
                                    label="Inactive Text"
                                    value={workingTrigger.inactiveText}
                                    onChange={(e) => workingTrigger.inactiveText = e.target.value}
                                    fullWidth
                                    placeholder="Is Inactive"
                                    helperText="Text to display when M95 is triggered (e.g., 'Is Inactive', 'OFF', 'disabled')"
                                />

                                <Box sx={{ display: 'flex', gap: 2 }}>
                                    <TextField
                                        label="ON M-Code"
                                        value={workingTrigger.onCommand}
                                        onChange={(e) => workingTrigger.onCommand = e.target.value.toUpperCase()}
                                        fullWidth
                                        placeholder="M94"
                                        helperText="M-code to turn ON outputs"
                                    />
                                    <TextField
                                        label="OFF M-Code"
                                        value={workingTrigger.offCommand}
                                        onChange={(e) => workingTrigger.offCommand = e.target.value.toUpperCase()}
                                        fullWidth
                                        placeholder="M95"
                                        helperText="M-code to turn OFF outputs"
                                    />
                                </Box>

                                <Box sx={{ border: `1px solid ${colors.borderColor}`, borderRadius: 1, p: 2 }}>
                                    <Typography variant="subtitle2" gutterBottom>
                                        Output Mapping
                                    </Typography>
                                    <Typography variant="caption" color="textSecondary" sx={{ display: 'block', mb: 2 }}>
                                        Specify which output(s) this trigger controls. You can select from existing outputs or type custom names.
                                    </Typography>

                                    {/* Output Input with Autocomplete */}
                                    <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                                        <Autocomplete
                                            freeSolo
                                            options={availableOutputs}
                                            inputValue={outputInput}
                                            onInputChange={(_, newValue) => setOutputInput(newValue)}
                                            onChange={(_, newValue) => {
                                                if (newValue && typeof newValue === 'string') {
                                                    handleAddOutput(newValue);
                                                }
                                            }}
                                            renderInput={(params) => (
                                                <TextField
                                                    {...params}
                                                    label="Add Output"
                                                    placeholder="Type or select output name"
                                                    size="small"
                                                    onKeyDown={(e) => {
                                                        if (e.key === 'Enter' && outputInput.trim()) {
                                                            e.preventDefault();
                                                            handleAddOutput(outputInput);
                                                        }
                                                    }}
                                                />
                                            )}
                                            sx={{ flex: 1 }}
                                            ListboxProps={{
                                                style: { maxHeight: '200px' }
                                            }}
                                            openOnFocus
                                        />
                                        <Button
                                            variant="contained"
                                            startIcon={<AddIcon />}
                                            onClick={() => handleAddOutput(outputInput)}
                                            disabled={!outputInput}
                                            sx={{
                                                backgroundColor: colors.primaryColor,
                                                '&:hover': {
                                                    backgroundColor: colors.primaryColor,
                                                    opacity: 0.9,
                                                },
                                            }}
                                        >
                                            Add
                                        </Button>
                                    </Box>

                                    {/* Current Outputs List */}
                                    <Box sx={{
                                        minHeight: 100,
                                        p: 1.5,
                                        border: `1px solid ${colors.borderColor}`,
                                        borderRadius: 1,
                                        backgroundColor: colors.lightBackgroundColor,
                                    }}>
                                        {workingTrigger.outputs.length === 0 ? (
                                            <Typography variant="body2" color="textSecondary" fontStyle="italic" textAlign="center">
                                                No outputs assigned
                                            </Typography>
                                        ) : (
                                            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                                                {workingTrigger.outputs.map((output, index) => (
                                                    <Chip
                                                        key={index}
                                                        label={output}
                                                        onDelete={() => handleRemoveOutput(output)}
                                                        deleteIcon={<DeleteIcon />}
                                                        sx={{
                                                            backgroundColor: colors.lightTextColor,
                                                            border: `1px solid ${colors.borderColor}`,
                                                        }}
                                                    />
                                                ))}
                                            </Box>
                                        )}
                                    </Box>

                                    <Typography variant="caption" color="textSecondary" sx={{ display: 'block', mt: 1 }}>
                                        Use {workingTrigger.onCommand}/{workingTrigger.number} to turn ON and {workingTrigger.offCommand}/{workingTrigger.number} to turn OFF these outputs
                                    </Typography>
                                </Box>
                            </Box>
                        </DialogContent>

                        <DialogActions>
                            <Button onClick={onClose}>
                                Cancel
                            </Button>
                            <Button
                                onClick={handleSave}
                                variant="contained"
                                disabled={!isValid}
                                sx={{
                                    backgroundColor: colors.primaryColor,
                                    '&:hover': {
                                        backgroundColor: colors.primaryColor,
                                        opacity: 0.9,
                                    },
                                }}
                            >
                                Save
                            </Button>
                        </DialogActions>
                    </>
                )}
            />
        </Dialog>
    );
}
