import { StateManager } from './statemanager/StateManager';

/**
 * Singleton manager for centralized tooltip display
 * Prevents duplicate tooltips and ensures proper cleanup
 */
export class TooltipManager {
    private static _instance: TooltipManager;

    private _tooltipContent: React.ReactNode = null;
    private _anchorPosition: { top: number; left: number } | null = null;
    private _isOpen: boolean = false;
    private _keepOpen: boolean = false;
    private _hideTimeout: NodeJS.Timeout | null = null;

    private constructor() {
        // Private constructor for singleton
    }

    public static get Instance(): TooltipManager {
        if (!TooltipManager._instance) {
            TooltipManager._instance = new TooltipManager();
        }
        return TooltipManager._instance;
    }

    /**
     * Show a tooltip at the specified position
     * @param content React element to display in tooltip
     * @param anchorPosition Position where tooltip should appear
     */
    public showTooltip(content: React.ReactNode, anchorPosition: { top: number; left: number }): void {
        // Clear any pending hide timeout - new tooltip should show immediately
        if (this._hideTimeout) {
            clearTimeout(this._hideTimeout);
            this._hideTimeout = null;
        }

        this._tooltipContent = content;
        this._anchorPosition = anchorPosition;
        this._isOpen = true;
        this._keepOpen = false;
        StateManager.propertyChanged(this, 'isOpen');
        StateManager.propertyChanged(this, 'tooltipContent');
        StateManager.propertyChanged(this, 'anchorPosition');
    }

    /**
     * Keep the tooltip open (called when hovering over the tooltip itself)
     */
    public keepTooltipOpen(): void {
        this._keepOpen = true;
        // Clear any pending hide timeout
        if (this._hideTimeout) {
            clearTimeout(this._hideTimeout);
            this._hideTimeout = null;
        }
    }

    /**
     * Hide the current tooltip with a delay to allow mouse movement to tooltip
     * @param delay Delay in milliseconds (default 300ms)
     */
    public hideTooltipWithDelay(delay: number = 300): void {
        // Clear any existing timeout
        if (this._hideTimeout) {
            clearTimeout(this._hideTimeout);
        }

        // Set new timeout to hide
        this._hideTimeout = setTimeout(() => {
            this.hideTooltip();
        }, delay);
    }

    /**
     * Hide the current tooltip
     */
    public hideTooltip(): void {
        // Clear any pending hide timeout
        if (this._hideTimeout) {
            clearTimeout(this._hideTimeout);
            this._hideTimeout = null;
        }

        // Reset keepOpen flag and hide
        this._keepOpen = false;
        this._isOpen = false;
        this._tooltipContent = null;
        this._anchorPosition = null;
        StateManager.propertyChanged(this, 'isOpen');
        StateManager.propertyChanged(this, 'tooltipContent');
        StateManager.propertyChanged(this, 'anchorPosition');
    }

    /**
     * Get whether tooltip is currently open
     */
    public get isOpen(): boolean {
        return this._isOpen;
    }

    /**
     * Get current tooltip content
     */
    public get tooltipContent(): React.ReactNode {
        return this._tooltipContent;
    }

    /**
     * Get current anchor position
     */
    public get anchorPosition(): { top: number; left: number } | null {
        return this._anchorPosition;
    }
}
