import { Add as AddIcon, Close as CloseIcon, KeyboardReturn as NewLineIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    Paper,
    Typography
} from '@mui/material';
import React, { useEffect, useRef, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { PLCRenderMode } from '../data/IPLCElement';
import { PLCProgramType } from '../data/PLCUtilities';
import { DataElementPiece, NewLinePiece, ScriptPiece, TextPiece } from './ScriptPiece';
import { ScriptStatement } from './ScriptStatement';

interface ScriptStatementDialogProps {
    open: boolean;
    statement: ScriptStatement;
    onClose: () => void;
    onSave: () => void;
}

/**
 * Dialog for editing script statements
 * Provides a rich text editor with inline data element references
 */
export function ScriptStatementDialog({ open, statement, onClose, onSave }: ScriptStatementDialogProps) {
    const colors = ConfigurationDataColors.Instance;
    const [pieces, setPieces] = useState<ScriptPiece[]>([]);
    const [focusedPieceIndex, setFocusedPieceIndex] = useState<number | null>(null);
    const [lastFocusedPieceIndex, setLastFocusedPieceIndex] = useState<number | null>(null);
    const [cursorPosition, setCursorPosition] = useState<number>(0);
    const [pendingFocus, setPendingFocus] = useState<{ index: number; position?: number } | null>(null);
    const textareaRefs = useRef<Map<number, HTMLTextAreaElement>>(new Map());

    /**
     * Centralized focus management - sets focus to a specific piece and cursor position
     */
    const focusPiece = (pieceIndex: number, cursorPos?: number) => {
        setFocusedPieceIndex(pieceIndex);
        setLastFocusedPieceIndex(pieceIndex);
        setPendingFocus({ index: pieceIndex, position: cursorPos });
    };

    // Handle pending focus after React renders
    useEffect(() => {
        if (pendingFocus !== null) {
            const textarea = textareaRefs.current.get(pendingFocus.index);
            if (textarea) {
                textarea.focus();
                const position = pendingFocus.position !== undefined ? pendingFocus.position : textarea.value.length;
                textarea.setSelectionRange(position, position);
                setCursorPosition(position);
            }
            setPendingFocus(null);
        }
    }, [pendingFocus, pieces]); // Trigger when pendingFocus is set or pieces change

    useEffect(() => {
        if (open) {
            setPieces([...statement.pieces]);
            // Focus the first text piece after a short delay
            setTimeout(() => {
                const firstTextIndex = statement.pieces.findIndex(p => p instanceof TextPiece);
                if (firstTextIndex !== -1) {
                    focusPiece(firstTextIndex, 0);
                }
            }, 100);
        }
    }, [open, statement]);

    const handleSave = () => {
        statement.pieces = pieces;
        onSave();
        onClose();
    };

    const handleCancel = () => {
        onClose();
    };

    const handleAddDataElement = () => {
        const newPieces = [...pieces];

        // Use the focused piece index, or fall back to last focused piece
        let textPieceIndex = focusedPieceIndex !== null ? focusedPieceIndex : lastFocusedPieceIndex;
        let insertPosition = cursorPosition;

        // If no piece is focused or was last focused, find the last text piece or append at the end
        if (textPieceIndex === null) {
            // Find the last text piece
            for (let i = newPieces.length - 1; i >= 0; i--) {
                if (newPieces[i] instanceof TextPiece) {
                    textPieceIndex = i;
                    insertPosition = (newPieces[i] as TextPiece).text.length; // Insert at end
                    break;
                }
            }

            // If still no text piece found, add one at the end
            if (textPieceIndex === null) {
                newPieces.push(new TextPiece(''));
                textPieceIndex = newPieces.length - 1;
                insertPosition = 0;
            }
        }

        // Make sure we have a valid index and it's a text piece
        if (textPieceIndex !== null && textPieceIndex < newPieces.length && newPieces[textPieceIndex] instanceof TextPiece) {
            const textPiece = newPieces[textPieceIndex] as TextPiece;
            const beforeText = textPiece.text.substring(0, insertPosition);
            const afterText = textPiece.text.substring(insertPosition);

            // Create a data element piece
            const dataElementPiece = new DataElementPiece();

            // Replace the text piece with: beforeText, dataElement, afterText
            const replacementPieces: ScriptPiece[] = [
                new TextPiece(beforeText),
                dataElementPiece,
                new TextPiece(afterText)
            ];

            newPieces.splice(textPieceIndex, 1, ...replacementPieces);

            // Focus at the beginning of the text piece after the data element
            const afterTextIndex = textPieceIndex + 2; // +1 for beforeText, +1 for dataElement = index of afterText
            focusPiece(afterTextIndex, 0);
            setPieces(newPieces);
        }
    };

    const handleFocus = (pieceIndex: number, e: React.FocusEvent<HTMLTextAreaElement>) => {
        setFocusedPieceIndex(pieceIndex);
        setLastFocusedPieceIndex(pieceIndex);
        setCursorPosition(e.target.selectionStart);
    };

    const handleBlur = () => {
        setFocusedPieceIndex(null);
        // Keep lastFocusedPieceIndex so we remember where we were
    };

    const handleTextClick = (pieceIndex: number) => {
        // Get the current text length to position at end
        const piece = pieces[pieceIndex];
        if (piece instanceof TextPiece) {
            focusPiece(pieceIndex, piece.text.length);
        }
    };

    const handleCursorMove = (pieceIndex: number, e: React.SyntheticEvent<HTMLTextAreaElement>) => {
        setFocusedPieceIndex(pieceIndex);
        setLastFocusedPieceIndex(pieceIndex);
        setCursorPosition((e.target as HTMLTextAreaElement).selectionStart);
    };

    const handleTextChange = (pieceIndex: number, newText: string) => {
        const newPieces = [...pieces];
        const piece = newPieces[pieceIndex];

        if (piece instanceof TextPiece) {
            // Check if newlines were added (Enter key or paste)
            if (newText.includes('\n')) {
                const lines = newText.split('\n');
                const splitPieces: ScriptPiece[] = [];

                for (let i = 0; i < lines.length; i++) {
                    splitPieces.push(new TextPiece(lines[i]));
                    if (i < lines.length - 1) {
                        splitPieces.push(new NewLinePiece());
                    }
                }

                newPieces.splice(pieceIndex, 1, ...splitPieces);

                // Focus at the start of the line after the last newline
                // pieceIndex + (number of pieces added) - 1
                // For "text\n", we get: TextPiece("text"), NewLinePiece, TextPiece("")
                // So focus should be on the last text piece (pieceIndex + splitPieces.length - 1)
                const lastPieceIndex = pieceIndex + splitPieces.length - 1;
                focusPiece(lastPieceIndex, 0);
            } else {
                // Check if this is a paste operation by comparing old and new text lengths
                const oldText = piece.text;
                const lengthDiff = newText.length - oldText.length;

                // If significant text was added (more than 2 characters), try auto-matching
                if (lengthDiff > 2 && statement.plcSource) {
                    // Get declarations for matching
                    const { sortedNames, declarationMap } = statement.getDeclarationsForMatching();

                    if (sortedNames.length > 0) {
                        // Parse the new text with auto-matching
                        const matchedPieces = statement.parseLineWithMatching(
                            newText,
                            sortedNames,
                            declarationMap
                        );

                        // Replace the current piece with the matched pieces
                        newPieces.splice(pieceIndex, 1, ...matchedPieces);
                    } else {
                        // No declarations available, just update text
                        piece.text = newText;
                    }
                } else {
                    // Simple text change (typing)
                    piece.text = newText;
                }
            }

            setPieces(newPieces);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>, pieceIndex: number) => {
        if (e.key === 'Backspace') {
            const textarea = e.target as HTMLTextAreaElement;
            const cursorPos = textarea.selectionStart;

            // Only handle backspace at the beginning of the textarea
            if (cursorPos === 0 && pieceIndex > 0) {
                e.preventDefault();

                const newPieces = [...pieces];
                const currentPiece = newPieces[pieceIndex];
                const prevPiece = newPieces[pieceIndex - 1];

                if (prevPiece instanceof NewLinePiece) {
                    // Remove the newline piece
                    newPieces.splice(pieceIndex - 1, 1);
                    // Focus at end of previous text piece (now at pieceIndex - 1)
                    const prevIndex = pieceIndex - 1;
                    if (newPieces[prevIndex] instanceof TextPiece) {
                        focusPiece(prevIndex);
                    }
                    setPieces(newPieces);
                } else if (prevPiece instanceof DataElementPiece) {
                    // Remove the data element piece and merge surrounding text pieces if both exist
                    const textBeforeIndex = pieceIndex - 2 >= 0 && newPieces[pieceIndex - 2] instanceof TextPiece ? pieceIndex - 2 : -1;
                    const textAfterIndex = currentPiece instanceof TextPiece ? pieceIndex : -1;

                    if (textBeforeIndex >= 0 && textAfterIndex >= 0) {
                        // Both sides are text - merge them
                        const textBefore = newPieces[textBeforeIndex] as TextPiece;
                        const textAfter = newPieces[textAfterIndex] as TextPiece;
                        const mergePoint = textBefore.text.length;
                        textBefore.text += textAfter.text;
                        // Remove data element and text after (2 pieces)
                        newPieces.splice(pieceIndex - 1, 2);
                        focusPiece(textBeforeIndex, mergePoint);
                        setPieces(newPieces);
                    } else if (textBeforeIndex >= 0) {
                        // Only text before - remove data element and focus at end of text before
                        newPieces.splice(pieceIndex - 1, 1);
                        focusPiece(textBeforeIndex);
                        setPieces(newPieces);
                    } else if (textAfterIndex >= 0) {
                        // Only text after - remove data element and focus at start of text after
                        newPieces.splice(pieceIndex - 1, 1);
                        focusPiece(pieceIndex - 1, 0);
                        setPieces(newPieces);
                    } else {
                        // No text pieces around - just remove the data element
                        newPieces.splice(pieceIndex - 1, 1);
                        setPieces(newPieces);
                    }
                } else if (prevPiece instanceof TextPiece && currentPiece instanceof TextPiece) {
                    // Merge with previous text piece
                    const prevTextLength = prevPiece.text.length;
                    prevPiece.text += currentPiece.text;
                    newPieces.splice(pieceIndex, 1);
                    // Focus at the merge point (end of previous text)
                    focusPiece(pieceIndex - 1, prevTextLength);
                    setPieces(newPieces);
                }
            }
        }
    };

    return (
        <>
            <Dialog open={open} onClose={handleCancel} maxWidth="md" fullWidth>
                <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3
                }}>
                    <Typography variant="h6">Edit Script Statement</Typography>
                    <IconButton
                        onClick={handleCancel}
                        sx={{
                            color: colors.lightTextColor,
                            '&:hover': {
                                backgroundColor: `${colors.lightTextColor}1A`
                            }
                        }}
                    >
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>
                <DialogContent>
                    <Box sx={{ mt: 3, mb: 2 }}>
                        <Button
                            variant="outlined"
                            startIcon={<AddIcon />}
                            onClick={handleAddDataElement}
                            sx={{ textTransform: 'none' }}
                        >
                            Insert Data Element
                        </Button>
                    </Box>
                    <Paper
                        sx={{
                            border: `1px solid ${colors.borderColor}`,
                            borderRadius: 1,
                            padding: 2,
                            minHeight: '200px',
                            backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor,
                            fontFamily: 'monospace',
                            fontSize: '0.95em',
                            lineHeight: 1.8,
                            whiteSpace: 'pre-wrap'
                        }}
                    >
                        {pieces.map((piece, index) => (
                            <React.Fragment key={piece.id}>
                                {piece instanceof TextPiece ? (
                                    focusedPieceIndex === index ? (
                                        <Box
                                            component="textarea"
                                            ref={(el) => {
                                                if (el) textareaRefs.current.set(index, el as HTMLTextAreaElement);
                                            }}
                                            value={piece.text}
                                            onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => handleTextChange(index, e.target.value)}
                                            onKeyDown={(e: React.KeyboardEvent<HTMLTextAreaElement>) => handleKeyDown(e, index)}
                                            onFocus={(e: React.FocusEvent<HTMLTextAreaElement>) => handleFocus(index, e)}
                                            onBlur={handleBlur}
                                            onClick={(e: React.MouseEvent<HTMLTextAreaElement>) => handleCursorMove(index, e)}
                                            onKeyUp={(e: React.KeyboardEvent<HTMLTextAreaElement>) => handleCursorMove(index, e)}
                                            placeholder={index === 0 && pieces.length === 1 && !piece.text ? "Enter your script here..." : ""}
                                            sx={{
                                                border: 'none',
                                                outline: 'none',
                                                backgroundColor: `${colors.darkTextColor}1F`,
                                                fontFamily: 'inherit',
                                                fontSize: 'inherit',
                                                lineHeight: 'inherit',
                                                resize: 'none',
                                                overflow: 'hidden',
                                                padding: '1px 3px',
                                                margin: 0,
                                                width: `${Math.max(piece.text.length + 5, 10)}ch`,
                                                minWidth: '10ch',
                                                height: '1.8em',
                                                verticalAlign: 'top',
                                                display: 'inline-block',
                                                borderRadius: '2px'
                                            }}
                                        />
                                    ) : (
                                        <Box
                                            component="span"
                                            onClick={() => handleTextClick(index)}
                                            sx={{
                                                backgroundColor: `${colors.darkTextColor}14`,
                                                padding: '1px 2px',
                                                borderRadius: '2px',
                                                cursor: 'text',
                                                display: 'inline-block',
                                                '&:hover': {
                                                    backgroundColor: `${colors.darkTextColor}1F`
                                                }
                                            }}
                                        >
                                            {piece.text || '\u00A0'}
                                        </Box>
                                    )
                                ) : piece instanceof NewLinePiece ? (
                                    <>
                                        <Box
                                            component="span"
                                            sx={{
                                                display: 'inline-flex',
                                                alignItems: 'center',
                                                color: colors.mutedTextColor,
                                                fontSize: '0.8em',
                                                marginLeft: '2px'
                                            }}
                                        >
                                            <NewLineIcon fontSize="inherit" />
                                        </Box>
                                        <br />
                                    </>
                                ) : piece instanceof DataElementPiece ? (
                                    <Box component="span" sx={{ display: 'inline-block', verticalAlign: 'middle', margin: '0 2px' }}>
                                        {piece.render(PLCRenderMode.Edit, PLCProgramType.SystemDefault)}
                                    </Box>
                                ) : null}
                            </React.Fragment>
                        ))}
                    </Paper>
                    <Typography variant="caption" sx={{ display: 'block', mt: 1, color: 'text.secondary' }}>
                        Tip: Click "Insert Data Element" to add a variable reference at the cursor position. Click the button to select a variable.
                    </Typography>
                </DialogContent>
                <DialogActions sx={{ px: 3, pb: 2 }}>
                    <Button onClick={handleCancel} sx={{ textTransform: 'none' }}>
                        Cancel
                    </Button>
                    <Button
                        onClick={handleSave}
                        variant="contained"
                        sx={{
                            textTransform: 'none',
                            backgroundColor: colors.primaryColor,
                            '&:hover': {
                                backgroundColor: colors.primaryColor,
                                opacity: 0.9
                            }
                        }}
                    >
                        Save
                    </Button>
                </DialogActions>
            </Dialog>
        </>
    );
}
