import { DataUtilities } from '../utils/storage/DataUtilities';
import { IStorable } from '../utils/storage/IStorable';

export enum StorageType {
    Flow = 'Flow',
    MDI = 'MDI',
}

export class Storage implements IStorable {
    name: string = '';
    createdAt: Date = new Date();
    updatedAt: Date = new Date();
    exposeAsAction: boolean = false;
    canBeCalledAsStep: boolean = false;
    categoryName: string = '';
    data: string = '';
    storageType: StorageType = StorageType.Flow;

    public toJSON(): any {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
        // Ensure dates are properly converted from JSON
        if (data.createdAt) {
            this.createdAt = new Date(data.createdAt);
        }
        if (data.updatedAt) {
            this.updatedAt = new Date(data.updatedAt);
        }
    }
}

export interface ICNCProgramStorage {
    getMDIStorageNames(): Promise<string[]>;
    getFlowStorageNames(): Promise<string[]>;
    getAllStorageNames(): Promise<string[]>;
    getStorageData(name: string): Promise<Storage | null>;
    saveStorageData(storage: Storage): Promise<void>;
    deleteStorageData(name: string): Promise<void>;
    getActionStorages(): Promise<Storage[]>;
    getActionStorageNames(): Promise<string[]>;
    exportAllAsJson(): Promise<string>;
    importFromJson(jsonData: string): Promise<void>;
}

