/**
 * Enum defining how a UI trigger should be added to the action panel
 */
export enum AddActionType {
    /**
     * Do not add this trigger to the action panel
     */
    No = 0,

    /**
     * Add as a click action (single press)
     */
    Click = 1,

    /**
     * Add as a press action (press and hold)
     */
    Press = 2
}
