import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { UserMessageQueue } from '../../../../data/UserMessageQueue';
import { TouchOffTarget } from '../../../../machine/ICNCSystem';
import { Machine } from '../../../../machine/Machine';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { WizardStep } from '../../../Wizard/WizardStep';
import { SurfaceSpoilboardWizard } from '../SurfaceSpoilboardWizard';
import { SurfacingStep } from './SurfacingStep';

export class TouchPlateTouchOffStep extends WizardStep {
    constructor(wizard: SurfaceSpoilboardWizard, priorStep: WizardStep | null = null) {
        super(wizard, priorStep);
    }

    getTitle(): string {
        return 'Surface Spoilboard - Touch Plate Touch Off';
    }

    nextStep(): WizardStep | null {
        return new SurfacingStep(this.wizard as SurfaceSpoilboardWizard, this);
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="touchplate-touchoff-surfacing-step"
                listenTo={this.wizard}
                properties={['state']}
                control={() => <TouchPlateTouchOffStepComponent step={this} />}
            />
        );
    }
}

interface TouchPlateTouchOffStepComponentProps {
    step: TouchPlateTouchOffStep;
}

function TouchPlateTouchOffStepComponent({ step }: TouchPlateTouchOffStepComponentProps) {
    const colors = ConfigurationDataColors.Instance;
    const machineData = MachineData.Instance;
    const wizard = step.wizard as SurfaceSpoilboardWizard;

    const handleTouchPlateTouchOff = async () => {
        try {
            // Get current position before touch off
            const currentPosition = await Machine.getInstance().movement.GetCurrentPosition();

            // Save corner position to wizard state
            wizard.state = {
                ...wizard.state,
                cornerX: currentPosition.x,
                cornerY: currentPosition.y
            };

            // Perform touch plate touch off for Z
            await Machine.getInstance().system.touchOffMaterial(TouchOffTarget.SpoilBoard);

            // Get position after touch off to save Z
            const afterPosition = await Machine.getInstance().movement.GetCurrentPosition();
            wizard.state = {
                ...wizard.state,
                cornerZ: afterPosition.z
            };
            StateManager.propertyChanged(wizard, 'state');


            // Advance to surfacing step
            wizard.advanceToNextStep();
        } catch (error) {
            UserMessageQueue.Instance.addMessage('❌ Touch plate touch off failed: ' + (error instanceof Error ? error.message : String(error)));
            wizard.errorWizard(error instanceof Error ? error : new Error(String(error)));
        }
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Typography variant="body1" sx={{ color: colors.darkTextColor }}>
                    Place the touch plate on the spoilboard surface directly under the tool.
                </Typography>

                <Typography variant="body2" sx={{ color: colors.mutedTextColor }}>
                    Touch plate thickness: {MachineData.Instance.movableTouchPlateHeight.toFixed(4)}"
                </Typography>

                <Typography variant="body2" sx={{ color: colors.warningColor, fontWeight: 500 }}>
                    ⚠ Ensure the touch plate is flat on the spoilboard and the tool is above it
                </Typography>
            </Box>

            <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 2, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                <Button
                    variant="text"
                    onClick={() => wizard.goToPreviousStep()}
                >
                    Back
                </Button>
                <Button
                    variant="contained"
                    onClick={handleTouchPlateTouchOff}
                >
                    Start Touch Off
                </Button>
            </Box>
        </Box>
    );
}
