/**
 * Stage for tool change operations (M06)
 */

import type { IMachineCallback } from '../../machine/IMachineCallback';
import { Machine } from '../../machine/Machine';
import { JobStage, StageStatus, StageType } from '../JobStage';

export class ToolChangeStage extends JobStage {
    public toolNumber: number;
    public lineNumber: number;
    public gcodeLine: string;

    constructor(stageNumber: number, toolNumber: number, lineNumber: number, gcodeLine: string) {
        super(stageNumber, StageType.ToolChange, lineNumber - 1, lineNumber - 1);
        this.toolNumber = toolNumber;
        this.lineNumber = lineNumber;
        this.gcodeLine = gcodeLine;
    }

    protected async executeStage(callback?: import('../JobStage').StageCallback): Promise<void> {
        // Create callback to handle tool change completion
        const machineCallback: IMachineCallback = {
            onComplete: async () => {
                this.status = StageStatus.Completed;
                this.endTime = new Date();

                // Tool change completed - continue to next stage
                if (callback) {
                    await callback.onComplete();
                }
            },
            onError: async (error: string | Error) => {
                this.status = StageStatus.Error;
                this.endTime = new Date();
                this.errorMessage = typeof error === 'string' ? error : error.message;

                if (callback) {
                    await callback.onError(this.errorMessage);
                }
            }
        };

        // Execute the tool change using the machine interface
        await Machine.getInstance().system.changeTool(this.toolNumber, machineCallback);
    }

    public getStageName(): string {
        return 'Tool Change';
    }

    public getDisplayName(): string {
        return `Tool Change → T${this.toolNumber}`;
    }

    public getDescription(): string {
        return `Change to Tool ${this.toolNumber} (Line ${this.lineNumber})\nPress CYCLE START to continue`;
    }

    public getStageDisplayData(): string[] {
        return [
            `Tool: ${this.toolNumber}`,
            `(Line ${this.lineNumber})`,
            'Press CYCLE START to continue'
        ];
    }
}
