import { CNCPoint } from '../../../data/CNCPoint';
import { CoordinateType } from '../../../data/Common/CoordinateType';
import { SimulatorView } from '../../../data/Common/SimulatorView';
import { ViewStyle } from '../../../data/Common/ViewStyle';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { CoordinateUtil } from '../../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { Box } from './Box';

export interface MachineBedProps {
  simulatorView: SimulatorView;
  machineData: MachineData;
}

export function MachineBed({
  simulatorView,
  machineData
}: MachineBedProps) {
  return (
    <ObserveMultiProperties
      listenTo={[
        { object: simulatorView, properties: ['base', 'bed'] },
        { object: ConfigurationDataColors.Instance, properties: ['baseTransparency', 'bedTransparency', 'baseColor', 'bedColor', 'railingColor'] }
      ]}
      control={() => {
        // Get configuration colors
        const colors = ConfigurationDataColors.Instance;

        // Get base box from CoordinateUtil
        const baseBox = CoordinateUtil.getBaseBox();
        const basePosition = CoordinateUtil.toSimulator(
          new CNCPoint(baseBox.centerX, baseBox.centerY, baseBox.z + baseBox.height / 2, CoordinateType.MachineZero)
        );

        // Get bed box from CoordinateUtil to ensure consistency
        const bedBox = CoordinateUtil.getBedBox(MachineStateData.Instance);
        const bedPosition = CoordinateUtil.toSimulator(
          new CNCPoint(bedBox.centerX, bedBox.centerY, bedBox.z + bedBox.height / 2, CoordinateType.MachineZero)
        );

        // Get railing boxes from CoordinateUtil
        const leftRailingBox = CoordinateUtil.getLeftRailingBox();
        const rightRailingBox = CoordinateUtil.getRightRailingBox();

        // Convert railing box centers to simulator coordinates for rendering
        const leftRailingPosition = CoordinateUtil.toSimulator(
          new CNCPoint(leftRailingBox.centerX, leftRailingBox.centerY, leftRailingBox.z + leftRailingBox.height / 2, CoordinateType.MachineZero)
        );
        const rightRailingPosition = CoordinateUtil.toSimulator(
          new CNCPoint(rightRailingBox.centerX, rightRailingBox.centerY, rightRailingBox.z + rightRailingBox.height / 2, CoordinateType.MachineZero)
        );

        // Create unique key for React re-rendering when material properties change
        const renderKey = `machinebed-${ViewStyle[simulatorView.base as keyof typeof ViewStyle]}-${ViewStyle[simulatorView.bed as keyof typeof ViewStyle]}-${ViewStyle[simulatorView.railing as keyof typeof ViewStyle]}-${Date.now()}`;

        return (
          <group key={renderKey}>
            {/* Machine Base */}
            {simulatorView.base !== ViewStyle.Hide && (
              <Box
                position={[basePosition.x, basePosition.y, basePosition.z]}
                size={[baseBox.width, baseBox.length, baseBox.height]}
                color={colors.baseColor}
                viewStyle={simulatorView.base}
                opacity={simulatorView.base === ViewStyle.SemiTransparent ? colors.baseTransparency : 1}
              />
            )}

            {/* Machine Bed */}
            {simulatorView.bed !== ViewStyle.Hide && (
              <Box
                position={[bedPosition.x, bedPosition.y, bedPosition.z]}
                size={[bedBox.width, bedBox.length, bedBox.height]}
                color={colors.bedColor}
                viewStyle={simulatorView.bed}
                opacity={simulatorView.bed === ViewStyle.SemiTransparent ? colors.bedTransparency : 1}
              />
            )}

            {/* Left Railing - Shown whenever base is visible */}
            {simulatorView.base !== ViewStyle.Hide && (
              <Box
                position={[leftRailingPosition.x, leftRailingPosition.y, leftRailingPosition.z]}
                size={[leftRailingBox.width, leftRailingBox.length, leftRailingBox.height]}
                color={colors.railingColor}
                viewStyle={simulatorView.base}
                opacity={simulatorView.base === ViewStyle.SemiTransparent ? colors.baseTransparency : 1}
              />
            )}

            {/* Right Railing - Shown whenever base is visible */}
            {simulatorView.base !== ViewStyle.Hide && (
              <Box
                position={[rightRailingPosition.x, rightRailingPosition.y, rightRailingPosition.z]}
                size={[rightRailingBox.width, rightRailingBox.length, rightRailingBox.height]}
                color={colors.railingColor}
                viewStyle={simulatorView.base}
                opacity={simulatorView.base === ViewStyle.SemiTransparent ? colors.baseTransparency : 1}
              />
            )}
          </group>
        );
      }}
    />
  );
}
