import { ExpandMore } from '@mui/icons-material';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Box,
  Grid,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { Job } from '../../../data/Job';
import { MachineData } from '../../../data/Machine/MachineData';
import { RotaryAxis } from '../../../data/Machine/RotaryAxis';
import { MachineStateData } from '../../../data/MachineStateData';
import { ObserveMultiProperties } from '../../../utils/statemanager/ObserveMultiProperties';
import { ViewDataFactory, ViewNames } from '../../../utils/ViewDataFactory';
import { SetupChecklistIndicator } from '../../Common/SetupChecklistIndicator';
import { FullSizeCNCViewer } from '../../MachineViewer/FullSizeCNCViewer';
import {
  ATCSetupSection,
  BaseSection,
  BedSection,
  DrillHeadSection,
  GantrySection,
  LaserPointerSection,
  LaserSection,
  RailingSection,
  RotarySection,
  SpindleSection,
  TouchPadSection,
  VerticalTableSection
} from './sections';

export const MachineDataTab: React.FC = () => {
  const [simulatorViewData] = useState(() => ViewDataFactory.createForContext(ViewNames.MACHINE_SETTINGS));
  // State for managing which accordion sections are expanded
  const [expandedSections, setExpandedSections] = useState<{ [key: string]: boolean }>({
    features: true,
    base: false,
    railing: false,
    bed: false,
    verticalTable: false,
    spindle: false,
    gantry: false,
    laser: false,
    laserPointer: false,
    drillHead: false,
    atcSetup: false,
    manualToolSetup: false,
    rotary: false,
    touchpad: false
  });

  const handleSectionToggle = (section: string) => {
    setExpandedSections(prev => ({
      ...prev,
      [section]: !prev[section]
    }));
  };

  return (
    <ObserveMultiProperties
      key="machine-data-tab"
      listenTo={[
        {
          object: MachineData.Instance,
          properties: [
            'hasVerticalTable', 'hasLaser', 'hasLaserPointer', 'hasDrillHead', 'hasATC', 'hasFixedTouchPlate', 'rotaryAxis'
          ]
        }
      ]}
      control={() => {
        const machine = MachineData.Instance;

        return (
          <Box sx={{ display: 'flex', gap: 3, height: 'calc(100vh - 200px)' }}>
            {/* Left side: Configuration accordions (50%) */}
            <Box sx={{ flex: 1, overflowY: 'auto', pr: 2 }}>
              <Typography variant="h4" gutterBottom>Simulator Setup</Typography>

              {/* Simulator Configuration Checklist Indicator */}
              <Grid container spacing={3} sx={{ mb: 3 }}>
                <Grid item xs={12}>
                  <SetupChecklistIndicator name="Simulator Configuration" />
                </Grid>
              </Grid>

              <Typography variant="h6" sx={{ mb: 3 }}>Machine Configuration</Typography>

              {/* Base */}
              <Accordion
                expanded={expandedSections.base}
                onChange={() => handleSectionToggle('base')}
                sx={{ mb: 2 }}
              >
                <AccordionSummary expandIcon={<ExpandMore />}>
                  <Typography variant="h5" sx={{ color: 'primary.main' }}>Base</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      <strong>Reference Point:</strong> Machine foundation/base platform dimensions measured from the base origin point.
                      These dimensions define the physical footprint and height of the machine's base structure that all other components mount to.
                    </Typography>
                  </Box>
                  <BaseSection />
                </AccordionDetails>
              </Accordion>

              {/* Railing */}
              <Accordion
                expanded={expandedSections.railing}
                onChange={() => handleSectionToggle('railing')}
                sx={{ mb: 2 }}
              >
                <AccordionSummary expandIcon={<ExpandMore />}>
                  <Typography variant="h5" sx={{ color: 'primary.main' }}>Railing</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      <strong>Reference Point:</strong> Guide rail dimensions measured from the base.
                      These rails define the X and Y axis travel paths for the gantry system. Position can be inside or outside the bed area.
                    </Typography>
                  </Box>
                  <RailingSection />
                </AccordionDetails>
              </Accordion>

              {/* Bed */}
              <Accordion
                expanded={expandedSections.bed}
                onChange={() => handleSectionToggle('bed')}
                sx={{ mb: 2 }}
              >
                <AccordionSummary expandIcon={<ExpandMore />}>
                  <Typography variant="h5" sx={{ color: 'primary.main' }}>Bed</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      <strong>Reference Point:</strong> Work surface dimensions measured from the base platform.
                      The bed is the work surface where materials are mounted and machined. These dimensions define the usable work area.
                    </Typography>
                  </Box>
                  <BedSection />
                </AccordionDetails>
              </Accordion>

              {/* Vertical Table */}
              {machine.hasVerticalTable && (
                <Accordion
                  expanded={expandedSections.verticalTable}
                  onChange={() => handleSectionToggle('verticalTable')}
                  sx={{ mb: 2 }}
                >
                  <AccordionSummary expandIcon={<ExpandMore />}>
                    <Typography variant="h5" sx={{ color: 'primary.main' }}>Vertical Table</Typography>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                      <Typography variant="body2" color="text.secondary">
                        <strong>Reference Point:</strong> Vertical work holding table dimensions measured from the bed surface.
                        The vertical table allows for side mounting of workpieces and can be positioned at various angles for complex machining operations.
                      </Typography>
                    </Box>
                    <VerticalTableSection />
                  </AccordionDetails>
                </Accordion>
              )}

              {/* Spindle */}
              <Accordion
                expanded={expandedSections.spindle}
                onChange={() => handleSectionToggle('spindle')}
                sx={{ mb: 2 }}
              >
                <AccordionSummary expandIcon={<ExpandMore />}>
                  <Typography variant="h5" sx={{ color: 'primary.main' }}>Spindle</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      <strong>Reference Point:</strong> Spindle assembly dimensions measured from the gantry mounting point.
                      These settings define the cutting tool spindle size and position, including the tool holder that holds cutting tools.
                    </Typography>
                  </Box>
                  <SpindleSection />
                </AccordionDetails>
              </Accordion>

              {/* Gantry */}
              <Accordion
                expanded={expandedSections.gantry}
                onChange={() => handleSectionToggle('gantry')}
                sx={{ mb: 2 }}
              >
                <AccordionSummary expandIcon={<ExpandMore />}>
                  <Typography variant="h5" sx={{ color: 'primary.main' }}>Gantry</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      <strong>Reference Point:</strong> Moving gantry assembly dimensions. Gantry Height is measured from the top of the bed.
                      The gantry carries the spindle and moves along the X and Y axes above the work surface.
                      Extension values define how far the gantry bar extends beyond the outside edges of the railings.
                    </Typography>
                  </Box>
                  <GantrySection />
                </AccordionDetails>
              </Accordion>

              {/* Laser */}
              {machine.hasLaser && (
                <Accordion
                  expanded={expandedSections.laser}
                  onChange={() => handleSectionToggle('laser')}
                  sx={{ mb: 2 }}
                >
                  <AccordionSummary expandIcon={<ExpandMore />}>
                    <Typography variant="h5" sx={{ color: 'primary.main' }}>Laser</Typography>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                      <Typography variant="body2" color="text.secondary">
                        <strong>Reference Point:</strong> Laser attachment with box-shaped housing.
                        Configure the laser offset from the spindle and its physical dimensions for collision detection.
                      </Typography>
                    </Box>
                    <LaserSection />
                  </AccordionDetails>
                </Accordion>
              )}

              {/* Laser Pointer */}
              {machine.hasLaserPointer && (
                <Accordion
                  expanded={expandedSections.laserPointer}
                  onChange={() => handleSectionToggle('laserPointer')}
                  sx={{ mb: 2 }}
                >
                  <AccordionSummary expandIcon={<ExpandMore />}>
                    <Typography variant="h5" sx={{ color: 'primary.main' }}>Laser Pointer</Typography>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                      <Typography variant="body2" color="text.secondary">
                        <strong>Reference Point:</strong> Laser pointer with cylindrical shape.
                        Configure the laser pointer offset from the spindle and its physical dimensions for collision detection.
                      </Typography>
                    </Box>
                    <LaserPointerSection />
                  </AccordionDetails>
                </Accordion>
              )}

              {/* Drill Head */}
              {machine.hasDrillHead && (
                <Accordion
                  expanded={expandedSections.drillHead}
                  onChange={() => handleSectionToggle('drillHead')}
                  sx={{ mb: 2 }}
                >
                  <AccordionSummary expandIcon={<ExpandMore />}>
                    <Typography variant="h5" sx={{ color: 'primary.main' }}>Drill Head</Typography>
                  </AccordionSummary>
                  <AccordionDetails>
                    <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                      <Typography variant="body2" color="text.secondary">
                        <strong>Reference Point:</strong> Multi-bit drill head attachment.
                        Configure the drill head offset from spindle to the back left corner, its physical dimensions, and drill bit positions.
                      </Typography>
                    </Box>
                    <DrillHeadSection />
                  </AccordionDetails>
                </Accordion>
              )}

              {/* ATC Setup */}
              {machine.hasATC && (
                <Accordion
                  expanded={expandedSections.atcSetup}
                  onChange={() => handleSectionToggle('atcSetup')}
                  sx={{ mb: 2 }}
                >
                  <AccordionSummary expandIcon={<ExpandMore />}>
                    <Typography variant="h5" sx={{ color: 'primary.main' }}>ATC Setup</Typography>
                  </AccordionSummary>
                  <AccordionDetails>
                    <ATCSetupSection />
                  </AccordionDetails>
                </Accordion>
              )}

              {/* Rotary */}
              {machine.rotaryAxis !== RotaryAxis.None && (
                <Accordion
                  expanded={expandedSections.rotary}
                  onChange={() => handleSectionToggle('rotary')}
                  sx={{ mb: 2 }}
                >
                  <AccordionSummary expandIcon={<ExpandMore />}>
                    <Typography variant="h5" sx={{ color: 'primary.main' }}>Rotary</Typography>
                  </AccordionSummary>
                  <AccordionDetails>
                    <RotarySection />
                  </AccordionDetails>
                </Accordion>
              )}

              {/* Touch Pad */}
              <Accordion
                expanded={expandedSections.touchpad}
                onChange={() => handleSectionToggle('touchpad')}
                sx={{ mb: 2 }}
              >
                <AccordionSummary expandIcon={<ExpandMore />}>
                  <Typography variant="h5" sx={{ color: 'primary.main' }}>Touch Pad</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Box sx={{ mb: 2, p: 2, backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, borderRadius: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      <strong>Reference Point:</strong> Touch probe/touch pad assembly dimensions measured from the bed surface.
                      The touch pad is used for tool length measurement and workpiece height detection during setup and operation.
                    </Typography>
                  </Box>
                  <TouchPadSection />
                </AccordionDetails>
              </Accordion>
            </Box>

            {/* Right side: 3D Viewer (50%) */}
            <Box sx={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
              <FullSizeCNCViewer
                simulatorViewData={simulatorViewData}
                machineState={MachineStateData.Instance}
                machineData={machine}
                job={ConfigurationState.Instance.currentJob || Job.createTestJob()}
              />
            </Box>
          </Box>
        );
      }}
    />
  );
};
