import { UserMessageQueue } from '../data/UserMessageQueue';
import { BaseCNCProgramStorage } from '../machine/BaseCNCProgramStorage';
import { Storage, StorageType } from '../machine/ICNCProgramStorage';

interface StorageIndexEntry {
    name: string;
    createdAt: string;  // ISO date string
    updatedAt: string;
    storageType: StorageType;
    exposeAsAction: boolean;
    categoryName: string;
}

export class SimulatorCNCProgramStorage extends BaseCNCProgramStorage {
    private static readonly STORAGE_INDEX_KEY = 'program_storage_index';

    private loadIndex(): StorageIndexEntry[] {
        try {
            const json = localStorage.getItem(SimulatorCNCProgramStorage.STORAGE_INDEX_KEY);
            return json ? JSON.parse(json) : [];
        } catch {
            return [];
        }
    }

    private saveIndex(index: StorageIndexEntry[]): void {
        localStorage.setItem(SimulatorCNCProgramStorage.STORAGE_INDEX_KEY, JSON.stringify(index));
    }

    private updateIndexEntry(storage: Storage): void {
        const index = this.loadIndex();
        const existingIndex = index.findIndex(e => e.name === storage.name);

        const entry: StorageIndexEntry = {
            name: storage.name,
            createdAt: storage.createdAt.toISOString(),
            updatedAt: storage.updatedAt.toISOString(),
            storageType: storage.storageType,
            exposeAsAction: storage.exposeAsAction,
            categoryName: storage.categoryName
        };

        if (existingIndex >= 0) {
            index[existingIndex] = entry;
        } else {
            index.push(entry);
        }

        this.saveIndex(index);
    }

    private removeIndexEntry(name: string): void {
        const index = this.loadIndex();
        const filtered = index.filter(e => e.name !== name);
        this.saveIndex(filtered);
    }

    private getStorageKey(name: string): string {
        return `program_storage_${name}`;
    }

    async getStorageNames(): Promise<string[]> {
        const index = this.loadIndex();
        return index.map(e => e.name).sort();
    }

    async getAllStorageNames(): Promise<string[]> {
        return this.getStorageNames();
    }

    async getStorageData(name: string): Promise<Storage | null> {
        try {
            const key = this.getStorageKey(name);
            const json = localStorage.getItem(key);
            if (!json) return null;

            const data = JSON.parse(json);
            const storage = new Storage();
            storage.fromJSON(data);
            return storage;
        } catch {
            return null;
        }
    }

    async saveStorageData(storage: Storage): Promise<void> {
        storage.updatedAt = new Date();

        // Save full data
        const key = this.getStorageKey(storage.name);
        localStorage.setItem(key, JSON.stringify(storage.toJSON()));

        // Update index
        this.updateIndexEntry(storage);

        UserMessageQueue.Instance.addMessage(`✓ Saved program storage: ${storage.name}`);
    }

    async deleteStorageData(name: string): Promise<void> {
        // Remove full data
        const key = this.getStorageKey(name);
        localStorage.removeItem(key);

        // Remove from index
        this.removeIndexEntry(name);

        UserMessageQueue.Instance.addMessage(`✓ Deleted program storage: ${name}`);
    }

    // Utility methods for specific storage types
    async getFlowStorageNames(): Promise<string[]> {
        const index = this.loadIndex();
        return index
            .filter(e => e.storageType === StorageType.Flow)
            .map(e => e.name)
            .sort();
    }

    async getMDIStorageNames(): Promise<string[]> {
        const index = this.loadIndex();
        return index
            .filter(e => e.storageType === StorageType.MDI)
            .map(e => e.name)
            .sort();
    }

    // Initialize index if needed (call on startup)
    initializeIndex(): void {
        const index = this.loadIndex();
        if (index.length === 0) {
            // Index is empty, scan for existing storage items
            this.rebuildIndex();
        }
    }

    // Rebuild index from existing localStorage items (recovery function)
    private rebuildIndex(): void {
        const index: StorageIndexEntry[] = [];

        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key && key.startsWith('program_storage_') && key !== SimulatorCNCProgramStorage.STORAGE_INDEX_KEY) {
                try {
                    const json = localStorage.getItem(key);
                    if (json) {
                        const data = JSON.parse(json);
                        const storage = new Storage();
                        storage.fromJSON(data);

                        index.push({
                            name: storage.name,
                            createdAt: storage.createdAt.toISOString(),
                            updatedAt: storage.updatedAt.toISOString(),
                            storageType: storage.storageType,
                            exposeAsAction: storage.exposeAsAction,
                            categoryName: storage.categoryName
                        });
                    }
                } catch {
                    // Skip corrupted entries
                }
            }
        }

        this.saveIndex(index);
        if (index.length > 0) {
            UserMessageQueue.Instance.addMessage(`✓ Rebuilt program storage index (${index.length} items)`);
        }
    }
}