import { Close as CloseIcon } from '@mui/icons-material';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  TextField,
  ToggleButton,
  ToggleButtonGroup,
  Typography,
} from '@mui/material';
import React, { useState } from 'react';
import { CNCPoint } from '../../data/CNCPoint';
import { Fixture, FixtureLibrary, FixtureType } from '../../data/Common/FixtureLibrary';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { MachineStateData } from '../../data/MachineStateData';
import { UserMessageQueue } from '../../data/UserMessageQueue';
import { ToolUtils } from '../../utils/ToolUtils';

interface FixtureNameInputDialogProps {
  open: boolean;
  onClose: () => void;
}

export function FixtureNameInputDialog({
  open,
  onClose
}: FixtureNameInputDialogProps) {
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [useCurrentLocation, setUseCurrentLocation] = useState(true);

  const handleSave = () => {
    const trimmedName = name.trim();

    // Validation
    if (!trimmedName) {
      setError('Please enter a name for the fixture');
      return;
    }

    const existingNames = FixtureLibrary.Instance.fixtures.map(f => f.name);
    if (existingNames.includes(trimmedName)) {
      setError('This name is already used for this fixture number. Please choose a different name.');
      return;
    }

    // Save the fixture position
    const machineState = MachineStateData.Instance;
    const fixtureNumber = machineState.currentFixtureNumber;
    const currentFixture = FixtureLibrary.getFixtureByNumber(fixtureNumber);
    const toolOffsets = ToolUtils.getCurrentToolOffsets();

    let x: number, y: number, z: number;

    if (useCurrentLocation) {
      const currentPoint = ConfigurationState.Instance.currentMachinePoint;
      // Use CNCPoint.subtractOffset for proper offset calculation
      const fixturePoint = CNCPoint.subtractOffset(currentPoint, toolOffsets);
      x = fixturePoint.x;
      y = fixturePoint.y;
      z = fixturePoint.z;
    } else {
      if (!currentFixture) {
        UserMessageQueue.Instance.addMessage('❌ No current fixture selected');
        return;
      }

      const currentPoint = ConfigurationState.Instance.currentMachinePoint;
      // Use CNCPoint.subtractOffset for proper offset calculation
      const fixturePoint = CNCPoint.subtractOffset(currentPoint, toolOffsets);
      currentFixture.xOffset = fixturePoint.x;
      currentFixture.yOffset = fixturePoint.y;
      currentFixture.zOffset = fixturePoint.z;

      handleClose();
      return;
    }

    const newFixture = new Fixture(
      trimmedName,
      trimmedName,
      x,
      y,
      z,
      false,
      FixtureType.SavedPoint,
      true
    );
    FixtureLibrary.Instance.addFixture(newFixture);

    handleClose();
  };

  const handleClose = () => {
    setName('');
    setError('');
    setUseCurrentLocation(true);
    onClose();
  };

  const handleNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setName(event.target.value);
    // Clear error when user starts typing
    if (error) {
      setError('');
    }
  };

  const handleKeyPress = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter') {
      handleSave();
    }
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        backgroundColor: ConfigurationDataColors.Instance.primaryColor,
        color: ConfigurationDataColors.Instance.lightTextColor,
        py: 2,
        px: 3
      }}>
        Create Saved Point
        <IconButton
          onClick={handleClose}
          sx={{
            color: ConfigurationDataColors.Instance.lightTextColor,
            '&:hover': {
              backgroundColor: ConfigurationDataColors.Instance.lightOverlay
            }
          }}
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      <DialogContent sx={{ pb: 2 }}>
        <Box sx={{ mt: 3, mb: 3 }}>
          <ToggleButtonGroup
            value={useCurrentLocation ? 'location' : 'fixture'}
            exclusive
            onChange={(_, newValue) => {
              if (newValue !== null) {
                setUseCurrentLocation(newValue === 'location');
              }
            }}
            fullWidth
            sx={{
              mb: 2,
              '& .MuiToggleButton-root': {
                color: ConfigurationDataColors.Instance.mutedTextColor,
                backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor,
                borderColor: ConfigurationDataColors.Instance.borderColor,
                borderWidth: '2px',
                '&.Mui-selected': {
                  backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                  color: ConfigurationDataColors.Instance.lightTextColor,
                  borderColor: ConfigurationDataColors.Instance.primaryColor,
                  fontWeight: 'bold',
                  '&:hover': {
                    backgroundColor: ConfigurationDataColors.Instance.primaryColor,
                  }
                },
                '&:hover': {
                  borderColor: ConfigurationDataColors.Instance.primaryColor,
                  backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor,
                }
              }
            }}
          >
            <ToggleButton value="fixture">
              Current Fixture Position
            </ToggleButton>
            <ToggleButton value="location">
              Current Machine Location
            </ToggleButton>
          </ToggleButtonGroup>

          <Typography variant="body2" color="text.secondary">
            {useCurrentLocation
              ? `Create a saved point at the current machine location.`
              : `Create a saved point using the position stored in the current fixture.`
            }
          </Typography>
        </Box>

        <TextField
          autoFocus
          margin="dense"
          label="Saved Point Name"
          fullWidth
          variant="outlined"
          value={name}
          onChange={handleNameChange}
          onKeyPress={handleKeyPress}
          error={!!error}
          helperText={error || 'Enter a unique name for this saved point'}
          placeholder="e.g., Top Left Corner, Center Position, etc."
          sx={{
            '& .MuiOutlinedInput-root': {
              backgroundColor: ConfigurationDataColors.Instance.lightTextColor,
            }
          }}
        />
      </DialogContent>
      <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${ConfigurationDataColors.Instance.borderColor}` }}>
        <Button onClick={handleClose} variant="outlined">
          Cancel
        </Button>
        <Button
          onClick={handleSave}
          variant="contained"
          disabled={!name.trim()}
          sx={{
            fontWeight: 'bold',
            backgroundColor: ConfigurationDataColors.Instance.primaryColor,
            '&:hover': {
              backgroundColor: ConfigurationDataColors.Instance.primaryColor,
              opacity: 0.9
            }
          }}
        >
          Create Saved Point
        </Button>
      </DialogActions>
    </Dialog>
  );
}
