import { StateManager } from '../../utils/statemanager/StateManager';
import { MachineData } from '../Machine/MachineData';
import { SetupChecklistItem } from './SetupChecklistItem';

/**
 * Checklist item for Fixed Touch Plate Position configuration
 * Conditional validation - only validates when fixed touch plate is enabled
 * Auto-validates that position is not at or very near 0,0,0
 */
export class FixedTouchPlatePositionChecklistItem extends SetupChecklistItem {
    constructor() {
        super(
            'Fixed Touch Plate Position',
            'Configure the X, Y, Z position of the fixed touch plate (must not be at 0,0,0)'
        );

        // Listen to MachineData changes that affect this checklist item
        const machine = MachineData.Instance;
        StateManager.addObserver(machine, () => {
            // Trigger update on this item when relevant properties change
            StateManager.propertyChanged(this, 'manuallyConfirmed');
        }, ['hasFixedTouchPlate', 'fixedTouchPlateX', 'fixedTouchPlateY', 'fixedTouchPlateZ']);
    }

    public shouldInclude(): boolean {
        // Only include this item if fixed touch plate is enabled
        return MachineData.Instance.hasFixedTouchPlate;
    }

    public needsManualConfirmation(): boolean {
        return false; // Auto-validation only
    }

    public completionCheck(): boolean {
        const machine = MachineData.Instance;

        // Validate that position is not at or very near 0,0,0
        const x = machine.fixedTouchPlateX;
        const y = machine.fixedTouchPlateY;
        const z = machine.fixedTouchPlateZ;

        // Check if any coordinate is significantly different from 0 (tolerance of 0.001)
        const tolerance = 0.001;
        const isNearZero = Math.abs(x) < tolerance && Math.abs(y) < tolerance && Math.abs(z) < tolerance;

        return !isNearZero;
    }

    public clone(): FixedTouchPlatePositionChecklistItem {
        const cloned = new FixedTouchPlatePositionChecklistItem();
        cloned.manuallyConfirmed = this.manuallyConfirmed;
        return cloned;
    }
}
