/// <reference path="./three-jsx.d.ts" />
import {
  useCallback,
  useRef,
  useState
} from 'react';
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { Canvas } from '@react-three/fiber';
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { OrbitControls, PerspectiveCamera } from '@react-three/drei';
import { Vector3 } from 'three';
import { CNCPoint } from '../../data/CNCPoint';
import { CoordinateType } from '../../data/Common/CoordinateType';
import { SimulatorViewData } from '../../data/Common/SimulatorViewData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../data/ConfigurationState';
import { Job } from '../../data/Job';
import { MachineData } from '../../data/Machine/MachineData';
import { MachineStateData } from '../../data/MachineStateData';
import { SystemIcons } from '../../SystemIcons';
import { CoordinateUtil } from '../../utils/CoordinateUtil';
import { ObserveMultiProperties } from '../../utils/statemanager/ObserveMultiProperties';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { CNCMachine } from './CNCMachine';
import { ViewerSettingsDialog } from './ViewerSettingsDialog';

export enum CNCViewType {
  Perspective = 'Perspective',
  Side = 'Side',
  Top = 'Top',
  DefaultTop = 'DefaultTop',
  Front = 'Front',
  ZAxisCalibration = 'ZAxisCalibration'
}

export enum CameraMode {
  MachineCenter = 'MachineCenter',
  FollowSpindle = 'FollowSpindle'
}

export enum CameraTarget {
  MachineCenter = 'MachineCenter',
  Spindle = 'Spindle',
  GCodeCenter = 'GCodeCenter',
  MaterialCenter = 'MaterialCenter'
}

export interface CNCViewerProps {
  simulatorViewData: SimulatorViewData; // Contains all 4 perspective views AND behavior configuration
  machineState: MachineStateData;
  machineData: MachineData;
  job: Job; // Required job - calling code determines which job to pass
  width?: number | string;
  height?: number | string;
  zAxisReferenceType?: 'bed' | 'spoilboard' | 'material'; // For Z-axis calibration camera positioning
}

export function CNCViewer({
  simulatorViewData,
  machineState,
  machineData,
  job, // Required job prop
  width = 800,
  height = 600,
  zAxisReferenceType = 'spoilboard'
}: CNCViewerProps) {
  // Read behavior configuration from simulatorViewData
  const enableOrbit = simulatorViewData.enableOrbit;
  const enableClampDragging = simulatorViewData.enableClampDragging;
  const enableSpindleDrag = simulatorViewData.enableSpindleDrag;
  const showViewTypeButtons = simulatorViewData.showViewTypeButtons;
  const showSettingsButton = simulatorViewData.showSettingsButton;
  const isHardcodedSettings = simulatorViewData.isHardcodedSettings;

  // Validate that width and height are not percentage-based values
  // Percentage sizing causes re-render cascades and layout thrashing
  if (typeof width === 'string' && (width.includes('%') || width.includes('vh') || width.includes('vw'))) {
    throw new Error(`CNCViewer: Percentage-based width "${width}" is not allowed. Use fixed pixel values only to prevent re-render issues.`);
  }
  if (typeof height === 'string' && (height.includes('%') || height.includes('vh') || height.includes('vw'))) {
    throw new Error(`CNCViewer: Percentage-based height "${height}" is not allowed. Use fixed pixel values only to prevent re-render issues.`);
  }

  // Ref for OrbitControls to allow direct manipulation
  const orbitControlsRef = useRef<any>(null);

  // Debug: Track job changes to detect if we're getting new objects
  const lastJobRef = useRef(job);
  const renderCountRef = useRef(0);

  // Debug logging on every render
  renderCountRef.current++;

  lastJobRef.current = job;

  // State for settings dialog
  const [settingsDialogOpen, setSettingsDialogOpen] = useState(false);

  // Get configuration state instance
  const configState = ConfigurationState.Instance;

  // Method to calculate if we're in top-down view
  const isTopDownView = useCallback((): boolean => {
    // OrbitControls are always rendered now, so we can rely on the ref
    if (!orbitControlsRef.current) {
      return false; // Should not happen since controls are always rendered
    }

    const controls = orbitControlsRef.current;
    const position = controls.object.position;
    const target = controls.target;

    const relativeZ = Math.abs(position.z - target.z);
    const relativeX = Math.abs(position.x - target.x);
    const relativeY = Math.abs(position.y - target.y);

    return relativeZ > relativeX && relativeZ > relativeY;
  }, []);

  /**
   * Extract spherical coordinates from current camera position relative to target
   * Used when saving camera state
   */
  const extractSphericalFromCamera = useCallback((
    cameraPosition: Vector3,
    target: Vector3
  ): { distance: number; polarAngle: number; azimuthalAngle: number } => {
    const offset = new Vector3().subVectors(cameraPosition, target);
    const distance = offset.length();

    // Compute polar angle (elevation)
    const polarAngle = Math.acos(Math.max(-1, Math.min(1, offset.z / distance)));

    // Compute azimuthal angle (rotation around Z axis)
    const azimuthalAngle = Math.atan2(offset.x, offset.y);

    return { distance, polarAngle, azimuthalAngle };
  }, []);

  // Save camera state when controls change
  const updateCameraCoordinates = useCallback(() => {
    // Always read current values from simulatorViewData
    const currentViewType = simulatorViewData.currentViewType;
    const simulatorView = simulatorViewData.getViewForType(currentViewType);

    // DefaultTop never saves camera state - always uses default positioning
    if (currentViewType === CNCViewType.DefaultTop) {
      return;
    }

    if (orbitControlsRef.current) {
      const controls = orbitControlsRef.current;
      const position = controls.object.position;
      const target = controls.target;

      // Extract spherical coordinates from current camera position/target
      const spherical = extractSphericalFromCamera(
        new Vector3(position.x, position.y, position.z),
        new Vector3(target.x, target.y, target.z)
      );

      // For Top view (polar angle near 0), force azimuth to 0 to prevent numerical instability
      // When looking straight down, azimuth is mathematically undefined
      let azimuthalAngle = spherical.azimuthalAngle;
      if (Math.abs(spherical.polarAngle) < 0.1) { // Within ~5.7 degrees of straight down
        azimuthalAngle = 0;
      }

      // Save spherical coordinates to SimulatorView
      simulatorView.cameraDistance = spherical.distance;
      simulatorView.cameraPolarAngle = spherical.polarAngle;
      simulatorView.cameraAzimuthalAngle = azimuthalAngle;
    }
  }, [simulatorViewData, extractSphericalFromCamera]);

  const getMachineCenter = useCallback((): Vector3 => {
    // Calculate the camera look-at point:
    // X/Y: Middle of the base
    // Z: Top of spoilboard (using CoordinateUtil for accurate positioning)
    const baseWidth = machineData.baseWidth;
    const baseLength = machineData.baseLength;

    // Get spoilboard zero point (top surface) in simulator coordinates
    const spoilboardZero = CoordinateUtil.spoilboardZero;

    // Camera looks at middle of base at spoilboard top height
    const center = new Vector3(
      baseWidth / 2,      // X center of the base
      baseLength / 2,     // Y center of the base  
      spoilboardZero.z    // Z at top of spoilboard
    );

    return center;
  }, [machineData]);

  // Calculate camera positions based on view type
  const getCameraPosition = useCallback((): Vector3 => {
    // Calculate the center of the machine based on its dimensions
    const machineCenter = getMachineCenter();

    // Base distances that scale with machine size
    const baseWidth = machineData.baseWidth;
    const baseLength = machineData.baseLength;
    const baseHeight = machineData.baseHeight;
    const gantryHeight = machineData.gantryHeight;
    const totalHeight = baseHeight + gantryHeight;

    switch (simulatorViewData.currentViewType) {
      case CNCViewType.Front:
        // Position camera in front of machine, at spoilboard height level
        const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);
        const spoilboardTopZ = spoilboardBox.origin.z + spoilboardBox.height;

        // Convert machine coordinate height to simulator coordinates
        const spoilboardMachinePoint = new CNCPoint(0, 0, spoilboardTopZ, CoordinateType.MachineZero);
        const spoilboardSimulatorPoint = CoordinateUtil.toSimulator(spoilboardMachinePoint);

        return new Vector3(
          machineCenter.x,
          machineCenter.y + baseLength * 1.8,   // In FRONT of machine (positive Y)
          spoilboardSimulatorPoint.z             // At spoilboard top level
        );

      case CNCViewType.Side:
        // Position camera to the right side, halfway down the base, at top of gantry level
        const gantryZHeight = CoordinateUtil.getGantryZHeight();

        // Convert machine coordinate height to simulator coordinates
        const gantryMachinePoint = new CNCPoint(0, 0, gantryZHeight, CoordinateType.Simulator);
        const gantrySimulatorPoint = CoordinateUtil.toSimulator(gantryMachinePoint);

        return new Vector3(
          machineCenter.x + baseWidth * 2.04,   // Distance proportional to machine width (to the right side)
          machineCenter.y,                      // Halfway down the base (at center Y)
          gantrySimulatorPoint.z                // At top of gantry level
        );

      case CNCViewType.Top:
        // Position camera directly above machine (rotated 180 degrees)
        // Based on your actual position: x: 18, y: 28.37, z: 95.02 with center (18, 22, 14)
        // Rotated 180 degrees by changing Y offset from positive to negative
        return new Vector3(
          machineCenter.x,                        // Directly over center
          machineCenter.y - baseLength * 0.145,  // Slightly behind center (180° rotation)
          machineCenter.z + totalHeight * 2.89   // Proper height above machine for top view
        );

      case CNCViewType.DefaultTop:
        // Position camera directly above machine (always uses default positioning, ignores user changes)
        // This ensures consistent top view for wizard steps regardless of user camera movements
        return new Vector3(
          machineCenter.x,                        // Directly over center
          machineCenter.y - baseLength * 0.145,  // Slightly behind center (180° rotation)
          machineCenter.z + totalHeight * 2.89   // Proper height above machine for top view
        );

      case CNCViewType.ZAxisCalibration:
        // Position camera at the height of whatever we're measuring
        let referenceMachineHeight: number;

        switch (zAxisReferenceType) {
          case 'bed':
            // Position camera at bed height
            const bedBox = CoordinateUtil.getBedBox(machineState);
            referenceMachineHeight = bedBox.origin.z + bedBox.height;
            break;
          case 'material':
            // Position camera at material height
            const materialBox = CoordinateUtil.getMaterialBox(machineState);
            referenceMachineHeight = materialBox.origin.z + materialBox.height;
            break;
          case 'spoilboard':
          default:
            // Position camera at spoilboard height
            const spoilboardBox = CoordinateUtil.getSpoilboardBox(machineState);
            referenceMachineHeight = spoilboardBox.origin.z + spoilboardBox.height;
            break;
        }

        // Convert machine coordinate height to simulator coordinates
        const referenceMachinePoint = new CNCPoint(0, 0, referenceMachineHeight, CoordinateType.MachineZero);
        const referenceSimulatorPoint = CoordinateUtil.toSimulator(referenceMachinePoint);

        return new Vector3(
          machineCenter.x,
          machineCenter.y - baseLength * 1.8,   // Same front distance as regular Front view
          referenceSimulatorPoint.z             // Converted to simulator coordinates
        );

      case CNCViewType.Perspective:
      default:
        // Position camera for natural "machine on floor" view - angled perspective  
        // Based on your actual position: x: 54.85, y: -46.35, z: 37.06 with center (18, 22, 14)
        // Ratios: x offset = 36.85/36 = 1.02, y offset = -68.35/44 = -1.55, z offset = 23.06/28 = 0.82
        return new Vector3(
          machineCenter.x + baseWidth * 1.02,   // Right side offset
          machineCenter.y - baseLength * 1.55,  // Front offset  
          machineCenter.z + totalHeight * 0.82  // Elevated perspective
        );
    }
  }, [simulatorViewData, getMachineCenter, machineData, machineState, zAxisReferenceType]);

  const getCameraTarget = useCallback((): Vector3 => {
    // Determine target based on simulatorViewData.cameraTargetMode
    switch (simulatorViewData.cameraTargetMode) {
      case CameraTarget.Spindle:
        // Follow spindle XY position at spoilboard height
        const currentPos = ConfigurationState.Instance.currentMachinePoint;
        const spoilboardZero = CoordinateUtil.spoilboardZero;
        const currentPosSim = CoordinateUtil.toSimulator(currentPos);

        return new Vector3(
          currentPosSim.x,
          currentPosSim.y,
          spoilboardZero.z
        );

      case CameraTarget.GCodeCenter:
        // Use center of G-code extents at spoilboard height
        const extents = job?.getToolpathExtents();
        if (extents) {
          // Convert work zero point (0,0) to machine coordinates, then simulator
          const workZeroMachine = CoordinateUtil.toMachineZero(new CNCPoint(extents.maxX / 2, extents.maxY / 2, 0, CoordinateType.WorkZero));
          const centerSimulator = CoordinateUtil.toSimulator(workZeroMachine);
          return new Vector3(
            centerSimulator.x,
            centerSimulator.y,
            CoordinateUtil.spoilboardZero.z
          );
        }
        // Fallback to machine center if no extents available
        return getMachineCenter();

      case CameraTarget.MaterialCenter:
        // Use center of material box at top of material Z
        const materialBox = CoordinateUtil.getMaterialBox(machineState);
        const materialCenterX = materialBox.origin.x + materialBox.width / 2;
        const materialCenterY = materialBox.origin.y + materialBox.length / 2;
        const materialTopZ = materialBox.origin.z + materialBox.height;

        // Material box is in machine coordinates, convert to simulator
        const materialCenterMachine = new CNCPoint(materialCenterX, materialCenterY, materialTopZ, CoordinateType.MachineZero);
        const materialCenterSim = CoordinateUtil.toSimulator(materialCenterMachine);

        return new Vector3(
          materialCenterSim.x,
          materialCenterSim.y,
          materialCenterSim.z
        );

      case CameraTarget.MachineCenter:
      default:
        // Look at the machine center
        return getMachineCenter();
    }
  }, [simulatorViewData.cameraTargetMode, machineState, getMachineCenter, job]);

  /**
   * Compute camera position from spherical coordinates relative to target
   * This allows the camera to maintain its viewing angle and distance while the target moves
   */
  const computeCameraPositionFromSpherical = useCallback((
    target: Vector3,
    distance: number,
    polarAngle: number,
    azimuthalAngle: number
  ): Vector3 => {
    // Convert spherical coordinates to Cartesian offset from target
    // polarAngle: 0 = top, PI/2 = horizon, PI = bottom
    // azimuthalAngle: 0 = front (+Y), PI/2 = right (+X), PI = back (-Y), 3PI/2 = left (-X)
    const x = distance * Math.sin(polarAngle) * Math.sin(azimuthalAngle);
    const y = distance * Math.sin(polarAngle) * Math.cos(azimuthalAngle);
    const z = distance * Math.cos(polarAngle);

    return new Vector3(
      target.x + x,
      target.y + y,
      target.z + z
    );
  }, []);

  /**
   * Calculate default camera parameters for a given view type
   * This centralizes the logic used by both initialization and the home button
   */
  const getDefaultCameraParameters = useCallback((viewType: CNCViewType) => {
    // Calculate proper distance to fit entire machine in view based on view type
    const fov = 45 * (Math.PI / 180); // Convert to radians

    // Try to get aspect from actual camera if available, otherwise use props
    let aspect: number;
    if (orbitControlsRef.current) {
      const camera = orbitControlsRef.current.object as THREE.PerspectiveCamera;
      aspect = camera.aspect;
    } else {
      aspect = (typeof width === 'number' ? width : 800) / (typeof height === 'number' ? height : 600);
    }

    let requiredDistance: number;
    let polarAngle: number;
    let azimuthalAngle: number;

    switch (viewType) {
      case CNCViewType.Front:
      case CNCViewType.ZAxisCalibration:
        // For front view, need to see full width and height
        const widthFront = machineData.baseWidth;
        const heightFront = machineData.baseHeight + machineData.gantryHeight;
        const maxDimFront = Math.max(widthFront, heightFront / aspect);
        requiredDistance = maxDimFront / (2 * Math.tan(fov / 2)) * 1.9; // 1.9x for more padding
        polarAngle = 85 * Math.PI / 180; // 85 degrees - slightly angled down from horizontal
        azimuthalAngle = Math.PI; // Looking from front (machine Y+ is back, so front is at PI radians)
        break;

      case CNCViewType.Side:
        // For side view, need to see full length and height
        const length = machineData.baseLength;
        const heightSide = machineData.baseHeight + machineData.gantryHeight;
        const maxDimSide = Math.max(length, heightSide / aspect);
        requiredDistance = maxDimSide / (2 * Math.tan(fov / 2)) * 1.2; // 1.2x for padding
        polarAngle = 85 * Math.PI / 180; // 85 degrees - slightly angled down from horizontal
        azimuthalAngle = Math.PI / 2; // Looking from side
        break;

      case CNCViewType.Top:
      case CNCViewType.DefaultTop:
        // For top view, distance varies based on camera target mode
        polarAngle = 0; // Looking straight down
        azimuthalAngle = 0; // Doesn't matter

        // Calculate appropriate distance based on camera target mode
        switch (simulatorViewData.cameraTargetMode) {
          case CameraTarget.MaterialCenter:
            // Distance based on material size (if defined)
            const materialBox = CoordinateUtil.getMaterialBox(machineState);
            const materialWidth = materialBox.width;
            const materialLength = materialBox.length;
            const materialMaxDim = Math.max(materialWidth, materialLength);

            // If material is not defined or is 0x0, fallback to toolpaths distance
            if (materialMaxDim > 0) {
              requiredDistance = materialMaxDim * 1.5;
            } else {
              // Fallback to toolpaths distance with minimum 18x18
              const extents = job?.getToolpathExtents();
              if (extents) {
                const gcodeMaxDim = Math.max(extents.maxX, extents.maxY, 18); // Minimum 18
                requiredDistance = gcodeMaxDim * 1.5;
              } else {
                requiredDistance = Math.max(machineData.baseWidth, machineData.baseLength) * 1.5;
              }
            }
            break;

          case CameraTarget.GCodeCenter:
            // Distance based on G-code extents with minimum 18x18
            const extents = job?.getToolpathExtents();
            if (extents) {
              const gcodeMaxDim = Math.max(extents.maxX, extents.maxY, 18); // Minimum 18
              requiredDistance = gcodeMaxDim * 1.5;
            } else {
              // Fallback to machine size
              requiredDistance = Math.max(machineData.baseWidth, machineData.baseLength) * 1.5;
            }
            break;

          case CameraTarget.Spindle:
            // Spindle should use same distance as toolpaths with minimum 18x18
            const extentsSpindle = job?.getToolpathExtents();
            if (extentsSpindle) {
              const gcodeMaxDimSpindle = Math.max(extentsSpindle.maxX, extentsSpindle.maxY, 18); // Minimum 18
              requiredDistance = gcodeMaxDimSpindle * 1.5;
            } else {
              requiredDistance = Math.max(machineData.baseWidth, machineData.baseLength) * 1.5;
            }
            break;

          case CameraTarget.MachineCenter:
          default:
            // Distance to see entire machine - use larger multiplier to show full machine
            const bedMaxDim = Math.max(machineData.baseWidth, machineData.baseLength);
            requiredDistance = bedMaxDim * 1.5;
            break;
        }
        break;

      case CNCViewType.Perspective:
      default:
        // For perspective, use diagonal to see entire machine
        const diagonal = Math.sqrt(
          Math.pow(machineData.baseWidth, 2) +
          Math.pow(machineData.baseLength, 2) +
          Math.pow(machineData.baseHeight + machineData.gantryHeight, 2)
        );
        requiredDistance = diagonal / (2 * Math.tan(fov / 2)) * 1.1; // 1.1x for padding
        polarAngle = 75 * Math.PI / 180; // 75 degree elevation
        azimuthalAngle = 3 * Math.PI / 4; // 135 degrees - front-right corner (between PI/2=right and PI=front)
        break;
    }

    return { distance: requiredDistance, polarAngle, azimuthalAngle };
  }, [machineData, width, height, simulatorViewData, machineState, job]);

  // Get current camera position - ONE place where camera position is calculated
  const getCurrentCameraPosition = () => {
    // Always read current values from simulatorViewData
    const currentViewType = simulatorViewData.currentViewType;
    const simulatorView = simulatorViewData.getViewForType(currentViewType);

    // DefaultTop always uses calculated position, never saves/loads from state
    if (currentViewType === CNCViewType.DefaultTop) {
      const calculatedPos = getCameraPosition();
      return calculatedPos;
    }

    // If camera parameters are undefined, initialize them once
    if (simulatorView.cameraPolarAngle === undefined ||
      simulatorView.cameraDistance === undefined ||
      simulatorView.cameraAzimuthalAngle === undefined) {
      const { distance, polarAngle, azimuthalAngle } = getDefaultCameraParameters(currentViewType);
      simulatorView.cameraDistance = distance;
      simulatorView.cameraPolarAngle = polarAngle;
      simulatorView.cameraAzimuthalAngle = azimuthalAngle;
    }

    // Always compute camera position from spherical coordinates
    const target = getCameraTarget();
    const cameraPos = computeCameraPositionFromSpherical(
      target,
      simulatorView.cameraDistance!,
      simulatorView.cameraPolarAngle!,
      simulatorView.cameraAzimuthalAngle!
    );

    return cameraPos;
  };

  // Get current camera target
  const getCurrentCameraTarget = useCallback(() => {
    // Always return the calculated target - no state persistence needed
    return getCameraTarget();
  }, [getCameraTarget]);

  // Zoom control functions
  const handleZoomIn = useCallback(() => {
    if (orbitControlsRef.current) {
      const controls = orbitControlsRef.current;
      const camera = controls.object;
      const direction = new Vector3();
      camera.getWorldDirection(direction);
      direction.multiplyScalar(5); // Zoom step
      camera.position.add(direction); // Move camera toward target (zoom in)
      controls.update();
      updateCameraCoordinates();
    }
  }, [updateCameraCoordinates]);

  const handleZoomOut = useCallback(() => {
    if (orbitControlsRef.current) {
      const controls = orbitControlsRef.current;
      const camera = controls.object;
      const direction = new Vector3();
      camera.getWorldDirection(direction);
      direction.multiplyScalar(5); // Zoom step
      camera.position.sub(direction); // Move camera away from target (zoom out)
      controls.update();
      updateCameraCoordinates();
    }
  }, [updateCameraCoordinates]);

  const handleZoomHome = useCallback(() => {
    if (orbitControlsRef.current) {
      // Always read current view type from simulatorViewData to get the latest value
      const viewTypeToUse = simulatorViewData.currentViewType;

      // Reset to default position for current view type
      const defaultTarget = getCameraTarget();

      // Get default camera parameters
      const { distance: requiredDistance, polarAngle, azimuthalAngle } = getDefaultCameraParameters(viewTypeToUse);

      // Compute camera position from spherical coordinates
      const defaultPosition = computeCameraPositionFromSpherical(
        defaultTarget,
        requiredDistance,
        polarAngle,
        azimuthalAngle
      );

      // Save the computed distance and angles to the appropriate view
      const targetSimulatorView = simulatorViewData.getViewForType(viewTypeToUse);
      targetSimulatorView.cameraDistance = requiredDistance;
      targetSimulatorView.cameraPolarAngle = polarAngle;
      targetSimulatorView.cameraAzimuthalAngle = azimuthalAngle;

      // Actually move the camera
      const controls = orbitControlsRef.current;
      controls.object.position.copy(defaultPosition);
      controls.target.copy(defaultTarget);
      controls.update();
    }
  }, [getCameraTarget, getDefaultCameraParameters, computeCameraPositionFromSpherical, simulatorViewData]);

  // Handle background clicks and spindle dragging
  const handleCanvasPointerDown = useCallback((event: any) => {
    // Don't handle click events if spindle dragging is disabled
    if (!enableSpindleDrag) return;

    // Check if this is a background click (no intersections with objects)
    // If the event reaches here without being stopped by an object, it's a background click
    if (configState.isSpindleDragging && event.intersections?.length === 0) {
      // Background click while spindle is selected - deselect spindle
      configState.deselectSpindle();
      return;
    }

    // If in spindle drag mode and clicking on something, allow the object to handle it
    if (configState.isSpindleDragging) {
      // The spindle or other objects will handle their own clicks
      return;
    }
  }, [configState, enableSpindleDrag]);

  const handleCanvasPointerMove = useCallback((event: any) => {
    if (!enableSpindleDrag || !configState.isSpindleDragging) return;

    // TODO: Implement spindle position calculation based on mouse position
    // This would involve raycasting to find the intersection with the work surface
    event.stopPropagation();
  }, [configState.isSpindleDragging, enableSpindleDrag]);

  const handleCanvasPointerUp = useCallback((event: any) => {
    if (!enableSpindleDrag || !configState.isSpindleDragging) return;

    event.stopPropagation();
  }, [configState.isSpindleDragging, enableSpindleDrag]);

  // Handle camera following when spindle position changes
  const handleCameraFollow = useCallback((changedProperties?: string[]) => {
    if (!orbitControlsRef.current) return;
    if (simulatorViewData.cameraTargetMode !== CameraTarget.Spindle) return;
    if (!changedProperties || !changedProperties.includes('currentMachinePoint')) return;

    // Get new target position
    const newTarget = getCameraTarget();

    // Read current view's camera settings
    const simulatorView = simulatorViewData.getViewForType(simulatorViewData.currentViewType);

    // Compute camera position from stored spherical coordinates
    const newCameraPos = computeCameraPositionFromSpherical(
      newTarget,
      simulatorView.cameraDistance ?? 20,
      simulatorView.cameraPolarAngle ?? Math.PI / 4,
      simulatorView.cameraAzimuthalAngle ?? Math.PI / 4
    );

    // Update camera position and target
    const camera = orbitControlsRef.current.object;
    camera.position.copy(newCameraPos);
    orbitControlsRef.current.target.copy(newTarget);
    orbitControlsRef.current.update();

  }, [simulatorViewData, getCameraTarget, computeCameraPositionFromSpherical]);

  // Handle camera target mode changes in Top view
  const handleTopViewTargetChange = useCallback((changedProperties?: string[]) => {
    // Only handle if we're in Top view and cameraTargetMode changed
    if (simulatorViewData.currentViewType !== CNCViewType.Top) return;
    if (!changedProperties || !changedProperties.includes('cameraTargetMode')) return;

    // Recalculate distance for the new target type using centralized function
    const { distance, polarAngle, azimuthalAngle } = getDefaultCameraParameters(CNCViewType.Top);

    // Update simulator view with new parameters
    const simulatorView = simulatorViewData.getViewForType(CNCViewType.Top);
    simulatorView.cameraDistance = distance;
    simulatorView.cameraPolarAngle = polarAngle;
    simulatorView.cameraAzimuthalAngle = azimuthalAngle;

    // Update camera position immediately
    if (orbitControlsRef.current) {
      const newTarget = getCameraTarget();
      const newCameraPos = computeCameraPositionFromSpherical(
        newTarget,
        distance,
        polarAngle,
        azimuthalAngle
      );

      const camera = orbitControlsRef.current.object;
      camera.position.copy(newCameraPos);
      orbitControlsRef.current.target.copy(newTarget);
      orbitControlsRef.current.update();
    }
  }, [simulatorViewData, getDefaultCameraParameters, getCameraTarget, computeCameraPositionFromSpherical]);

  return (
    <>
      {/* Listen to simulatorViewData and specific configState properties only */}
      <ObserveMultiProperties
        key="cnc-viewer-state-observer"
        listenTo={[
          {
            object: simulatorViewData.getViewForType(simulatorViewData.currentViewType), properties: [
              'workHome', 'toolpaths', 'dryRunToolpaths', 'softLimits', 'machineZero', 'machineHome',
              'gantry', 'base', 'spindle', 'bed', 'railing', 'spoilBoard', 'material', 'clamps', 'tool',
              'rotary', 'verticalTable', 'laser', 'laserPointer', 'drillHead', 'atc',
              'cameraDistance', 'cameraPolarAngle', 'cameraAzimuthalAngle'
            ]
          }, // All visual properties and camera spherical coordinates
          { object: simulatorViewData, properties: ['currentViewType', 'cameraTargetMode', 'viewChangeCounter', 'shareVisibilitySettings'] }, // View type, camera target, view change trigger, and sharing setting
          { object: configState, properties: ['isSpindleDragging', 'isOrbitEnabled', 'currentMachinePoint'] }, // Interaction properties and current position
          { object: machineData, properties: ['hasVerticalTable', 'hasLaser', 'hasLaserPointer', 'hasDrillHead', 'hasATC', 'hasFixedTouchPlate', 'rotaryAxis'] } // Feature existence flags
        ]}
        control={(changedProperties) => {
          const colors = ConfigurationDataColors.Instance;

          // Handle camera following when currentMachinePoint changes
          handleCameraFollow(changedProperties);

          // Handle camera target mode changes in Top view
          handleTopViewTargetChange(changedProperties);

          return (
            <div style={{
              width: typeof width === 'number' ? `${width}px` : width,
              height: typeof height === 'number' ? `${height}px` : height,
              position: 'relative',
              cursor: configState.isSpindleDragging ? 'crosshair' : 'default'
            }}>
              {/* Zoom Controls */}
              <div style={{
                position: 'absolute',
                top: '20px',
                right: '20px',
                display: 'flex',
                flexDirection: 'column',
                gap: '8px',
                zIndex: 1000
              }}>

                <button
                  onClick={handleZoomIn}
                  style={{
                    width: '40px',
                    height: '40px',
                    backgroundColor: ConfigurationDataColors.Instance.lightOverlay,
                    border: `2px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '18px',
                    fontWeight: 'bold',
                    color: ConfigurationDataColors.Instance.darkTextColor,
                    transition: 'all 0.2s ease',
                    userSelect: 'none'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.8'); // Primary color with transparency
                    e.currentTarget.style.color = ConfigurationDataColors.Instance.lightTextColor;
                    e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.primaryColor;
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                    e.currentTarget.style.color = ConfigurationDataColors.Instance.darkTextColor;
                    e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.secondaryBorderColor;
                  }}
                  title="Zoom In"
                >
                  +
                </button>

                <button
                  onClick={handleZoomOut}
                  style={{
                    width: '40px',
                    height: '40px',
                    backgroundColor: ConfigurationDataColors.Instance.lightOverlay,
                    border: `2px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '18px',
                    fontWeight: 'bold',
                    color: ConfigurationDataColors.Instance.darkTextColor,
                    transition: 'all 0.2s ease',
                    userSelect: 'none'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.8'); // Primary color with transparency
                    e.currentTarget.style.color = ConfigurationDataColors.Instance.lightTextColor;
                    e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.primaryColor;
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                    e.currentTarget.style.color = ConfigurationDataColors.Instance.darkTextColor;
                    e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.secondaryBorderColor;
                  }}
                  title="Zoom Out"
                >
                  −
                </button>

                <button
                  onClick={handleZoomHome}
                  style={{
                    width: '40px',
                    height: '40px',
                    backgroundColor: ConfigurationDataColors.Instance.lightOverlay,
                    border: `2px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '18px',
                    fontWeight: 'bold',
                    color: ConfigurationDataColors.Instance.darkTextColor,
                    transition: 'all 0.2s ease',
                    userSelect: 'none'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.8'); // Primary color with transparency
                    e.currentTarget.style.color = ConfigurationDataColors.Instance.lightTextColor;
                    e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.primaryColor;
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                    e.currentTarget.style.color = ConfigurationDataColors.Instance.darkTextColor;
                    e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.secondaryBorderColor;
                  }}
                  title="Reset to Default View"
                >
                  {SystemIcons.home}
                </button>

                {/* Settings Button */}
                {showSettingsButton && (
                  <button
                    onClick={() => setSettingsDialogOpen(true)}
                    style={{
                      width: '40px',
                      height: '40px',
                      backgroundColor: ConfigurationDataColors.Instance.lightOverlay,
                      border: `2px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
                      borderRadius: '6px',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: '18px',
                      fontWeight: 'bold',
                      color: ConfigurationDataColors.Instance.darkTextColor,
                      transition: 'all 0.2s ease',
                      userSelect: 'none'
                    }}
                    onMouseEnter={(e) => {
                      e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.8'); // Primary color with transparency
                      e.currentTarget.style.color = ConfigurationDataColors.Instance.lightTextColor;
                      e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.primaryColor;
                    }}
                    onMouseLeave={(e) => {
                      e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                      e.currentTarget.style.color = ConfigurationDataColors.Instance.darkTextColor;
                      e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.secondaryBorderColor;
                    }}
                    title="3D Viewer Settings"
                  >
                    {SystemIcons.viewerSettings}
                  </button>
                )}

                {/* Share Visibility Settings Toggle Button */}
                {showSettingsButton && (
                  <button
                    onClick={() => {
                      simulatorViewData.shareVisibilitySettings = !simulatorViewData.shareVisibilitySettings;
                    }}
                    style={{
                      width: '40px',
                      height: '40px',
                      backgroundColor: simulatorViewData.shareVisibilitySettings
                        ? ConfigurationDataColors.Instance.successColor  // Green when sharing enabled
                        : ConfigurationDataColors.Instance.lightOverlay,
                      border: `2px solid ${simulatorViewData.shareVisibilitySettings
                        ? ConfigurationDataColors.Instance.successColor
                        : ConfigurationDataColors.Instance.secondaryBorderColor}`,
                      borderRadius: '6px',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      fontSize: '18px',
                      fontWeight: 'bold',
                      color: simulatorViewData.shareVisibilitySettings
                        ? ConfigurationDataColors.Instance.lightTextColor
                        : ConfigurationDataColors.Instance.darkTextColor,
                      transition: 'all 0.2s ease',
                      userSelect: 'none'
                    }}
                    onMouseEnter={(e) => {
                      if (!simulatorViewData.shareVisibilitySettings) {
                        e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.hoverColor.replace('0.1', '0.8');
                        e.currentTarget.style.color = ConfigurationDataColors.Instance.lightTextColor;
                        e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.primaryColor;
                      }
                    }}
                    onMouseLeave={(e) => {
                      if (!simulatorViewData.shareVisibilitySettings) {
                        e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                        e.currentTarget.style.color = ConfigurationDataColors.Instance.darkTextColor;
                        e.currentTarget.style.borderColor = ConfigurationDataColors.Instance.secondaryBorderColor;
                      }
                    }}
                    title={simulatorViewData.shareVisibilitySettings
                      ? "Share Visibility Settings Across Views (Enabled)"
                      : "Share Visibility Settings Across Views (Disabled)"}
                  >
                    {SystemIcons.shareVisibilitySettings}
                  </button>
                )}
              </div>

              {/* View Type Buttons - Bottom Right */}
              {showViewTypeButtons && (
                <div style={{
                  position: 'absolute',
                  bottom: '20px',
                  right: '20px',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '8px',
                  zIndex: 1000
                }}>
                  {[CNCViewType.Perspective, CNCViewType.Side, CNCViewType.Top, CNCViewType.Front]
                    .map((type) => {
                      const isActive = simulatorViewData.currentViewType === type;

                      // Get icon based on view type
                      let viewIcon;
                      switch (type) {
                        case CNCViewType.Perspective:
                          viewIcon = SystemIcons.viewPerspective;
                          break;
                        case CNCViewType.Side:
                          viewIcon = SystemIcons.viewSide;
                          break;
                        case CNCViewType.Top:
                          viewIcon = SystemIcons.viewTop;
                          break;
                        case CNCViewType.Front:
                          viewIcon = SystemIcons.viewFront;
                          break;
                        default:
                          viewIcon = SystemIcons.viewPerspective;
                      }

                      return (
                        <button
                          key={type}
                          onClick={() => {
                            // Copy visibility settings if sharing is enabled
                            if (simulatorViewData.shareVisibilitySettings && simulatorViewData.currentViewType !== type) {
                              const sourceView = simulatorViewData.getViewForType(simulatorViewData.currentViewType);
                              const targetView = simulatorViewData.getViewForType(type);
                              simulatorViewData.copyVisibilitySettings(sourceView, targetView);
                            }

                            simulatorViewData.currentViewType = type;
                            // Counter is incremented in setter, triggering re-render
                            // Now reset camera for the new view
                            handleZoomHome();
                          }}
                          style={{
                            width: '40px',
                            height: '40px',
                            backgroundColor: isActive
                              ? ConfigurationDataColors.Instance.successColor  // Green for selected
                              : ConfigurationDataColors.Instance.lightOverlay, // Transparent for unselected
                            border: `2px solid ${isActive ? ConfigurationDataColors.Instance.successColor : colors.secondaryBorderColor
                              }`,
                            borderRadius: '6px',
                            cursor: isActive ? 'default' : 'pointer',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            color: isActive ? colors.lightTextColor : colors.darkTextColor,
                            transition: 'all 0.2s ease',
                            userSelect: 'none'
                          }}
                          onMouseEnter={(e) => {
                            if (!isActive) {
                              e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay.replace('0.3', '0.5');
                            }
                          }}
                          onMouseLeave={(e) => {
                            if (!isActive) {
                              e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                            }
                          }}
                          title={type}
                        >
                          {viewIcon}
                        </button>
                      );
                    })}
                </div>
              )}

              {/* Camera Target Controls - Bottom Left */}
              <ObserveState
                key="camera-target-mode-buttons"
                listenTo={simulatorViewData}
                properties={['cameraTargetMode']}
                control={() => {
                  return (
                    <div style={{
                      position: 'absolute',
                      bottom: '20px',
                      left: '20px',
                      display: 'flex',
                      flexDirection: 'column',
                      gap: '8px',
                      zIndex: 1000
                    }}>
                      {/* Machine Center Target */}
                      <button
                        onClick={() => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.MachineCenter) {
                            simulatorViewData.cameraTargetMode = CameraTarget.MachineCenter;
                            handleZoomHome();
                          }
                        }}
                        style={{
                          width: '40px',
                          height: '40px',
                          backgroundColor: simulatorViewData.cameraTargetMode === CameraTarget.MachineCenter
                            ? ConfigurationDataColors.Instance.successColor  // Green for selected
                            : ConfigurationDataColors.Instance.lightOverlay, // Transparent for unselected
                          border: `2px solid ${simulatorViewData.cameraTargetMode === CameraTarget.MachineCenter
                            ? ConfigurationDataColors.Instance.successColor
                            : ConfigurationDataColors.Instance.secondaryBorderColor}`,
                          borderRadius: '6px',
                          cursor: simulatorViewData.cameraTargetMode === CameraTarget.MachineCenter ? 'default' : 'pointer',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          color: simulatorViewData.cameraTargetMode === CameraTarget.MachineCenter
                            ? ConfigurationDataColors.Instance.lightTextColor
                            : ConfigurationDataColors.Instance.darkTextColor,
                          transition: 'all 0.2s ease',
                          userSelect: 'none'
                        }}
                        onMouseEnter={(e) => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.MachineCenter) {
                            e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay.replace('0.3', '0.5');
                          }
                        }}
                        onMouseLeave={(e) => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.MachineCenter) {
                            e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                          }
                        }}
                        title="Target: Machine Center"
                      >
                        {SystemIcons.cameraCenter}
                      </button>

                      {/* Spindle Target */}
                      <button
                        onClick={() => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.Spindle) {
                            simulatorViewData.cameraTargetMode = CameraTarget.Spindle;
                            handleZoomHome();
                          }
                        }}
                        style={{
                          width: '40px',
                          height: '40px',
                          backgroundColor: simulatorViewData.cameraTargetMode === CameraTarget.Spindle
                            ? ConfigurationDataColors.Instance.successColor  // Green for selected
                            : ConfigurationDataColors.Instance.lightOverlay, // Transparent for unselected
                          border: `2px solid ${simulatorViewData.cameraTargetMode === CameraTarget.Spindle
                            ? ConfigurationDataColors.Instance.successColor
                            : ConfigurationDataColors.Instance.secondaryBorderColor}`,
                          borderRadius: '6px',
                          cursor: simulatorViewData.cameraTargetMode === CameraTarget.Spindle ? 'default' : 'pointer',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          color: simulatorViewData.cameraTargetMode === CameraTarget.Spindle
                            ? ConfigurationDataColors.Instance.lightTextColor
                            : ConfigurationDataColors.Instance.darkTextColor,
                          transition: 'all 0.2s ease',
                          userSelect: 'none'
                        }}
                        onMouseEnter={(e) => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.Spindle) {
                            e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay.replace('0.3', '0.5');
                          }
                        }}
                        onMouseLeave={(e) => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.Spindle) {
                            e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                          }
                        }}
                        title="Target: Spindle Position"
                      >
                        {SystemIcons.cameraFollowSpindle}
                      </button>

                      {/* GCode Center Target */}
                      <button
                        onClick={() => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.GCodeCenter) {
                            simulatorViewData.cameraTargetMode = CameraTarget.GCodeCenter;
                            handleZoomHome();
                          }
                        }}
                        style={{
                          width: '40px',
                          height: '40px',
                          backgroundColor: simulatorViewData.cameraTargetMode === CameraTarget.GCodeCenter
                            ? ConfigurationDataColors.Instance.successColor  // Green for selected
                            : ConfigurationDataColors.Instance.lightOverlay, // Transparent for unselected
                          border: `2px solid ${simulatorViewData.cameraTargetMode === CameraTarget.GCodeCenter
                            ? ConfigurationDataColors.Instance.successColor
                            : ConfigurationDataColors.Instance.secondaryBorderColor}`,
                          borderRadius: '6px',
                          cursor: simulatorViewData.cameraTargetMode === CameraTarget.GCodeCenter ? 'default' : 'pointer',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          color: simulatorViewData.cameraTargetMode === CameraTarget.GCodeCenter
                            ? ConfigurationDataColors.Instance.lightTextColor
                            : ConfigurationDataColors.Instance.darkTextColor,
                          transition: 'all 0.2s ease',
                          userSelect: 'none'
                        }}
                        onMouseEnter={(e) => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.GCodeCenter) {
                            e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay.replace('0.3', '0.5');
                          }
                        }}
                        onMouseLeave={(e) => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.GCodeCenter) {
                            e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                          }
                        }}
                        title="Target: G-Code Center"
                      >
                        {SystemIcons.layers}
                      </button>

                      {/* Material Center Target */}
                      <button
                        onClick={() => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.MaterialCenter) {
                            simulatorViewData.cameraTargetMode = CameraTarget.MaterialCenter;
                            handleZoomHome();
                          }
                        }}
                        style={{
                          width: '40px',
                          height: '40px',
                          backgroundColor: simulatorViewData.cameraTargetMode === CameraTarget.MaterialCenter
                            ? ConfigurationDataColors.Instance.successColor  // Green for selected
                            : ConfigurationDataColors.Instance.lightOverlay, // Transparent for unselected
                          border: `2px solid ${simulatorViewData.cameraTargetMode === CameraTarget.MaterialCenter
                            ? ConfigurationDataColors.Instance.successColor
                            : ConfigurationDataColors.Instance.secondaryBorderColor}`,
                          borderRadius: '6px',
                          cursor: simulatorViewData.cameraTargetMode === CameraTarget.MaterialCenter ? 'default' : 'pointer',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          color: simulatorViewData.cameraTargetMode === CameraTarget.MaterialCenter
                            ? ConfigurationDataColors.Instance.lightTextColor
                            : ConfigurationDataColors.Instance.darkTextColor,
                          transition: 'all 0.2s ease',
                          userSelect: 'none'
                        }}
                        onMouseEnter={(e) => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.MaterialCenter) {
                            e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay.replace('0.3', '0.5');
                          }
                        }}
                        onMouseLeave={(e) => {
                          if (simulatorViewData.cameraTargetMode !== CameraTarget.MaterialCenter) {
                            e.currentTarget.style.backgroundColor = ConfigurationDataColors.Instance.lightOverlay;
                          }
                        }}
                        title="Target: Material Center"
                      >
                        {SystemIcons.material}
                      </button>
                    </div>
                  );
                }}
              />

              <Canvas
                onPointerDown={handleCanvasPointerDown}
                onPointerMove={handleCanvasPointerMove}
                onPointerUp={handleCanvasPointerUp}
                gl={{
                  antialias: true,
                  alpha: true,
                  preserveDrawingBuffer: false, // Can cause memory issues if true
                  powerPreference: 'high-performance', // Request dedicated GPU if available
                  failIfMajorPerformanceCaveat: false // Don't fail on slower hardware
                }}
                onCreated={({ gl }) => {
                  // Add WebGL context recovery
                  const canvas = gl.domElement;

                  const handleContextLost = (event: Event) => {
                    console.warn('🚨 WebGL context lost! Preventing default to enable recovery...');
                    event.preventDefault();
                  };

                  const handleContextRestored = () => {
                    // //// console.log('✅ WebGL context restored successfully');
                  };

                  canvas.addEventListener('webglcontextlost', handleContextLost);
                  canvas.addEventListener('webglcontextrestored', handleContextRestored);

                  // Store cleanup function
                  const cleanup = () => {
                    canvas.removeEventListener('webglcontextlost', handleContextLost);
                    canvas.removeEventListener('webglcontextrestored', handleContextRestored);
                  };

                  // Return cleanup function (React Three Fiber will call this on unmount)
                  return cleanup;
                }}
              >
                {/* Camera */}
                <PerspectiveCamera
                  makeDefault
                  position={getCurrentCameraPosition()}
                  fov={45}
                  near={0.1}
                  far={1000}
                  up={[0, 0, 1]}
                />

                {/* Controls - always render but disable interaction when orbit is off */}
                <OrbitControls
                  ref={orbitControlsRef}
                  target={getCurrentCameraTarget()}
                  enablePan={enableOrbit && configState.isOrbitEnabled && !configState.isSpindleDragging}
                  enableZoom={enableOrbit && !configState.isSpindleDragging}
                  enableRotate={enableOrbit && configState.isOrbitEnabled && !configState.isSpindleDragging}
                  onChange={updateCameraCoordinates}
                  zoomSpeed={1.2}
                  enableDamping={true}
                  dampingFactor={0.1}
                />

                {/* Enhanced Lighting Setup */}
                {/* Main directional light from above-front */}
                {/* eslint-disable-next-line @typescript-eslint/ban-ts-comment */}
                {/* @ts-ignore */}
                <directionalLight
                  position={[10, 10, 15]}
                  intensity={2.5}
                  color={ConfigurationDataColors.Instance.lightTextColor}
                  castShadow={false}
                />

                {/* Secondary directional light from the side */}
                {/* eslint-disable-next-line @typescript-eslint/ban-ts-comment */}
                {/* @ts-ignore */}
                <directionalLight
                  position={[-10, 5, 10]}
                  intensity={2.0}
                  color={ConfigurationDataColors.Instance.lightTextColor}
                />

                {/* Fill light from below to reduce harsh shadows */}
                {/* eslint-disable-next-line @typescript-eslint/ban-ts-comment */}
                {/* @ts-ignore */}
                <directionalLight
                  position={[0, -5, 5]}
                  intensity={1.2}
                  color={ConfigurationDataColors.Instance.lightTextColor}
                />

                {/* Bright ambient light for overall illumination */}
                {/* eslint-disable-next-line @typescript-eslint/ban-ts-comment */}
                {/* @ts-ignore */}
                <ambientLight intensity={2.0} color={ConfigurationDataColors.Instance.lightTextColor} />

                {/* Point light for local highlights */}
                {/* eslint-disable-next-line @typescript-eslint/ban-ts-comment */}
                {/* @ts-ignore */}
                <pointLight
                  position={[20, 20, 20]}
                  intensity={1.5}
                  color={ConfigurationDataColors.Instance.lightTextColor}
                  decay={2}
                  distance={100}
                />

                {/* Background plane to capture clicks for deselecting spindle */}
                {configState.isSpindleDragging && (
                  <mesh
                    position={[0, 0, -1000]}
                    onPointerDown={(e) => {
                      e.stopPropagation();
                      configState.deselectSpindle();
                    }}
                  >
                    <planeGeometry args={[10000, 10000]} />
                    <meshBasicMaterial transparent opacity={0} />
                  </mesh>
                )}

                {/* CNC Machine - pass data directly without observing here */}
                {(() => {
                  // //// console.log('🎥 CNCViewer Render Check:', {
                  //   simulatorView: simulatorView,
                  //   gantryStyle: simulatorView?.gantry,
                  //   machineData: !!machineData,
                  //   machineState: !!machineState
                  // });
                  return null;
                })()}
                <CNCMachine
                  simulatorView={simulatorViewData.getViewForType(simulatorViewData.currentViewType)}
                  machineState={machineState}
                  machineData={machineData}
                  job={job}
                  orbitControlsRef={orbitControlsRef}
                  enableClampDragging={enableClampDragging}
                  enableSpindleDrag={enableSpindleDrag}
                  isTopDownView={isTopDownView}
                />
              </Canvas>
            </div>
          );
        }}
      />

      {/* Settings Dialog - Reads current view dynamically */}
      <ViewerSettingsDialog
        open={settingsDialogOpen}
        onClose={() => setSettingsDialogOpen(false)}
        simulatorView={simulatorViewData.getViewForType(simulatorViewData.currentViewType)}
        isHardcodedSettings={isHardcodedSettings}
      />
    </>
  );
}
