import { Vector3 } from 'three';
import { LinePoint } from './LinePoint';
import { SegmentColorizer, SegmentMetadata, SimpleColorizer } from './SegmentColorizer';

/**
 * Interface for G-code parsing results
 */
export interface GCodeParseResult {
  linePoints: LinePoint[];
  totalDistance: number;
  estimatedTime: number;
  bounds: {
    min: Vector3;
    max: Vector3;
  };
}

/**
 * G-code command interface
 */
interface GCodeCommand {
  command: string;
  x?: number;
  y?: number;
  z?: number;
  i?: number; // Arc center offset X
  j?: number; // Arc center offset Y
  k?: number; // Arc center offset Z
  r?: number; // Arc radius
  f?: number; // Feed rate
  s?: number; // Spindle speed
  t?: number; // Tool number
  line: number;
}

/**
 * Custom G-code parser for CNC toolpath visualization
 */
export class GCodeParser {
  private currentPosition = new Vector3(0, 0, 0);
  private currentFeedRate = 1000; // mm/min
  private currentSpindleSpeed = 0;
  private currentTool = 0;
  private lastGCommand = ''; // Track last G command for lines without explicit commands
  private colorizer: SegmentColorizer;
  private isInches = true; // Track units: true = G20 (inches), false = G21 (mm)
  private readonly MM_TO_INCHES = 1 / 25.4; // Conversion factor

  // Tool diameter lookup (tool number -> diameter in mm)
  private toolDiameters = new Map<number, number>([
    [1, 6.35], // 1/4 inch end mill
    [2, 3.175], // 1/8 inch end mill
    [3, 1.5875], // 1/16 inch end mill
    [4, 12.7], // 1/2 inch end mill
  ]);

  constructor(colorizer?: SegmentColorizer) {
    this.colorizer = colorizer || new SimpleColorizer();
  }

  /**
   * Parse G-code text into line points for visualization
   */
  public parse(gCodeText: string): GCodeParseResult {
    const lines = gCodeText.split('\n');
    const linePoints: LinePoint[] = [];
    let totalDistance = 0;
    let estimatedTime = 0;

    const bounds = {
      min: new Vector3(Infinity, Infinity, Infinity),
      max: new Vector3(-Infinity, -Infinity, -Infinity)
    };

    // Reset parser state
    this.currentPosition.set(0, 0, 0);
    this.currentFeedRate = 1000;
    this.currentSpindleSpeed = 0;
    this.currentTool = 0;
    this.lastGCommand = 'G0'; // Default to rapid positioning
    this.isInches = true; // Default to inches (G20)

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line || line.startsWith(';') || line.startsWith('(')) {
        continue; // Skip empty lines and comments
      }

      const command = this.parseLine(line, i + 1);
      if (!command) continue;

      const previousPosition = this.currentPosition.clone();

      // Handle arc commands specially (G2/G3)
      if (command.command === 'G2' || command.command === 'G02' ||
        command.command === 'G3' || command.command === 'G03') {
        const arcData = this.interpolateArc(command);

        for (let segIdx = 0; segIdx < arcData.segments.length; segIdx++) {
          const arcPoint = arcData.segments[segIdx];
          const segStart = linePoints.length > 0 ? linePoints[linePoints.length - 1].position : previousPosition;
          const distance = segStart.distanceTo(arcPoint);
          totalDistance += distance;

          const timeMinutes = distance / this.currentFeedRate;
          estimatedTime += timeMinutes * 60;

          this.updateBounds(arcPoint, bounds);

          const metadata: SegmentMetadata = {
            radius: 0,
            segmentStart: segStart,
            segmentEnd: arcPoint,
            speed: this.currentFeedRate,
            temp: this.currentSpindleSpeed,
            gCodeLine: command.line
          };

          const color = this.colorizer.getColor(metadata);
          const linePoint = new LinePoint(arcPoint, 0, color);

          // Populate G-code metadata
          linePoint.segmentStart = segStart.clone();
          linePoint.gCommand = command.command;
          linePoint.lineNumber = command.line;
          linePoint.originalGCodeLine = lines[command.line - 1]?.trim();
          linePoint.parameters = {
            x: command.x,
            y: command.y,
            z: command.z,
            i: command.i,
            j: command.j,
            k: command.k,
            r: command.r,
            f: command.f,
            s: command.s
          };
          linePoint.isArcSegment = true;
          linePoint.arcCenter = arcData.center;
          linePoint.arcRadius = arcData.radius;
          linePoint.isClockwise = arcData.isClockwise;
          linePoint.arcStartAngle = arcData.startAngle;
          linePoint.arcEndAngle = arcData.endAngle;
          linePoint.arcSegmentIndex = segIdx;
          linePoint.arcTotalSegments = arcData.segments.length;

          linePoints.push(linePoint);
        }

        continue;
      }

      const movement = this.processCommand(command);

      if (movement) {
        const distance = previousPosition.distanceTo(this.currentPosition);
        totalDistance += distance;

        // Calculate movement time (feed rate is in mm/min)
        const timeMinutes = distance / this.currentFeedRate;
        estimatedTime += timeMinutes * 60; // Convert to seconds

        // Update bounds
        this.updateBounds(this.currentPosition, bounds);

        // Create line point with appropriate visualization
        const metadata: SegmentMetadata = {
          radius: 0, // Not used for simple lines
          segmentStart: previousPosition,
          segmentEnd: this.currentPosition,
          speed: this.currentFeedRate,
          temp: this.currentSpindleSpeed,
          gCodeLine: command.line
        };

        const color = this.colorizer.getColor(metadata);

        const linePoint = new LinePoint(
          this.currentPosition.clone(),
          0, // Radius not used for simple lines
          color
        );

        // Populate G-code metadata
        linePoint.segmentStart = previousPosition.clone();
        linePoint.gCommand = command.command;
        linePoint.lineNumber = command.line;
        linePoint.originalGCodeLine = lines[command.line - 1]?.trim();
        linePoint.parameters = {
          x: command.x,
          y: command.y,
          z: command.z,
          f: command.f,
          s: command.s
        };
        linePoint.isArcSegment = false;

        linePoints.push(linePoint);
      }
    }

    return {
      linePoints,
      totalDistance,
      estimatedTime,
      bounds
    };
  }

  /**
   * Parse a single G-code line into a command object
   */
  private parseLine(line: string, lineNumber: number): GCodeCommand | null {
    // Split line into tokens, handling both space-separated and concatenated parameters
    // Convert "G0X1.0Y2.0" into ["G0", "X1.0", "Y2.0"]
    // Remove N-code line numbers (e.g., "N0001 ", "N100 ")
    const cleanLine = line.toUpperCase().trim().replace(/^N\d+\s*/i, '');
    const tokens: string[] = [];

    // Match patterns like G0, M3, X1.234, Y-5.678, etc.
    const tokenRegex = /([GMTXYZIJKRFSP][-+]?\d*\.?\d+)/g;
    let match;
    while ((match = tokenRegex.exec(cleanLine)) !== null) {
      tokens.push(match[1]);
    }

    if (tokens.length === 0) return null;

    let command: GCodeCommand = {
      command: this.lastGCommand, // Default to last G command (modal)
      line: lineNumber
    };

    // Look for G/M/T command in tokens
    for (const token of tokens) {
      if (token.startsWith('G') && token.length > 1) {
        // Extract G command (e.g., "G0", "G01", "G20")
        const gMatch = token.match(/G(\d+)/);
        if (gMatch) {
          command.command = 'G' + gMatch[1];
          this.lastGCommand = command.command;
        }
      } else if (token.startsWith('M') && token.length > 1) {
        const mMatch = token.match(/M(\d+)/);
        if (mMatch) {
          command.command = 'M' + mMatch[1];
        }
      } else if (token.startsWith('T') && token.length > 1) {
        const tMatch = token.match(/T(\d+)/);
        if (tMatch) {
          command.t = parseInt(tMatch[1]);
        }
      }
    }

    // Parse all parameter tokens
    for (const token of tokens) {
      if (token.length < 2) continue;

      const param = token[0];
      const value = parseFloat(token.substring(1));

      if (isNaN(value)) continue;

      switch (param) {
        case 'X': command.x = value; break;
        case 'Y': command.y = value; break;
        case 'Z': command.z = value; break;
        case 'I': command.i = value; break;
        case 'J': command.j = value; break;
        case 'K': command.k = value; break;
        case 'R': command.r = value; break;
        case 'F': command.f = value; break;
        case 'S': command.s = value; break;
      }
    }

    return command;
  }

  /**
   * Process a G-code command and update parser state
   */
  private processCommand(command: GCodeCommand): boolean {
    switch (command.command) {
      case 'G0': // Rapid positioning
      case 'G00':
        return this.moveToPosition(command, true);

      case 'G1': // Linear interpolation
      case 'G01':
        return this.moveToPosition(command, false);

      // G2/G3 arcs handled specially in parse() method

      case 'G20': // Inches
        this.isInches = true;
        return false;

      case 'G21': // Millimeters
        this.isInches = false;
        return false;

      case 'G90': // Absolute positioning
      case 'G91': // Relative positioning
      case 'G17': // XY plane
      case 'G54': // Work coordinate system
      case 'G28': // Home
      case 'G43': // Tool length offset
      case 'G49': // Cancel tool length offset
      case 'G94': // Feed per minute mode
        // These commands don't generate movement
        return false;

      case 'F': // Set feed rate
        if (command.f !== undefined) {
          this.currentFeedRate = command.f;
        }
        return false;

      case 'S': // Set spindle speed
        if (command.s !== undefined) {
          this.currentSpindleSpeed = command.s;
        }
        return false;

      case 'T': // Tool change
        if (command.t !== undefined) {
          this.currentTool = command.t;
        }
        return false;

      case 'M3': // Spindle on clockwise
      case 'M03':
      case 'M4': // Spindle on counter-clockwise
      case 'M04':
      case 'M5': // Spindle stop
      case 'M05':
      case 'M6': // Tool change
      case 'M06':
      case 'M8': // Coolant on
      case 'M9': // Coolant off
      case 'M30': // Program end
        return false;

      default:
        return false;
    }
  }

  /**
   * Convert coordinate value to inches if currently in mm mode
   */
  private convertToInches(value: number): number {
    return this.isInches ? value : value * this.MM_TO_INCHES;
  }

  /**
   * Move to a new position
   */
  private moveToPosition(command: GCodeCommand, isRapid: boolean): boolean {
    const newPosition = this.currentPosition.clone();
    let hasMovement = false;

    if (command.x !== undefined) {
      newPosition.x = this.convertToInches(command.x);
      hasMovement = true;
    }
    if (command.y !== undefined) {
      newPosition.y = this.convertToInches(command.y);
      hasMovement = true;
    }
    if (command.z !== undefined) {
      newPosition.z = this.convertToInches(command.z);
      hasMovement = true;
    }

    if (command.f !== undefined) {
      this.currentFeedRate = command.f;
    }

    if (hasMovement) {
      this.currentPosition.copy(newPosition);
      return true;
    }

    return false;
  }

  /**
   * Interpolate arc motion (G2/G3) into line segments
   * Returns arc data including segments and metadata
   */
  private interpolateArc(command: GCodeCommand): {
    segments: Vector3[];
    center: { x: number; y: number; z: number };
    radius: number;
    isClockwise: boolean;
    startAngle: number;
    endAngle: number;
  } {
    const segments: Vector3[] = [];

    // Target position (convert to inches if in mm mode)
    const targetX = command.x !== undefined ? this.convertToInches(command.x) : this.currentPosition.x;
    const targetY = command.y !== undefined ? this.convertToInches(command.y) : this.currentPosition.y;
    const targetZ = command.z !== undefined ? this.convertToInches(command.z) : this.currentPosition.z;

    // Arc center (I, J offsets from current position, also convert)
    const centerX = this.currentPosition.x + this.convertToInches(command.i || 0);
    const centerY = this.currentPosition.y + this.convertToInches(command.j || 0);
    const centerZ = this.currentPosition.z; // Center Z is typically same as start Z

    // Calculate start and end angles
    const startAngle = Math.atan2(
      this.currentPosition.y - centerY,
      this.currentPosition.x - centerX
    );
    const endAngle = Math.atan2(targetY - centerY, targetX - centerX);

    // Calculate radius
    const radius = Math.sqrt(
      Math.pow(this.currentPosition.x - centerX, 2) +
      Math.pow(this.currentPosition.y - centerY, 2)
    );

    // Determine direction (G2 = clockwise, G3 = counter-clockwise)
    const isClockwise = command.command === 'G2' || command.command === 'G02';

    // Calculate total angle to sweep
    let totalAngle = endAngle - startAngle;
    if (isClockwise) {
      if (totalAngle >= 0) totalAngle -= 2 * Math.PI;
    } else {
      if (totalAngle <= 0) totalAngle += 2 * Math.PI;
    }

    // Number of segments based on arc length (aim for ~1mm per segment)
    const arcLength = Math.abs(totalAngle * radius);
    const numSegments = Math.max(8, Math.ceil(arcLength / 1.0));

    // Generate intermediate points along the arc
    for (let i = 1; i <= numSegments; i++) {
      const t = i / numSegments;
      const angle = startAngle + totalAngle * t;

      // Calculate Z position (linear interpolation)
      const z = this.currentPosition.z + (targetZ - this.currentPosition.z) * t;

      // Create new position
      const x = centerX + radius * Math.cos(angle);
      const y = centerY + radius * Math.sin(angle);

      segments.push(new Vector3(x, y, z));
    }

    // Update current position to end of arc
    this.currentPosition.set(targetX, targetY, targetZ);

    // Update feed rate if specified
    if (command.f !== undefined) {
      this.currentFeedRate = command.f;
    }

    return {
      segments,
      center: { x: centerX, y: centerY, z: centerZ },
      radius,
      isClockwise,
      startAngle,
      endAngle
    };
  }

  /**
   * Get the line radius for visualization based on command type
   */
  private getLineRadius(command: string): number {
    switch (command) {
      case 'G0':
      case 'G00':
        return 0; // Rapid moves - no material removal

      case 'G1':
      case 'G01':
      case 'G2':
      case 'G02':
      case 'G3':
      case 'G03':
        // Use current tool diameter / 2 for cutting moves
        const toolDiameter = this.toolDiameters.get(this.currentTool) || 3.175;
        return toolDiameter / 2;

      default:
        return 0.1; // Small default for other moves
    }
  }

  /**
   * Update bounding box with new position
   */
  private updateBounds(position: Vector3, bounds: { min: Vector3; max: Vector3 }): void {
    bounds.min.x = Math.min(bounds.min.x, position.x);
    bounds.min.y = Math.min(bounds.min.y, position.y);
    bounds.min.z = Math.min(bounds.min.z, position.z);

    bounds.max.x = Math.max(bounds.max.x, position.x);
    bounds.max.y = Math.max(bounds.max.y, position.y);
    bounds.max.z = Math.max(bounds.max.z, position.z);
  }
}
