import CloseIcon from '@mui/icons-material/Close';
import LabelIcon from '@mui/icons-material/Label';
import {
    Autocomplete,
    Box,
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    IconButton,
    TextField,
    Typography
} from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { JobMetadata } from '../../../machine/ICNCJobStorage';

interface JobCategoryDialogProps {
    open: boolean;
    job: JobMetadata | null;
    existingCategories: string[];
    onClose: () => void;
    onSave: (category: string | undefined) => void;
}

export function JobCategoryDialog({ open, job, existingCategories, onClose, onSave }: JobCategoryDialogProps) {
    const config = ConfigurationDataColors.Instance;
    const [selectedCategory, setSelectedCategory] = useState<string>('');

    useEffect(() => {
        if (open && job) {
            setSelectedCategory(job.category ?? '');
        }
    }, [open, job]);

    const handleSave = () => {
        onSave(selectedCategory.trim() || undefined);
        onClose();
    };

    const handleClear = () => {
        onSave(undefined);
        onClose();
    };

    return (
        <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
            <DialogTitle sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                backgroundColor: config.primaryColor,
                color: 'white',
                py: 2,
                px: 3
            }}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <LabelIcon />
                    <Typography variant="h6">Set Job Category</Typography>
                </Box>
                <IconButton
                    onClick={onClose}
                    sx={{
                        color: 'white',
                        '&:hover': { backgroundColor: 'rgba(255, 255, 255, 0.1)' }
                    }}
                >
                    <CloseIcon />
                </IconButton>
            </DialogTitle>

            <DialogContent>
                <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
                    <Typography variant="body2" color="text.secondary">
                        Assign a category to <strong>{job?.name}</strong> to help organize your jobs.
                    </Typography>

                    <Autocomplete
                        freeSolo
                        options={existingCategories}
                        value={selectedCategory}
                        onChange={(_, value) => setSelectedCategory(value ?? '')}
                        onInputChange={(_, value) => setSelectedCategory(value)}
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                label="Category"
                                placeholder="Type a new category or pick an existing one"
                                autoFocus
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') handleSave();
                                }}
                            />
                        )}
                    />

                    {existingCategories.length > 0 && (
                        <Typography variant="caption" color="text.secondary">
                            Existing categories: {existingCategories.join(', ')}
                        </Typography>
                    )}
                </Box>
            </DialogContent>

            <DialogActions sx={{
                p: 2,
                gap: 1,
                justifyContent: 'flex-end',
                borderTop: `1px solid ${config.borderColor}`
            }}>
                {job?.category && (
                    <Button onClick={handleClear} variant="outlined" color="warning" sx={{ mr: 'auto' }}>
                        Clear Category
                    </Button>
                )}
                <Button onClick={onClose} variant="outlined">
                    Cancel
                </Button>
                <Button onClick={handleSave} variant="contained">
                    Save
                </Button>
            </DialogActions>
        </Dialog>
    );
}
