import React from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { Wizard } from './Wizard';
import { WizardManager } from './WizardManager';

export const WizardContainer: React.FC = () => {
  return (
    <ObserveState
      key="wizard-container"
      listenTo={WizardManager.Instance}
      properties={['wizards']}
      control={() => {
        const wizards = WizardManager.Instance.wizards;

        if (wizards.length === 0) {
          return null;
        }

        // Render all wizards in the stack (bottom to top)
        return (
          <>
            {wizards.map((wizard, index) => (
              <WizardRenderer key={index} wizard={wizard} zIndex={1400 + index * 2} />
            ))}
          </>
        );
      }}
    />
  );
};

interface WizardRendererProps {
  wizard: Wizard;
  zIndex: number;
}

const WizardRenderer: React.FC<WizardRendererProps> = ({ wizard, zIndex }) => {
  return (
    <ObserveState
      key={`wizard-${zIndex}`}
      listenTo={wizard}
      properties={['currentStep', 'state']}
      control={() => {
        // If currentStep is null (wizard is closing), don't render
        if (!wizard.currentStep) {
          return null;
        }

        const dialogStyle: React.CSSProperties = {
          position: 'fixed',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          width: wizard.width,
          height: wizard.height,
          backgroundColor: ConfigurationDataColors.Instance.lightTextColor,
          borderRadius: '8px',
          boxShadow: `0 4px 20px ${ConfigurationDataColors.Instance.shadowColor}`,
          zIndex: zIndex,
          display: 'flex',
          flexDirection: 'column'
        };

        const overlayStyle: React.CSSProperties = {
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: ConfigurationDataColors.Instance.modalBackdrop,
          zIndex: zIndex - 1
        };

        const headerStyle: React.CSSProperties = {
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '16px 20px',
          borderBottom: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
          minHeight: '60px'
        };

        const closeButtonStyle: React.CSSProperties = {
          background: 'none',
          border: 'none',
          fontSize: '24px',
          cursor: 'pointer',
          padding: '4px',
          lineHeight: 1,
          color: ConfigurationDataColors.Instance.mutedTextColor
        };

        const contentStyle: React.CSSProperties = {
          flex: 1,
          padding: '20px',
          overflow: 'auto'
        };

        const handleOverlayClick = (e: React.MouseEvent) => {
          if (wizard.clickAwayClose && e.target === e.currentTarget) {
            wizard.closeWizard();
          }
        };

        const handleCloseClick = () => {
          wizard.closeWizard();
        };

        return (
          <div>
            <div style={overlayStyle} onClick={handleOverlayClick} />
            <div style={dialogStyle}>
              <div style={headerStyle}>
                <h2 style={{ margin: 0, fontSize: '18px', fontWeight: 600 }}>
                  {wizard.currentStep.getTitle()}
                </h2>
                {wizard.canClose && (
                  <button
                    style={closeButtonStyle}
                    onClick={handleCloseClick}
                    aria-label="Close"
                  >
                    ×
                  </button>
                )}
              </div>
              <div style={contentStyle}>
                {wizard.currentStep.render()}
              </div>
            </div>
          </div>
        );
      }}
    />
  );
};
