import { ArrowDownward, ArrowUpward, Clear } from '@mui/icons-material';
import { Box, Button, ButtonGroup, IconButton, ToggleButton, ToggleButtonGroup, Typography } from '@mui/material';
import { useEffect, useRef, useState } from 'react';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { MessageDisplay, SignalRMessagesData } from '../../data/SignalRMessagesData';
import { ObserveState } from '../../utils/statemanager/ObserveState';

type MessageFilter = 'messages-only' | 'all';
type MessageOrder = 'newest-top' | 'newest-bottom';

export function MessageViewer() {
    const [config] = useState(() => ConfigurationData.Instance);
    const colors = ConfigurationDataColors.Instance;
    const [filter, setFilter] = useState<MessageFilter>('messages-only');
    const [order, setOrder] = useState<MessageOrder>('newest-bottom');
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const messagesTopRef = useRef<HTMLDivElement>(null);
    const [messageCount, setMessageCount] = useState(0);

    // Auto-scroll when message count changes (only if newest-bottom)
    useEffect(() => {
        if (order === 'newest-bottom') {
            messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messageCount, order]);

    /**
     * Enhance I/O messages - new format already includes all necessary information
     * Format: "[I7 On] Emergency Stop is Active" or "[O3 Off] Coolant is Inactive"
     */
    const enhanceIOMessage = (messageText: string): string => {
        // All messages from backend are already properly formatted
        return messageText;
    };

    /**
     * Check if a message is an I/O status message and extract state
     * Format: "[I7 On] ..." or "[O3 Off] ..."
     * Returns { isIO: true, isActive: boolean } or { isIO: false }
     */
    const getIOStatus = (message: MessageDisplay): { isIO: boolean; isActive?: boolean } => {
        const text = message.message;

        // Format: [I7 On] or [O3 Off]
        const ioMatch = text.match(/^\[([IO])(\d+)\s+(On|Off)\]/);
        if (ioMatch) {
            const isActive = ioMatch[3].toLowerCase() === 'on';
            return { isIO: true, isActive };
        }

        return { isIO: false };
    };

    const getMessageColor = (message: MessageDisplay): string => {
        const eventCode = message.eventCode;
        const eventType = message.eventType;

        // Use event code ranges for coloring if available
        if (eventCode !== undefined && eventCode !== null) {
            // Configuration messages (special codes)
            if ([111, 444, 555, 556, 777, 888, 999].includes(eventCode)) {
                return colors.primaryColor; // Blue/Info
            }

            // Status and Info (300-399, with exceptions)
            if (eventCode >= 300 && eventCode <= 399) {
                if (eventCode === 306) return colors.successColor; // Job Finished - Green
                if (eventCode >= 318 && eventCode <= 337) return colors.errorColor; // Probe errors - Red
                if (eventCode >= 320 && eventCode <= 330) return colors.errorColor; // Cancellations - Red
                return colors.primaryColor; // Blue/Info
            }

            // Faults (400-499) - All RED
            if (eventCode >= 400 && eventCode <= 499) {
                return colors.errorColor;
            }

            // Syntax errors (500-599) - Orange/Warning
            if (eventCode >= 500 && eventCode <= 599) {
                return colors.warningColor;
            }

            // Cutter compensation errors (600-699) - Orange/Warning
            if (eventCode >= 600 && eventCode <= 699) {
                return colors.warningColor;
            }

            // Parameter errors (700-799) - Orange/Warning
            if (eventCode >= 700 && eventCode <= 799) {
                return colors.warningColor;
            }

            // Canned cycle errors (800-899) - Orange/Warning
            if (eventCode >= 800 && eventCode <= 899) {
                return colors.warningColor;
            }

            // Miscellaneous errors (900-999) - Red
            if (eventCode >= 900 && eventCode <= 999) {
                return colors.errorColor;
            }

            // Scaling errors (1000-1199) - Orange/Warning
            if (eventCode >= 1000 && eventCode <= 1199) {
                return colors.warningColor;
            }

            // Startup messages (100-199)
            if (eventCode >= 100 && eventCode <= 199) {
                if (eventCode >= 102 && eventCode <= 106) return colors.errorColor; // Startup errors
                return colors.primaryColor; // Status messages
            }

            // Exit messages (200-299) - Blue/Info
            if (eventCode >= 200 && eventCode <= 299) {
                return colors.primaryColor;
            }
        }

        // Fallback to eventType classification
        if (eventType && typeof eventType === 'string') {
            if (eventType.includes('Error') || eventType.includes('Fault')) {
                return colors.errorColor;
            }
            if (eventType.includes('Syntax') || eventType.includes('Parameter')) {
                return colors.warningColor;
            }
            if (eventType.includes('Completed')) {
                return colors.successColor;
            }
            if (eventType.includes('Job') || eventType.includes('Status')) {
                return colors.primaryColor;
            }
        }

        // Fallback to severity if provided
        if (message.severity === 'Error') {
            return colors.errorColor;
        }
        if (message.severity === 'Warning') {
            return colors.warningColor;
        }

        // Type-based coloring (when no event code or type)
        switch (message.type) {
            case 'Job Completed':
                return colors.successColor; // Green
            case 'Job Started':
            case 'Job Info':
            case 'Message':
                return colors.primaryColor; // Blue/Info
            case 'Step Execution':
                return ConfigurationDataColors.Instance.successColor; // Dark Green
            case 'DRO Update':
                return ConfigurationDataColors.Instance.mutedTextColor; // Purple
            default:
                return colors.darkTextColor; // Black/Normal
        }
    };

    const handleClear = () => {
        SignalRMessagesData.Instance.clearMessages();
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Header with toggle and clear button */}
            <Box sx={{
                p: 1,
                borderBottom: `1px solid ${colors.borderColor}`,
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
                backgroundColor: colors.lightBackgroundColor,
                gap: 1
            }}>
                <Typography variant="subtitle2" sx={{ fontWeight: 'bold', color: colors.darkTextColor, fontSize: '0.85rem' }}>
                    Messages
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                    {/* Sort order toggle */}
                    <ToggleButtonGroup
                        value={order}
                        exclusive
                        onChange={(_, newOrder) => {
                            if (newOrder !== null) {
                                setOrder(newOrder);
                            }
                        }}
                        size="small"
                    >
                        <ToggleButton
                            value="newest-top"
                            sx={{
                                fontSize: '0.7rem',
                                px: 1,
                                py: 0.25,
                                minWidth: '32px',
                                height: '26px'
                            }}
                            title="Newest messages at top"
                        >
                            <ArrowUpward sx={{ fontSize: '0.9rem' }} />
                        </ToggleButton>
                        <ToggleButton
                            value="newest-bottom"
                            sx={{
                                fontSize: '0.7rem',
                                px: 1,
                                py: 0.25,
                                minWidth: '32px',
                                height: '26px'
                            }}
                            title="Newest messages at bottom"
                        >
                            <ArrowDownward sx={{ fontSize: '0.9rem' }} />
                        </ToggleButton>
                    </ToggleButtonGroup>

                    {/* Filter toggle */}
                    <ButtonGroup size="small" variant="outlined">
                        <Button
                            variant={filter === 'messages-only' ? 'contained' : 'outlined'}
                            onClick={() => setFilter('messages-only')}
                            sx={{
                                fontSize: '0.7rem',
                                textTransform: 'none',
                                minWidth: '70px',
                                py: 0.25,
                                height: '26px'
                            }}
                        >
                            Messages
                        </Button>
                        <Button
                            variant={filter === 'all' ? 'contained' : 'outlined'}
                            onClick={() => setFilter('all')}
                            sx={{
                                fontSize: '0.7rem',
                                textTransform: 'none',
                                minWidth: '50px',
                                py: 0.25,
                                height: '26px'
                            }}
                        >
                            All
                        </Button>
                    </ButtonGroup>

                    {/* Clear button */}
                    <IconButton
                        size="small"
                        onClick={handleClear}
                        title="Clear all messages"
                        sx={{
                            color: colors.errorColor,
                            padding: '4px'
                        }}
                    >
                        <Clear fontSize="small" />
                    </IconButton>
                </Box>
            </Box>

            {/* Messages list */}
            <ObserveState
                key="message-viewer-list"
                listenTo={SignalRMessagesData.Instance}
                properties={['messages']}
                control={() => {
                    const allMessages = SignalRMessagesData.Instance.messages;

                    // Filter messages based on selected filter
                    // Messages-only mode excludes only Job Info (progress) and DRO Update
                    const filteredMessages = filter === 'messages-only'
                        ? allMessages.filter(m => m.type !== 'Job Info' && m.type !== 'DRO Update')
                        : allMessages;

                    // Sort messages based on order preference
                    // Messages are stored chronologically (oldest first)
                    const sortedMessages = order === 'newest-top'
                        ? [...filteredMessages].reverse()
                        : filteredMessages;

                    // Update message count to trigger auto-scroll
                    if (filteredMessages.length !== messageCount) {
                        setMessageCount(filteredMessages.length);
                    }

                    return (
                        <Box sx={{
                            flex: 1,
                            overflow: 'auto',
                            p: 0.5
                        }}>
                            {order === 'newest-top' && <div ref={messagesTopRef} />}
                            {sortedMessages.length === 0 ? (
                                <Box sx={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    height: '100%'
                                }}>
                                    <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic', fontSize: '0.75rem' }}>
                                        No messages yet
                                    </Typography>
                                </Box>
                            ) : (
                                <>
                                    {sortedMessages.map((message, index) => {
                                        // Use persistent message ID for consistent numbering
                                        const displayNumber = message.id;

                                        // Check if this is an I/O status message
                                        const ioStatus = getIOStatus(message);

                                        if (filter === 'messages-only') {
                                            // Compact single-line format for messages-only mode
                                            const displayText = enhanceIOMessage(message.message);

                                            return (
                                                <Box
                                                    key={message.id}
                                                    sx={{
                                                        mb: 0.5,
                                                        px: 1,
                                                        py: 0.5,
                                                        borderLeft: `3px solid ${getMessageColor(message)}`,
                                                        backgroundColor: colors.lightBackgroundColor,
                                                        borderRadius: '3px',
                                                        '&:hover': {
                                                            backgroundColor: colors.borderColor
                                                        }
                                                    }}
                                                >
                                                    <Typography
                                                        variant="body2"
                                                        sx={{
                                                            color: colors.darkTextColor,
                                                            fontSize: '0.75rem',
                                                            lineHeight: 1.3,
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            gap: 0.75
                                                        }}
                                                    >
                                                        <span style={{
                                                            color: colors.secondaryColor,
                                                            fontWeight: 'bold',
                                                            marginRight: '6px'
                                                        }}>
                                                            [{displayNumber}]
                                                        </span>
                                                        {ioStatus.isIO && (
                                                            <span style={{
                                                                display: 'inline-block',
                                                                width: '10px',
                                                                height: '10px',
                                                                borderRadius: '50%',
                                                                backgroundColor: ioStatus.isActive ? colors.successColor : colors.errorColor,
                                                                flexShrink: 0
                                                            }} />
                                                        )}
                                                        {displayText}
                                                    </Typography>
                                                </Box>
                                            );
                                        } else {
                                            // Two-column format for all messages mode
                                            const displayText = enhanceIOMessage(message.message);

                                            return (
                                                <Box
                                                    key={message.id}
                                                    sx={{
                                                        mb: 0.5,
                                                        px: 1,
                                                        py: 0.5,
                                                        borderLeft: `3px solid ${getMessageColor(message)}`,
                                                        backgroundColor: colors.lightBackgroundColor,
                                                        borderRadius: '3px',
                                                        display: 'flex',
                                                        gap: 1,
                                                        alignItems: 'flex-start',
                                                        '&:hover': {
                                                            backgroundColor: colors.borderColor
                                                        }
                                                    }}
                                                >
                                                    <Typography
                                                        variant="caption"
                                                        sx={{
                                                            color: colors.secondaryColor,
                                                            fontWeight: 'bold',
                                                            fontSize: '0.7rem',
                                                            minWidth: '40px',
                                                            flexShrink: 0
                                                        }}
                                                    >
                                                        [{displayNumber}]
                                                    </Typography>
                                                    <Typography
                                                        variant="caption"
                                                        sx={{
                                                            fontWeight: 'bold',
                                                            color: getMessageColor(message),
                                                            fontSize: '0.7rem',
                                                            minWidth: '80px',
                                                            flexShrink: 0
                                                        }}
                                                    >
                                                        {message.type}
                                                    </Typography>
                                                    {ioStatus.isIO && (
                                                        <Box
                                                            sx={{
                                                                width: '10px',
                                                                height: '10px',
                                                                borderRadius: '50%',
                                                                backgroundColor: ioStatus.isActive ? colors.successColor : colors.errorColor,
                                                                flexShrink: 0,
                                                                mt: '3px' // Align with text baseline
                                                            }}
                                                        />
                                                    )}
                                                    <Typography
                                                        variant="body2"
                                                        sx={{
                                                            color: colors.darkTextColor,
                                                            fontSize: '0.75rem',
                                                            lineHeight: 1.3,
                                                            flex: 1
                                                        }}
                                                    >
                                                        {displayText}
                                                    </Typography>
                                                </Box>
                                            );
                                        }
                                    })}
                                    {order === 'newest-bottom' && <div ref={messagesEndRef} />}
                                </>
                            )}
                        </Box>
                    );
                }}
            />
        </Box>
    );
}
