import { ConfigurationData } from '../data/ConfigurationData';
import { ConfigurationState } from '../data/ConfigurationState';
import { GCodeExecutionCallback } from '../machine/ICNCProgram';
import { Machine } from '../machine/Machine';

/**
 * Global G-code preview dialog manager using the ModalManager system
 * Provides a consistent way to preview and save G-code before execution
 */
export class GCodePreviewManager {
    private static _instance: GCodePreviewManager;

    public static get Instance(): GCodePreviewManager {
        if (!GCodePreviewManager._instance) {
            GCodePreviewManager._instance = new GCodePreviewManager();
        }
        return GCodePreviewManager._instance;
    }

    private constructor() { }

    /**
     * Execute G-code immediately or show preview dialog based on ConfigurationData.previewGCode setting
     * @param title Dialog title (used for preview and logging)
     * @param gcodeLines Array of G-code lines to execute
     * @param callback Optional callback for G-code execution events
     * @param skipPreview If true, bypass preview even if enabled (used when already in run dialog)
     * @returns Promise that resolves when execution completes or preview is shown
     */
    public async executeOrPreview(
        title: string,
        gcodeLines: string[],
        callback?: GCodeExecutionCallback,
        skipPreview: boolean = false
    ): Promise<void> {
        const config = ConfigurationData.Instance;

        if (config.previewGCode && !skipPreview) {
            // Show preview dialog - user will click Run, which will invoke the callback
            ConfigurationState.Instance.showGCodePreview(title, gcodeLines, callback);
        } else {
            // Execute immediately with callback
            const machine = Machine.getInstance();
            await machine.program.RunGCode(gcodeLines, true, undefined, callback);
        }
    }
}
