/**
 * Direction for jog movements
 */
export enum JogDirection {
    XPlus = 'XPlus',
    XMinus = 'XMinus',
    YPlus = 'YPlus',
    YMinus = 'YMinus',
    ZPlus = 'ZPlus',
    ZMinus = 'ZMinus',
    APlus = 'APlus',
    AMinus = 'AMinus',
    XPlusYPlus = 'XPlusYPlus',      // Northeast
    XPlusYMinus = 'XPlusYMinus',    // Southeast
    XMinusYMinus = 'XMinusYMinus',  // Southwest
    XMinusYPlus = 'XMinusYPlus'     // Northwest
}
