import { CoordinateUtil } from '../utils/CoordinateUtil';
import { StateManager } from '../utils/statemanager/StateManager';
import { ConfigurationState } from './ConfigurationState';
import { CoordinateType } from './Common/CoordinateType';
import { MachineStateData } from './MachineStateData';

/**
 * Display mode for axis coordinates
 */
export enum CoordinateDisplayType {
    /** Display work coordinates (relative to work zero with tool offsets) */
    Work = 'Work',
    /** Display machine zero coordinates (absolute machine position) */
    Machine = 'Machine'
}

/**
 * Tracks the state of a single axis coordinate input
 */
export class AxisState {
    private _userEnteredValue: number | null = null;
    private _isUserEditing: boolean = false;
    private _showButtons: 'none' | 'set' | 'go' = 'none';

    /**
     * User's entered value (null if not edited)
     */
    public get userEnteredValue(): number | null {
        return this._userEnteredValue;
    }

    public set userEnteredValue(value: number | null) {
        this._userEnteredValue = value;
    }

    /**
     * Whether user is currently editing this axis
     */
    public get isUserEditing(): boolean {
        return this._isUserEditing;
    }

    public set isUserEditing(value: boolean) {
        this._isUserEditing = value;
    }

    /**
     * Which buttons to show for this axis
     */
    public get showButtons(): 'none' | 'set' | 'go' {
        return this._showButtons;
    }

    public set showButtons(value: 'none' | 'set' | 'go') {
        this._showButtons = value;
    }

    /**
     * Clear user input and reset to default state
     */
    public clear(): void {
        this._userEnteredValue = null;
        this._isUserEditing = false;
        this._showButtons = 'none';
    }
}

/**
 * Singleton class to manage coordinate display state across all axes
 * Computes display values from machine state and user input
 */
export class AxisCoordinateState {
    private static _instance: AxisCoordinateState;

    private _axisStates: Map<string, AxisState> = new Map();
    private _displayType: CoordinateDisplayType = CoordinateDisplayType.Work;
    private _machineModeStartTime: number | null = null; // Timestamp when machine mode was activated

    // Define actual properties for state observation
    private _X: number = 0;
    private _Y: number = 0;
    private _Z: number = 0;
    private _A: number = 0;

    public get X(): number { return this._X; }
    public set X(value: number) { this._X = value; }

    public get Y(): number { return this._Y; }
    public set Y(value: number) { this._Y = value; }

    public get Z(): number { return this._Z; }
    public set Z(value: number) { this._Z = value; }

    public get A(): number { return this._A; }
    public set A(value: number) { this._A = value; }

    /**
     * Get/set the coordinate display type (Work or Machine)
     */
    public get displayType(): CoordinateDisplayType {
        return this._displayType;
    }

    public set displayType(value: CoordinateDisplayType) {
        this._displayType = value;
        StateManager.propertyChanged(this, 'displayType');
        // Notify all axes to trigger recalculation of display values
        StateManager.propertyChanged(this, 'X');
        StateManager.propertyChanged(this, 'Y');
        StateManager.propertyChanged(this, 'Z');
        StateManager.propertyChanged(this, 'A');
    }

    /**
     * Get/set the timestamp when machine mode was activated (null if not in machine mode)
     */
    public get machineModeStartTime(): number | null {
        return this._machineModeStartTime;
    }

    public set machineModeStartTime(value: number | null) {
        this._machineModeStartTime = value;
        StateManager.propertyChanged(this, 'machineModeStartTime');
    }

    private constructor() {
        // Initialize common axes
        this.getAxisState('X');
        this.getAxisState('Y');
        this.getAxisState('Z');
        this.getAxisState('A');
    }

    public static get Instance(): AxisCoordinateState {
        if (!AxisCoordinateState._instance) {
            AxisCoordinateState._instance = new AxisCoordinateState();
        }
        return AxisCoordinateState._instance;
    }

    /**
     * Get the state for a specific axis (creates if doesn't exist)
     */
    public getAxisState(axis: string): AxisState {
        const axisKey = axis.toUpperCase();
        if (!this._axisStates.has(axisKey)) {
            this._axisStates.set(axisKey, new AxisState());
        }
        return this._axisStates.get(axisKey)!;
    }

    /**
     * Get the display value for an axis
     * Priority: user entered value > proposed value > current value
     * Computes coordinates based on displayType (Work or Machine)
     */
    public getDisplayValue(axis: string): number {
        const state = this.getAxisState(axis);
        const axisKey = axis.toUpperCase();

        // Priority 1: User entered value
        if (state.userEnteredValue !== null) {
            return state.userEnteredValue;
        }

        const machineState = MachineStateData.Instance;

        // Priority 2: Proposed value (from drag or other operations)
        const proposedPos = ConfigurationState.Instance.proposedSpindlePosition;
        if (proposedPos) {
            const coordinates = this._displayType === CoordinateDisplayType.Work
                ? CoordinateUtil.toWorkZeroWithOffsets(proposedPos)
                : CoordinateUtil.toMachineZero(proposedPos);

            let proposedValue: number;

            switch (axisKey) {
                case 'X': proposedValue = coordinates.x; break;
                case 'Y': proposedValue = coordinates.y; break;
                case 'Z': proposedValue = coordinates.z; break;
                case 'A': proposedValue = 0; break; // A-axis not implemented yet
                default: proposedValue = 0;
            }

            return proposedValue;
        }

        // Priority 3: Current value
        const currentMachinePos = ConfigurationState.Instance.currentMachinePoint;
        const coordinates = this._displayType === CoordinateDisplayType.Work
            ? CoordinateUtil.toWorkZeroWithOffsets(currentMachinePos)
            : CoordinateUtil.toMachineZero(currentMachinePos);

        let currentValue: number;

        switch (axisKey) {
            case 'X': currentValue = coordinates.x; break;
            case 'Y': currentValue = coordinates.y; break;
            case 'Z': currentValue = coordinates.z; break;
            case 'A': currentValue = 0; break; // A-axis not implemented yet
            default: currentValue = 0;
        }

        return currentValue;
    }

    /**
     * Set user-entered value for an axis
     */
    public setUserValue(axis: string, value: number): void {
        const state = this.getAxisState(axis);
        state.userEnteredValue = value;
        state.isUserEditing = false; // No longer editing once value is committed
        state.showButtons = 'go';

        // Update dummy property to trigger observation
        const axisKey = axis.toUpperCase();
        if (axisKey === 'X') this._X = value;
        else if (axisKey === 'Y') this._Y = value;
        else if (axisKey === 'Z') this._Z = value;
        else if (axisKey === 'A') this._A = value;

        StateManager.propertyChanged(this, axisKey);
    }

    /**
     * Mark that user started editing (but hasn't committed yet)
     */
    public startEditing(axis: string): void {
        const state = this.getAxisState(axis);
        state.isUserEditing = true;
        state.showButtons = 'go';
        const axisKey = axis.toUpperCase();
        StateManager.propertyChanged(this, axisKey);
    }

    /**
     * Stop editing without committing
     */
    public stopEditing(axis: string): void {
        const state = this.getAxisState(axis);
        state.isUserEditing = false;
        const axisKey = axis.toUpperCase();
        StateManager.propertyChanged(this, axisKey);
    }

    /**
     * Clear user value for an axis
     */
    public clearAxis(axis: string): void {
        const state = this.getAxisState(axis);
        state.clear();

        // Update dummy property to trigger observation
        const axisKey = axis.toUpperCase();
        if (axisKey === 'X') this._X = 0;
        else if (axisKey === 'Y') this._Y = 0;
        else if (axisKey === 'Z') this._Z = 0;
        else if (axisKey === 'A') this._A = 0;

        StateManager.propertyChanged(this, axisKey);
    }

    /**
     * Clear all axes
     */
    public clearAll(): void {
        for (const [axis] of this._axisStates) {
            this.clearAxis(axis);
        }
    }

    /**
     * Set which buttons to show for an axis
     */
    public setButtonMode(axis: string, mode: 'none' | 'set' | 'go'): void {
        const state = this.getAxisState(axis);
        state.showButtons = mode;
        const axisKey = axis.toUpperCase();
        StateManager.propertyChanged(this, axisKey);
    }

    /**
     * Check if axis has user-entered value
     */
    public hasUserValue(axis: string): boolean {
        const state = this.getAxisState(axis);
        return state.userEnteredValue !== null;
    }

    /**
     * Create a MoveAction for a specific axis, using the display value
     * Returns the MoveAction that should be added to ActionBus
     */
    public createMoveActionForAxis(axis: string): any {
        // WORKAROUND: Dynamic require to break circular dependency (MoveAction -> CollisionDetection -> MachineData -> ... -> AxisCoordinateState)
        const { MoveAction, MoveType } = require('../utils/actions/MoveAction');

        // Get current coordinates in the selected display type
        const currentMachinePos = ConfigurationState.Instance.currentMachinePoint;
        const machineZeroPos = CoordinateUtil.toMachineZero(currentMachinePos);
        const isMachineMode = this._displayType === CoordinateDisplayType.Machine;

        const coordType = isMachineMode
            ? CoordinateType.MachineZero
            : CoordinateType.WorkZeroWithOffsets;

        // Build coordinate with only the specified axis changed
        // Other axes will be undefined so MoveAction will use current position
        let x: number | undefined;
        let y: number | undefined;
        let z: number | undefined;

        switch (axis.toUpperCase()) {
            case 'X':
                x = this.getDisplayValue('X');
                break;
            case 'Y':
                y = this.getDisplayValue('Y');
                break;
            case 'Z':
                z = this.getDisplayValue('Z');
                break;
            case 'A':
                // A-axis not yet implemented
                break;
        }

        // Create MoveAction with only the changed axis specified
        // ActionBus will automatically combine this with any existing MoveAction
        return new MoveAction(coordType, x, y, z, undefined, MoveType.Coordinates);
    }
}
