import { Box } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { DataType, Declaration, Visibility } from '../data/Declaration';
import { IPLCElement, PLCRenderMode, PLCValidationIssue } from '../data/IPLCElement';
import { PLCProgramType } from '../data/PLCUtilities';
import { StatementIdRegistry } from '../statements/StatementIdRegistry';
import { BasePLCPredicate } from './BasePLCPredicate';

/**
 * Toggle Memory Bit Predicate
 * Toggles the value of a memory bit (flips between true/false)
 * Generates a unique toggle trigger bit and secondary logic to perform the toggle
 */
export class ToggleMemoryBitPredicate extends BasePLCPredicate {
    private _targetElement: DataElement | undefined;  // The memory bit to toggle

    constructor() {
        super();
        // Initialize with a target element
        this._targetElement = new DataElement();
        this._targetElement.allowNew = false;  // Must be existing memory bit
        this._targetElement.needsWrite = true;  // Target must be writable
        this._targetElement.setParentElement(this);
    }

    /**
     * Get the target data element (the memory bit to toggle)
     */
    public get targetElement(): DataElement | undefined {
        return this._targetElement;
    }

    /**
     * Set the target data element
     */
    public set targetElement(value: DataElement | undefined) {
        this._targetElement = value;
        if (this._targetElement) {
            this._targetElement.allowNew = false;
            this._targetElement.needsWrite = true;
            this._targetElement.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'targetElement');
    }

    /**
     * Get a short, single-line description for display in tree views
     * Example: "Toggle DustCollector"
     * @returns A human-readable summary of the toggle action
     */
    public getShortDescription(): string {
        const targetName = this._targetElement?.declarationName || '(unknown)';
        return `Toggle ${targetName}`;
    }

    /**
     * Render the predicate to JSX
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        // Check if this predicate should be disabled:
        // 1. If renderMode is Disabled (parent condition is disabled), OR
        // 2. If predicate itself is disabled due to unavailable declarations
        const isPredicateDisabled = mode === PLCRenderMode.Disabled || this.isDisabled(PLCRenderMode.Edit, targetProgramType);
        const disabledStyle = isPredicateDisabled ? {
            opacity: 0.5,
            textDecoration: 'line-through',
            color: ConfigurationDataColors.Instance.mutedTextColor
        } : {};

        return (
            <ObserveState
                key="toggle-memory-bit-predicate"
                profilerName="ToggleMemoryBitPredicate-render"
                listenTo={this}
                properties={['targetElement']}
                control={() => (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, ...disabledStyle }}>
                        <span style={{ fontSize: '14px', fontWeight: 500 }}>Toggle Value:</span>
                        {this._targetElement && (
                            <Box>
                                {this._targetElement.render(mode, targetProgramType)}
                            </Box>
                        )}
                    </Box>
                )}
            />
        );
    }

    /**
     * Get declarations used by this predicate (the target memory bit)
     */
    public getUsedDeclarations(): Declaration[] {
        if (!this._targetElement) {
            return [];
        }
        return this._targetElement.getUsedDeclarations();
    }

    /**
     * Get declarations added by this predicate (the should-toggle trigger bit)
     */
    public getAddedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];

        // Add should-toggle memory bit using predicate's unique ID
        const predicateId = StatementIdRegistry.getId(this);
        const shouldToggleBit = new Declaration(`ShouldToggle${predicateId}_M`);
        shouldToggleBit.dataType = DataType.MemoryBit;
        shouldToggleBit.category = ['* Internal'];
        shouldToggleBit.readOnly = false;
        shouldToggleBit.visibility = Visibility.Hidden;
        shouldToggleBit.description = `Should-toggle trigger for predicate ${predicateId}`;
        declarations.push(shouldToggleBit);

        // Also include any declarations added by target element
        if (this._targetElement) {
            declarations.push(...this._targetElement.getAddedDeclarations());
        }

        // Remove duplicates
        const uniqueMap = new Map<string, Declaration>();
        for (const decl of declarations) {
            uniqueMap.set(decl.name, decl);
        }
        return Array.from(uniqueMap.values());
    }

    /**
     * Get pre-PLC logic (reset the should-toggle bit before each scan)
     */
    public getPrePLCLogic(): string[] {
        if (!this._targetElement || !this._targetElement.effectiveName) {
            return [];
        }

        const predicateId = StatementIdRegistry.getId(this);
        const shouldToggleBitName = `ShouldToggle${predicateId}_M`;

        // Reset the should-toggle bit at the start of each scan
        return [`; Toggle predicate logic - control variable`, `IF 1==1 THEN RST ${shouldToggleBitName}`, ''];
    }

    /**
     * Get primary PLC logic (set the should-toggle bit when condition fires)
     */
    public getPLCLogic(): string[] {
        if (!this._targetElement || !this._targetElement.effectiveName) {
            return ['; [Toggle predicate: no target element]'];
        }

        const predicateId = StatementIdRegistry.getId(this);
        const shouldToggleBitName = `ShouldToggle${predicateId}_M`;

        // Primary logic: set the should-toggle bit when parent condition is true
        return [`SET ${shouldToggleBitName}`];
    }

    /**
     * Get secondary PLC logic (the actual toggle execution using should-toggle bit)
     */
    public getSecondaryPLCLogic(): string[] {
        if (!this._targetElement || !this._targetElement.effectiveName) {
            return [];
        }

        const predicateId = StatementIdRegistry.getId(this);
        const shouldToggleBitName = `ShouldToggle${predicateId}_M`;
        const targetName = this._targetElement.effectiveName;

        const logic: string[] = [];

        logic.push('');
        logic.push('; Toggle predicate logic');

        // If should-toggle bit is on AND target is on, turn target off
        logic.push(`IF ${shouldToggleBitName} && ${targetName} THEN RST ${targetName}`);

        // If should-toggle bit is on AND target is off, turn target on
        logic.push(`IF ${shouldToggleBitName} && !${targetName} THEN SET ${targetName}`);

        return logic;
    }

    /**
     * Get validation issues
     */
    public getValidationIssues(): PLCValidationIssue[] {
        const issues: PLCValidationIssue[] = [];

        if (!this._targetElement || !this._targetElement.effectiveName) {
            issues.push(new PLCValidationIssue(this, 'Toggle predicate must have a target memory bit'));
        }

        return issues;
    }

    /**
     * Get all data elements used by this predicate
     */
    public getDataElements(): DataElement[] {
        const elements: DataElement[] = [];
        if (this._targetElement) {
            elements.push(this._targetElement);
        }
        return elements;
    }

    /**
     * Override setParentElement to cascade to target element
     */
    public override setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        if (this._targetElement) {
            this._targetElement.setParentElement(this);
        }
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        const baseData = DataUtilities.getStorageData(this, ['_parentElement', '_plcSource', '_targetElement']);
        return {
            type: 'ToggleMemoryBitPredicate',
            ...baseData,
            targetElement: this._targetElement?.toJSON()
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        if (!data) return;

        // Load base properties
        DataUtilities.loadStorageData(this, data, ['_parentElement', '_plcSource', '_targetElement']);

        // Restore target element
        if (data.targetElement) {
            this._targetElement = new DataElement();
            this._targetElement.fromJSON(data.targetElement);
            this._targetElement.setParentElement(this);
        }
    }
}
