import { Box, Button, FormControlLabel, Grid, Switch, Typography } from '@mui/material';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';

export function FixedToolMeasurementSection() {
    const machine = MachineData.Instance;

    return (
        <Grid container spacing={3}>
            <Grid item xs={12}>
                <ObserveState
                    key="fixed-tool-measurement-enabled"
                    listenTo={machine}
                    properties={['fixedToolMeasurementPointEnabled']}
                    control={() => (
                        <FormControlLabel
                            control={
                                <Switch
                                    checked={machine.fixedToolMeasurementPointEnabled}
                                    onChange={(e) => machine.fixedToolMeasurementPointEnabled = e.target.checked}
                                />
                            }
                            label="Enable Fixed Tool Measurement Point"
                        />
                    )}
                />
            </Grid>

            <ObserveState
                key="fixed-tool-measurement-config"
                listenTo={machine}
                properties={['fixedToolMeasurementPointEnabled']}
                control={() => {
                    if (!machine.fixedToolMeasurementPointEnabled) {
                        return null;
                    }
                    return (
                        <>
                            <Grid item xs={12}>
                                <SetupChecklistIndicator name="Fixed Tool Measurement Position" />
                            </Grid>

                            <Grid item xs={12}>
                                <ObserveState
                                    key="fixed-tool-measurement-x"
                                    listenTo={machine}
                                    properties={['fixedToolMeasurementPointX']}
                                    control={() => (
                                        <>
                                            <NumberInput
                                                label="X Position"
                                                value={machine.fixedToolMeasurementPointX}
                                                onChange={(value) => machine.fixedToolMeasurementPointX = value}
                                                margin="normal"
                                                precision={3}
                                                sx={{ width: '150px' }}
                                            />
                                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                                X coordinate from Machine Zero
                                            </Typography>
                                        </>
                                    )}
                                />
                            </Grid>

                            <Grid item xs={12}>
                                <ObserveState
                                    key="fixed-tool-measurement-y"
                                    listenTo={machine}
                                    properties={['fixedToolMeasurementPointY']}
                                    control={() => (
                                        <>
                                            <NumberInput
                                                label="Y Position"
                                                value={machine.fixedToolMeasurementPointY}
                                                onChange={(value) => machine.fixedToolMeasurementPointY = value}
                                                margin="normal"
                                                precision={3}
                                                sx={{ width: '150px' }}
                                            />
                                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                                Y coordinate from Machine Zero
                                            </Typography>
                                        </>
                                    )}
                                />
                            </Grid>

                            <Grid item xs={12}>
                                <ObserveState
                                    key="fixed-tool-measurement-z"
                                    listenTo={machine}
                                    properties={['fixedToolMeasurementPointZ']}
                                    control={() => (
                                        <>
                                            <NumberInput
                                                label="Z Position"
                                                value={machine.fixedToolMeasurementPointZ}
                                                onChange={(value) => machine.fixedToolMeasurementPointZ = value}
                                                margin="normal"
                                                precision={3}
                                                sx={{ width: '150px' }}
                                            />
                                            <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                                Z coordinate from Machine Zero (when spindle without tool touches fixed point)
                                            </Typography>
                                        </>
                                    )}
                                />
                            </Grid>

                            <Grid item xs={12}>
                                <Box sx={{ display: 'flex', gap: 2 }}>
                                    <Button
                                        variant="outlined"
                                        onClick={() => {
                                            const currentPos = ConfigurationState.Instance.currentMachinePoint;
                                            machine.fixedToolMeasurementPointX = currentPos.x;
                                            machine.fixedToolMeasurementPointY = currentPos.y;
                                            machine.fixedToolMeasurementPointZ = currentPos.z;
                                        }}
                                    >
                                        Capture Current X/Y/Z Position
                                    </Button>
                                    <Button
                                        variant="outlined"
                                        onClick={() => {
                                            ConfigurationState.Instance.isJogWindowOpen = true;
                                        }}
                                    >
                                        Open Jog Controls
                                    </Button>
                                </Box>
                            </Grid>
                        </>
                    );
                }}
            />
        </Grid>
    );
}
