import { ICNCJobStorage, JobMetadata, ListJobsRequest } from '../machine/ICNCJobStorage';
import { StateManager } from '../utils/statemanager/StateManager';
import { Job } from './Job';

/**
 * In-memory cache for recent jobs.
 *
 * Jobs cache is invalidated by:
 *   - JobCache.Instance.invalidateJobs() — call after storeJob / deleteJob / setJobCategory
 *
 * Deduplicates concurrent loads: multiple callers awaiting the same
 * missing cache entry share a single in-flight Promise.
 */
export class JobCache {
    private static _instance: JobCache;

    private _recentJobs: JobMetadata[] | null = null;

    // In-flight promise — prevents duplicate concurrent loads
    private _loadingJobsPromise: Promise<JobMetadata[]> | null = null;

    private constructor() { }

    public static get Instance(): JobCache {
        if (!JobCache._instance) {
            JobCache._instance = new JobCache();
        }
        return JobCache._instance;
    }

    // ── Cache state ──────────────────────────────────────────────────────────

    /** Current cached job metadata, or null if the cache is dirty and needs a reload. */
    public get recentJobs(): JobMetadata[] | null {
        return this._recentJobs;
    }

    // ── Invalidation ─────────────────────────────────────────────────────────

    /**
     * Mark the jobs cache as dirty.
     * The next call to getRecentJobs() will fetch from storage.
     * Call this after storeJob, deleteJob, or setJobCategory.
     */
    public invalidateJobs(): void {
        this._recentJobs = null;
        this._loadingJobsPromise = null;
        StateManager.propertyChanged(this, 'recentJobs');
    }

    // ── Data access ───────────────────────────────────────────────────────────

    /**
     * Get recent job metadata list.
     * - Returns the cached list immediately if available.
     * - Otherwise fetches from storage (concurrent callers share one Promise).
     */
    public getRecentJobs(jobStorage: ICNCJobStorage): Promise<JobMetadata[]> {
        if (this._recentJobs !== null) {
            return Promise.resolve(this._recentJobs);
        }

        if (this._loadingJobsPromise) {
            return this._loadingJobsPromise;
        }

        this._loadingJobsPromise = (async (): Promise<JobMetadata[]> => {
            try {
                this._recentJobs = await jobStorage.listJobs({
                    sortBy: 'lastModified',
                    sortDirection: 'desc'
                } as ListJobsRequest);
                StateManager.propertyChanged(this, 'recentJobs');
                return this._recentJobs;
            } catch {
                this._recentJobs = [];
                return [];
            } finally {
                this._loadingJobsPromise = null;
            }
        })();

        return this._loadingJobsPromise;
    }

    /**
     * Fetch the full Job object for a given metadata entry.
     * Not cached — always delegates to storage.
     */
    public fetchJob(id: string, jobStorage: ICNCJobStorage): Promise<Job | null> {
        return jobStorage.fetchJob(id);
    }
}
