import React from 'react';
import { StateManager } from './statemanager/StateManager';

/**
 * Simple notification item
 */
export interface NotificationItem {
  id: string;
  component: React.ReactNode;
  ordinal: number;
}

/**
 * Simple notification list that manages React components to render
 * Uses ordinal for sorting and prevents duplicates by ID
 */
export class NotificationList {
  private static _instance: NotificationList;
  private _notifications: Map<string, NotificationItem> = new Map();

  private constructor() { }

  public static get Instance(): NotificationList {
    if (!NotificationList._instance) {
      NotificationList._instance = new NotificationList();
    }
    return NotificationList._instance;
  }

  /**
   * Add a notification component to the list
   * @param id Unique identifier for the notification
   * @param component React component to render
   * @param ordinal Sort order (lower numbers appear first)
   */
  public add(id: string, component: React.ReactNode, ordinal: number = 0): void {
    this._notifications.set(id, {
      id,
      component,
      ordinal
    });

    // Notify observers that the list changed
    StateManager.propertyChanged(this, 'notifications');
  }

  /**
   * Remove a notification by ID
   * @param id Unique identifier of the notification to remove
   */
  public remove(id: string): void {
    if (this._notifications.has(id)) {
      this._notifications.delete(id);

      // Notify observers that the list changed
      StateManager.propertyChanged(this, 'notifications');
    }
  }

  /**
   * Get all notifications sorted by ordinal
   */
  public get notifications(): NotificationItem[] {
    return Array.from(this._notifications.values())
      .sort((a, b) => a.ordinal - b.ordinal);
  }

  /**
   * Clear all notifications
   */
  public clear(): void {
    this._notifications.clear();

    // Notify observers that the list changed
    StateManager.propertyChanged(this, 'notifications');
  }

  /**
   * Check if a notification exists
   */
  public has(id: string): boolean {
    return this._notifications.has(id);
  }

  /**
   * Get count of notifications
   */
  public get count(): number {
    return this._notifications.size;
  }
}
