import { FormControl, InputLabel, MenuItem, Select, SelectChangeEvent, Tooltip } from '@mui/material';
import { useMemo } from 'react';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { DataElement } from './DataElement';
import { DataType } from './Declaration';
import { DeclarationTooltipBuilder } from './DeclarationTooltipBuilder';
import { DeclarationScope, PLCUtilities } from './PLCUtilities';

interface DataElementDropdownProps {
    dataElement: DataElement;
    onSelect: (dataElement: DataElement) => void;
    label?: string;
    requiresType?: DataType;
    scope?: DeclarationScope;
    disabled?: boolean;
    fullWidth?: boolean;
    size?: 'small' | 'medium';
    variant?: 'standard' | 'outlined' | 'filled';
}

/**
 * Dropdown component for selecting data elements (stages, timers, etc.)
 * Alternative to DataElementPickerDialog for simple selection scenarios
 */
export function DataElementDropdown({
    dataElement,
    onSelect,
    label = 'Select',
    requiresType,
    scope = DeclarationScope.All,
    disabled = false,
    fullWidth = false,
    size = 'small',
    variant = 'standard'
}: DataElementDropdownProps) {
    // Get the program this data element belongs to
    const program = dataElement.getPLCProgram();

    // Get available declarations
    const declarations = useMemo(() => {
        if (!program) return [];

        const scopeContext = dataElement.getParentElement();
        return PLCUtilities.searchDeclarations(program, '', {
            scope,
            scopeContext,
            requiresType,
            needsWrite: dataElement.needsWrite,
            includeHidden: false
        });
    }, [program, scope, requiresType, dataElement]);

    const handleChange = (event: SelectChangeEvent<string>) => {
        const selectedName = event.target.value;

        // Directly update the existing dataElement instance
        dataElement.declarationName = selectedName;

        // Clear the declaration if empty value selected
        if (!selectedName) {
            dataElement.declaration = undefined;
        }

        // Notify via onSelect callback (for compatibility)
        onSelect(dataElement);
    };

    return (
        <ObserveState
            key="data-element-dropdown"
            profilerName="DataElementDropdown-render"
            listenTo={dataElement}
            properties={['declarationName', 'declaration']}
            control={() => {
                // Get current value from the observed dataElement
                const currentValue = dataElement.declarationName || dataElement.declaration?.name || '';
                const isEmpty = !currentValue;

                // Get current declaration for tooltip (recalculated on each render when value changes)
                const currentDeclaration = currentValue && program ?
                    PLCUtilities.getDeclarationByName(program, currentValue) : undefined;

                // Build tooltip content using shared utility class
                const tooltipContent = DeclarationTooltipBuilder.buildTooltip(currentDeclaration, program, isEmpty);

                return (
                    <Tooltip
                        title={tooltipContent}
                        arrow
                        placement="top"
                        enterDelay={500}
                        {...DeclarationTooltipBuilder.getTooltipProps()}
                    >
                        <FormControl fullWidth={fullWidth} size={size} variant={variant} disabled={disabled}>
                            {label && <InputLabel>{label}</InputLabel>}
                            <Select
                                value={currentValue}
                                onChange={handleChange}
                                label={label}
                                displayEmpty
                            >
                                <MenuItem value="">
                                    <em>None</em>
                                </MenuItem>
                                {declarations.map((decl) => (
                                    <MenuItem key={decl.name} value={decl.name}>
                                        {decl.name}
                                    </MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Tooltip>
                );
            }}
        />
    );
}
