import { ICNCPLC } from '../machine/ICNCPLC';
import { PLCApi } from '../services/src/apis/PLCApi';
import { MonitoredIODefinition } from '../services/src/models/MonitoredIODefinition';
import { PLCComparisonResult } from '../services/src/models/PLCComparisonResult';
import { PLCCompilationResult } from '../services/src/models/PLCCompilationResult';
import { PLCInstallationResult } from '../services/src/models/PLCInstallationResult';
import { Configuration } from '../services/src/runtime';
import { LogCategory, Logger } from '../utils/Logger';
import { MachineInterfaceManager } from '../utils/MachineInterfaceManager';

/**
 * Simulator PLC implementation that uses localStorage for data storage
 * Simulates compilation and installation operations locally
 * For testing: CompilePLC will use Centroid service if available
 */
export class SimulatorCNCPLC implements ICNCPLC {
    private readonly STORAGE_PREFIX = 'simulator_plc_';

    async CompilePLC(sourceLines: string[]): Promise<PLCCompilationResult> {
        try {
            // Always use Centroid service for compilation testing, even in simulator mode
            // Check if server is configured first, otherwise use default localhost
            let config = MachineInterfaceManager.Instance.getServiceConfiguration();

            if (!config || !config.basePath) {
                // Use default localhost when no server URL is configured
                config = new Configuration({
                    basePath: 'http://localhost:5000'
                });
            }

            const api = new PLCApi(config);

            // Create a timeout promise
            const timeoutPromise = new Promise<never>((_, reject) => {
                setTimeout(() => reject(new Error('Compilation request timed out after 30 seconds')), 30000);
            });

            // Race between the API call and timeout
            const response = await Promise.race([
                api.apiPLCCompilePLCPost({
                    compilePLCRequest: { plcLines: sourceLines }
                }),
                timeoutPromise
            ]);

            return response;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'SimulatorCNCPLC: Failed to compile PLC:', error);

            // Return error result instead of throwing
            return {
                success: false,
                issues: [`Compilation service error: ${error instanceof Error ? error.message : String(error)}`],
                compilerOutput: []
            };
        }
    }

    async CompileAndInstallPLC(sourceLines: string[], messages?: string[], estopInputNumber?: number, invertEstopInput?: boolean, inputsToMonitor?: MonitoredIODefinition[], outputsToMonitor?: MonitoredIODefinition[]): Promise<PLCInstallationResult> {
        try {
            // Simulate compilation and installation
            // Store the source in localStorage as the "installed" program
            const storageKey = `${this.STORAGE_PREFIX}installed_program`;
            localStorage.setItem(storageKey, JSON.stringify({
                sourceLines,
                messages,
                estopInputNumber,
                invertEstopInput,
                inputsToMonitor,
                outputsToMonitor,
                installedAt: new Date().toISOString()
            }));

            const result: PLCInstallationResult = {
                compilationResult: {
                    success: true,
                    issues: []
                },
                installationSuccess: true,
                message: 'PLC program installed successfully in simulator'
            };

            return result;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'SimulatorCNCPLC: Failed to compile and install PLC:', error);
            throw error;
        }
    }

    async GetPLCData(name: string): Promise<string[]> {
        try {
            const storageKey = `${this.STORAGE_PREFIX}${name}`;
            const dataString = localStorage.getItem(storageKey);

            if (!dataString) {
                return [];
            }

            const lines = JSON.parse(dataString) as string[];
            return lines;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, `SimulatorCNCPLC: Failed to get PLC data for ${name}:`, error);
            throw error;
        }
    }

    async SetPLCData(name: string, lines: string[]): Promise<void> {
        try {
            const storageKey = `${this.STORAGE_PREFIX}${name}`;
            localStorage.setItem(storageKey, JSON.stringify(lines));
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, `SimulatorCNCPLC: Failed to set PLC data for ${name}:`, error);
            throw error;
        }
    }

    async GetInstalledPLC(): Promise<string[]> {
        try {
            const storageKey = `${this.STORAGE_PREFIX}installed_program`;
            const dataString = localStorage.getItem(storageKey);

            if (!dataString) {
                throw new Error('No installed PLC file exists (404)');
            }

            const data = JSON.parse(dataString);
            const sourceLines = data.sourceLines || [];

            return sourceLines;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'SimulatorCNCPLC: Failed to get installed PLC:', error);
            throw error;
        }
    }

    async GetInstalledMessages(): Promise<string[]> {
        try {
            const storageKey = `${this.STORAGE_PREFIX}installed_program`;
            const dataString = localStorage.getItem(storageKey);

            if (!dataString) {
                throw new Error('No installed message file exists (404)');
            }

            const data = JSON.parse(dataString);
            const messages = data.messages || [];

            return messages;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'SimulatorCNCPLC: Failed to get installed messages:', error);
            throw error;
        }
    }

    async ComparePLC(sourceLines: string[]): Promise<PLCComparisonResult> {
        try {
            const storageKey = `${this.STORAGE_PREFIX}installed_program`;
            const dataString = localStorage.getItem(storageKey);

            if (!dataString) {
                return {
                    installedFileExists: false,
                    isDifferent: true,
                    message: 'No installed PLC file exists to compare against'
                };
            }

            const data = JSON.parse(dataString);
            const installedLines = data.sourceLines || [];

            // Compare files ignoring the first line (timestamp)
            const newLines = sourceLines.slice(1);
            const oldLines = installedLines.slice(1);

            const isDifferent = JSON.stringify(newLines) !== JSON.stringify(oldLines);

            const result: PLCComparisonResult = {
                installedFileExists: true,
                isDifferent,
                message: isDifferent
                    ? 'The new PLC source differs from the installed version'
                    : 'The new PLC source is identical to the installed version (ignoring timestamp)'
            };

            return result;
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'SimulatorCNCPLC: Failed to compare PLC:', error);
            throw error;
        }
    }
}
