import React from 'react';
import { ConfirmDialog } from '../components/Common/ConfirmDialog';
import { ModalManager } from './ModalManager';

export interface ConfirmOptions {
  title: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
  severity?: 'warning' | 'error' | 'info';
}

/**
 * Global confirmation dialog manager using the ModalManager system
 * Provides consistent styled confirmation dialogs throughout the application
 */
export class ConfirmDialogManager {
  private static _instance: ConfirmDialogManager;

  public static get Instance(): ConfirmDialogManager {
    if (!ConfirmDialogManager._instance) {
      ConfirmDialogManager._instance = new ConfirmDialogManager();
    }
    return ConfirmDialogManager._instance;
  }

  private constructor() {}

  /**
   * Show a confirmation dialog
   * @param options Configuration options for the dialog
   * @returns Promise that resolves to true if confirmed, false if cancelled
   */
  public showConfirm(options: ConfirmOptions): Promise<boolean> {
    return new Promise<boolean>((resolve) => {
      const modalId = `confirm-dialog-${Date.now()}`;
      
      const handleConfirm = () => {
        ModalManager.Instance.closeModal(modalId);
        resolve(true);
      };

      const handleCancel = () => {
        ModalManager.Instance.closeModal(modalId);
        resolve(false);
      };

      const modal = {
        id: modalId,
        render: () => React.createElement(ConfirmDialog, {
          open: true,
          title: options.title,
          message: options.message,
          confirmText: options.confirmText,
          cancelText: options.cancelText,
          severity: options.severity,
          onConfirm: handleConfirm,
          onCancel: handleCancel
        })
      };

      ModalManager.Instance.showModal(modal);
    });
  }

  /**
   * Show a warning confirmation dialog (convenience method)
   */
  public showWarning(title: string, message: string, confirmText: string = 'Continue'): Promise<boolean> {
    return this.showConfirm({
      title,
      message,
      confirmText,
      severity: 'warning'
    });
  }

  /**
   * Show an error confirmation dialog (convenience method)
   */
  public showError(title: string, message: string, confirmText: string = 'Continue'): Promise<boolean> {
    return this.showConfirm({
      title,
      message,
      confirmText,
      severity: 'error'
    });
  }

  /**
   * Show a delete confirmation dialog (convenience method)
   */
  public showDeleteConfirm(itemName: string): Promise<boolean> {
    return this.showConfirm({
      title: 'Confirm Delete',
      message: `Are you sure you want to delete "${itemName}"? This action cannot be undone.`,
      confirmText: 'Delete',
      severity: 'error'
    });
  }

  /**
   * Show a reset confirmation dialog (convenience method)
   */
  public showResetConfirm(itemName: string): Promise<boolean> {
    return this.showConfirm({
      title: 'Confirm Reset',
      message: `Are you sure you want to reset ${itemName}? This action cannot be undone.`,
      confirmText: 'Reset',
      severity: 'warning'
    });
  }
}
