import { Box, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { DataType, Declaration } from '../data/Declaration';
import { IPLCElement, PLCRenderMode } from '../data/IPLCElement';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType, PLCUtilities } from '../data/PLCUtilities';
import { KeybindingItem } from '../data/ui/KeybindingItem';
import { BasePLCStatement } from './BasePLCStatement';

/**
 * System UI Events Statement
 * System-only statement that outputs UI event handling code based on keybindings defined in UI triggers
 * Only available in SystemDefault PLC programs
 */
export class SystemUIEventsStatement extends BasePLCStatement {
    /**
     * Get all keybindings from UI triggers in both System and SystemDefault programs
     * Returns array of {triggerName, keybinding} objects
     */
    private getAllKeybindings(): Array<{ triggerName: string, keybinding: any }> {
        const keybindings: Array<{ triggerName: string, keybinding: any }> = [];

        // Get UI triggers from both programs
        const systemDefault = PLCUtilities.getSystemDefault() as PLCProgram;
        const program = PLCUtilities.getSystem() as PLCProgram;

        // Add keybindings from SystemDefault UI triggers
        if (systemDefault?.uiTriggers) {
            for (const trigger of systemDefault.uiTriggers) {
                if (trigger.keybindings && trigger.keybindings.length > 0) {
                    for (const kb of trigger.keybindings) {
                        if (kb.key) {
                            keybindings.push({ triggerName: trigger.eventName, keybinding: kb });
                        }
                    }
                }
            }
        }

        // Add keybindings from System UI triggers
        if (program?.uiTriggers && program !== systemDefault) {
            for (const trigger of program.uiTriggers) {
                if (trigger.keybindings && trigger.keybindings.length > 0) {
                    for (const kb of trigger.keybindings) {
                        if (kb.key) {
                            keybindings.push({ triggerName: trigger.eventName, keybinding: kb });
                        }
                    }
                }
            }
        }

        return keybindings;
    }

    /**
     * Get a short, single-line description for display in tree views
     * @returns A human-readable summary
     */
    public getShortDescription(): string {
        return 'System UI event handlers';
    }

    /**
     * Validate the statement
     */
    public validate(): string | undefined {
        return undefined; // Always valid
    }

    /**
     * Render the statement (informational display only, no editable properties)
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): any {
        const colors = ConfigurationDataColors.Instance;

        // Get keybindings count from both programs
        const keybindings = this.getAllKeybindings();
        const keybindingsCount = keybindings.length;

        return React.createElement(Box, {
            sx: {
                padding: 2,
                backgroundColor: colors.selectionColor,
                border: `1px solid ${colors.borderColor}`,
                borderRadius: 1,
                opacity: this._enabled ? 1 : 0.5
            }
        }, [
            React.createElement(Typography, {
                key: 'title',
                variant: 'subtitle2',
                sx: { color: colors.primaryColor, fontWeight: 'bold' }
            }, 'System UI Events'),
            React.createElement(Typography, {
                key: 'description',
                variant: 'body2',
                sx: { marginTop: 0.5 }
            }, `Generates UI event handling logic for ${keybindingsCount} defined keybinding(s)`)
        ]);
    }

    /**
     * Get declarations used by this statement
     * Returns Kb_*_SV declarations for all keys used in defined keybindings
     */
    public getUsedDeclarations(): Declaration[] {
        const keybindings = this.getAllKeybindings();

        const usedKeys = new Set<string>();

        // Always include modifier keys
        usedKeys.add('Kb_L_Shift_SV');
        usedKeys.add('Kb_R_Shift_SV');
        usedKeys.add('Kb_L_Ctrl_SV');
        usedKeys.add('Kb_R_Ctrl_SV');
        usedKeys.add('Kb_L_Alt_SV');
        usedKeys.add('Kb_R_Alt_SV');

        // Add keys from all keybindings
        for (const item of keybindings) {
            if (item.keybinding.key) {
                // Map the key to its Kb_*_SV declaration name
                const keyDecl = this.mapKeyToDeclaration(item.keybinding.key);
                if (keyDecl) {
                    usedKeys.add(keyDecl);
                }
            }
        }

        // Look up actual Declaration objects from system declarations
        const declarations: Declaration[] = [];
        for (const name of usedKeys) {
            const decl = PLCUtilities.lookupDeclarationSafe(name);
            if (decl) {
                declarations.push(decl);
            }
        }

        return declarations;
    }

    /**
     * Map a key string to its Kb_*_SV declaration name
     */
    private mapKeyToDeclaration(key: string): string | null {
        // Convert key to lowercase for mapping
        const lowerKey = key.toLowerCase();

        // Letter keys (a-z)
        if (/^[a-z]$/.test(lowerKey)) {
            return `Kb_${lowerKey}_SV`;
        }

        // Number keys (0-9)
        if (/^[0-9]$/.test(lowerKey)) {
            return `Kb_${lowerKey}_SV`;
        }

        // Function keys (F1-F12)
        if (/^f([1-9]|1[0-2])$/i.test(key)) {
            return `Kb_F${key.substring(1)}_SV`;
        }

        // Special keys mapping
        const specialKeys: Record<string, string> = {
            // Modifiers (for reference, handled separately)
            'shift': 'Kb_L_Shift_SV',
            'shiftleft': 'Kb_L_Shift_SV',
            'shiftright': 'Kb_R_Shift_SV',
            'control': 'Kb_L_Ctrl_SV',
            'ctrl': 'Kb_L_Ctrl_SV',
            'controlleft': 'Kb_L_Ctrl_SV',
            'ctrlleft': 'Kb_L_Ctrl_SV',
            'controlright': 'Kb_R_Ctrl_SV',
            'ctrlright': 'Kb_R_Ctrl_SV',
            'alt': 'Kb_L_Alt_SV',
            'altleft': 'Kb_L_Alt_SV',
            'altright': 'Kb_R_Alt_SV',

            // Navigation keys
            'insert': 'Kb_Ins_SV',
            'ins': 'Kb_Ins_SV',
            'delete': 'Kb_Del_SV',
            'del': 'Kb_Del_SV',
            'home': 'Kb_Home_SV',
            'end': 'Kb_End_SV',
            'pageup': 'Kb_PgUp_SV',
            'pgup': 'Kb_PgUp_SV',
            'pagedown': 'Kb_PgDown_SV',
            'pgdown': 'Kb_PgDown_SV',
            'pgdn': 'Kb_PgDown_SV',
            'backspace': 'Kb_Back_SV',
            'back': 'Kb_Back_SV',
            'tab': 'Kb_Tab_SV',

            // Arrow keys
            'arrowup': 'Kb_Up_SV',
            'up': 'Kb_Up_SV',
            'arrowdown': 'Kb_Down_SV',
            'down': 'Kb_Down_SV',
            'arrowleft': 'Kb_Left_SV',
            'left': 'Kb_Left_SV',
            'arrowright': 'Kb_Right_SV',
            'right': 'Kb_Right_SV',

            // Special function keys
            'escape': 'Kb_Escape_SV',
            'esc': 'Kb_Escape_SV',
            'enter': 'Kb_Enter_SV',
            'return': 'Kb_Enter_SV',
            ' ': 'Kb_spacebar_SV',
            'space': 'Kb_spacebar_SV',
            'spacebar': 'Kb_spacebar_SV',

            // Print/Scroll/Break
            'printscreen': 'Kb_Prt_Scrn_SV',
            'prtscn': 'Kb_Prt_Scrn_SV',
            'printscrn': 'Kb_Prt_Scrn_SV',
            'scrolllock': 'Kb_Scrl_Lck_SV',
            'scrllock': 'Kb_Scrl_Lck_SV',
            'scrllck': 'Kb_Scrl_Lck_SV',
            'break': 'Kb_Break_SV',
            'numlock': 'Kb_Num_Lock_SV',
            'numlk': 'Kb_Num_Lock_SV',

            // Punctuation and symbols (main keyboard)
            '=': 'Kb_Equals_SV',
            'equals': 'Kb_Equals_SV',
            '-': 'Kb_Hyphen_SV',
            'minus': 'Kb_Hyphen_SV',
            'hyphen': 'Kb_Hyphen_SV',
            '\\': 'Kb_Backslash_SV',
            'backslash': 'Kb_Backslash_SV',
            '.': 'Kb_Period_SV',
            'period': 'Kb_Period_SV',
            ',': 'Kb_Comma_SV',
            'comma': 'Kb_Comma_SV',
            '/': 'Kb_Slash_SV',
            'slash': 'Kb_Slash_SV',
            '[': 'Kb_L_Sq_Bracket_SV',
            'bracketleft': 'Kb_L_Sq_Bracket_SV',
            ']': 'Kb_R_Sq_Bracket_SV',
            'bracketright': 'Kb_R_Sq_Bracket_SV',

            // Numpad keys
            'numpad0': 'Kb_Num_0_SV',
            'numpad1': 'Kb_Num_1_SV',
            'numpad2': 'Kb_Num_2_SV',
            'numpad3': 'Kb_Num_3_SV',
            'numpad4': 'Kb_Num_4_SV',
            'numpad5': 'Kb_Num_5_SV',
            'numpad6': 'Kb_Num_6_SV',
            'numpad7': 'Kb_Num_7_SV',
            'numpad8': 'Kb_Num_8_SV',
            'numpad9': 'Kb_Num_9_SV',
            'numpaddivide': 'Kb_Num_Div_SV',
            'numpadmultiply': 'Kb_Num_Mlt_SV',
            'numpadsubtract': 'Kb_Num_Sub_SV',
            'numpadadd': 'Kb_Num_Plus_SV',
            'numpadenter': 'Kb_Num_Enter_SV',
            'numpaddecimal': 'Kb_Num_Dec_Pt_SV'
        };

        return specialKeys[lowerKey] || null;
    }

    /**
     * Get declarations added by this statement
     */
    public getAddedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];

        // Validate that this statement has a valid plcSource
        if (!this.plcSource) {
            throw new Error('SystemUIEventsStatement: plcSource is not set. Statement must be added to a program before calling getAddedDeclarations()');
        }

        // CRITICAL: SystemUIEventsStatement should ONLY be used in SystemDefault program
        const myProgramType = this.plcSource.getProgramType();
        if (myProgramType !== PLCProgramType.SystemDefault) {
            throw new Error(`SystemUIEventsStatement can only be used in SystemDefault program, but found in ${myProgramType} program`);
        }

        const keybindings = this.getAllKeybindings();

        // Create modifier key combination memory bits
        const kbShift = new Declaration('KbShiftPressed_M');
        kbShift.displayName = 'Keyboard Shift Pressed';
        kbShift.description = 'Combined left/right shift key state';
        kbShift.dataType = DataType.MemoryBit;
        kbShift.category = ['* Control', "Keyboard"];
        declarations.push(kbShift);

        const kbCtrl = new Declaration('KbCtrlPressed_M');
        kbCtrl.displayName = 'Keyboard Ctrl Pressed';
        kbCtrl.description = 'Combined left/right ctrl key state';
        kbCtrl.dataType = DataType.MemoryBit;
        kbCtrl.category = ['* Control', "Keyboard"];
        kbCtrl.readOnly = true;
        declarations.push(kbCtrl);

        const kbAlt = new Declaration('KbAltPressed_M');
        kbAlt.displayName = 'Keyboard Alt Pressed';
        kbAlt.description = 'Combined left/right alt key state';
        kbAlt.dataType = DataType.MemoryBit;
        kbAlt.category = ['* Control', "Keyboard"];
        kbAlt.readOnly = true;
        declarations.push(kbAlt);

        // Get unique UI triggers and their keybindings
        const uniqueTriggers = new Map<string, { triggerName: string, eventNumber: number, description: string, pressedText: string, notPressedText: string, keybindings: KeybindingItem[] }>();

        const systemDefault = PLCUtilities.getSystemDefault() as PLCProgram;
        const program = PLCUtilities.getSystem() as PLCProgram;

        // Add triggers from SystemDefault
        if (systemDefault?.uiTriggers) {
            for (const trigger of systemDefault.uiTriggers) {
                if (!uniqueTriggers.has(trigger.eventName)) {
                    uniqueTriggers.set(trigger.eventName, {
                        triggerName: trigger.eventName,
                        eventNumber: trigger.eventNumber,
                        description: trigger.description || `UI Event ${trigger.eventNumber}`,
                        pressedText: trigger.pressedText,
                        notPressedText: trigger.notPressedText,
                        keybindings: [...trigger.keybindings]
                    });
                }
            }
        }

        // Add triggers from System (will override SystemDefault if same name)
        if (program?.uiTriggers && program !== systemDefault) {
            for (const trigger of program.uiTriggers) {
                uniqueTriggers.set(trigger.eventName, {
                    triggerName: trigger.eventName,
                    eventNumber: trigger.eventNumber,
                    description: trigger.description || `UI Event ${trigger.eventNumber}`,
                    pressedText: trigger.pressedText,
                    notPressedText: trigger.notPressedText,
                    keybindings: [...trigger.keybindings]
                });
            }
        }

        // Create keybinding declarations only if there are keybindings (e.g., Ctrl_S_KB)
        // Use a map to deduplicate keybindings by variable name (multiple triggers can share the same key combo)
        const keybindingMap = new Map<string, { keybinding: KeybindingItem, triggerInfo: typeof uniqueTriggers extends Map<any, infer T> ? T : never }>();

        if (keybindings.length > 0) {
            for (const triggerInfo of uniqueTriggers.values()) {
                for (let i = 0; i < triggerInfo.keybindings.length; i++) {
                    const keybinding = triggerInfo.keybindings[i];
                    const kbName = keybinding.getVariableName();

                    // Only add if not already present (deduplicate by variable name)
                    if (!keybindingMap.has(kbName)) {
                        keybindingMap.set(kbName, { keybinding, triggerInfo });
                    }
                }
            }

            // Create declarations from the deduplicated map
            for (const [kbName, { keybinding }] of keybindingMap.entries()) {
                const kbDecl = new Declaration(kbName);
                kbDecl.displayName = `Keybinding ${keybinding.getKeyString()}`;
                kbDecl.description = `Keybinding: ${keybinding.getKeyString()}`;
                kbDecl.dataType = DataType.MemoryBit;
                kbDecl.category = ['Keybindings'];
                kbDecl.readOnly = true;
                declarations.push(kbDecl);
            }
        }

        // Create UI event declarations (e.g., SAVE_FILE_UI mapped to SV_SKIN_EVENT_1)
        for (const triggerInfo of uniqueTriggers.values()) {
            // Create _RAW declaration that maps to SV_SKIN_EVENT_X
            const rawDecl = new Declaration(`${triggerInfo.triggerName}_RAW`);
            rawDecl.displayName = `${triggerInfo.triggerName} Raw`;
            rawDecl.description = `Raw UI event from system: ${triggerInfo.description}`;
            rawDecl.dataType = DataType.MemoryBit;
            rawDecl.category = ['UI Events'];
            rawDecl.readOnly = true;
            rawDecl.mappedToLocation = `SV_SKIN_EVENT_${triggerInfo.eventNumber}`;
            rawDecl.isSetText = triggerInfo.pressedText;
            rawDecl.isResetText = triggerInfo.notPressedText;
            declarations.push(rawDecl);

            // Create processed declaration with no mapping - will be assigned MEM### during code gen
            const decl = new Declaration(triggerInfo.triggerName);
            decl.displayName = triggerInfo.triggerName;
            decl.description = triggerInfo.description;
            decl.dataType = DataType.MemoryBit;
            decl.category = ['UI Events'];
            decl.readOnly = true;
            decl.isSetText = triggerInfo.pressedText;
            decl.isResetText = triggerInfo.notPressedText;
            // No mappedToLocation - will be handled specially in code generation
            declarations.push(decl);
        }

        return declarations;
    }

    /**
     * Get PLC logic code
     * Outputs keybinding handling code for all defined keybindings
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        if (!this._enabled) {
            return [];
        }

        const logic: string[] = [];
        const keybindings = this.getAllKeybindings();


        logic.push('; **** UI Trigger Section ****');
        logic.push('; combine left and right');

        logic.push('IF Kb_L_Shift_SV || Kb_R_Shift_SV THEN (KbShiftPressed_M)');
        logic.push('IF Kb_L_Ctrl_SV || Kb_R_Ctrl_SV THEN (KbCtrlPressed_M)');
        logic.push('IF Kb_L_Alt_SV || Kb_R_Alt_SV THEN (KbAltPressed_M)');
        logic.push('');
        // Header comment
        logic.push('; **** System UI Events ****');

        if (keybindings.length === 0) {
            logic.push('; No keybindings defined');
        } else {
            // Only generate modifier key combinations if there are keybindings
            logic.push('; Modifier key combinations');
        }
        logic.push('');

        // Get all unique UI triggers from both programs
        const systemDefault = PLCUtilities.getSystemDefault() as PLCProgram;
        const program = PLCUtilities.getSystem() as PLCProgram;
        const allTriggers = new Map<string, { triggerName: string, eventNumber: number, description: string }>();

        // Add triggers from SystemDefault
        if (systemDefault?.uiTriggers) {
            for (const trigger of systemDefault.uiTriggers) {
                if (!allTriggers.has(trigger.eventName)) {
                    allTriggers.set(trigger.eventName, {
                        triggerName: trigger.eventName,
                        eventNumber: trigger.eventNumber,
                        description: trigger.description || `UI Event ${trigger.eventNumber}`
                    });
                }
            }
        }

        // Add triggers from System (will override SystemDefault if same name)
        if (program?.uiTriggers && program !== systemDefault) {
            for (const trigger of program.uiTriggers) {
                allTriggers.set(trigger.eventName, {
                    triggerName: trigger.eventName,
                    eventNumber: trigger.eventNumber,
                    description: trigger.description || `UI Event ${trigger.eventNumber}`
                });
            }
        }

        // Group keybindings by trigger name
        const triggerKeybindings = new Map<string, KeybindingItem[]>();
        for (const item of keybindings) {
            if (!item.triggerName) continue;

            if (!triggerKeybindings.has(item.triggerName)) {
                triggerKeybindings.set(item.triggerName, []);
            }
            triggerKeybindings.get(item.triggerName)!.push(item.keybinding);
        }

        // Generate logic for each UI trigger
        for (const [triggerName] of allTriggers.entries()) {
            logic.push(`; Process ${triggerName}`);

            // Reset the UI event
            logic.push(`IF 1==1 THEN RST ${triggerName}`);

            // Set UI event from RAW (system event) - ALWAYS generate this
            logic.push(`IF ${triggerName}_RAW THEN SET ${triggerName}`);

            // Process keybindings for this trigger (if any)
            const kbItems = triggerKeybindings.get(triggerName);
            if (kbItems && kbItems.length > 0) {
                for (let i = 0; i < kbItems.length; i++) {
                    const kb = kbItems[i];

                    if (!kb.key) {
                        continue; // Skip invalid keybindings
                    }

                    const keyDecl = this.mapKeyToDeclaration(kb.key);
                    if (!keyDecl) {
                        // Log unmapped key for debugging
                        logic.push(`; WARNING: Could not map key "${kb.key}" for UI trigger ${triggerName}`);
                        continue; // Skip unmapped keys
                    }

                    // Create the keybinding declaration name
                    const kbDeclName = kb.getVariableName();

                    // Generate comment with key combination description
                    logic.push(`; ${kbDeclName}: ${kb.getKeyString()} -> ${triggerName}`);

                    // Build condition parts
                    const shiftCondition = kb.shiftKey ? 'KbShiftPressed_M' : '!KbShiftPressed_M';
                    const ctrlCondition = kb.ctrlKey ? 'KbCtrlPressed_M' : '!KbCtrlPressed_M';
                    const altCondition = kb.altKey ? 'KbAltPressed_M' : '!KbAltPressed_M';

                    // Output logic to set the keybinding memory bit when key combination is pressed
                    logic.push(`IF ${keyDecl} && ${shiftCondition} && ${ctrlCondition} && ${altCondition} THEN (${kbDeclName})`);

                    // Trigger the UI event from keybinding
                    logic.push(`IF ${kbDeclName} THEN SET ${triggerName}`);
                }
            }

            logic.push('');
        }

        logic.push('; **** [END] UI Trigger Section ****');
        return logic;
    }

    /**
     * Get validation issues
     */
    public getValidationIssues(): any[] {
        return [];
    }

    /**
     * Get all data elements (none for this statement)
     */
    public getDataElements(): DataElement[] {
        return [];
    }

    /**
     * Clone the statement
     */
    public clone(): SystemUIEventsStatement {
        const cloned = new SystemUIEventsStatement();
        cloned._comment = this._comment;
        cloned._enabled = this._enabled;
        return cloned;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return {
            type: 'SystemUIEventsStatement',
            ...DataUtilities.getStorageData(this, ['_parentElement', '_plcSource'])
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['_parentElement', '_plcSource']);
    }

    /**
     * Set parent element and cascade to children
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        // No children to cascade to
    }
}
