import { Box, Button, Typography } from '@mui/material';
import React from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../../data/ConfigurationState';
import { MachineData } from '../../../../data/Machine/MachineData';
import { MachineStateData } from '../../../../data/MachineStateData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { ZJogControls } from '../../../Common/ZJogControls';
import { WizardStep } from '../../../Wizard/WizardStep';
import { SurfaceSpoilboardWizard } from '../SurfaceSpoilboardWizard';
import { SelectToolParametersStep } from './SelectToolParametersStep';
import { TouchPlateTouchOffStep } from './TouchPlateTouchOffStep';

export class TouchOffZStep extends WizardStep {
    constructor(wizard: SurfaceSpoilboardWizard, priorStep: WizardStep | null = null) {
        super(wizard, priorStep);
    }

    getTitle(): string {
        return 'Surface Spoilboard - Touch Off Z';
    }

    nextStep(): WizardStep | null {
        return new SelectToolParametersStep(this.wizard as SurfaceSpoilboardWizard, this);
    }

    backStep(): WizardStep | null {
        return this.priorStep;
    }

    render(): React.ReactNode {
        return (
            <ObserveState
                key="touch-off-z-step"
                listenTo={MachineStateData.Instance}
                properties={['workZ']}
                control={() => <TouchOffZStepComponent step={this} />}
            />
        );
    }
}

interface TouchOffZStepComponentProps {
    step: TouchOffZStep;
}

function TouchOffZStepComponent({ step }: TouchOffZStepComponentProps) {
    const colors = ConfigurationDataColors.Instance;
    const machineData = MachineData.Instance;
    const wizard = step.wizard as SurfaceSpoilboardWizard;

    const hasMoveableTouchpad = machineData.hasMovableTouchPlate;

    const handleTouchPlateTouchOff = () => {
        wizard.currentStep = new TouchPlateTouchOffStep(wizard, step);
        wizard.advanceToNextStep();
    };

    const handleNext = () => {
        wizard.advanceToNextStep();
    };

    return (
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, height: '100%' }}>
            <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Typography
                    variant="h5"
                    sx={{
                        color: colors.darkTextColor,
                        fontWeight: 'bold',
                        mb: 1
                    }}
                >
                    Touch the Spoilboard with the Tool
                </Typography>

                <Typography variant="body1" sx={{ color: colors.darkTextColor, mb: 1 }}>
                    Jog Z down until the tool touches the spoilboard surface. This sets the Z work zero for the surfacing operation.
                </Typography>

                <Typography variant="body2" sx={{ color: colors.mutedTextColor }}>
                    Current Z Position: {ConfigurationState.Instance.currentMachinePoint.z.toFixed(3)}"
                </Typography>

                <Box sx={{
                    display: 'flex',
                    justifyContent: 'center',
                    border: `1px solid ${colors.borderColor}`,
                    borderRadius: 1,
                    p: 2,
                    backgroundColor: colors.lightBackgroundColor
                }}>
                    <ZJogControls />
                </Box>
            </Box>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5, pt: 2, borderTop: `1px solid ${colors.borderColor}` }}>
                {hasMoveableTouchpad && (
                    <>
                        <Typography variant="body2" sx={{ color: colors.mutedTextColor, mb: 1 }}>
                            Or use touch plate for automatic Z touch off:
                        </Typography>

                        <Button
                            variant="outlined"
                            fullWidth
                            onClick={handleTouchPlateTouchOff}
                            sx={{ py: 1.5, mb: 2 }}
                        >
                            Touch Off with Touch Plate
                        </Button>
                    </>
                )}

                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                    <Button
                        variant="text"
                        onClick={() => wizard.goToPreviousStep()}
                    >
                        Back
                    </Button>
                    <Button
                        variant="contained"
                        onClick={handleNext}
                    >
                        Next: Run Parameters
                    </Button>
                </Box>
            </Box>
        </Box>
    );
}
