import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager';
import { DataUtilities } from '../../utils/storage/DataUtilities';

/**
 * Spindle configuration class
 * Contains all the configuration settings for a spindle
 * All values are nullable - null means not set/not configured
 */



export class SpindleConfig implements IStorable {
    // Basic spindle parameters
    private _encoderCounts: number | null = 8000;
    private _spindleAxis: number | null = null;
    private _lowGearRatio: number | null = 1;
    private _mediumGearRatio: number | null = 1;
    private _highGearRatio: number | null = null;
    private _maxSpeed: number | null = 24000;
    private _minSpeed: number | null = 3000;
    private _analogRange: number | null = null;
    private _okDelay: number | null = 0;
    private _fanDelay: number | null = 0;

    // Advanced parameters
    private _encoderEnabled: boolean | null = false;
    private _rigidTappingEnabled: boolean | null = null;
    private _rtgDisplay: boolean | null = null;
    private _spindleScalingEnabled: boolean | null = false;
    private _decelTime: number | null = null;
    private _rigidTappingSlowSpeed: number | null = null;
    private _rigidTappingSlowTime: number | null = null;
    private _threadingTappingAccelDecelDistance: number | null = null;
    private _minimumRigidTappingRPM: number | null = null;
    private _durationForMinRigidTappingRPM: number | null = null;
    private _spindleDrift: number | null = null;
    private _spindleAccelDecelTime: number | null = null;
    private _rigidTappingZAxisSyncDistance: number | null = null;
    private _allowSpindleOverride: boolean | null = null;
    private _doNotWaitForIndexPulse: boolean | null = null;
    private _ssvCycleTime: number | null = 0;
    private _ssvAmount: number | null = 0;
    private _frvCycleTime: number | null = 0;

    // M function strings
    private _mFuncBottomHoleG84: string | null = null;
    private _mFuncTopHoleG74Counter: string | null = null;
    private _mFuncBottomHoleG74LeftHand: string | null = null;
    private _mFuncTopHoleG84Counter: string | null = null;

    // Getters and setters
    public get encoderCounts(): number | null { return this._encoderCounts; }
    public set encoderCounts(value: number | null) { this._encoderCounts = value; StateManager.propertyChanged(this, 'encoderCounts'); }

    public get spindleAxis(): number | null { return this._spindleAxis; }
    public set spindleAxis(value: number | null) { this._spindleAxis = value; StateManager.propertyChanged(this, 'spindleAxis'); }

    public get lowGearRatio(): number | null { return this._lowGearRatio; }
    public set lowGearRatio(value: number | null) { this._lowGearRatio = value; StateManager.propertyChanged(this, 'lowGearRatio'); }

    public get mediumGearRatio(): number | null { return this._mediumGearRatio; }
    public set mediumGearRatio(value: number | null) { this._mediumGearRatio = value; StateManager.propertyChanged(this, 'mediumGearRatio'); }

    public get highGearRatio(): number | null { return this._highGearRatio; }
    public set highGearRatio(value: number | null) { this._highGearRatio = value; StateManager.propertyChanged(this, 'highGearRatio'); }

    public get maxSpeed(): number | null { return this._maxSpeed; }
    public set maxSpeed(value: number | null) { this._maxSpeed = value; StateManager.propertyChanged(this, 'maxSpeed'); }

    public get minSpeed(): number | null { return this._minSpeed; }
    public set minSpeed(value: number | null) { this._minSpeed = value; StateManager.propertyChanged(this, 'minSpeed'); }

    public get analogRange(): number | null { return this._analogRange; }
    public set analogRange(value: number | null) { this._analogRange = value; StateManager.propertyChanged(this, 'analogRange'); }

    public get okDelay(): number | null { return this._okDelay; }
    public set okDelay(value: number | null) { this._okDelay = value; StateManager.propertyChanged(this, 'okDelay'); }

    public get fanDelay(): number | null { return this._fanDelay; }
    public set fanDelay(value: number | null) { this._fanDelay = value; StateManager.propertyChanged(this, 'fanDelay'); }

    public get encoderEnabled(): boolean | null { return this._encoderEnabled; }
    public set encoderEnabled(value: boolean | null) { this._encoderEnabled = value; StateManager.propertyChanged(this, 'encoderEnabled'); }

    public get rigidTappingEnabled(): boolean | null { return this._rigidTappingEnabled; }
    public set rigidTappingEnabled(value: boolean | null) { this._rigidTappingEnabled = value; StateManager.propertyChanged(this, 'rigidTappingEnabled'); }

    public get rtgDisplay(): boolean | null { return this._rtgDisplay; }
    public set rtgDisplay(value: boolean | null) { this._rtgDisplay = value; StateManager.propertyChanged(this, 'rtgDisplay'); }

    public get spindleScalingEnabled(): boolean | null { return this._spindleScalingEnabled; }
    public set spindleScalingEnabled(value: boolean | null) { this._spindleScalingEnabled = value; StateManager.propertyChanged(this, 'spindleScalingEnabled'); }

    public get decelTime(): number | null { return this._decelTime; }
    public set decelTime(value: number | null) { this._decelTime = value; StateManager.propertyChanged(this, 'decelTime'); }

    public get rigidTappingSlowSpeed(): number | null { return this._rigidTappingSlowSpeed; }
    public set rigidTappingSlowSpeed(value: number | null) { this._rigidTappingSlowSpeed = value; StateManager.propertyChanged(this, 'rigidTappingSlowSpeed'); }

    public get rigidTappingSlowTime(): number | null { return this._rigidTappingSlowTime; }
    public set rigidTappingSlowTime(value: number | null) { this._rigidTappingSlowTime = value; StateManager.propertyChanged(this, 'rigidTappingSlowTime'); }

    public get threadingTappingAccelDecelDistance(): number | null { return this._threadingTappingAccelDecelDistance; }
    public set threadingTappingAccelDecelDistance(value: number | null) { this._threadingTappingAccelDecelDistance = value; StateManager.propertyChanged(this, 'threadingTappingAccelDecelDistance'); }

    public get minimumRigidTappingRPM(): number | null { return this._minimumRigidTappingRPM; }
    public set minimumRigidTappingRPM(value: number | null) { this._minimumRigidTappingRPM = value; StateManager.propertyChanged(this, 'minimumRigidTappingRPM'); }

    public get durationForMinRigidTappingRPM(): number | null { return this._durationForMinRigidTappingRPM; }
    public set durationForMinRigidTappingRPM(value: number | null) { this._durationForMinRigidTappingRPM = value; StateManager.propertyChanged(this, 'durationForMinRigidTappingRPM'); }

    public get spindleDrift(): number | null { return this._spindleDrift; }
    public set spindleDrift(value: number | null) { this._spindleDrift = value; StateManager.propertyChanged(this, 'spindleDrift'); }

    public get spindleAccelDecelTime(): number | null { return this._spindleAccelDecelTime; }
    public set spindleAccelDecelTime(value: number | null) { this._spindleAccelDecelTime = value; StateManager.propertyChanged(this, 'spindleAccelDecelTime'); }

    public get rigidTappingZAxisSyncDistance(): number | null { return this._rigidTappingZAxisSyncDistance; }
    public set rigidTappingZAxisSyncDistance(value: number | null) { this._rigidTappingZAxisSyncDistance = value; StateManager.propertyChanged(this, 'rigidTappingZAxisSyncDistance'); }

    public get allowSpindleOverride(): boolean | null { return this._allowSpindleOverride; }
    public set allowSpindleOverride(value: boolean | null) { this._allowSpindleOverride = value; StateManager.propertyChanged(this, 'allowSpindleOverride'); }

    public get doNotWaitForIndexPulse(): boolean | null { return this._doNotWaitForIndexPulse; }
    public set doNotWaitForIndexPulse(value: boolean | null) { this._doNotWaitForIndexPulse = value; StateManager.propertyChanged(this, 'doNotWaitForIndexPulse'); }

    public get ssvCycleTime(): number | null { return this._ssvCycleTime; }
    public set ssvCycleTime(value: number | null) { this._ssvCycleTime = value; StateManager.propertyChanged(this, 'ssvCycleTime'); }

    public get ssvAmount(): number | null { return this._ssvAmount; }
    public set ssvAmount(value: number | null) { this._ssvAmount = value; StateManager.propertyChanged(this, 'ssvAmount'); }

    public get frvCycleTime(): number | null { return this._frvCycleTime; }
    public set frvCycleTime(value: number | null) { this._frvCycleTime = value; StateManager.propertyChanged(this, 'frvCycleTime'); }

    public get mFuncBottomHoleG84(): string | null { return this._mFuncBottomHoleG84; }
    public set mFuncBottomHoleG84(value: string | null) { this._mFuncBottomHoleG84 = value; StateManager.propertyChanged(this, 'mFuncBottomHoleG84'); }

    public get mFuncTopHoleG74Counter(): string | null { return this._mFuncTopHoleG74Counter; }
    public set mFuncTopHoleG74Counter(value: string | null) { this._mFuncTopHoleG74Counter = value; StateManager.propertyChanged(this, 'mFuncTopHoleG74Counter'); }

    public get mFuncBottomHoleG74LeftHand(): string | null { return this._mFuncBottomHoleG74LeftHand; }
    public set mFuncBottomHoleG74LeftHand(value: string | null) { this._mFuncBottomHoleG74LeftHand = value; StateManager.propertyChanged(this, 'mFuncBottomHoleG74LeftHand'); }

    public get mFuncTopHoleG84Counter(): string | null { return this._mFuncTopHoleG84Counter; }
    public set mFuncTopHoleG84Counter(value: string | null) { this._mFuncTopHoleG84Counter = value; StateManager.propertyChanged(this, 'mFuncTopHoleG84Counter'); }

    // IStorable implementation
    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }
}
