import { Box, Typography } from '@mui/material';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { Declaration } from '../data/Declaration';
import { PLCInput } from '../data/io/PLCInput';
import { PLCOutput } from '../data/io/PLCOutput';
import { IPLCElement, PLCRenderMode } from '../data/IPLCElement';
import { PLCProgram } from '../data/PLCProgram';
import { PLCProgramType } from '../data/PLCUtilities';
import { MessageLevel, MessageMode, SendMessagePredicate } from '../predicates/SendMessagePredicate';
import { BasePLCStatement } from './BasePLCStatement';
import { IsChangedStatement } from './IsChangedStatement';

/**
 * IO State Changes Statement
 * System-only statement that generates IsChangedStatements for all inputs/outputs with assigned numbers
 * Only available in SystemDefault PLC programs
 */
export class IOStateChangesStatement extends BasePLCStatement {
    private _generatedStatements: IsChangedStatement[] = [];

    /**
     * Get a short, single-line description for display in tree views
     * @returns A human-readable summary
     */
    public getShortDescription(): string {
        return 'Track I/O state changes';
    }

    /**
     * Validate the statement
     */
    public validate(): string | undefined {
        return undefined; // Always valid
    }

    /**
     * Render the statement (informational display only, no editable properties)
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): any {
        const config = ConfigurationData.Instance;
        const colors = ConfigurationDataColors.Instance;

        return (
            <Box
                sx={{
                    padding: 2,
                    backgroundColor: ConfigurationDataColors.Instance.selectionColor,
                    border: `1px solid ${colors.borderColor}`,
                    borderRadius: 1,
                    opacity: this._enabled ? 1 : 0.5
                }}
            >
                <Typography
                    variant="subtitle2"
                    sx={{ color: colors.primaryColor, fontWeight: 'bold' }}
                >
                    IO State Changes
                </Typography>
                <Typography variant="body2" sx={{ marginTop: 0.5 }}>
                    Auto-generates state change tracking for all numbered inputs/outputs (system only)
                </Typography>
            </Box>
        );
    }

    /**
     * Get declarations used by this statement
     */
    public getUsedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];

        // Generate statements on demand
        this.generateStatements();

        // Collect declarations from all generated statements
        for (const stmt of this._generatedStatements) {
            declarations.push(...stmt.getUsedDeclarations());
        }

        return declarations;
    }

    /**
     * Get declarations added by this statement
     */
    public getAddedDeclarations(): Declaration[] {
        // Validate that this statement has a valid plcSource
        if (!this.plcSource) {
            throw new Error('IOStateChangesStatement: plcSource is not set. Statement must be added to a program before calling getAddedDeclarations()');
        }

        // CRITICAL: IOStateChangesStatement should ONLY be used in SystemDefault program
        const myProgramType = this.plcSource.getProgramType();
        if (myProgramType !== PLCProgramType.SystemDefault) {
            throw new Error(`IOStateChangesStatement can only be used in SystemDefault program, but found in ${myProgramType} program`);
        }

        if (!this._enabled) {
            return [];
        }

        const declarations: Declaration[] = [];

        // Generate statements on demand
        this.generateStatements();

        // Collect declarations from all generated statements
        for (const stmt of this._generatedStatements) {
            declarations.push(...stmt.getAddedDeclarations());
        }

        return declarations;
    }

    /**
     * Get PLC logic code
     * Outputs IsChangedStatements for all numbered inputs/outputs
     */
    public getPLCLogic(availableDeclarations: string[]): string[] {
        if (!this._enabled) {
            return [];
        }

        const lines: string[] = [];
        lines.push('; IO State Changes - Auto-generated for all numbered inputs/outputs');
        lines.push('');

        // Generate statements on demand
        this.generateStatements();

        if (this._generatedStatements.length === 0) {
            lines.push('; No numbered inputs or outputs to track');
            return lines;
        }

        // Generate PLC logic for each statement
        for (const stmt of this._generatedStatements) {
            const stmtLines = stmt.getPLCLogic();
            lines.push(...stmtLines);
            lines.push('');
        }

        return lines;
    }

    /**
     * Reset cached state before rendering or code generation
     * Clears generated statements so they can be regenerated with fresh IDs
     */
    public preRenderReset(): void {
        this._generatedStatements = [];
    }

    /**
     * Generate IsChangedStatements for all numbered inputs and outputs
     */
    private generateStatements(): void {
        // Only generate once - reuse existing statements to maintain consistent IDs
        if (this._generatedStatements.length > 0) {
            return;
        }

        if (!this.plcSource) {
            return;
        }

        const systemProgram = PLCProgram.Instance(PLCProgramType.System);
        let counter = 0;

        // Generate for inputs
        for (const input of systemProgram.inputs) {
            if (input.number !== null) {
                const stmt = this.createIsChangedStatementForInput(input, counter++);
                this._generatedStatements.push(stmt);
            }
        }

        // Generate for outputs
        for (const output of systemProgram.outputs) {
            if (output.number !== null) {
                const stmt = this.createIsChangedStatementForOutput(output, counter++);
                this._generatedStatements.push(stmt);
            }
        }
    }

    /**
     * Create an IsChangedStatement for an input
     */
    private createIsChangedStatementForInput(input: PLCInput, index: number): IsChangedStatement {
        // Create data element for the input (just the name, no type in constructor)
        const dataElement = new DataElement(input.centroidName);

        // Create IsChangedStatement
        const stmt = new IsChangedStatement(dataElement);
        stmt.skipInitial = true;

        // Set parent (plcSource will be resolved through parent chain)
        stmt.setParentElement(this);

        // Create rising edge message (false → true, input becomes active)
        const risingMessage = new SendMessagePredicate();
        risingMessage.messageText = `[I${input.number}+] ${input.name} is ON [${input.activeText}]`;
        risingMessage.level = MessageLevel.Info;
        risingMessage.mode = MessageMode.Async;
        stmt.addRisingEdgePredicate(risingMessage);

        // Create falling edge message (true → false, input becomes inactive)
        const fallingMessage = new SendMessagePredicate();
        fallingMessage.messageText = `[I${input.number}-] ${input.name} is OFF [${input.inactiveText}]`;
        fallingMessage.level = MessageLevel.Info;
        fallingMessage.mode = MessageMode.Async;
        stmt.addFallingEdgePredicate(fallingMessage);

        return stmt;
    }

    /**
     * Create an IsChangedStatement for an output
     */
    private createIsChangedStatementForOutput(output: PLCOutput, index: number): IsChangedStatement {
        // Create data element for the output (just the name, no type in constructor)
        const dataElement = new DataElement(output.centroidName);

        // Create IsChangedStatement
        const stmt = new IsChangedStatement(dataElement);
        stmt.skipInitial = true;

        // Set parent (plcSource will be resolved through parent chain)
        stmt.setParentElement(this);

        // Create rising edge message (false → true, output becomes active)
        const risingMessage = new SendMessagePredicate();
        risingMessage.messageText = `[O${output.number}+] ${output.name} is ON [${output.activeText}]`;
        risingMessage.level = MessageLevel.Info;
        risingMessage.mode = MessageMode.Async;
        stmt.addRisingEdgePredicate(risingMessage);

        // Create falling edge message (true → false, output becomes inactive)
        const fallingMessage = new SendMessagePredicate();
        fallingMessage.messageText = `[O${output.number}-] ${output.name} is OFF [${output.inactiveText}]`;
        fallingMessage.level = MessageLevel.Info;
        fallingMessage.mode = MessageMode.Async;
        stmt.addFallingEdgePredicate(fallingMessage);

        return stmt;
    }

    /**
     * Get validation issues
     */
    public getValidationIssues(): any[] {
        return [];
    }

    /**
     * Get all data elements (none for this statement directly)
     */
    public getDataElements(): DataElement[] {
        return [];
    }

    /**
     * Clone the statement
     */
    public clone(): IOStateChangesStatement {
        const cloned = new IOStateChangesStatement();
        cloned._comment = this._comment;
        cloned._enabled = this._enabled;
        return cloned;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return {
            type: 'IOStateChangesStatement',
            ...DataUtilities.getStorageData(this, ['_parentElement', '_plcSource', '_generatedStatements'])
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data, ['_parentElement', '_plcSource', '_generatedStatements']);
    }

    /**
     * Set parent element and cascade to children
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        // Generated statements will have their parent set when generated
    }
}
