import {
  Build as ClampIcon,
  Inventory as MaterialIcon
} from '@mui/icons-material';
import {
  Box,
  Button
} from '@mui/material';
import { useState } from 'react';
import { Material } from '../../../data/Common/Material';
import { GrainDirection, MaterialType } from '../../../data/Common/MaterialLibrary';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { Job } from '../../../data/Job';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { ViewDataFactory, ViewNames } from '../../../utils/ViewDataFactory';
import { DraggableDialog } from '../../Common/DraggableDialog';
import { FullSizeCNCViewer } from '../../MachineViewer/FullSizeCNCViewer';
import { ClampEditorForm } from '../ClampEditorForm';
import { MaterialEditorForm } from '../MaterialEditorForm';
import { JobInfoHeader } from './JobInfoHeader';

export interface ConfirmRunStageProps {
  onMovingToNext?: () => void;
  getNextStepName?: () => string;
}

export function ConfirmRunStage({ onMovingToNext, getNextStepName }: ConfirmRunStageProps) {
  const machineState = MachineStateData.Instance;
  const config = ConfigurationData.Instance;
  const colors = ConfigurationDataColors.Instance;
  const [materialDialogOpen, setMaterialDialogOpen] = useState(false);
  const [clampDialogOpen, setClampDialogOpen] = useState(false);
  const [simulatorViewData] = useState(() => ViewDataFactory.createForContext(ViewNames.CONFIRM_RUN_STAGE));

  // Ensure machineState has a currentJob with material
  const ensureCurrentJobMaterial = () => {
    if (!ConfigurationState.Instance.currentJob) {
      return;
    }
    if (!ConfigurationState.Instance.currentJob.material) {
      const defaultMaterial = new Material();
      defaultMaterial.name = "Job Material";
      defaultMaterial.type = MaterialType.Wood;
      defaultMaterial.xLength = 6;
      defaultMaterial.yLength = 8;
      defaultMaterial.height = 1.5;
      defaultMaterial.grainDirection = GrainDirection.X;
      defaultMaterial.materialColor = colors.defaultMaterialColor;
      ConfigurationState.Instance.currentJob.material = defaultMaterial;
      StateManager.propertyChanged(machineState, 'currentJob');
    }
  };

  const handleMaterialChange = (field: keyof Material, value: any) => {
    if (ConfigurationState.Instance.currentJob && ConfigurationState.Instance.currentJob.material) {
      (ConfigurationState.Instance.currentJob.material as any)[field] = value;
      StateManager.propertyChanged(machineState, 'currentJob');
    }
  };

  const handleClearMaterial = () => {
    if (ConfigurationState.Instance.currentJob) {
      // Reset to a new default material instead of undefined
      const defaultMaterial = new Material();
      defaultMaterial.name = "New Material";
      defaultMaterial.type = MaterialType.Wood;
      defaultMaterial.xLength = 0;
      defaultMaterial.yLength = 0;
      defaultMaterial.height = 0;
      defaultMaterial.grainDirection = GrainDirection.X;
      defaultMaterial.materialColor = colors.defaultMaterialColor;
      ConfigurationState.Instance.currentJob.material = defaultMaterial;
      StateManager.propertyChanged(machineState, 'currentJob');
    }
  };

  const handleClearClamps = () => {
    if (ConfigurationState.Instance.currentJob) {
      ConfigurationState.Instance.currentJob.clamps = [];
      StateManager.propertyChanged(machineState, 'currentJob');
    }
  };

  return (
    <>
      <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
        {/* Job Info Header - Fixed height header bar */}
        <Box sx={{
          p: 2,
          borderBottom: `1px solid ${colors.borderColor}`,
          backgroundColor: 'background.paper',
          flexShrink: 0
        }}>
          <JobInfoHeader
            jobName={ConfigurationState.Instance.currentJob?.name || 'Unnamed Job'}
            job={ConfigurationState.Instance.currentJob || null}
          />
        </Box>

        {/* 3D Viewer - Main content area */}
        <Box sx={{ flex: 1, minHeight: 0 }}>
          <FullSizeCNCViewer
            simulatorViewData={simulatorViewData}
            machineState={machineState}
            machineData={MachineData.Instance}
            job={ConfigurationState.Instance.currentJob || new Job()}
          />
        </Box>

        {/* Bottom Action Bar - Fixed height */}
        <Box sx={{
          p: 2,
          borderTop: `1px solid ${colors.borderColor}`,
          backgroundColor: 'background.paper',
          flexShrink: 0
        }}>
          <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center', alignItems: 'center' }}>
            <Button
              variant="outlined"
              color="error"
              startIcon={<MaterialIcon />}
              onClick={handleClearMaterial}
              disabled={!ConfigurationState.Instance.currentJob?.material ||
                ConfigurationState.Instance.currentJob.material.xLength === 0}
            >
              Clear Material
            </Button>

            <Button
              variant="outlined"
              color="success"
              startIcon={<MaterialIcon />}
              onClick={() => {
                ensureCurrentJobMaterial();
                setMaterialDialogOpen(true);
              }}
            >
              Edit Material
            </Button>

            <Box sx={{ width: 2, height: 32, backgroundColor: colors.borderColor }} />

            <Button
              variant="outlined"
              color="error"
              startIcon={<ClampIcon />}
              onClick={handleClearClamps}
              disabled={!ConfigurationState.Instance.currentJob?.clamps ||
                ConfigurationState.Instance.currentJob.clamps.length === 0}
            >
              Clear Clamps
            </Button>

            <Button
              variant="outlined"
              color="success"
              startIcon={<ClampIcon />}
              onClick={() => setClampDialogOpen(true)}
            >
              Edit Clamps
            </Button>
          </Box>
        </Box>

        {/* Material Editor Dialog */}
        <DraggableDialog
          open={materialDialogOpen}
          onClose={() => setMaterialDialogOpen(false)}
          title="Material Configuration"
          maxWidth="lg"
          fullWidth
          actions={
            <>
              <Button onClick={() => setMaterialDialogOpen(false)}>
                Cancel
              </Button>
              <Button
                variant="contained"
                onClick={() => setMaterialDialogOpen(false)}
              >
                Save Changes
              </Button>
            </>
          }
        >
          {ConfigurationState.Instance.currentJob?.material && (
            <MaterialEditorForm
              material={ConfigurationState.Instance.currentJob.material}
              onMaterialChange={handleMaterialChange}
            />
          )}
        </DraggableDialog>

        {/* Clamp Editor Dialog */}
        <DraggableDialog
          open={clampDialogOpen}
          onClose={() => setClampDialogOpen(false)}
          title="Clamp Configuration"
          maxWidth="xl"
          fullWidth
          PaperProps={{ sx: { height: '80vh' } }}
          actions={
            <Button onClick={() => setClampDialogOpen(false)} variant="contained">
              Done
            </Button>
          }
        >
          <Box sx={{ p: 2, height: 'calc(80vh - 120px)', overflow: 'auto' }}>
            <ClampEditorForm
              onSaveToLibrary={() => { }}
              onLoadFromLibrary={() => { }}
              height="100%"
            />
          </Box>
        </DraggableDialog>
      </Box>
    </>
  );
}
