import { Box, Button, FormControlLabel, Grid, Switch, Typography } from '@mui/material';
import { useState } from 'react';
import { ConfigurationDataColors } from '../../../../data/ConfigurationDataColors';
import { MachineData } from '../../../../data/Machine/MachineData';
import { ObserveState } from '../../../../utils/statemanager/ObserveState';
import { ATCToolClampComponent } from '../../../Common/ATCToolHolderComponent';
import { NumberInput } from '../../../Common/NumberInput';
import { SetupChecklistIndicator } from '../../../Common/SetupChecklistIndicator';
import { LayoutToolHoldersDialog } from '../LayoutToolHoldersDialog';

export function ATCConfigurationSection() {
    const machine = MachineData.Instance;
    const [layoutDialogOpen, setLayoutDialogOpen] = useState<boolean>(false);

    return (
        <>
            <ObserveState
                key="atc-configuration-section"
                listenTo={machine}
                properties={['hasATC']}
                control={() => (
                    <Grid container spacing={3}>
                        {/* Has ATC Switch */}
                        <Grid item xs={12}>
                            <FormControlLabel
                                control={
                                    <Switch
                                        checked={machine.hasATC}
                                        onChange={(e) => machine.hasATC = e.target.checked}
                                    />
                                }
                                label="Has ATC (Automatic Tool Changer)"
                            />
                        </Grid>

                        {/* ATC Setup Checklist Indicator - Only show when ATC is enabled */}
                        {machine.hasATC && (
                            <Grid item xs={12}>
                                <SetupChecklistIndicator name="ATC Setup" />
                            </Grid>
                        )}

                        {/* ATC Configuration - Only show if hasATC is true */}
                        {machine.hasATC && (
                            <>
                                {/* Number of Tools */}
                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-number-of-tools"
                                        listenTo={machine}
                                        properties={['atcNumberOfTools']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="Number of Tools"
                                                    value={machine.atcNumberOfTools}
                                                    onChange={(value) => machine.atcNumberOfTools = value}
                                                    margin="normal"
                                                    precision={0}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Total number of tool holders in the ATC
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                {/* Tool Change Speed Settings */}
                                <Grid item xs={12}>
                                    <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Tool Change Speed Settings</Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                        Configure movement speeds during tool change operations (in/min)
                                    </Typography>
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-xy-move-speed"
                                        listenTo={machine}
                                        properties={['xyMoveToATC']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="XY Move to ATC Speed"
                                                    value={machine.xyMoveToATC}
                                                    onChange={(value) => machine.xyMoveToATC = value}
                                                    margin="normal"
                                                    precision={0}
                                                    min={1}
                                                    max={1000}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    XY axis speed when moving to ATC area (default: 200 in/min)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-z-move-speed"
                                        listenTo={machine}
                                        properties={['zMoveToATC']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="Z Move to ATC Speed"
                                                    value={machine.zMoveToATC}
                                                    onChange={(value) => machine.zMoveToATC = value}
                                                    margin="normal"
                                                    precision={0}
                                                    min={1}
                                                    max={1000}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Z axis speed when moving to ATC area (default: 100 in/min)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-xy-approach-speed"
                                        listenTo={machine}
                                        properties={['xyApproachSpeed']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="XY Approach Speed"
                                                    value={machine.xyApproachSpeed}
                                                    onChange={(value) => machine.xyApproachSpeed = value}
                                                    margin="normal"
                                                    precision={0}
                                                    min={1}
                                                    max={1000}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    XY axis speed when approaching tool holder (default: 200 in/min)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-z-approach-speed"
                                        listenTo={machine}
                                        properties={['zApproachSpeed']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="Z Approach Speed"
                                                    value={machine.zApproachSpeed}
                                                    onChange={(value) => machine.zApproachSpeed = value}
                                                    margin="normal"
                                                    precision={0}
                                                    min={1}
                                                    max={1000}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Z axis speed when approaching tool holder (default: 100 in/min)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-xy-dock-speed"
                                        listenTo={machine}
                                        properties={['xyDockSpeed']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="XY Dock Speed"
                                                    value={machine.xyDockSpeed}
                                                    onChange={(value) => machine.xyDockSpeed = value}
                                                    margin="normal"
                                                    precision={0}
                                                    min={1}
                                                    max={1000}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    XY axis speed when docking/undocking tool (default: 30 in/min)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-z-dock-speed"
                                        listenTo={machine}
                                        properties={['zDockSpeed']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="Z Dock Speed"
                                                    value={machine.zDockSpeed}
                                                    onChange={(value) => machine.zDockSpeed = value}
                                                    margin="normal"
                                                    precision={0}
                                                    min={1}
                                                    max={1000}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Z axis speed when docking/undocking tool (default: 30 in/min)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-clamp-dwell-time"
                                        listenTo={machine}
                                        properties={['atcClampDwellTime']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="ATC Clamp Dwell Time"
                                                    value={machine.atcClampDwellTime}
                                                    onChange={(value) => machine.atcClampDwellTime = value}
                                                    margin="normal"
                                                    precision={1}
                                                    min={0.1}
                                                    max={10}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Pause time in seconds after opening/closing tool clamp (default: 2 seconds)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                {/* ATC Clearance Settings */}
                                <Grid item xs={12}>
                                    <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>ATC Clearance Settings</Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                        Safety clearance distances for tool change movements
                                    </Typography>
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-vertical-clearance"
                                        listenTo={machine}
                                        properties={['atcVerticalClearance']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="Vertical Clearance"
                                                    value={machine.atcVerticalClearance}
                                                    onChange={(value) => machine.atcVerticalClearance = value}
                                                    margin="normal"
                                                    precision={3}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Z-axis clearance above tool holder (default: 3.000, can be negative)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                <Grid item xs={12} md={6}>
                                    <ObserveState
                                        key="atc-horizontal-clearance"
                                        listenTo={machine}
                                        properties={['atcHorizontalClearance']}
                                        control={() => (
                                            <>
                                                <NumberInput
                                                    fullWidth
                                                    label="Horizontal Clearance"
                                                    value={machine.atcHorizontalClearance}
                                                    onChange={(value) => machine.atcHorizontalClearance = value}
                                                    margin="normal"
                                                    precision={3}
                                                />
                                                <Typography variant="caption" color="text.secondary">
                                                    Horizontal clearance from tool holder (default: 4.000, can be negative)
                                                </Typography>
                                            </>
                                        )}
                                    />
                                </Grid>

                                {/* Approach Axis Selection */}
                                <Grid item xs={12}>
                                    <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Approach Axis</Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                        Select which axis to use for horizontal approach movements
                                    </Typography>
                                    <ObserveState
                                        key="atc-approach-axis"
                                        listenTo={machine}
                                        properties={['atcApproachAxis']}
                                        control={() => (
                                            <Box sx={{ display: 'flex', gap: 1 }}>
                                                <Button
                                                    variant={machine.atcApproachAxis === 'X' ? 'contained' : 'outlined'}
                                                    onClick={() => machine.atcApproachAxis = 'X'}
                                                >
                                                    X-Axis
                                                </Button>
                                                <Button
                                                    variant={machine.atcApproachAxis === 'Y' ? 'contained' : 'outlined'}
                                                    onClick={() => machine.atcApproachAxis = 'Y'}
                                                >
                                                    Y-Axis
                                                </Button>
                                            </Box>
                                        )}
                                    />
                                </Grid>

                                {/* Tool Holder Positions */}
                                <Grid item xs={12}>
                                    <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>Tool Holder Positions</Typography>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                        Individual tool holder positions relative to Machine Zero. Use the layout button to automatically arrange tool holders based on ATC bar location.
                                    </Typography>
                                    <Box sx={{ mb: 2 }}>
                                        <Button
                                            variant="contained"
                                            onClick={() => setLayoutDialogOpen(true)}
                                        >
                                            Lay Out Tool Holders
                                        </Button>
                                    </Box>

                                    {/* Shared Coordinate Controls */}
                                    <ObserveState
                                        key="atc-shared-coordinates"
                                        listenTo={machine}
                                        properties={['atcShareHorizontalCoordinate', 'atcShareZCoordinate', 'atcSharedHorizontalValue', 'atcSharedZValue', 'atcApproachAxis']}
                                        control={() => (
                                            <Box sx={{ mb: 3, p: 2, backgroundColor: ConfigurationDataColors.Instance.selectionColor, borderRadius: 1 }}>
                                                <Typography variant="subtitle2" sx={{ mb: 2 }}>Shared Coordinates</Typography>
                                                <Grid container spacing={2}>
                                                    {/* Share Horizontal Coordinate */}
                                                    <Grid item xs={12} md={6}>
                                                        <Box sx={{ minHeight: '100px' }}>
                                                            <FormControlLabel
                                                                control={
                                                                    <Switch
                                                                        checked={machine.atcShareHorizontalCoordinate}
                                                                        onChange={(e) => {
                                                                            const checked = e.target.checked;
                                                                            machine.atcShareHorizontalCoordinate = checked;
                                                                            if (checked && machine.atcToolClamps.length > 0) {
                                                                                // Initialize shared value from first tool holder
                                                                                const firstClamp = machine.atcToolClamps[0];
                                                                                const sharedValue = machine.atcApproachAxis === 'Y' ? firstClamp.offsetY : firstClamp.offsetX;
                                                                                machine.atcSharedHorizontalValue = sharedValue;
                                                                                // Apply to all tool holders
                                                                                machine.atcToolClamps.forEach(clamp => {
                                                                                    if (machine.atcApproachAxis === 'Y') {
                                                                                        clamp.offsetY = sharedValue;
                                                                                    } else {
                                                                                        clamp.offsetX = sharedValue;
                                                                                    }
                                                                                });
                                                                            }
                                                                        }}
                                                                    />
                                                                }
                                                                label={`Share ${machine.atcApproachAxis === 'Y' ? 'Y' : 'X'} Coordinate (approach axis)`}
                                                            />
                                                            {machine.atcShareHorizontalCoordinate && (
                                                                <NumberInput
                                                                    fullWidth
                                                                    label={`Shared ${machine.atcApproachAxis === 'Y' ? 'Y' : 'X'} Value`}
                                                                    value={machine.atcSharedHorizontalValue}
                                                                    onChange={(value) => {
                                                                        machine.atcSharedHorizontalValue = value;
                                                                        // Apply to all tool holders
                                                                        machine.atcToolClamps.forEach(clamp => {
                                                                            if (machine.atcApproachAxis === 'Y') {
                                                                                clamp.offsetY = value;
                                                                            } else {
                                                                                clamp.offsetX = value;
                                                                            }
                                                                        });
                                                                    }}
                                                                    margin="normal"
                                                                    precision={3}
                                                                    size="small"
                                                                />
                                                            )}
                                                        </Box>
                                                    </Grid>

                                                    {/* Share Z Coordinate */}
                                                    <Grid item xs={12} md={6}>
                                                        <Box sx={{ minHeight: '100px' }}>
                                                            <FormControlLabel
                                                                control={
                                                                    <Switch
                                                                        checked={machine.atcShareZCoordinate}
                                                                        onChange={(e) => {
                                                                            const checked = e.target.checked;
                                                                            machine.atcShareZCoordinate = checked;
                                                                            if (checked && machine.atcToolClamps.length > 0) {
                                                                                // Initialize shared value from first tool holder
                                                                                const sharedValue = machine.atcToolClamps[0].offsetZ;
                                                                                machine.atcSharedZValue = sharedValue;
                                                                                // Apply to all tool holders
                                                                                machine.atcToolClamps.forEach(clamp => {
                                                                                    clamp.offsetZ = sharedValue;
                                                                                });
                                                                            }
                                                                        }}
                                                                    />
                                                                }
                                                                label="Share Z Coordinate"
                                                            />
                                                            {machine.atcShareZCoordinate && (
                                                                <NumberInput
                                                                    fullWidth
                                                                    label="Shared Z Value"
                                                                    value={machine.atcSharedZValue}
                                                                    onChange={(value) => {
                                                                        machine.atcSharedZValue = value;
                                                                        // Apply to all tool holders
                                                                        machine.atcToolClamps.forEach(clamp => {
                                                                            clamp.offsetZ = value;
                                                                        });
                                                                    }}
                                                                    margin="normal"
                                                                    precision={3}
                                                                    size="small"
                                                                />
                                                            )}
                                                        </Box>
                                                    </Grid>
                                                </Grid>
                                                <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
                                                    Enable sharing to lock coordinates across all tool holders. Disable to adjust individual positions.
                                                </Typography>
                                            </Box>
                                        )}
                                    />
                                </Grid>

                                {/* Tool Clamp List */}
                                <ObserveState
                                    key="atc-tool-clamps-list"
                                    listenTo={machine}
                                    properties={['atcToolClamps']}
                                    control={() => (
                                        <>
                                            {machine.atcToolClamps.map((clamp: any) => (
                                                <ATCToolClampComponent
                                                    key={clamp.clampNumber}
                                                    toolClamp={clamp}
                                                    disableHorizontal={machine.atcShareHorizontalCoordinate}
                                                    disableZ={machine.atcShareZCoordinate}
                                                    approachAxis={machine.atcApproachAxis}
                                                    onChange={() => { }}
                                                />
                                            ))}
                                        </>
                                    )}
                                />
                            </>
                        )}
                    </Grid>
                )}
            />

            <LayoutToolHoldersDialog
                open={layoutDialogOpen}
                onClose={() => setLayoutDialogOpen(false)}
                onConfirm={(spacing) => {
                    machine.layoutToolHoldersWithSpacing(spacing);
                }}
                approachAxis={machine.atcApproachAxis}
            />
        </>
    );
}
