/**
 * StageDialogManager - Manager for stage confirmation dialogs
 * Handles M00, M01, M02, M200, M201, M224 dialogs with Continue/Cancel buttons
 */

import React from 'react';
import { StageConfirmationDialog } from '../components/Common/StageConfirmationDialog';
import { ModalManager } from './ModalManager';

export interface StageDialogOptions {
    title: string;
    message: string;
    showWarning?: boolean;
    confirmButtonText?: string;
    cancelButtonText?: string;
}

/**
 * Global stage dialog manager using the ModalManager system
 * Shows confirmation dialogs for job stages that require user interaction
 */
export class StageDialogManager {
    private static _instance: StageDialogManager;

    private constructor() { }

    public static get Instance(): StageDialogManager {
        if (!StageDialogManager._instance) {
            StageDialogManager._instance = new StageDialogManager();
        }
        return StageDialogManager._instance;
    }

    /**
     * Show a stage confirmation dialog with Continue/Cancel buttons
     * @param options Dialog configuration
     * @returns Promise that resolves to true if Continue clicked, false if Cancel clicked
     */
    public showStageDialog(options: StageDialogOptions): Promise<boolean> {
        return new Promise<boolean>((resolve) => {
            const modalId = `stage-dialog-${Date.now()}`;

            const handleConfirm = () => {
                ModalManager.Instance.closeModal(modalId);
                resolve(true);
            };

            const handleCancel = () => {
                ModalManager.Instance.closeModal(modalId);
                resolve(false);
            };

            const modal = {
                id: modalId,
                render: () => React.createElement(StageConfirmationDialog, {
                    open: true,
                    title: options.title,
                    message: options.message,
                    showWarning: options.showWarning || false,
                    confirmButtonText: options.confirmButtonText,
                    cancelButtonText: options.cancelButtonText,
                    onConfirm: handleConfirm,
                    onCancel: handleCancel
                })
            };

            ModalManager.Instance.showModal(modal);
        });
    }

    /**
     * Show M00 stop dialog
     */
    public showM00Dialog(message?: string): Promise<boolean> {
        return this.showStageDialog({
            title: 'Program Stop (M00)',
            message: message || 'Motion stopped.\n\nPress CYCLE START to continue or Cancel to stop the job.',
            showWarning: false
        });
    }

    /**
     * Show M01 optional stop dialog
     */
    public showM01Dialog(message?: string): Promise<boolean> {
        return this.showStageDialog({
            title: 'Optional Stop (M01)',
            message: message || 'Optional stop.\n\nPress CYCLE START to continue or Cancel to stop the job.',
            showWarning: false
        });
    }

    /**
     * Show M02 program restart dialog
     */
    public showM02Dialog(message?: string): Promise<boolean> {
        return this.showStageDialog({
            title: 'Restart Program (M02)',
            message: message || 'Program will restart from beginning.\nZ-axis will move to home.\n\nPress CYCLE START to continue or Cancel to stop the job.',
            showWarning: true
        });
    }

    /**
     * Show M200/M201 prompt for action dialog
     */
    public showPromptActionDialog(message?: string, enableJogging: boolean = false): Promise<boolean> {
        const joggingText = enableJogging ? '\n\nJogging is enabled.' : '';
        return this.showStageDialog({
            title: 'Operator Action Required',
            message: (message || 'Please perform the required action.') + joggingText + '\n\nPress Continue when ready or Cancel Job to stop.',
            showWarning: false,
            confirmButtonText: 'Continue',
            cancelButtonText: 'Cancel Job'
        });
    }

    /**
     * Show M224 prompt for input dialog
     */
    public showPromptInputDialog(message?: string): Promise<boolean> {
        return this.showStageDialog({
            title: 'Operator Input Required',
            message: (message || 'Please provide the required input.') + '\n\nPress CYCLE START when ready or Cancel to stop the job.',
            showWarning: false
        });
    }
}
