import {
  ChevronLeft,
  ChevronRight,
  PlayArrow
} from '@mui/icons-material';
import {
  Alert,
  Box,
  Button,
  Checkbox,
  Divider,
  FormControlLabel,
  IconButton,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { IOStateData } from '../../../data/IOStateData';
import { MachineStateData } from '../../../data/MachineStateData';
import { ToolUtils } from '../../../utils/ToolUtils';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StageGCodeViewer } from '../../Common/StageGCodeViewer';
import { JobRunDialog } from '../../JobRunDialog';
import { JobInfoHeader } from './JobInfoHeader';

type JobStatus = 'ready' | 'running' | 'paused' | 'completed' | 'error' | 'stopped';

export interface RunStageProps {
  onMovingToNext?: () => void;
  getNextStepName?: () => string;
}
export const RunStage: React.FC<RunStageProps> = ({ onMovingToNext, getNextStepName } = {}) => {
  const colors = ConfigurationDataColors.Instance;
  const machineState = MachineStateData.Instance;
  const ioState = IOStateData.Instance;
  const currentJob = ConfigurationState.Instance.currentJob;

  const [jobStatus, setJobStatus] = useState<JobStatus>('ready');
  const [emergencyStop] = useState(false);
  const [showRunDialog, setShowRunDialog] = useState(false);

  // Check if outputs are configured
  const hasVacuumOutput = ioState.outputs.some((o: any) => o.centroidName === 'VacuumPump');
  const hasDustCollectorOutput = ioState.outputs.some((o: any) => o.centroidName === 'CustomOutput1');
  const hasDustBootOutput = ioState.outputs.some((o: any) => o.centroidName === 'DustBootDown');

  const handleRunJob = () => {
    if (!emergencyStop && currentJob && jobStatus !== 'running') {
      setShowRunDialog(true);
    }
  };

  // TODO: Implement stop job functionality
  // const stopJob = async () => {
  //   setJobStatus('stopped');
  //   // TODO: Stop stage execution
  // };

  // TODO: Implement stage icon display
  // const getStageIcon = (status: string) => {
  //   if (status === 'completed') return <CheckIcon sx={{ color: 'success.main', fontSize: 20 }} />;
  //   if (status === 'active') return <TimerIcon sx={{ color: 'primary.main', fontSize: 20 }} />;
  //   return null;
  // };

  return (
    <>
      <ObserveState
        key="run-stage-config-observer"
        listenTo={ConfigurationState.Instance}
        properties={['currentJob']}
        control={() => {
          const currentJob = ConfigurationState.Instance.currentJob;

          if (!currentJob) {
            return (
              <Box sx={{ height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Typography variant="h6" color="text.secondary">
                  No job loaded
                </Typography>
              </Box>
            );
          }

          return (
            <ObserveState
              key="run-stage-job-observer"
              listenTo={currentJob}
              properties={['stages', 'noToolChanges', 'skipOptionalStops', 'resetZInsteadOfToolMeasure', 'browsedStageIndex']}
              control={() => {
                // Read stages INSIDE the observed function so changes trigger re-renders
                const stages = currentJob.stages || [];
                const totalStages = stages.length;
                const browsedStageIndex = currentJob.browsedStageIndex || 0;
                const currentStage = stages[browsedStageIndex];

                const handlePreviousStage = () => {
                  if (currentJob && browsedStageIndex > 0) {
                    currentJob.browsedStageIndex = browsedStageIndex - 1;
                  }
                };

                const handleNextStage = () => {
                  if (currentJob && browsedStageIndex < totalStages - 1) {
                    currentJob.browsedStageIndex = browsedStageIndex + 1;
                  }
                };

                return (
                  <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
                    {/* Job Info Header - Fixed height header bar */}
                    <Box sx={{
                      p: 2,
                      borderBottom: `1px solid ${colors.borderColor}`,
                      backgroundColor: 'background.paper',
                      flexShrink: 0
                    }}>
                      <JobInfoHeader
                        jobName={currentJob?.name || 'Unnamed Job'}
                        job={currentJob || null}
                      />
                    </Box>

                    {emergencyStop && (
                      <Alert severity="error" sx={{ m: 2 }}>
                        Emergency stop activated. Please reset the machine.
                      </Alert>
                    )}

                    {/* Main Layout: 25% Stages | 75% GCode Viewer */}
                    <Box sx={{ display: 'flex', gap: 2, flex: 1, minHeight: 0, p: 2 }}>

                      {/* Left: Stage Browser & Controls (25%) */}
                      <Box sx={{ width: '25%', minWidth: '300px', maxWidth: '400px', display: 'flex', flexDirection: 'column' }}>

                        {/* Stage Browser - Always visible */}
                        {totalStages > 0 && (
                          <>
                            {/* Stage Navigation Header */}
                            <Box sx={{
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'space-between',
                              mb: 2,
                              p: 1.5,
                              backgroundColor: colors.primaryColor,
                              borderRadius: 1,
                              color: colors.lightTextColor
                            }}>
                              <IconButton
                                size="small"
                                onClick={handlePreviousStage}
                                disabled={browsedStageIndex === 0}
                                sx={{ color: colors.lightTextColor, '&:disabled': { color: `${colors.lightTextColor}4D` } }}
                              >
                                <ChevronLeft />
                              </IconButton>

                              <Typography variant="body1" fontWeight="bold">
                                Stage {browsedStageIndex + 1} of {totalStages}
                              </Typography>

                              <IconButton
                                size="small"
                                onClick={handleNextStage}
                                disabled={browsedStageIndex === totalStages - 1}
                                sx={{ color: colors.lightTextColor, '&:disabled': { color: `${colors.lightTextColor}4D` } }}
                              >
                                <ChevronRight />
                              </IconButton>
                            </Box>

                            {/* Current Stage Info */}
                            {currentStage && typeof currentStage.getStageName === 'function' && (
                              <Box sx={{ mb: 2, p: 2, backgroundColor: 'action.hover', borderRadius: 1 }}>
                                <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
                                  {currentStage.getStageName()}
                                </Typography>
                                {currentStage.getStageDisplayData().map((line: string, idx: number) => (
                                  <Typography key={idx} variant="body2" color="text.primary">
                                    {line}
                                  </Typography>
                                ))}
                              </Box>
                            )}

                            <Divider sx={{ my: 2 }} />
                          </>
                        )}

                        {/* Run Configuration Options */}
                        {currentJob && (
                          <ObserveState
                            key="run-options-observer"
                            listenTo={currentJob}
                            properties={['noToolChanges', 'skipOptionalStops', 'startVacuumTable', 'turnVacuumOffAtEnd', 'startDustCollector', 'lowerDustBoot']}
                            control={() => (
                              <Box sx={{ mb: 2 }}>
                                <Typography variant="subtitle2" gutterBottom fontWeight="bold">
                                  Run Options
                                </Typography>

                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      checked={currentJob.noToolChanges}
                                      onChange={(e) => currentJob.noToolChanges = e.target.checked}
                                      size="small"
                                    />
                                  }
                                  label={
                                    <Box>
                                      <Typography variant="body2">
                                        Use Current Tool
                                      </Typography>
                                      <Typography variant="caption" color="text.secondary">
                                        (skip tool changes)
                                      </Typography>
                                    </Box>
                                  }
                                  sx={{ mb: 0.5, alignItems: 'flex-start' }}
                                />

                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      checked={currentJob.skipOptionalStops}
                                      onChange={(e) => currentJob.skipOptionalStops = e.target.checked}
                                      size="small"
                                    />
                                  }
                                  label={
                                    <Typography variant="body2">
                                      Skip optional stops (M01)
                                    </Typography>
                                  }
                                  sx={{ mb: 1 }}
                                />

                                <FormControlLabel
                                  control={
                                    <Checkbox
                                      checked={currentJob.resetZInsteadOfToolMeasure}
                                      onChange={(e) => currentJob.resetZInsteadOfToolMeasure = e.target.checked}
                                      size="small"
                                    />
                                  }
                                  label={
                                    <Box>
                                      <Typography variant="body2">
                                        Reset Z Instead of Tool Measure
                                      </Typography>
                                      <Typography variant="caption" color="text.secondary">
                                        (use work zero wizard at tool changes)
                                      </Typography>
                                    </Box>
                                  }
                                  sx={{ mb: 1, alignItems: 'flex-start' }}
                                />

                                {hasDustCollectorOutput && (
                                  <FormControlLabel
                                    control={
                                      <Checkbox
                                        checked={currentJob.startDustCollector}
                                        onChange={(e) => currentJob.startDustCollector = e.target.checked}
                                        size="small"
                                      />
                                    }
                                    label={
                                      <Typography variant="body2">
                                        Start dust collector
                                      </Typography>
                                    }
                                    sx={{ mb: 1 }}
                                  />
                                )}

                                {hasDustBootOutput && (
                                  <FormControlLabel
                                    control={
                                      <Checkbox
                                        checked={currentJob.lowerDustBoot}
                                        onChange={(e) => currentJob.lowerDustBoot = e.target.checked}
                                        size="small"
                                      />
                                    }
                                    label={
                                      <Typography variant="body2">
                                        Lower dust boot
                                      </Typography>
                                    }
                                    sx={{ mb: 1 }}
                                  />
                                )}

                                {hasVacuumOutput && (
                                  <FormControlLabel
                                    control={
                                      <Checkbox
                                        checked={currentJob.startVacuumTable}
                                        onChange={(e) => currentJob.startVacuumTable = e.target.checked}
                                        size="small"
                                      />
                                    }
                                    label={
                                      <Typography variant="body2">
                                        Start vacuum table
                                      </Typography>
                                    }
                                    sx={{ mb: 0.5 }}
                                  />
                                )}

                                {currentJob.startVacuumTable && hasVacuumOutput && (
                                  <FormControlLabel
                                    control={
                                      <Checkbox
                                        checked={currentJob.turnVacuumOffAtEnd}
                                        onChange={(e) => currentJob.turnVacuumOffAtEnd = e.target.checked}
                                        size="small"
                                      />
                                    }
                                    label={
                                      <Typography variant="body2">
                                        Turn vacuum off at end
                                      </Typography>
                                    }
                                    sx={{ mb: 1, ml: 3 }}
                                  />
                                )}

                                {/* Manual Vacuum Control - TODO: Implement manual control */}
                                {/* <Button
                        variant="outlined"
                        size="small"
                        startIcon={<VacuumIcon />}
                        onClick={() => {}}
                        fullWidth
                        sx={{ mt: 1 }}
                      >
                        Start Vacuum Now
                      </Button> */}
                              </Box>
                            )}
                          />
                        )}

                        {/* Job Completion Statistics */}
                        {jobStatus === 'completed' && currentJob && (
                          <ObserveState
                            key="job-completion-stats"
                            listenTo={currentJob}
                            properties={['runStatistics', 'executionCount']}
                            control={() => {
                              const lastRun = currentJob.lastRunStatistic;
                              const execCount = currentJob.executionCount;

                              if (!lastRun) return null;

                              const durationSeconds = lastRun.durationMs / 1000;
                              const minutes = Math.floor(durationSeconds / 60);
                              const seconds = (durationSeconds % 60).toFixed(1);

                              // Handle both Date objects and string dates (for backward compatibility)
                              const endTime = lastRun.endTime instanceof Date
                                ? lastRun.endTime
                                : new Date(lastRun.endTime);

                              return (
                                <Box sx={{ p: 2, backgroundColor: 'success.light', borderRadius: 1 }}>
                                  <Typography variant="h6" fontWeight="bold" gutterBottom sx={{ color: 'success.dark' }}>
                                    ✓ Job Completed Successfully
                                  </Typography>
                                  <Typography variant="body2" gutterBottom>
                                    <strong>Duration:</strong> {minutes > 0 ? `${minutes}m ` : ''}{seconds}s
                                  </Typography>
                                  <Typography variant="body2" gutterBottom>
                                    <strong>Completed:</strong> {endTime.toLocaleTimeString()}
                                  </Typography>
                                  <Typography variant="body2">
                                    <strong>Total Runs:</strong> {execCount}
                                  </Typography>
                                </Box>
                              );
                            }}
                          />
                        )}
                      </Box>

                      {/* Right: Stage Info & GCode Viewer (75%) */}
                      <Box sx={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', position: 'relative' }}>

                        {/* Floating Run Button - Centered */}
                        {currentJob && jobStatus !== 'running' && (
                          <Button
                            onClick={handleRunJob}
                            disabled={emergencyStop}
                            sx={{
                              position: 'absolute',
                              top: '50%',
                              left: '50%',
                              transform: 'translate(-50%, -50%)',
                              zIndex: 10,
                              width: 120,
                              height: 120,
                              borderRadius: '50%',
                              backgroundColor: `${colors.lightTextColor}4D`,
                              color: colors.lightTextColor,
                              fontSize: '3rem',
                              minWidth: 0,
                              padding: 0,
                              boxShadow: `0 8px 24px ${colors.darkTextColor}66`,
                              backdropFilter: 'blur(8px)',
                              border: `3px solid ${colors.lightTextColor}66`,
                              transition: 'all 0.3s ease',
                              '&:hover': {
                                backgroundColor: `${colors.lightTextColor}80`,
                                transform: 'translate(-50%, -50%) scale(1.05)',
                                boxShadow: `0 12px 32px ${colors.darkTextColor}80`,
                              },
                              '&:disabled': {
                                backgroundColor: `${colors.secondaryBorderColor}4D`,
                                color: `${colors.lightTextColor}66`,
                              },
                            }}
                          >
                            <PlayArrow sx={{ fontSize: '4rem' }} />
                          </Button>
                        )}

                        {/* Stage G-code Viewer with Context */}
                        {currentStage && currentJob && (
                          <StageGCodeViewer
                            stage={currentStage}
                            allGCodeLines={currentJob.getModifiedGCode(
                              machineState.currentFixtureNumber,
                              machineState.currentToolNumber,
                              ToolUtils.getCurrentTool()?.toolMeasured || false
                            ).split('\n')}
                            contextLineCount={5}
                          />
                        )}
                      </Box>

                    </Box>
                  </Box>
                );
              }}
            />
          );
        }}
      />

      {/* Job Run Dialog */}
      {ConfigurationState.Instance.currentJob && showRunDialog && (
        <JobRunDialog
          open={showRunDialog}
          onClose={() => {
            setShowRunDialog(false);
          }}
          job={ConfigurationState.Instance.currentJob}
          onRunComplete={() => {
            setJobStatus('completed');
          }}
        />
      )}
    </>
  );
};