import { Button, Grid, Typography } from '@mui/material';
import { ConfigurationState } from '../../data/ConfigurationState';
import { ATCLocation } from '../../data/Machine/ATCLocation';
import { MachineStateData } from '../../data/MachineStateData';
import { NumberInput } from './NumberInput';

interface ATCLocationComponentProps {
  atcLocation: ATCLocation;
  onChange: () => void;
  title?: string;
  showSetButtons?: boolean;
}

export function ATCLocationComponent({
  atcLocation,
  onChange,
  title = "Location (from Machine Zero)",
  showSetButtons = true
}: ATCLocationComponentProps) {

  const handleSetXY = () => {
    const machineState = MachineStateData.Instance;
    atcLocation.x = ConfigurationState.Instance.currentMachinePoint.x;
    atcLocation.y = ConfigurationState.Instance.currentMachinePoint.y;
    onChange();
  };

  const handleSetXYZ = () => {
    const machineState = MachineStateData.Instance;
    atcLocation.x = ConfigurationState.Instance.currentMachinePoint.x;
    atcLocation.y = ConfigurationState.Instance.currentMachinePoint.y;
    atcLocation.z = ConfigurationState.Instance.currentMachinePoint.z;
    onChange();
  };

  return (
    <>
      <Grid item xs={12}>
        <Typography variant="subtitle1" sx={{ mt: 2, mb: 1 }}>{title}</Typography>
      </Grid>

      <Grid item xs={12} md={3}>
        <NumberInput
          fullWidth
          label="X Position"
          value={atcLocation.x}
          onChange={(value) => {
            atcLocation.x = value;
            onChange();
          }}
          margin="normal"
          precision={3}
        />
        <Typography variant="caption" color="text.secondary">
          X coordinate from machine zero
        </Typography>
      </Grid>

      <Grid item xs={12} md={3}>
        <NumberInput
          fullWidth
          label="Y Position"
          value={atcLocation.y}
          onChange={(value) => {
            atcLocation.y = value;
            onChange();
          }}
          margin="normal"
          precision={3}
        />
        <Typography variant="caption" color="text.secondary">
          Y coordinate from machine zero
        </Typography>
      </Grid>

      <Grid item xs={12} md={3}>
        <NumberInput
          fullWidth
          label="Z Position"
          value={atcLocation.z}
          onChange={(value) => {
            atcLocation.z = value;
            onChange();
          }}
          margin="normal"
          precision={3}
        />
        <Typography variant="caption" color="text.secondary">
          Z coordinate from machine zero
        </Typography>
      </Grid>

      {showSetButtons && (
        <Grid item xs={12}>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2, mt: 2 }}>
            Navigate the machine to the corner of the ATC bar, then use these buttons to capture the current position:
          </Typography>
          <Button
            variant="outlined"
            onClick={handleSetXY}
            sx={{ mr: 2 }}
          >
            Set XY
          </Button>
          <Button
            variant="outlined"
            onClick={handleSetXYZ}
          >
            Set XYZ
          </Button>
        </Grid>
      )}
    </>
  );
}
