import { UserActionData } from '../../data/UserActionData';
import { ChangeFixtureUserAction } from './ChangeFixtureUserAction';
import { ChangeToolUserAction } from './ChangeToolUserAction';
import { DustBootUserAction } from './DustBootUserAction';
import { DustCollectorUserAction } from './DustCollectorUserAction';
import { EditClampsUserAction } from './EditClampsUserAction';
import { EditMaterialUserAction } from './EditMaterialUserAction';
import { GoToWorkZeroUserAction } from './GoToWorkZeroUserAction';
import { HomeMachineUserAction } from './HomeMachineUserAction';
import { LaserPointerUserAction } from './LaserPointerUserAction';
import { UnhomeMachineUserAction } from './UnhomeMachineUserAction';
import { MeasureAllToolsUserAction } from './MeasureAllToolsUserAction';
import { MeasureToolUserAction } from './MeasureToolUserAction';
import { MeasureZUserAction } from './MeasureZUserAction';
import { PositioningPinsUserAction } from './PositioningPinsUserAction';
import { RememberPointUserAction } from './RememberPointUserAction';
import { ReplaceToolUserAction } from './ReplaceToolUserAction';
import { SurfaceSpoilboardUserAction } from './SurfaceSpoilboardUserAction';
import { UserActionRegistry } from './UserActionRegistry';
import { VacuumUserAction } from './VacuumUserAction';
import { WarmUpSpindleUserAction } from './WarmUpSpindleUserAction';

/**
 * Registers all default user actions for the ActionsPanel
 */
export class DefaultUserActions {
  private static _initialized = false;
  private static _onViewChange?: (view: string) => void;

  /**
   * Initialize and register all default actions
   * @param onViewChange Callback for view changes (optional on first call)
   */
  public static initialize(onViewChange?: (view: string) => void): void {
    // Store the callback for use in actions
    if (onViewChange) {
      DefaultUserActions._onViewChange = onViewChange;
    }

    // Only register actions once
    if (!DefaultUserActions._initialized) {
      const registry = UserActionRegistry.Instance;

      // Register all actions from separate files (instantiate classes)
      registry.registerAction(new HomeMachineUserAction());
      registry.registerAction(new UnhomeMachineUserAction());
      registry.registerAction(new GoToWorkZeroUserAction());
      registry.registerAction(new ChangeFixtureUserAction());
      registry.registerAction(new RememberPointUserAction());
      registry.registerAction(new EditMaterialUserAction());
      registry.registerAction(new EditClampsUserAction());
      registry.registerAction(new ChangeToolUserAction());
      registry.registerAction(new ReplaceToolUserAction());
      registry.registerAction(new DustBootUserAction());
      registry.registerAction(new VacuumUserAction());
      registry.registerAction(new DustCollectorUserAction());
      registry.registerAction(new LaserPointerUserAction());
      registry.registerAction(new PositioningPinsUserAction());
      registry.registerAction(new MeasureZUserAction());
      registry.registerAction(new MeasureToolUserAction());
      registry.registerAction(new MeasureAllToolsUserAction());
      registry.registerAction(new WarmUpSpindleUserAction());
      registry.registerAction(new SurfaceSpoilboardUserAction());

      // Register user-defined actions after code-defined actions
      registry.registerUserDefinedActions();

      DefaultUserActions._initialized = true;
    }

    // Always ensure default home page actions are added (in case of reset)
    const registry = UserActionRegistry.Instance;
    const userActionData = UserActionData.Instance;

    // Find all code-defined actions that should be on home page
    const allActions = registry.getAllActionsSync();
    const defaultHomeActions = allActions.filter(action => action.isDefaultHomeAction);

    // Ensure all default home actions are in the home page array
    defaultHomeActions.forEach(action => {
      if (!userActionData.isOnHomePage(action.id)) {
        userActionData.addToHomePage(action.id);
      }
    });
  }

  /**
   * Reset initialization state (useful for testing)
   */
  public static reset(): void {
    DefaultUserActions._initialized = false;
  }
}
