import {
  Add as AddIcon,
  Close as CloseIcon,
  Delete as DeleteIcon,
  Edit as EditIcon
} from '@mui/icons-material';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { CutterType, Tool } from '../../../data/Common/Tool';
import { ToolLibrary } from '../../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { MachineStateData } from '../../../data/MachineStateData';
import { ConfirmDialogManager } from '../../../utils/ConfirmDialogManager';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { ToolEditorForm } from '../../Common/ToolEditorForm';

interface ToolDialogProps {
  open: boolean;
  tool: Tool;  // Always requires a tool instance (use new Tool() for new tools)
  library: ToolLibrary;
  onClose: () => void;
  onSave: (tool: Tool) => void;
  isNewTool: boolean;  // True when creating new tool, false when editing
}

const ToolDialog: React.FC<ToolDialogProps> = ({ open, tool, library, onClose, onSave, isNewTool }) => {
  const config = ConfigurationData.Instance;
  const colors = ConfigurationDataColors.Instance;
  const [, forceUpdate] = useState(0); // Counter to force re-renders when tool is modified in place
  const [toolNumberError, setToolNumberError] = useState<string>('');
  const [toolNumberWarning, setToolNumberWarning] = useState<string>('');
  const [conflictingTool, setConflictingTool] = useState<Tool | null>(null);
  const [cuttingLengthError, setCuttingLengthError] = useState<string>('');
  const [vBitAngleError, setVBitAngleError] = useState<string>('');

  // Validate tool number for duplicates
  const validateToolNumber = React.useCallback((toolNumber: number | null) => {
    // Allow null tool numbers (unassigned)
    if (toolNumber === null) {
      setToolNumberError('');
      setToolNumberWarning('');
      setConflictingTool(null);
      return;
    }

    const existingTool = library.tools.find((existingTool, index) => {
      // If we're editing a tool, exclude it from the duplicate check
      if (!isNewTool && library.tools[index] === tool) {
        return false;
      }
      return existingTool.toolNumber === toolNumber;
    });

    if (existingTool) {
      setToolNumberWarning(`Warning: Tool number ${toolNumber} is assigned to "${existingTool.displayName}". Saving will unassign that tool.`);
      setConflictingTool(existingTool);
      setToolNumberError('');
    } else {
      setToolNumberError('');
      setToolNumberWarning('');
      setConflictingTool(null);
    }
  }, [library.tools, tool]);

  // Validate cutting length
  const validateCuttingLength = React.useCallback((cuttingLength: number, lengthBelowHolder: number) => {
    // Compare absolute values since lengthBelowHolder is stored negative
    if (cuttingLength > Math.abs(lengthBelowHolder)) {
      setCuttingLengthError('Cutting length must be <= length below holder');
    } else {
      setCuttingLengthError('');
    }
  }, []);

  // Validate V-bit angle
  const validateVBitAngle = React.useCallback((angle: number) => {
    if (angle <= 0 || angle >= 180) {
      setVBitAngleError('V-bit angle must be between 0° and 180°');
    } else {
      setVBitAngleError('');
    }
  }, []);

  React.useEffect(() => {
    // Clear any existing errors when dialog opens
    setToolNumberError('');
    setToolNumberWarning('');
    setConflictingTool(null);
    setCuttingLengthError('');
    setVBitAngleError('');
    // Validate the initial tool
    validateToolNumber(tool.toolNumber);
  }, [tool, validateToolNumber]);





  const handleSave = () => {
    // Final validation before save
    validateToolNumber(tool.toolNumber);
    validateCuttingLength(tool.cuttingLength, tool.lengthBelowHolder);
    if (tool.cutterType === CutterType.VBit) {
      validateVBitAngle(tool.vCuttingEdgeAngle);
    }

    if (toolNumberError || cuttingLengthError || vBitAngleError) {
      return; // Don't save if there are errors (warnings are OK)
    }

    // If there's a conflicting tool, unassign its tool number
    if (conflictingTool) {
      conflictingTool.toolNumber = null;
    }

    onSave(tool);
    onClose();
  };

  // Check if all required fields are filled
  const isFormValid = () => {
    // Required fields
    if (tool.shankWidth <= 0) return false;
    if (Math.abs(tool.lengthBelowHolder) <= 0) return false;
    if (tool.cuttingDiameter <= 0) return false;

    // Type-specific required fields
    if (tool.cutterType === CutterType.VBit) {
      if (tool.vCuttingEdgeAngle <= 0 || tool.vCuttingEdgeAngle >= 180) return false;
    } else {
      if (tool.cuttingLength <= 0) return false;
    }

    // Check for validation errors
    if (toolNumberError || cuttingLengthError || vBitAngleError) return false;

    return true;
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="lg" fullWidth>
      <DialogTitle sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        backgroundColor: colors.primaryColor,
        color: colors.lightTextColor,
        py: 2,
        px: 3
      }}>
        {isNewTool ? 'Add New Tool' : 'Edit Tool'}
        <IconButton
          onClick={onClose}
          sx={{
            color: colors.lightTextColor,
            '&:hover': {
              backgroundColor: `${colors.lightTextColor}1A`
            }
          }}
        >
          <CloseIcon />
        </IconButton>
      </DialogTitle>
      <DialogContent sx={{ mt: 3 }}>
        {/* Using ToolEditorForm component - inline form code below is kept for reference but not used */}
        <ToolEditorForm
          tool={tool}
          library={library}
          onToolChange={(updatedTool) => {
            // Tool is modified in place, force re-render
            forceUpdate(prev => prev + 1);
          }}
          showToolViewer={true}
          disabled={tool.systemLocked}
          isNewTool={isNewTool}
        />
      </DialogContent>
      <DialogActions sx={{
        p: 2,
        gap: 1,
        justifyContent: 'flex-end',
        borderTop: `1px solid ${colors.borderColor}`
      }}>
        <Button onClick={onClose} variant="outlined">
          Cancel
        </Button>
        <Button
          onClick={handleSave}
          variant="contained"
          disabled={!isFormValid()}
        >
          Save
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export const ToolLibraryTab: React.FC = () => {
  const [library] = useState(() => ToolLibrary.Instance);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingTool, setEditingTool] = useState<Tool | null>(null);
  const [isNewTool, setIsNewTool] = useState(false);

  const handleAddTool = () => {
    // Create a new Tool instance for adding
    setEditingTool(new Tool());
    setIsNewTool(true);
    setDialogOpen(true);
  };

  const handleEditTool = (tool: Tool) => {
    if (tool.systemLocked) return; // Prevent editing system locked tools
    setEditingTool(tool);
    setIsNewTool(false);
    setDialogOpen(true);
  };

  const handleDeleteTool = async (tool: Tool) => {
    if (tool.systemLocked) return; // Prevent deleting system locked tools

    const toolLabel = tool.toolNumber !== null ? `T${tool.toolNumber.toFixed(0)}` : 'Unassigned tool';
    const confirmed = await ConfirmDialogManager.Instance.showDeleteConfirm(`${toolLabel} - ${tool.displayName}`);

    if (confirmed) {
      library.removeTool(tool.toolNumber); // Use library method to trigger state update
    }
  };

  const handleSaveTool = (tool: Tool) => {
    // Note: Duplicate tool number handling is done in the dialog
    // The conflicting tool's number is unassigned before we get here

    if (isNewTool) {
      // Add new tool using library method to trigger listeners and auto-save
      library.addTool(tool);
    } else {
      // Update existing tool using library method to trigger listeners and auto-save
      // editingTool contains the original tool reference
      library.updateTool(editingTool!.toolNumber, tool);
    }
  };

  return (
    <ObserveState
      listenTo={library}
      control={() => (
        <Box sx={{ p: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
            <Typography variant="h6">Tool Library</Typography>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={handleAddTool}
            >
              Add Tool
            </Button>
          </Box>

          <TableContainer component={Paper}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Tool #</TableCell>
                  <TableCell>Name</TableCell>
                  <TableCell>Type</TableCell>
                  <TableCell>Diameter</TableCell>
                  <TableCell>Length</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell align="right">Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {library.tools
                  .sort((a, b) => {
                    // Sort unassigned (null) tool numbers to the bottom
                    if (a.toolNumber === null && b.toolNumber === null) return 0;
                    if (a.toolNumber === null) return 1;
                    if (b.toolNumber === null) return -1;
                    return a.toolNumber - b.toolNumber;
                  })
                  .map((tool, index) => (
                    <TableRow key={index}>
                      <TableCell>{tool.toolNumber !== null ? tool.toolNumber.toFixed(0) : '-'}</TableCell>
                      <TableCell>{tool.displayName}</TableCell>
                      <TableCell>
                        <Chip
                          label={tool.cutterType}
                          size="small"
                          color={tool.cutterType === CutterType.FlatEndMill ? 'primary' :
                            tool.cutterType === CutterType.BallEndMill ? 'success' : 'warning'}
                        />
                      </TableCell>
                      <TableCell>{tool.cuttingDiameter}</TableCell>
                      <TableCell>{tool.lengthBelowHolder}</TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                          {!tool.needsMeasurement(MachineStateData.Instance.sessionNumber) && (
                            <Chip label="Measured" size="small" color="success" />
                          )}
                          {tool.systemLocked && (
                            <Chip label="System Locked" size="small" color="default" />
                          )}
                        </Box>
                      </TableCell>
                      <TableCell align="right">
                        <IconButton
                          size="small"
                          onClick={() => handleEditTool(tool)}
                          color="primary"
                          title={tool.systemLocked ? "View tool (read-only)" : "Edit Tool"}
                        >
                          <EditIcon />
                        </IconButton>
                        <IconButton
                          size="small"
                          onClick={() => handleDeleteTool(tool)}
                          color="error"
                          disabled={tool.systemLocked}
                          title={tool.systemLocked ? "Cannot delete system locked tool" : "Delete Tool"}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                {library.tools.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={8} align="center" sx={{ py: 4, color: 'text.secondary' }}>
                      No tools found. Click "Add Tool" to create your first tool.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          {editingTool && (
            <ToolDialog
              open={dialogOpen}
              tool={editingTool}
              library={library}
              onClose={() => setDialogOpen(false)}
              onSave={handleSaveTool}
              isNewTool={isNewTool}
            />
          )}
        </Box>
      )}
    />
  );
};
