import {
    Close as CloseIcon,
    Build as ToolIcon
} from '@mui/icons-material';
import {
    Box,
    Button,
    ButtonGroup,
    Chip,
    Dialog,
    DialogContent,
    DialogTitle,
    IconButton,
    List,
    ListItem,
    ListItemIcon,
    ListItemText,
    Paper,
    Tab,
    Tabs,
    Typography
} from '@mui/material';
import { useState } from 'react';
import { ToolLibrary } from '../../../data/Common/ToolLibrary';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { MachineData } from '../../../data/Machine/MachineData';
import { MachineStateData } from '../../../data/MachineStateData';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { ViewDataFactory, ViewNames } from '../../../utils/ViewDataFactory';
import { GCodeEditor } from '../../Common/GCodeEditor';
import { FullSizeCNCViewer } from '../../MachineViewer/FullSizeCNCViewer';
import { JobInfoHeader } from './JobInfoHeader';

export interface PreviewGCodeStageProps {
    onMovingToNext?: () => void;
    getNextStepName?: () => string;
}

const colors = ConfigurationDataColors.Instance;

// Detect if G-code already has G20 or G21 command
const detectUnit = (gcode: string): 'inches' | 'mm' | null => {
    const lines = gcode.split('\n');
    for (const line of lines) {
        const cleanLine = line.trim().toUpperCase();
        // Skip comments
        if (cleanLine.startsWith('(') || cleanLine.startsWith(';')) continue;

        // Check for G20 (inches) or G21 (mm)
        if (/\bG\s*20\b/.test(cleanLine) || /\bG20\b/.test(cleanLine)) {
            return 'inches';
        }
        if (/\bG\s*21\b/.test(cleanLine) || /\bG21\b/.test(cleanLine)) {
            return 'mm';
        }
    }
    return null;
};

export function PreviewGCodeStage({ onMovingToNext, getNextStepName }: PreviewGCodeStageProps = {}) {
    const [simulatorViewData] = useState(() => ViewDataFactory.createForContext(ViewNames.GCODE_STAGE));
    const [showToolsDialog, setShowToolsDialog] = useState<boolean>(false);
    const [viewerTab, setViewerTab] = useState<number>(0);

    // State for unit selection (null = not specified, 'inches' = G20, 'mm' = G21)
    const [specifiedUnit, setSpecifiedUnit] = useState<'inches' | 'mm' | null>(() => {
        // Detect unit from proposedJob on mount
        const job = ConfigurationState.Instance.proposedJob;
        if (job) {
            return detectUnit(job.gcode);
        }
        return null;
    });

    // Track if unit was originally specified in the G-code (to control toggle visibility)
    const [originallySpecified] = useState<boolean>(() => {
        const job = ConfigurationState.Instance.proposedJob;
        if (job) {
            return detectUnit(job.gcode) !== null;
        }
        return false;
    });

    // Instance references
    const machineState = MachineStateData.Instance;
    const toolLibrary = ToolLibrary.Instance;

    // Add or replace unit command in G-code
    const setGCodeUnit = (gcode: string, unit: 'inches' | 'mm'): string => {
        const unitCommand = unit === 'inches' ? 'G20' : 'G21';
        const lines = gcode.split('\n');
        let unitLineIndex = -1;
        let insertAfterLine = -1;

        // Find existing G20/G21 or where to insert (after first non-comment line)
        for (let i = 0; i < lines.length; i++) {
            const cleanLine = lines[i].trim().toUpperCase();

            // Skip empty lines and comments
            if (!cleanLine || cleanLine.startsWith('(') || cleanLine.startsWith(';')) continue;

            // Check if this line has G20 or G21
            if (/\bG\s*2[01]\b/.test(cleanLine) || /\bG2[01]\b/.test(cleanLine)) {
                unitLineIndex = i;
                break;
            }

            // Track first G-code line (good place to insert unit)
            if (insertAfterLine === -1 && /\bG\s*\d+/.test(cleanLine)) {
                insertAfterLine = i;
            }
        }

        if (unitLineIndex >= 0) {
            // Replace existing unit line
            const line = lines[unitLineIndex];
            lines[unitLineIndex] = line.replace(/\bG\s*2[01]\b|\bG2[01]\b/i, unitCommand);
        } else {
            // Insert new unit command
            const insertIndex = insertAfterLine >= 0 ? insertAfterLine : 0;
            lines.splice(insertIndex, 0, unitCommand);
        }

        return lines.join('\n');
    };

    // Handle unit change
    const handleUnitChange = (unit: 'inches' | 'mm') => {
        const job = ConfigurationState.Instance.proposedJob;
        if (!job) return;

        setSpecifiedUnit(unit);
        const modifiedGCode = setGCodeUnit(job.gcode, unit);
        job.gcode = modifiedGCode;
        StateManager.propertyChanged(job, 'gcode');
        StateManager.propertyChanged(ConfigurationState.Instance, 'proposedJob');
    };

    return (
        <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            <ObserveState
                key="preview-gcode-stage"
                listenTo={ConfigurationState.Instance}
                properties={['proposedJob']}
                control={() => {
                    const job = ConfigurationState.Instance.proposedJob;

                    if (!job) {
                        // No job to preview - redirect back to selection
                        return (
                            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', flex: 1 }}>
                                <Typography variant="h6" color="text.secondary">
                                    No file selected. Please go back and select a file.
                                </Typography>
                            </Box>
                        );
                    }

                    return (
                        <ObserveState
                            key="preview-gcode-job-content"
                            listenTo={job}
                            properties={['gcode']}
                            control={() => (
                                <>
                                    {/* Info Bar - Top */}
                                    <Paper
                                        sx={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 2,
                                            p: 2,
                                            borderRadius: 0
                                        }}
                                    >
                                        <JobInfoHeader
                                            jobName={job.name}
                                            job={job}
                                            gcodeContent={job.gcode}
                                        />
                                    </Paper>

                                    {/* Tabbed Viewer Area */}
                                    <Box sx={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
                                        {/* Tabs */}
                                        <Tabs
                                            value={viewerTab}
                                            onChange={(e, newValue) => setViewerTab(newValue)}
                                            sx={{
                                                borderBottom: 1,
                                                borderColor: 'divider',
                                                backgroundColor: colors.lightBackgroundColor
                                            }}
                                        >
                                            <Tab label="3D Viewer" />
                                            <Tab label="G-Code" />
                                        </Tabs>

                                        {/* Tab Content */}
                                        <Box sx={{ flex: 1, minHeight: 0, position: 'relative' }}>
                                            {viewerTab === 0 && (
                                                <>
                                                    {!originallySpecified && (
                                                        <Box
                                                            sx={{
                                                                position: 'absolute',
                                                                top: 16,
                                                                left: 16,
                                                                zIndex: 10,
                                                                display: 'flex',
                                                                flexDirection: 'column',
                                                                alignItems: 'flex-start',
                                                                gap: 1,
                                                                backgroundColor: `${colors.lightTextColor}F2`,
                                                                p: 1.5,
                                                                borderRadius: 1,
                                                                boxShadow: 2
                                                            }}
                                                        >
                                                            {specifiedUnit === null && (
                                                                <Chip
                                                                    label="Units not specified"
                                                                    size="small"
                                                                    color="warning"
                                                                />
                                                            )}
                                                            <ButtonGroup size="small" variant="outlined">
                                                                <Button
                                                                    variant={specifiedUnit === 'inches' ? 'contained' : 'outlined'}
                                                                    onClick={() => handleUnitChange('inches')}
                                                                    sx={{
                                                                        minWidth: 70,
                                                                        backgroundColor: specifiedUnit === 'inches' ? colors.primaryColor : undefined,
                                                                        color: specifiedUnit === 'inches' ? colors.lightTextColor : undefined,
                                                                        '&:hover': {
                                                                            backgroundColor: specifiedUnit === 'inches' ? colors.primaryColor : undefined,
                                                                        }
                                                                    }}
                                                                >
                                                                    INCHES
                                                                </Button>
                                                                <Button
                                                                    variant={specifiedUnit === 'mm' ? 'contained' : 'outlined'}
                                                                    onClick={() => handleUnitChange('mm')}
                                                                    sx={{
                                                                        minWidth: 70,
                                                                        backgroundColor: specifiedUnit === 'mm' ? colors.primaryColor : undefined,
                                                                        color: specifiedUnit === 'mm' ? colors.lightTextColor : undefined,
                                                                        '&:hover': {
                                                                            backgroundColor: specifiedUnit === 'mm' ? colors.primaryColor : undefined,
                                                                        }
                                                                    }}
                                                                >
                                                                    MM
                                                                </Button>
                                                            </ButtonGroup>
                                                        </Box>
                                                    )}

                                                    <FullSizeCNCViewer
                                                        simulatorViewData={simulatorViewData}
                                                        machineState={machineState}
                                                        machineData={MachineData.Instance}
                                                        job={job}
                                                    />
                                                </>
                                            )}

                                            {viewerTab === 1 && (
                                                <Box sx={{ p: 2, height: '100%', display: 'flex', flexDirection: 'column' }}>
                                                    <GCodeEditor
                                                        value={job.gcode}
                                                        onChange={(newGcode) => {
                                                            job.gcode = newGcode;
                                                            StateManager.propertyChanged(job, 'gcode');
                                                        }}
                                                        fillHeight={true}
                                                    />
                                                </Box>
                                            )}
                                        </Box>
                                    </Box>
                                </>
                            )}
                        />
                    );
                }}
            />

            {/* Tools Dialog */}
            <Dialog
                open={showToolsDialog}
                onClose={() => setShowToolsDialog(false)}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.lightBackgroundColor,
                    borderBottom: `1px solid ${colors.borderColor}`
                }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <ToolIcon />
                        <Typography variant="h6">Required Tools</Typography>
                    </Box>
                    <IconButton onClick={() => setShowToolsDialog(false)} size="small">
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>
                <DialogContent sx={{ p: 0 }}>
                    <List>
                        {(() => {
                            const job = ConfigurationState.Instance.proposedJob;
                            const toolNumbers = job ? job.getToolNumbers() : [];

                            if (toolNumbers.length === 0) {
                                return (
                                    <ListItem>
                                        <ListItemText
                                            primary="No tools required"
                                            secondary="This G-code does not contain any tool changes"
                                        />
                                    </ListItem>
                                );
                            }

                            return toolNumbers.map((toolNumber: number, index: number) => {
                                const tool = toolLibrary.getToolByNumber(toolNumber);

                                return (
                                    <ListItem
                                        key={toolNumber}
                                        sx={{
                                            borderBottom: index < toolNumbers.length - 1 ? `1px solid ${colors.borderColor}` : 'none'
                                        }}
                                    >
                                        <ListItemIcon>
                                            <Box
                                                sx={{
                                                    width: 40,
                                                    height: 40,
                                                    borderRadius: '50%',
                                                    backgroundColor: colors.primaryColor,
                                                    color: colors.lightTextColor,
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    justifyContent: 'center',
                                                    fontWeight: 'bold'
                                                }}
                                            >
                                                T{toolNumber}
                                            </Box>
                                        </ListItemIcon>
                                        <ListItemText
                                            primary={
                                                <Typography variant="subtitle1" sx={{ fontWeight: 'bold' }}>
                                                    {tool ? tool.toolName : `Tool ${toolNumber}`}
                                                </Typography>
                                            }
                                            secondary={
                                                tool ? (
                                                    <>
                                                        <Typography variant="body2" component="span" display="block">
                                                            Diameter: {tool.cuttingDiameter.toFixed(3)}", Length: {tool.lengthBelowHolder.toFixed(3)}"
                                                        </Typography>
                                                        <Typography variant="body2" component="span" display="block" color="text.secondary">
                                                            {tool.cutterType}
                                                        </Typography>
                                                    </>
                                                ) : (
                                                    <Typography variant="body2" color="warning.main">
                                                        Tool not found in library
                                                    </Typography>
                                                )
                                            }
                                        />
                                    </ListItem>
                                );
                            });
                        })()}
                    </List>
                </DialogContent>
            </Dialog>
        </Box>
    );
}
