import { Box, Button, ButtonGroup, Menu, MenuItem } from '@mui/material';
import React from 'react';
import { NumberInput } from '../../../components/Common/NumberInput';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ObserveState } from '../../../utils/statemanager/ObserveState';
import { StateManager } from '../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../utils/storage/DataUtilities';
import { DataElement } from '../data/DataElement';
import { DataType, Declaration, Visibility } from '../data/Declaration';
import { IPLCElement, PLCRenderMode, PLCValidationIssue } from '../data/IPLCElement';
import { PLCProgramType, PLCSerializationHelper, PLCUtilities } from '../data/PLCUtilities';
import { StatementIdRegistry } from '../statements/StatementIdRegistry';
import { BasePLCPredicate } from './BasePLCPredicate';

/**
 * Assignment verbs - how the value is assigned
 */
export enum AssignmentVerb {
    Set = 'SET',                        // Set boolean to true: SET A
    Reset = 'RESET',                    // Reset boolean to false: RESET A
    EqualsValue = '= Value',            // Direct assignment from value: A = 123
    EqualsDataElement = '= Data Element', // Numeric data element assignment: WordVar = WordVar2
    EqualsMemoryBit = '= Memory Bit',   // Memory bit to memory bit: MemBit = MemBit2 (uses pre/post code)
    NotEqualsMemoryBit = '!= Memory Bit', // Inverted memory bit: MemBit = !MemBit2 (uses pre/post code)
}

/**
 * Assignment predicate - assigns a value to a data element using a verb operator
 */
export class AssignmentPredicate extends BasePLCPredicate {
    private _targetElement: DataElement | undefined;  // The element being assigned to
    private _verb: AssignmentVerb = AssignmentVerb.Set;
    private _sourceValue: number = 0;  // Value when using EqualsValue
    private _sourceElement: DataElement | undefined;  // Element when using EqualsDataElement

    constructor() {
        super();
        // Initialize with a target element that allows new and accepts any type
        this._targetElement = new DataElement();
        this._targetElement.allowNew = true;
        this._targetElement.needsWrite = true;  // Target must be writable
        this._targetElement.setParentElement(this);
        // Initialize source element for EqualsDataElement - cannot create new variables here
        this._sourceElement = new DataElement();
        this._sourceElement.allowNew = false;  // Source must be existing variable
        this._sourceElement.needsWrite = false;  // Source is read-only
        this._sourceElement.setParentElement(this);
        // Default verb is Set (for boolean types)
        this._verb = AssignmentVerb.Set;
    }

    /**
     * Get the target data element
     */
    public get targetElement(): DataElement | undefined {
        return this._targetElement;
    }

    /**
     * Set the target data element
     */
    public set targetElement(value: DataElement | undefined) {
        this._targetElement = value;
        if (this._targetElement) {
            this._targetElement.allowNew = true;
            this._targetElement.needsWrite = true;  // Target must be writable
            this._targetElement.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'targetElement');
        // Invalidate cache since this might create a new declaration
        PLCUtilities.invalidateProgramCache();
    }

    /**
     * Get the assignment verb
     */
    public get verb(): AssignmentVerb {
        return this._verb;
    }

    /**
     * Get the inline comment for this predicate based on the target declaration
     */
    public getComment(): string {
        // If there's a manual comment, use that
        const manualComment = super.getComment();
        if (manualComment) {
            return manualComment;
        }

        // Get the declaration - either direct reference or from cache/lookup
        let decl: Declaration | undefined = undefined;

        if (this._targetElement) {
            // First try direct declaration reference
            decl = this._targetElement.declaration;

            // If no direct reference, check the cached lookup declaration
            if (!decl && this._targetElement.declarationName) {
                // Use getUsedDeclarations which handles caching and lookup
                const usedDecls = this._targetElement.getUsedDeclarations();
                if (usedDecls.length > 0) {
                    decl = usedDecls[0];
                }
            }
        }

        // Generate comment from declaration metadata
        if (decl) {
            // Generate action-based comment based on verb action
            const varName = decl.name;
            const description = decl.description && decl.description.trim() ? ` (${decl.description})` : '';

            if (this._verb === AssignmentVerb.Set) {
                // Use isSetText to show what state we're setting to - but only if it's meaningful
                const setState = decl.isSetText || 'active';
                // Don't generate redundant comments like "OUTPUT_M set to Set"
                if (setState.toLowerCase() === 'set') {
                    return ''; // No comment for generic "Set"
                }
                return `${varName} set to ${setState}`;
            } else if (this._verb === AssignmentVerb.Reset) {
                // Use isResetText to show what state we're resetting to - but only if it's meaningful
                const resetState = decl.isResetText || 'inactive';
                // Don't generate redundant comments like "OUTPUT_M set to Reset"
                if (resetState.toLowerCase() === 'reset') {
                    return ''; // No comment for generic "Reset"
                }
                return `${varName} set to ${resetState}`;
            } else if (this._verb === AssignmentVerb.EqualsValue) {
                return `${varName} = ${this._sourceValue}${description}`;
            } else if (this._verb === AssignmentVerb.EqualsDataElement) {
                const sourceName = this._sourceElement?.declaration?.name || this._sourceElement?.declarationName || 'value';
                return `${varName} = ${sourceName}${description}`;
            }
        }

        return '';
    }

    /**
     * Get all data elements used by this predicate
     */
    public getDataElements(): DataElement[] {
        const elements: DataElement[] = [];
        if (this._targetElement) {
            elements.push(this._targetElement);
        }
        if (this._sourceElement) {
            elements.push(this._sourceElement);
        }
        return elements;
    }



    /**
     */
    public set verb(value: AssignmentVerb) {
        this._verb = value;
        StateManager.propertyChanged(this, 'verb');
    }

    /**
     * Check if this verb uses the memory bit assignment pattern (helper bit with pre/post logic)
     */
    private isMemoryBitAssignment(): boolean {
        return this._verb === AssignmentVerb.EqualsMemoryBit || this._verb === AssignmentVerb.NotEqualsMemoryBit;
    }

    /**
     * Get the source value (for EqualsValue)
     */
    public get sourceValue(): number {
        return this._sourceValue;
    }

    /**
     * Set the source value (for EqualsValue)
     */
    public set sourceValue(value: number) {
        this._sourceValue = value;
        StateManager.propertyChanged(this, 'sourceValue');
    }

    /**
     * Get the source data element (for EqualsDataElement)
     */
    public get sourceElement(): DataElement | undefined {
        return this._sourceElement;
    }

    /**
     * Set the source data element (for EqualsDataElement)
     */
    public set sourceElement(value: DataElement | undefined) {
        this._sourceElement = value;
        if (this._sourceElement) {
            this._sourceElement.allowNew = false;  // Source must be existing variable
            this._sourceElement.needsWrite = false;  // Source is read-only
            this._sourceElement.setParentElement(this);
        }
        StateManager.propertyChanged(this, 'sourceElement');
        // Invalidate cache since this might affect declarations
        PLCUtilities.invalidateProgramCache();
    }

    /**
     * Render the predicate to JSX
     * @param mode Optional rendering mode (Edit, ReadOnly, or Disabled)
     */
    public render(mode: PLCRenderMode, targetProgramType: PLCProgramType): React.ReactNode {
        return <AssignmentPredicateRenderer predicate={this} renderMode={mode} targetProgramType={targetProgramType} />;
    }

    /**
     * Get declarations that are used/referenced by this predicate
     */
    public getUsedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];

        // Target element can be used or added
        if (this._targetElement) {
            declarations.push(...this._targetElement.getUsedDeclarations());
        }

        // Source element (if using data element verbs) is always used
        if ((this._verb === AssignmentVerb.EqualsDataElement ||
            this._verb === AssignmentVerb.EqualsMemoryBit ||
            this._verb === AssignmentVerb.NotEqualsMemoryBit) && this._sourceElement) {
            declarations.push(...this._sourceElement.getUsedDeclarations());
        }

        return declarations;
    }

    /**
     * Get declarations that are added/defined by this predicate
     */
    public getAddedDeclarations(): Declaration[] {
        const declarations: Declaration[] = [];

        // Target element can be used or added
        if (this._targetElement) {
            const targetDecls = this._targetElement.getAddedDeclarations();
            declarations.push(...targetDecls);
        }

        // Source element can also define new declarations
        if ((this._verb === AssignmentVerb.EqualsDataElement ||
            this._verb === AssignmentVerb.EqualsMemoryBit ||
            this._verb === AssignmentVerb.NotEqualsMemoryBit) && this._sourceElement) {
            const sourceDecls = this._sourceElement.getAddedDeclarations();
            declarations.push(...sourceDecls);
        }

        // Memory bit assignments need a helper bit for the pre/post logic pattern
        if (this.isMemoryBitAssignment()) {
            // Create helper bit declaration
            const predicateId = StatementIdRegistry.getId(this);
            const shouldSetBitName = `ShouldSet${predicateId}_M`;


            const helperBit = new Declaration(shouldSetBitName);
            helperBit.dataType = DataType.MemoryBit;
            helperBit.visibility = Visibility.Hidden;
            helperBit.description = 'Helper bit for assignment predicate';
            // helperBit.isSystem = true;

            declarations.push(helperBit);

        }

        return declarations;
    }

    /**
     * Get the PLC logic code for this predicate
     */
    public getPLCLogic(): string[] {
        if (!this._targetElement) {
            return [];
        }
        const targetName = this._targetElement.effectiveName || 'unknown';

        // For memory-bit assignment verbs, use helper bit pattern
        if (this.isMemoryBitAssignment()) {
            // Use helper bit pattern - actual logic is in getSecondaryPLCLogic()
            const predicateId = StatementIdRegistry.getId(this);
            const shouldSetBitName = `ShouldSet${predicateId}_M`;
            return [`SET ${shouldSetBitName}`];
        }

        // Generate standard assignment logic
        if (this._verb === AssignmentVerb.Set) {
            return [`SET ${targetName}`];
        } else if (this._verb === AssignmentVerb.Reset) {
            return [`RST ${targetName}`];
        } else if (this._verb === AssignmentVerb.EqualsValue) {
            // Numeric value assignment: A = 123
            // Convert number to string for PLC output
            const value = String(this._sourceValue);
            return [`${targetName} = ${value}`];
        } else if (this._verb === AssignmentVerb.EqualsDataElement) {
            // Numeric data element assignment: A = B
            const sourceName = this._sourceElement?.effectiveName || '<source>';
            return [`${targetName} = ${sourceName}`];
        } else {
            // Fallback for unknown verb
            return [`${targetName} = <value>`];
        }
    }

    /**
     * Get pre-PLC logic (reset helper bit for memory-bit-to-memory-bit assignments)
     */
    public getPrePLCLogic(): string[] {
        // Only generate pre-code for memory-bit assignment verbs
        if (!this.isMemoryBitAssignment()) {
            return [];
        }

        const predicateId = StatementIdRegistry.getId(this);
        const shouldSetBitName = `ShouldSet${predicateId}_M`;

        // Reset the should-set bit at the start of each scan
        return [`; Assignment predicate logic - control variable`, `IF 1==1 THEN RST ${shouldSetBitName}`, ''];
    }

    /**
     * Get secondary PLC logic (the actual SET/RST execution for memory-bit-to-memory-bit assignments)
     */
    public getSecondaryPLCLogic(): string[] {
        // Only generate post-code for memory-bit assignment verbs
        if (!this.isMemoryBitAssignment()) {
            return [];
        }

        const predicateId = StatementIdRegistry.getId(this);
        const shouldSetBitName = `ShouldSet${predicateId}_M`;
        const targetName = this._targetElement!.effectiveName || 'unknown';
        const sourceName = this._sourceElement!.effectiveName || 'unknown';

        const logic: string[] = [];

        logic.push('');
        logic.push('; Assignment predicate logic');

        if (this._verb === AssignmentVerb.EqualsMemoryBit) {
            // Standard assignment: target = source
            // If should-set bit is on AND source is on, turn target on
            logic.push(`IF ${shouldSetBitName} && ${sourceName} THEN SET ${targetName}`);
            // If should-set bit is on AND source is off, turn target off
            logic.push(`IF ${shouldSetBitName} && !${sourceName} THEN RST ${targetName}`);
        } else if (this._verb === AssignmentVerb.NotEqualsMemoryBit) {
            // Inverted assignment: target = !source
            // If should-set bit is on AND source is off, turn target on
            logic.push(`IF ${shouldSetBitName} && !${sourceName} THEN SET ${targetName}`);
            // If should-set bit is on AND source is on, turn target off
            logic.push(`IF ${shouldSetBitName} && ${sourceName} THEN RST ${targetName}`);
        }

        return logic;
    }

    /**
     * Get validation issues for this predicate
     */
    public getValidationIssues(): PLCValidationIssue[] {
        const issues: PLCValidationIssue[] = [];
        if (!this._targetElement) {
            issues.push(new PLCValidationIssue(this, 'Assignment predicate requires a target element'));
        } else {
            const targetIssues = this._targetElement.getValidationIssues();
            targetIssues.forEach(issue => {
                issues.push(new PLCValidationIssue(issue.element, `[Assignment target] ${issue.message}`));
            });
        }
        return issues;
    }

    /**
     * Get available verbs based on target element type
     */
    public getAvailableVerbs(): AssignmentVerb[] {
        if (!this._targetElement) {
            return [];
        }

        // Get the data type from the declaration if available
        let dataType = this._targetElement.declaration?.dataType;

        // If no declaration object but we have a name, look it up
        if (!dataType && this._targetElement.declarationName) {
            const program = this._targetElement.getPLCProgram();
            if (program) {
                const declaration = PLCUtilities.getDeclarationByName(program, this._targetElement.declarationName);
                dataType = declaration?.dataType;
            }
        }

        // Fall back to requiresType
        if (!dataType) {
            dataType = this._targetElement.requiresType;
        }

        // If still no type, return empty array to show message
        if (!dataType) {
            return [];
        }

        // Use PLCUtilities to check type categories
        if (PLCUtilities.isBooleanType(dataType)) {
            // Boolean types: SET, RESET, and memory-bit assignment options
            const verbs = [AssignmentVerb.Set, AssignmentVerb.Reset];

            // If both target and source are memory bits, add memory bit verbs
            // These use the pre/post code pattern
            if (dataType === DataType.MemoryBit && this._sourceElement) {
                const sourceType = this._sourceElement.declaration?.dataType;
                if (sourceType === DataType.MemoryBit) {
                    verbs.push(AssignmentVerb.EqualsMemoryBit, AssignmentVerb.NotEqualsMemoryBit);
                }
            }

            return verbs;
        } else if (PLCUtilities.isNumericType(dataType)) {
            // Numeric types: equals value or equals data element
            return [AssignmentVerb.EqualsValue, AssignmentVerb.EqualsDataElement];
        } else {
            // Unknown type - return empty array to show message
            return [];
        }
    }

    /**
     * Validate the predicate
     */
    public validate(): string | undefined {
        if (!this._targetElement) {
            return 'Assignment predicate requires a target element';
        }
        return undefined;
    }

    /**
     * Clone the predicate
     */
    public clone(): AssignmentPredicate {
        const cloned = new AssignmentPredicate();
        if (this._targetElement) {
            const newElement = new DataElement();
            newElement.fromJSON(this._targetElement.toJSON());
            cloned.targetElement = newElement;
        }
        cloned.verb = this._verb;
        return cloned;
    }

    /**
     * Override setParentElement to cascade to child DataElements
     */
    public setParentElement(parent: IPLCElement | undefined): void {
        super.setParentElement(parent);
        // Cascade to child elements
        if (this._targetElement) {
            this._targetElement.setParentElement(this);
        }
        if (this._sourceElement) {
            this._sourceElement.setParentElement(this);
        }
    }

    /**
     * Get a short, single-line description of this predicate for display in tree views
     * Examples: "Set DustCollector", "Reset safety_gate", "spindle_speed = 1000"
     * @returns A human-readable summary of the assignment action
     */
    public getShortDescription(): string {
        const targetName = this._targetElement?.declarationName || '(unknown)';

        switch (this._verb) {
            case AssignmentVerb.Set:
                return `Set ${targetName}`;
            case AssignmentVerb.Reset:
                return `Reset ${targetName}`;
            case AssignmentVerb.EqualsValue:
                return `${targetName} = ${this._sourceValue}`;
            case AssignmentVerb.EqualsDataElement:
            case AssignmentVerb.EqualsMemoryBit:
                const sourceName = this._sourceElement?.declarationName || '(unknown)';
                return `${targetName} = ${sourceName}`;
            case AssignmentVerb.NotEqualsMemoryBit:
                const invertedSource = this._sourceElement?.declarationName || '(unknown)';
                return `${targetName} = !${invertedSource}`;
            default:
                return `${targetName} = ...`;
        }
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        const baseData = PLCSerializationHelper.getStorageData(this, ['_targetElement', '_sourceElement']);
        return {
            type: 'AssignmentPredicate',
            ...baseData,
            targetElement: this._targetElement ? this._targetElement.toJSON() : null,
            sourceElement: this._sourceElement ? this._sourceElement.toJSON() : null,
            verb: this._verb,
            sourceValue: this._sourceValue
        };
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        if (!data) return;

        // Load target element - support both underscore and non-underscore formats for backward compatibility
        const targetElementData = data.targetElement || data._targetElement;
        if (targetElementData) {
            this._targetElement = new DataElement();
            this._targetElement.fromJSON(targetElementData);
            this._targetElement.setParentElement(this);
        }

        // Load source element - support both formats
        const sourceElementData = data.sourceElement || data._sourceElement;
        if (sourceElementData) {
            this._sourceElement = new DataElement();
            this._sourceElement.fromJSON(sourceElementData);
            this._sourceElement.setParentElement(this);
        }

        // Load verb and source value - support both formats
        const verbData = data.verb !== undefined ? data.verb : data._verb;
        if (verbData !== undefined) {
            this._verb = verbData;
        }
        const sourceValueData = data.sourceValue !== undefined ? data.sourceValue : data._sourceValue;
        if (sourceValueData !== undefined) {
            // Parse as number, handling both string and number inputs
            this._sourceValue = typeof sourceValueData === 'number' ? sourceValueData : parseFloat(sourceValueData) || 0;
        }

        // MIGRATION: Convert old EqualsDataElement verb to EqualsMemoryBit when both target and source are memory bits
        // This handles predicates created before we split the verb types
        if (this._verb === AssignmentVerb.EqualsDataElement &&
            this._targetElement && this._sourceElement &&
            this._targetElement.declaration?.dataType === DataType.MemoryBit &&
            this._sourceElement.declaration?.dataType === DataType.MemoryBit) {
            this._verb = AssignmentVerb.EqualsMemoryBit;
        }

        // Load remaining properties
        DataUtilities.loadStorageData(this, data, ['_targetElement', 'targetElement', '_sourceElement', 'sourceElement', '_verb', 'verb', '_sourceValue', 'sourceValue']);
    }
}

/**
 * Functional component wrapper for AssignmentPredicate rendering to allow hooks
 */
function AssignmentPredicateRenderer({ predicate, renderMode, targetProgramType }: { predicate: AssignmentPredicate; renderMode?: PLCRenderMode; targetProgramType: PLCProgramType }) {
    const [verbMenuAnchor, setVerbMenuAnchor] = React.useState<null | HTMLElement>(null);
    const effectiveRenderMode = renderMode || PLCRenderMode.Edit;
    const isReadOnly = effectiveRenderMode === PLCRenderMode.ReadOnly;
    const colors = ConfigurationDataColors.Instance;

    // Check if this predicate should be disabled:
    // 1. If renderMode is Disabled (parent condition is disabled), OR
    // 2. If predicate itself is disabled due to unavailable declarations
    const isPredicateDisabled = effectiveRenderMode === PLCRenderMode.Disabled || predicate.isDisabled(PLCRenderMode.Edit, targetProgramType);
    const disabledStyle = isPredicateDisabled ? {
        opacity: 0.5,
        textDecoration: 'line-through',
        color: colors.mutedTextColor
    } : {};

    return (
        <ObserveState
            key="assignment-predicate-render"
            profilerName="AssignmentPredicate-render"
            listenTo={predicate.targetElement}
            properties={['declarationName', 'declaration']}

            control={() => {
                const availableVerbs = predicate.getAvailableVerbs();
                const isBooleanType = availableVerbs.includes(AssignmentVerb.Set) && availableVerbs.includes(AssignmentVerb.Reset);
                const isEqualsType = availableVerbs.includes(AssignmentVerb.EqualsValue);
                const hasTargetElement = predicate.targetElement?.declarationName || predicate.targetElement?.declaration;

                // Get the declaration for display text
                const program = predicate.targetElement?.getPLCProgram();
                const declaration = predicate.targetElement?.declaration ||
                    (predicate.targetElement?.declarationName && program ?
                        PLCUtilities.getDeclarationByName(program, predicate.targetElement.declarationName) :
                        undefined);

                // Get friendly display text for SET/RESET based on data type (isCondition = false)
                const setDisplayText = PLCUtilities.getDataElementDisplayText(declaration, program, true, false) || 'SET';
                const resetDisplayText = PLCUtilities.getDataElementDisplayText(declaration, program, false, false) || 'RESET';

                return (
                    <ObserveState
                        key="assignment-predicate-verb"
                        profilerName="AssignmentPredicate-verb"
                        listenTo={predicate}
                        properties={['verb', 'sourceValue']}

                        control={() => (
                            <Box sx={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: 1,
                                minHeight: '28px',
                                ...disabledStyle
                            }}>
                                <span style={{ lineHeight: '28px' }}>Set</span>
                                {predicate.targetElement?.render(effectiveRenderMode, targetProgramType)}
                                {!hasTargetElement ? (
                                    <span style={{
                                        color: colors.mutedTextColor,
                                        fontStyle: 'italic',
                                        lineHeight: '28px',
                                        display: 'inline-block',
                                        verticalAlign: 'middle'
                                    }}>
                                        Pick or create data element
                                    </span>
                                ) : availableVerbs.length === 0 ? (
                                    <span style={{
                                        color: ConfigurationDataColors.Instance.errorColor,
                                        fontStyle: 'italic',
                                        lineHeight: '28px',
                                        display: 'inline-block',
                                        verticalAlign: 'middle'
                                    }}>
                                        Unknown data type - cannot determine operation
                                    </span>
                                ) : isBooleanType ? (
                                    <>
                                        <span style={{ lineHeight: '28px' }}>to</span>
                                        <Button
                                            onClick={isReadOnly ? undefined : (e) => setVerbMenuAnchor(e.currentTarget)}
                                            disabled={isReadOnly}
                                            size="small"
                                            sx={{
                                                fontFamily: 'monospace',
                                                fontSize: '12px',
                                                minWidth: 'auto',
                                                px: 1.5,
                                                py: 0.5,
                                                textTransform: 'uppercase',
                                                backgroundColor: predicate.verb === AssignmentVerb.Set ? colors.successColor :
                                                    predicate.verb === AssignmentVerb.Reset ? colors.errorColor :
                                                        undefined,
                                                color: (predicate.verb === AssignmentVerb.EqualsMemoryBit ||
                                                    predicate.verb === AssignmentVerb.NotEqualsMemoryBit) ? colors.mutedTextColor : colors.lightTextColor,
                                                border: (predicate.verb === AssignmentVerb.EqualsMemoryBit ||
                                                    predicate.verb === AssignmentVerb.NotEqualsMemoryBit) ? `1px solid ${colors.mutedTextColor}` : 'none',
                                                '&:hover': {
                                                    opacity: 0.9
                                                }
                                            }}
                                        >
                                            {predicate.verb === AssignmentVerb.Set ? setDisplayText :
                                                predicate.verb === AssignmentVerb.Reset ? resetDisplayText :
                                                    predicate.verb}
                                        </Button>
                                        <Menu
                                            anchorEl={verbMenuAnchor}
                                            open={Boolean(verbMenuAnchor)}
                                            onClose={() => setVerbMenuAnchor(null)}
                                        >
                                            <MenuItem
                                                onClick={() => {
                                                    predicate.verb = AssignmentVerb.Set;
                                                    setVerbMenuAnchor(null);
                                                }}
                                            >
                                                {setDisplayText}
                                            </MenuItem>
                                            <MenuItem
                                                onClick={() => {
                                                    predicate.verb = AssignmentVerb.Reset;
                                                    setVerbMenuAnchor(null);
                                                }}
                                            >
                                                {resetDisplayText}
                                            </MenuItem>
                                            {/* Show memory-bit-specific options when target is memory bit */}
                                            {(() => {
                                                // Check target type - look at declaration or look it up by name
                                                let targetType = predicate.targetElement?.declaration?.dataType;

                                                // If no declaration object, try to look it up by name
                                                if (!targetType && predicate.targetElement?.declarationName) {
                                                    const program = predicate.targetElement.getPLCProgram();
                                                    if (program) {
                                                        const decl = PLCUtilities.getDeclarationByName(program, predicate.targetElement.declarationName);
                                                        targetType = decl?.dataType;
                                                    }
                                                }

                                                const isTargetMemoryBit = targetType === DataType.MemoryBit;

                                                if (isTargetMemoryBit) {
                                                    return (
                                                        <>
                                                            <MenuItem
                                                                onClick={() => {
                                                                    predicate.verb = AssignmentVerb.EqualsMemoryBit;
                                                                    if (predicate.sourceElement) {
                                                                        predicate.sourceElement.requiresType = DataType.MemoryBit;
                                                                    }
                                                                    setVerbMenuAnchor(null);
                                                                }}
                                                            >
                                                                {AssignmentVerb.EqualsMemoryBit}
                                                            </MenuItem>
                                                            <MenuItem
                                                                onClick={() => {
                                                                    predicate.verb = AssignmentVerb.NotEqualsMemoryBit;
                                                                    if (predicate.sourceElement) {
                                                                        predicate.sourceElement.requiresType = DataType.MemoryBit;
                                                                    }
                                                                    setVerbMenuAnchor(null);
                                                                }}
                                                            >
                                                                {AssignmentVerb.NotEqualsMemoryBit}
                                                            </MenuItem>
                                                        </>
                                                    );
                                                }
                                                return null;
                                            })()}
                                        </Menu>
                                        {/* Show filtered data element picker for memory bit verbs on same line */}
                                        {(predicate.verb === AssignmentVerb.EqualsMemoryBit ||
                                            predicate.verb === AssignmentVerb.NotEqualsMemoryBit) && (
                                                <>
                                                    {predicate.sourceElement?.render(effectiveRenderMode, targetProgramType)}
                                                    {!predicate.sourceElement?.declarationName && !predicate.sourceElement?.declaration && (
                                                        <span style={{ color: colors.mutedTextColor, fontStyle: 'italic', marginLeft: 8 }}>
                                                            Pick value to assign
                                                        </span>
                                                    )}
                                                </>
                                            )}
                                    </>
                                ) : isEqualsType ? (
                                    <>
                                        <span>to</span>
                                        <ButtonGroup
                                            size="small"
                                            disabled={isReadOnly}
                                        >
                                            <Button
                                                variant={predicate.verb === AssignmentVerb.EqualsValue ? 'contained' : 'outlined'}
                                                onClick={() => predicate.verb = AssignmentVerb.EqualsValue}
                                                sx={{
                                                    fontFamily: 'monospace',
                                                    fontSize: '12px',
                                                    minWidth: 'auto',
                                                    px: 1.5,
                                                    py: 0.5,
                                                    textTransform: 'uppercase',
                                                    backgroundColor: predicate.verb === AssignmentVerb.EqualsValue ? colors.successColor : undefined,
                                                    color: predicate.verb === AssignmentVerb.EqualsValue ? colors.lightTextColor : undefined,
                                                    border: predicate.verb === AssignmentVerb.EqualsValue ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                                    '&:hover': {
                                                        opacity: 0.9
                                                    }
                                                }}
                                            >
                                                Value
                                            </Button>
                                            <Button
                                                variant={predicate.verb === AssignmentVerb.EqualsDataElement ? 'contained' : 'outlined'}
                                                onClick={() => predicate.verb = AssignmentVerb.EqualsDataElement}
                                                sx={{
                                                    fontFamily: 'monospace',
                                                    fontSize: '12px',
                                                    minWidth: 'auto',
                                                    px: 1.5,
                                                    py: 0.5,
                                                    textTransform: 'uppercase',
                                                    backgroundColor: predicate.verb === AssignmentVerb.EqualsDataElement ? colors.successColor : undefined,
                                                    color: predicate.verb === AssignmentVerb.EqualsDataElement ? colors.lightTextColor : undefined,
                                                    border: predicate.verb === AssignmentVerb.EqualsDataElement ? 'none' : `1px solid ${colors.mutedTextColor}`,
                                                    '&:hover': {
                                                        opacity: 0.9
                                                    }
                                                }}
                                            >
                                                Data Element
                                            </Button>
                                        </ButtonGroup>
                                        {predicate.verb === AssignmentVerb.EqualsValue ? (
                                            <NumberInput
                                                value={predicate.sourceValue}
                                                onChange={(value) => {
                                                    predicate.sourceValue = value;
                                                    StateManager.propertyChanged(predicate, 'sourceValue');
                                                }}
                                                disabled={isReadOnly}
                                                showHelperText={false}
                                                size="small"
                                                sx={{
                                                    width: 140,
                                                    '& .MuiOutlinedInput-root': {
                                                        height: '28px'
                                                    }
                                                }}
                                            />
                                        ) : (
                                            predicate.sourceElement?.render(effectiveRenderMode, targetProgramType)
                                        )}
                                    </>
                                ) : (
                                    <span>{predicate.verb}</span>
                                )}
                            </Box>
                        )}
                    />
                );
            }}
        />
    );
}
