import React, { ReactNode } from 'react';
import { Tool } from '../../data/Common/Tool';
import { ToolLibrary } from '../../data/Common/ToolLibrary';
import { ConfigurationData } from '../../data/ConfigurationData';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { Machine } from '../../machine/Machine';
import { ObserveState } from '../statemanager/ObserveState';
import { ActionBus, IAction } from './ActionBus';

export class ToolChangeAction implements IAction {
    public type = 'ToolChange';
    public id: string = `tool-change-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    public singleAction = true; // Only one tool change action allowed at a time
    public targetToolNumber: number;
    public targetTool: Tool | null;
    public _timeoutId?: number;
    public _startTime: number = Date.now();

    constructor(targetToolNumber: number) {
        this.targetToolNumber = targetToolNumber;
        // Find the tool in the library
        this.targetTool = ToolLibrary.Instance.tools.find(tool => tool.toolNumber === targetToolNumber) || null;
    }

    canCombine(other: IAction): boolean {
        if (!(other instanceof ToolChangeAction)) {
            return false; // Cannot combine with non-ToolChangeAction
        }
        return true; // Can combine with other ToolChangeActions
    }

    combineWith(other: IAction): IAction {
        if (other instanceof ToolChangeAction) {
            // Cancel this existing action's timeout to prevent it from executing
            if (this._timeoutId) {
                clearTimeout(this._timeoutId);
                this._timeoutId = undefined;
            }

            // Return the new action (take the most recent target tool)
            return other;
        }
        return this;
    }

    getNotificationUI(): ReactNode {
        const delayTime = ConfigurationData.Instance.toolChangeDelay;
        if (delayTime <= 0) return null; // No UI if no delay

        return (
            <ToolChangeActionUI
                key={this.id}
                action={this}
                delayTime={delayTime}
                startTime={this._startTime}
            />
        );
    }

    execute(): void {
        const delayTime = ConfigurationData.Instance.toolChangeDelay;

        if (delayTime > 0) {
            // Schedule the tool change with delay
            this._timeoutId = window.setTimeout(() => {
                this.performToolChange().finally(() => {
                    ActionBus.Instance.completeAction(this);
                });
            }, delayTime);
        } else {
            // Execute immediately if no delay
            this.performToolChange().finally(() => {
                ActionBus.Instance.completeAction(this);
            });
        }
    }

    cancel(): void {
        if (this._timeoutId) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }

        ActionBus.Instance.completeAction(this);
    }

    executeImmediate(): void {
        // Clear any existing timeout
        if (this._timeoutId) {
            clearTimeout(this._timeoutId);
            this._timeoutId = undefined;
        }

        // Execute the tool change immediately
        this.performToolChange();
    }

    public async performToolChange(): Promise<void> {
        // Call the IMachine interface for proper tool change workflow
        // This will trigger the preview dialog if config.previewGCode is enabled
        const machine = Machine.getInstance();
        await machine.system.changeTool(this.targetToolNumber);
    }
}

// UI Component for tool change feedback
interface ToolChangeActionUIProps {
    action: ToolChangeAction;
    delayTime: number;
    startTime: number;
}

function ToolChangeActionUI({ action, delayTime, startTime }: ToolChangeActionUIProps): ReactNode {
    // Don't use useState for timeRemaining - calculate it directly each render
    const [, forceUpdate] = React.useReducer(x => x + 1, 0);
    const [isPaused, setIsPaused] = React.useState(false);
    const [remainingTimeWhenPaused, setRemainingTimeWhenPaused] = React.useState<number | null>(null);
    const [isExecuting, setIsExecuting] = React.useState(false); // Prevent multiple executions

    // Get the current configuration delay for tool changes
    const getCurrentConfigDelay = () => {
        return ConfigurationData.Instance.toolChangeDelay;
    };

    const [adjustedDelayTime, setAdjustedDelayTime] = React.useState(getCurrentConfigDelay());

    // Calculate remaining time based on current props and pause state
    const now = Date.now();
    let elapsed: number;
    let timeRemaining: number;

    if (isPaused && remainingTimeWhenPaused !== null) {
        // Use the saved remaining time when paused
        timeRemaining = remainingTimeWhenPaused;
        elapsed = adjustedDelayTime - timeRemaining;
    } else {
        // Normal time calculation
        elapsed = now - startTime;
        timeRemaining = Math.max(0, adjustedDelayTime - elapsed);
    }

    // Use refs to store stable values that won't trigger effect re-runs
    const delayTimeRef = React.useRef(adjustedDelayTime);
    const startTimeRef = React.useRef(startTime);

    // Update refs when values change
    React.useEffect(() => {
        delayTimeRef.current = adjustedDelayTime;
        startTimeRef.current = startTime;
    }, [adjustedDelayTime, startTime]);

    // Handle execute now button
    const handleExecuteNow = React.useCallback(() => {
        // Prevent multiple executions
        if (isExecuting) {
            return;
        }
        
        setIsExecuting(true);
        
        // Clear existing timeout
        if (action._timeoutId) {
            clearTimeout(action._timeoutId);
            action._timeoutId = undefined;
        }

        // Execute immediately and complete action after tool change finishes
        action.performToolChange().finally(() => {
            ActionBus.Instance.completeAction(action);
        });
    }, [action, isExecuting]);

    React.useEffect(() => {
        const interval = setInterval(() => {
            if (!isPaused && !isExecuting) {
                const currentTimeRemaining = Math.max(0, adjustedDelayTime - (Date.now() - startTime));

                // Check if time has expired and execute the action
                if (currentTimeRemaining <= 0) {
                    handleExecuteNow();
                } else {
                    forceUpdate(); // Force component to re-render and recalculate timeRemaining
                }
            }
        }, 100); // Update every 100ms for smooth countdown

        return () => {
            clearInterval(interval);
        };
    }, [action.id, isPaused, isExecuting, adjustedDelayTime, startTime, handleExecuteNow]); // Reset interval when these change

    // Handle mouse enter/leave for pause functionality
    const handleMouseEnter = () => {
        if (!isPaused) {
            // Clear the existing timeout to actually pause the action
            if (action._timeoutId) {
                clearTimeout(action._timeoutId);
                action._timeoutId = undefined;
            }

            // Calculate and save remaining time when pausing
            const currentRemaining = Math.max(0, adjustedDelayTime - (Date.now() - startTime));
            setRemainingTimeWhenPaused(currentRemaining);
            setIsPaused(true);
        }
    };

    const handleMouseLeave = () => {
        if (isPaused && remainingTimeWhenPaused !== null) {
            // Resume the action with the remaining time
            if (remainingTimeWhenPaused > 0) {
                // Update start time to account for the pause
                action._startTime = Date.now() - (adjustedDelayTime - remainingTimeWhenPaused);

                // Restart the timeout with remaining time
                action._timeoutId = window.setTimeout(() => {
                    handleExecuteNow();
                }, remainingTimeWhenPaused);
            }

            setIsPaused(false);
            setRemainingTimeWhenPaused(null);
        }
    };

    // Handle delay adjustment - this updates the configuration for tool changes
    const handleDelayChange = (event: React.ChangeEvent<HTMLInputElement>) => {
        const newDelaySeconds = parseInt(event.target.value);
        const newDelay = newDelaySeconds * 1000; // Convert seconds to milliseconds

        // Update the configuration setting for tool change delay
        ConfigurationData.Instance.toolChangeDelay = newDelay;

        // Update the current action's adjusted delay time for UI display
        setAdjustedDelayTime(newDelay);

        // Clear existing timeout
        if (action._timeoutId) {
            clearTimeout(action._timeoutId);
            action._timeoutId = undefined;
        }

        if (newDelay > 0) {
            if (isPaused) {
                // If paused, just update the remaining time
                setRemainingTimeWhenPaused(newDelay);
            } else {
                // If not paused, restart with new timing
                const currentElapsed = Date.now() - startTime;
                const newTimeRemaining = Math.max(0, newDelay - currentElapsed);

                if (newTimeRemaining > 0) {
                    // Update start time to match new delay
                    action._startTime = Date.now() - (newDelay - newTimeRemaining);

                    action._timeoutId = window.setTimeout(() => {
                        handleExecuteNow();
                    }, newTimeRemaining);
                } else {
                    handleExecuteNow(); // Execute immediately if no time remaining
                }
            }
        }
    };

    const progressPercent = Math.max(0, (timeRemaining / adjustedDelayTime) * 100);
    const secondsRemaining = Math.ceil(timeRemaining / 1000);
    const delaySeconds = Math.round(adjustedDelayTime / 1000);

    // Don't show UI if delay is set to 0 or action is executing
    if (adjustedDelayTime <= 0 || isExecuting) {
        return null;
    }

    return (
        <ObserveState
            key={`tool-change-action-${action.id}`}
            listenTo={ConfigurationData.Instance}
            control={() => (
                <div
                    onMouseEnter={handleMouseEnter}
                    onMouseLeave={handleMouseLeave}
                    style={{
                        // Note: position fixed removed - let NotificationArea handle positioning
                        backgroundColor: isPaused ? ConfigurationDataColors.Instance.darkOverlay : ConfigurationDataColors.Instance.modalBackdrop,
                        color: ConfigurationDataColors.Instance.lightTextColor,
                        padding: '12px 16px',
                        borderRadius: '8px',
                        minWidth: '250px',
                        // Note: z-index removed - let NotificationArea handle stacking via ordinal
                        fontFamily: 'Arial, sans-serif',
                        border: isPaused ? `2px solid ${ConfigurationDataColors.Instance.warningColor}` : 'none'
                    }}
                >
                    <div style={{ fontSize: '14px', fontWeight: 'bold', marginBottom: '8px' }}>
                        {`Tool Change Executing...${isPaused ? ' (PAUSED)' : ''}`}
                    </div>

                    <div style={{ fontSize: '12px', marginBottom: '4px' }}>
                        {`Changing to: T${action.targetToolNumber} - ${action.targetTool?.toolName || 'Unknown Tool'}`}
                    </div>

                    <div style={{ fontSize: '12px', marginBottom: '8px' }}>
                        {`${secondsRemaining} seconds remaining`}
                    </div>

                    <div style={{
                        width: '100%',
                        height: '4px',
                        backgroundColor: ConfigurationDataColors.Instance.lightOverlay,
                        borderRadius: '2px',
                        marginBottom: '8px',
                        overflow: 'hidden'
                    }}>
                        <div style={{
                            width: `${progressPercent}%`,
                            height: '100%',
                            backgroundColor: isPaused ? ConfigurationDataColors.Instance.warningColor : ConfigurationDataColors.Instance.successColor,
                            transition: isPaused ? 'none' : 'width 0.1s ease'
                        }} />
                    </div>

                    <div style={{ marginBottom: '8px' }}>
                        <label style={{ fontSize: '11px', display: 'block', marginBottom: '4px' }}>
                            {`Tool Change Delay: ${delaySeconds}s`}
                        </label>
                        <input
                            type="range"
                            min="0"
                            max="20"
                            value={delaySeconds.toString()}
                            onChange={handleDelayChange}
                            style={{
                                width: '100%',
                                height: '4px',
                                background: ConfigurationDataColors.Instance.lightOverlay,
                                outline: 'none',
                                borderRadius: '2px'
                            }}
                        />
                    </div>

                    <div style={{ display: 'flex', gap: '8px' }}>
                        <button
                            onClick={handleExecuteNow}
                            style={{
                                backgroundColor: ConfigurationDataColors.Instance.successColor,
                                color: ConfigurationDataColors.Instance.lightTextColor,
                                border: 'none',
                                padding: '4px 8px',
                                borderRadius: '4px',
                                fontSize: '12px',
                                cursor: 'pointer',
                                flex: 1
                            }}
                        >
                            Change Now
                        </button>

                        <button
                            onClick={() => action.cancel()}
                            style={{
                                backgroundColor: ConfigurationDataColors.Instance.errorColor,
                                color: ConfigurationDataColors.Instance.lightTextColor,
                                border: 'none',
                                padding: '4px 8px',
                                borderRadius: '4px',
                                fontSize: '12px',
                                cursor: 'pointer',
                                flex: 1
                            }}
                        >
                            Cancel
                        </button>
                    </div>
                </div>
            )}
        />
    );
}
