import { IStorable } from '../../../../common/IStorable';
import { StateManager } from '../../../../utils/statemanager/StateManager';
import { DataUtilities } from '../../../../utils/storage/DataUtilities';

/**
 * Represents an M94/M95 trigger for output control
 * M94/## - Turn on output(s) mapped to trigger number ##
 * M95/## - Turn off output(s) mapped to trigger number ##
 * Trigger numbers range from 1 to 128
 */
export class M94M95Trigger implements IStorable {
    private _name: string = '';
    private _description: string = '';
    private _number: number = 1;  // Trigger number (1-128)
    private _outputs: string[] = [];  // Array of output names that this trigger manages
    private _activeText: string = 'Is Active';
    private _inactiveText: string = 'Is Inactive';
    private _onCommand: string = '';  // M-code to turn on (empty = use M94)
    private _offCommand: string = '';  // M-code to turn off (empty = use M95)

    constructor(name?: string, number?: number) {
        this._name = name || '';
        this._number = number || 1;
    }

    /**
     * Get the name of this trigger
     */
    public get name(): string {
        return this._name;
    }

    public set name(value: string) {
        this._name = value;
        StateManager.propertyChanged(this, 'name');
    }

    /**
     * Get the description of this trigger
     */
    public get description(): string {
        return this._description;
    }

    public set description(value: string) {
        this._description = value;
        StateManager.propertyChanged(this, 'description');
    }

    /**
     * Get the text to display when trigger is active (M94 triggered)
     */
    public get activeText(): string {
        return this._activeText;
    }

    public set activeText(value: string) {
        this._activeText = value;
        StateManager.propertyChanged(this, 'activeText');
    }

    /**
     * Get the text to display when trigger is inactive (M95 triggered)
     */
    public get inactiveText(): string {
        return this._inactiveText;
    }

    public set inactiveText(value: string) {
        this._inactiveText = value;
        StateManager.propertyChanged(this, 'inactiveText');
    }

    /**
     * Get the M-code used to turn on this trigger's outputs
     */
    public get onCommand(): string {
        return this._onCommand;
    }

    public set onCommand(value: string) {
        this._onCommand = value;
        StateManager.propertyChanged(this, 'onCommand');
    }

    /**
     * Get the M-code used to turn off this trigger's outputs
     */
    public get offCommand(): string {
        return this._offCommand;
    }

    public set offCommand(value: string) {
        this._offCommand = value;
        StateManager.propertyChanged(this, 'offCommand');
    }

    /**
     * Get the trigger number (1-128)
     */
    public get number(): number {
        return this._number;
    }

    public set number(value: number) {
        // Validate range
        if (value < 1 || value > 128) {
            throw new Error('M94/M95 trigger number must be between 1 and 128');
        }
        this._number = value;
        StateManager.propertyChanged(this, 'number');
    }

    /**
     * Get the array of output names managed by this trigger
     */
    public get outputs(): string[] {
        return [...this._outputs];  // Return copy to prevent direct modification
    }

    public set outputs(value: string[]) {
        this._outputs = [...value];  // Store copy
        StateManager.propertyChanged(this, 'outputs');
    }

    /**
     * Add an output to this trigger
     * @param outputName The name of the output to add
     */
    public addOutput(outputName: string): void {
        if (!this._outputs.includes(outputName)) {
            this._outputs.push(outputName);
            StateManager.propertyChanged(this, 'outputs');
        }
    }

    /**
     * Remove an output from this trigger
     * @param outputName The name of the output to remove
     */
    public removeOutput(outputName: string): void {
        const index = this._outputs.indexOf(outputName);
        if (index > -1) {
            this._outputs.splice(index, 1);
            StateManager.propertyChanged(this, 'outputs');
        }
    }

    /**
     * Check if this trigger manages a specific output
     * @param outputName The name of the output to check
     * @returns True if the output is managed by this trigger
     */
    public hasOutput(outputName: string): boolean {
        return this._outputs.includes(outputName);
    }

    /**
     * Clear all outputs from this trigger
     */
    public clearOutputs(): void {
        this._outputs = [];
        StateManager.propertyChanged(this, 'outputs');
    }

    /**
     * Get the ON G-code command string
     * @returns The ON command (e.g., "M94/15" for default, or "M3" for custom)
     */
    public getM94Command(): string {
        const command = this._onCommand || 'M94';
        // Only append /number for default M94/M95 commands
        if (!this._onCommand || this._onCommand === 'M94') {
            return `${command}/${this._number}`;
        }
        return command;
    }

    /**
     * Get the OFF G-code command string
     * @returns The OFF command (e.g., "M95/15" for default, or "M5" for custom)
     */
    public getM95Command(): string {
        const command = this._offCommand || 'M95';
        // Only append /number for default M94/M95 commands
        if (!this._offCommand || this._offCommand === 'M95') {
            return `${command}/${this._number}`;
        }
        return command;
    }

    /**
     * Get a human-readable display string for this trigger
     * @returns Display string (e.g., "M94/M95 #15: Turn Coolant On/Off")
     */
    public getDisplayString(): string {
        const numberStr = this._number.toString();
        const nameStr = this._name || 'Unnamed Trigger';
        return `M94/M95 #${numberStr}: ${nameStr}`;
    }

    /**
     * Get the output count for this trigger
     * @returns Number of outputs managed by this trigger
     */
    public getOutputCount(): number {
        return this._outputs.length;
    }

    /**
     * Serialize to JSON
     */
    public toJSON(): object {
        return DataUtilities.getStorageData(this);
    }

    /**
     * Deserialize from JSON
     */
    public fromJSON(data: any): void {
        DataUtilities.loadStorageData(this, data);
    }

    /**
     * Clone this trigger
     */
    public clone(): M94M95Trigger {
        const cloned = new M94M95Trigger();
        cloned.fromJSON(this.toJSON());
        return cloned;
    }

    /**
     * Validate this trigger
     * @returns Error message if invalid, undefined if valid
     */
    public validate(): string | undefined {
        if (!this._name || this._name.trim().length === 0) {
            return 'Trigger name cannot be empty';
        }
        if (this._number < 1 || this._number > 128) {
            return 'Trigger number must be between 1 and 128';
        }
        if (this._outputs.length === 0) {
            return 'Trigger must have at least one output assigned';
        }
        return undefined;
    }
}
