import { Box, Typography } from '@mui/material';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';
import { JobStage } from '../../data/JobStage';

interface StageGCodeViewerProps {
    stage: JobStage;
    allGCodeLines: string[];
    contextLineCount?: number;
}

/**
 * Displays G-code for a specific stage with context lines before and after
 * - Context lines (before/after): dimmed
 * - Stage lines: highlighted
 */
export function StageGCodeViewer({
    stage,
    allGCodeLines,
    contextLineCount = 5
}: StageGCodeViewerProps) {
    const colors = ConfigurationDataColors.Instance;
    // Get the stage's preprocessed G-code lines instead of extracting from original
    const { beforeLines, stageLines, afterLines } = stage.getGCodeLinesWithContext(allGCodeLines, contextLineCount);

    // For stage 1 (first stage), don't show before lines
    const displayBeforeLines = stage.stageNumber === 1 ? [] : beforeLines;

    // For GCodeStage, beforeLines will be empty to avoid mixing preprocessed and unprocessed lines
    // Start line number should be 1-based
    const startLineNum = Math.max(1, stage.startLineIndex - displayBeforeLines.length + 1);

    return (
        <Box sx={{
            flex: 1,
            overflow: 'auto',
            backgroundColor: colors.darkBackgroundColor,
            borderRadius: 1,
            p: 2,
            fontFamily: 'monospace',
            fontSize: '0.875rem',
            lineHeight: 1.6
        }}>
            {/* Context lines BEFORE stage */}
            {displayBeforeLines.map((line, idx) => (
                <Box key={`before-${idx}`} sx={{
                    color: colors.secondaryBorderColor,
                    opacity: 0.9,
                    '&:hover': { backgroundColor: `${colors.errorColor}0D` }
                }}>
                    <Typography component="span" sx={{
                        display: 'inline-block',
                        width: '50px',
                        color: colors.mutedTextColor,
                        textAlign: 'right',
                        mr: 2,
                        userSelect: 'none'
                    }}>
                        {startLineNum + idx}:
                    </Typography>
                    {line}
                </Box>
            ))}

            {/* STAGE lines - highlighted */}
            {stageLines.map((line, idx) => (
                <Box key={`stage-${idx}`} sx={{
                    color: colors.infoColor,
                    fontWeight: 'bold',
                    backgroundColor: `${colors.infoColor}1A`,
                    '&:hover': { backgroundColor: `${colors.infoColor}33` }
                }}>
                    <Typography component="span" sx={{
                        display: 'inline-block',
                        width: '50px',
                        color: colors.infoColor,
                        textAlign: 'right',
                        mr: 2,
                        userSelect: 'none'
                    }}>
                        {startLineNum + displayBeforeLines.length + idx}:
                    </Typography>
                    {line}
                </Box>
            ))}

            {/* Context lines AFTER stage */}
            {afterLines.map((line, idx) => (
                <Box key={`after-${idx}`} sx={{
                    color: colors.secondaryBorderColor,
                    opacity: 0.9,
                    '&:hover': { backgroundColor: `${colors.lightTextColor}0D` }
                }}>
                    <Typography component="span" sx={{
                        display: 'inline-block',
                        width: '50px',
                        color: colors.mutedTextColor,
                        textAlign: 'right',
                        mr: 2,
                        userSelect: 'none'
                    }}>
                        {startLineNum + displayBeforeLines.length + stageLines.length + idx}:
                    </Typography>
                    {line}
                </Box>
            ))}
        </Box>
    );
}
