import { Box, FormControl, Grid, InputLabel, MenuItem, Paper, Select, Typography } from "@mui/material";
import React from "react";
import { ConfigurationDataColors } from "../../../../data/ConfigurationDataColors";
import { MachineData } from "../../../../data/Machine/MachineData";
import { ObserveState } from "../../../../utils/statemanager/ObserveState";

export function MPGSetupTab(): React.ReactElement {
    const machine = MachineData.Instance;
    const colors = ConfigurationDataColors.Instance;

    const handleWirelessMpgTypeChange = (event: any) => {
        machine.wirelessMpgType = event.target.value;
    };

    const handlePerformanceChange = (event: any) => {
        machine.mpgPerformance = event.target.value;
    };

    return (
        <Box sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
                MPG Setup
            </Typography>
            <Typography variant="body1" color="text.secondary" paragraph>
                Configure Manual Pulse Generator (MPG) settings and axis assignments.
            </Typography>

            <ObserveState
                key="mpg-setup-state"
                listenTo={machine}
                properties={['wirelessMpgType', 'mpgPerformance']}
                control={() => (
                    <Paper sx={{ p: 3, backgroundColor: colors.lightBackgroundColor }}>
                        <Grid container spacing={3}>
                            {/* Wireless MPG Type */}
                            <Grid item xs={12} md={6}>
                                <FormControl fullWidth>
                                    <InputLabel>Wireless MPG Type</InputLabel>
                                    <Select
                                        value={machine.wirelessMpgType}
                                        onChange={handleWirelessMpgTypeChange}
                                        label="Wireless MPG Type"
                                    >
                                        <MenuItem value={-1}>None (Disabled)</MenuItem>
                                        <MenuItem value={0}>CWP-4 (Centroid CWP-4 pendant)</MenuItem>
                                        <MenuItem value={1}>WMPG-4 (Centroid WMPG-4)</MenuItem>
                                        <MenuItem value={2}>WMPG-6 (Centroid WMPG-6)</MenuItem>
                                        <MenuItem value={3}>WMPG-4 Plasma</MenuItem>
                                    </Select>
                                </FormControl>
                            </Grid>

                            {/* MPG Performance Mode */}
                            <Grid item xs={12} md={6}>
                                <FormControl fullWidth>
                                    <InputLabel>Performance Mode</InputLabel>
                                    <Select
                                        value={machine.mpgPerformance}
                                        onChange={handlePerformanceChange}
                                        label="Performance Mode"
                                    >
                                        <MenuItem value={0}>Smooth Response</MenuItem>
                                        <MenuItem value={1}>Balanced Response</MenuItem>
                                        <MenuItem value={2}>Quick Response</MenuItem>
                                    </Select>
                                </FormControl>
                            </Grid>
                        </Grid>
                    </Paper>
                )}
            />
        </Box>
    );
}

