import { IStorable } from '../../common/IStorable';
import { StateManager } from '../../utils/statemanager/StateManager';
import { DataUtilities } from '../../utils/storage/DataUtilities';
import { ConfigurationDataColors } from '../ConfigurationDataColors';
import { GrainDirection, MaterialType } from './MaterialLibrary';

/**
 * Material class
 * Direct conversion from C# Material class
 */

export class Material implements IStorable {
  private _name: string;
  private _type: MaterialType;
  private _xLength: number;
  private _yLength: number;
  private _height: number;
  private _grainDirection: GrainDirection;
  private _materialColor: string = ConfigurationDataColors.Instance.defaultMaterialColor;

  constructor() {
    this._name = "New Material";
    this._type = MaterialType.Other;
    this._xLength = 0;
    this._yLength = 0;
    this._height = 0;
    this._grainDirection = GrainDirection.X;
  }

  public get name(): string {
    return this._name;
  }

  public set name(value: string) {
    this._name = value;
    StateManager.propertyChanged(this, 'name');
  }

  public get type(): MaterialType {
    return this._type;
  }

  public set type(value: MaterialType) {
    this._type = value;
    StateManager.propertyChanged(this, 'type');
  }

  public get xLength(): number {
    return this._xLength;
  }

  public set xLength(value: number) {
    this._xLength = value;
    StateManager.propertyChanged(this, 'xLength');
  }

  public get yLength(): number {
    return this._yLength;
  }

  public set yLength(value: number) {
    this._yLength = value;
    StateManager.propertyChanged(this, 'yLength');
  }

  public get height(): number {
    return this._height;
  }

  public set height(value: number) {
    this._height = value;
    StateManager.propertyChanged(this, 'height');
  }

  public get grainDirection(): GrainDirection {
    return this._grainDirection;
  }

  public set grainDirection(value: GrainDirection) {
    this._grainDirection = value;
    StateManager.propertyChanged(this, 'grainDirection');
  }

  public get materialColor(): string {
    return this._materialColor;
  }

  public set materialColor(value: string) {
    this._materialColor = value;
    StateManager.propertyChanged(this, 'materialColor');
  }

  /**
   * Creates a deep copy of this Material instance
   */
  public clone(): Material {
    const cloned = new Material();
    cloned.name = this.name;
    cloned.type = this.type;
    cloned.xLength = this.xLength;
    cloned.yLength = this.yLength;
    cloned.height = this.height;
    cloned.grainDirection = this.grainDirection;
    cloned.materialColor = this.materialColor;

    return cloned;
  }

  /**
   * Serialize to JSON using generic DataUtilities approach
   */
  public toJSON(): any {
    return DataUtilities.getStorageData(this);
  }

  /**
   * Load from JSON using generic DataUtilities approach
   */
  public fromJSON(data: any): void {
    DataUtilities.loadStorageData(this, data);
  }
}
