import { Box } from '@mui/material';
import { FloatingWindow } from './FloatingWindow';
import { JogControls } from './JogControls';

export interface JogControlsWindowProps {
    onClose: () => void;
}

/**
 * Floating window containing jog controls
 * Can be dragged around and closed
 */
export function JogControlsWindow({ onClose }: JogControlsWindowProps) {
    return (
        <FloatingWindow
            title="Jog Controls"
            onClose={onClose}
            defaultPosition={{ x: 100, y: 100 }}
            width={700}
            minWidth={700}
            maxWidth={1000}
            defaultHeight={575}
        >
            <Box sx={{ height: '100%', overflow: 'auto' }}>
                <JogControls />
            </Box>
        </FloatingWindow>
    );
}
