import { IMachineCallback } from "../../../machine/IMachineCallback";
import { Wizard } from "../../Wizard/Wizard";
import { WizardManager } from "../../Wizard/WizardManager";
import { SelectToolsStep } from "./steps/SelectToolsStep";

export interface MeasureAllToolsWizardState {
    selectedTools: number[];
    currentToolNumber: number | null;
    isRunning: boolean;
    currentToolIndex: number;
    completedTools: number[];
    failedTools: number[];
}

export class MeasureAllToolsWizard extends Wizard<MeasureAllToolsWizardState> {
    constructor(callback?: IMachineCallback) {
        const initialState: MeasureAllToolsWizardState = {
            selectedTools: [],
            currentToolNumber: null,
            isRunning: false,
            currentToolIndex: 0,
            completedTools: [],
            failedTools: []
        };

        super(
            null as any, // Temporary - will be set below
            initialState,
            true, // canClose
            false, // clickAwayClose
            '80%', // width
            '85%'  // height
        );

        // Set callback on wizard instance
        this.callback = callback;

        // Create the first step with proper wizard reference
        const firstStep = new SelectToolsStep(this, null);
        this.firstStep = firstStep;
        this.currentStep = firstStep;
    }

    static show(callback?: IMachineCallback): void {
        const wizard = new MeasureAllToolsWizard(callback);
        WizardManager.Instance.start(wizard);
    }
}
