import { Add as AddIcon, Close as CloseIcon } from '@mui/icons-material';
import {
    Box,
    Button,
    Checkbox,
    Chip,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    FormControlLabel,
    IconButton,
    Link,
    List,
    ListItem,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    Switch,
    TextField,
    Typography
} from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { DefaultPLCInputs } from '../data/io/DefaultPLCInputs';
import { DefaultPLCOutputs } from '../data/io/DefaultPLCOutputs';
import { PLCBlock } from '../data/PLCBlock';

interface BlockDialogProps {
    open: boolean;
    block: PLCBlock;
    onClose: () => void;
    onSave: (name: string, description: string, enabled: boolean, requiredInputs: string[], requiredOutputs: string[], requiredBoardTypes: string[]) => void;
}

/**
 * Dialog for editing a PLC block's properties
 */
export function BlockDialog({ open, block, onClose, onSave }: BlockDialogProps) {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [enabled, setEnabled] = useState(true);
    const [requiredInputs, setRequiredInputs] = useState<string[]>([]);
    const [requiredOutputs, setRequiredOutputs] = useState<string[]>([]);
    const [requiredBoardTypes, setRequiredBoardTypes] = useState<string[]>([]);
    const [showInputSelector, setShowInputSelector] = useState(false);
    const [showOutputSelector, setShowOutputSelector] = useState(false);
    const [showBoardTypeSelector, setShowBoardTypeSelector] = useState(false);
    const colors = ConfigurationDataColors.Instance;

    // Available board types
    const availableBoardTypes = [
        { label: 'Acorn', value: 'Acorn' },
        { label: 'Acorn6', value: 'Acorn6' },
        { label: 'Oak', value: 'Oak' },
        { label: 'Hickory', value: 'Hickory' },
        { label: 'Allin1DC', value: 'Allin1DC' }
    ];

    // Get available inputs and outputs from defaults
    const availableInputs = DefaultPLCInputs.getDefaults().map(input => ({
        label: `${input.name} (${input.centroidName})`,
        value: input.centroidName
    }));
    const availableOutputs = DefaultPLCOutputs.getDefaults().map(output => ({
        label: `${output.name} (${output.centroidName})`,
        value: output.centroidName
    }));

    const handleRemoveInput = (centroidName: string) => {
        setRequiredInputs(prev => prev.filter(i => i !== centroidName));
    };

    const handleRemoveOutput = (centroidName: string) => {
        setRequiredOutputs(prev => prev.filter(o => o !== centroidName));
    };

    const handleToggleInput = (centroidName: string) => {
        setRequiredInputs(prev =>
            prev.includes(centroidName)
                ? prev.filter(i => i !== centroidName)
                : [...prev, centroidName]
        );
    };

    const handleToggleOutput = (centroidName: string) => {
        setRequiredOutputs(prev =>
            prev.includes(centroidName)
                ? prev.filter(o => o !== centroidName)
                : [...prev, centroidName]
        );
    };

    const handleToggleBoardType = (boardType: string) => {
        setRequiredBoardTypes(prev =>
            prev.includes(boardType)
                ? prev.filter(b => b !== boardType)
                : [...prev, boardType]
        );
    };

    const handleRemoveBoardType = (boardType: string) => {
        setRequiredBoardTypes(prev => prev.filter(b => b !== boardType));
    };

    // Initialize form when dialog opens or block changes
    useEffect(() => {
        if (open && block) {
            setName(block.name || '');
            setDescription(block.comment || '');
            setEnabled(block.enabled);
            setRequiredInputs(block.requiredInputs || []);
            setRequiredOutputs(block.requiredOutputs || []);
            setRequiredBoardTypes(block.requiredBoardTypes || []);
        }
    }, [open, block]);

    const handleSave = () => {
        onSave(name.trim(), description.trim(), enabled, requiredInputs, requiredOutputs, requiredBoardTypes);
        onClose();
    };

    const handleCancel = () => {
        onClose();
    };

    const isValid = name.trim();

    return (
        <>
            <Dialog open={open} onClose={handleCancel} maxWidth="sm" fullWidth>
                <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor,
                    py: 2,
                    px: 3
                }}>
                    Edit Block
                    <IconButton
                        onClick={handleCancel}
                        sx={{
                            color: colors.lightTextColor,
                            '&:hover': {
                                backgroundColor: `${colors.lightTextColor}1A`
                            }
                        }}
                    >
                        <CloseIcon />
                    </IconButton>
                </DialogTitle>
                <DialogContent>
                    <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 3 }}>
                        {/* Block Name */}
                        <TextField
                            label="Block Name"
                            value={name}
                            onChange={(e) => setName(e.target.value)}
                            fullWidth
                            autoFocus
                            required
                        />

                        {/* Description */}
                        <TextField
                            label="Description"
                            value={description}
                            onChange={(e) => setDescription(e.target.value)}
                            placeholder="Optional description or comment"
                            multiline
                            rows={3}
                            fullWidth
                        />

                        {/* Enabled Toggle */}
                        <Box>
                            <FormControlLabel
                                control={
                                    <Switch
                                        checked={enabled}
                                        onChange={(e) => setEnabled(e.target.checked)}
                                        sx={{
                                            '& .MuiSwitch-switchBase.Mui-checked': {
                                                color: colors.primaryColor,
                                            },
                                            '& .MuiSwitch-switchBase.Mui-checked + .MuiSwitch-track': {
                                                backgroundColor: colors.primaryColor,
                                            },
                                        }}
                                    />
                                }
                                label="Block Enabled"
                            />
                        </Box>

                        {/* Required Inputs */}
                        <Box>
                            <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                                Required Inputs
                            </Typography>
                            <Typography variant="caption" sx={{ display: 'block', mb: 1, color: 'text.secondary' }}>
                                Block will auto-disable if these inputs are not present in System PLC
                            </Typography>
                            <Box sx={{
                                display: 'flex',
                                flexWrap: 'wrap',
                                gap: 1,
                                minHeight: 32,
                                mb: 1
                            }}>
                                {requiredInputs.map(centroidName => {
                                    const input = availableInputs.find(i => i.value === centroidName);
                                    return (
                                        <Chip
                                            key={centroidName}
                                            label={input?.label || centroidName}
                                            onDelete={() => handleRemoveInput(centroidName)}
                                            size="small"
                                            sx={{ backgroundColor: colors.borderColor }}
                                        />
                                    );
                                })}
                            </Box>
                            <Link
                                component="button"
                                type="button"
                                onClick={() => setShowInputSelector(true)}
                                sx={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: 0.5,
                                    color: colors.primaryColor,
                                    textDecoration: 'none',
                                    '&:hover': { textDecoration: 'underline' }
                                }}
                            >
                                <AddIcon fontSize="small" />
                                Add Input
                            </Link>
                        </Box>

                        {/* Required Outputs */}
                        <Box>
                            <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                                Required Outputs
                            </Typography>
                            <Typography variant="caption" sx={{ display: 'block', mb: 1, color: 'text.secondary' }}>
                                Block will auto-disable if these outputs are not present in System PLC
                            </Typography>
                            <Box sx={{
                                display: 'flex',
                                flexWrap: 'wrap',
                                gap: 1,
                                minHeight: 32,
                                mb: 1
                            }}>
                                {requiredOutputs.map(centroidName => {
                                    const output = availableOutputs.find(o => o.value === centroidName);
                                    return (
                                        <Chip
                                            key={centroidName}
                                            label={output?.label || centroidName}
                                            onDelete={() => handleRemoveOutput(centroidName)}
                                            size="small"
                                            sx={{ backgroundColor: colors.borderColor }}
                                        />
                                    );
                                })}
                            </Box>
                            <Link
                                component="button"
                                type="button"
                                onClick={() => setShowOutputSelector(true)}
                                sx={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: 0.5,
                                    color: colors.primaryColor,
                                    textDecoration: 'none',
                                    '&:hover': { textDecoration: 'underline' }
                                }}
                            >
                                <AddIcon fontSize="small" />
                                Add Output
                            </Link>
                        </Box>

                        {/* Required Board Types */}
                        <Box>
                            <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                                Required Board Types
                            </Typography>
                            <Typography variant="caption" sx={{ display: 'block', mb: 1, color: 'text.secondary' }}>
                                Block will only render for these board types. Leave empty to render for all boards.
                            </Typography>
                            <Box sx={{
                                display: 'flex',
                                flexWrap: 'wrap',
                                gap: 1,
                                minHeight: 32,
                                mb: 1
                            }}>
                                {requiredBoardTypes.length === 0 ? (
                                    <Typography variant="caption" sx={{ fontStyle: 'italic', color: 'text.secondary' }}>
                                        All boards
                                    </Typography>
                                ) : (
                                    requiredBoardTypes.map(boardType => {
                                        const board = availableBoardTypes.find(b => b.value === boardType);
                                        return (
                                            <Chip
                                                key={boardType}
                                                label={board?.label || boardType}
                                                onDelete={() => handleRemoveBoardType(boardType)}
                                                size="small"
                                                sx={{ backgroundColor: colors.borderColor }}
                                            />
                                        );
                                    })
                                )}
                            </Box>
                            <Link
                                component="button"
                                type="button"
                                onClick={() => setShowBoardTypeSelector(true)}
                                sx={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: 0.5,
                                    color: colors.primaryColor,
                                    textDecoration: 'none',
                                    '&:hover': { textDecoration: 'underline' }
                                }}
                            >
                                <AddIcon fontSize="small" />
                                Add Board Type
                            </Link>
                        </Box>
                    </Box>
                </DialogContent>

                <DialogActions sx={{ p: 2, gap: 1, justifyContent: 'flex-end', borderTop: `1px solid ${colors.borderColor}` }}>
                    <Button onClick={handleCancel}>Cancel</Button>
                    <Button
                        onClick={handleSave}
                        variant="contained"
                        disabled={!isValid}
                        sx={{
                            backgroundColor: colors.primaryColor,
                            '&:hover': {
                                backgroundColor: colors.primaryColor,
                                opacity: 0.9
                            }
                        }}
                    >
                        Save Changes
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Input Selector Dialog */}
            <Dialog
                open={showInputSelector}
                onClose={() => setShowInputSelector(false)}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle sx={{
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor
                }}>
                    Select Required Inputs
                </DialogTitle>
                <DialogContent sx={{ pt: 2 }}>
                    <List sx={{ pt: 0 }}>
                        {availableInputs.map(input => (
                            <ListItem key={input.value} disablePadding>
                                <ListItemButton onClick={() => handleToggleInput(input.value)} dense>
                                    <ListItemIcon>
                                        <Checkbox
                                            edge="start"
                                            checked={requiredInputs.includes(input.value)}
                                            tabIndex={-1}
                                            disableRipple
                                            sx={{
                                                '&.Mui-checked': {
                                                    color: colors.primaryColor
                                                }
                                            }}
                                        />
                                    </ListItemIcon>
                                    <ListItemText primary={input.label} />
                                </ListItemButton>
                            </ListItem>
                        ))}
                    </List>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setShowInputSelector(false)}>Done</Button>
                </DialogActions>
            </Dialog>

            {/* Output Selector Dialog */}
            <Dialog
                open={showOutputSelector}
                onClose={() => setShowOutputSelector(false)}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle sx={{
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor
                }}>
                    Select Required Outputs
                </DialogTitle>
                <DialogContent sx={{ pt: 2 }}>
                    <List sx={{ pt: 0 }}>
                        {availableOutputs.map(output => (
                            <ListItem key={output.value} disablePadding>
                                <ListItemButton onClick={() => handleToggleOutput(output.value)} dense>
                                    <ListItemIcon>
                                        <Checkbox
                                            edge="start"
                                            checked={requiredOutputs.includes(output.value)}
                                            tabIndex={-1}
                                            disableRipple
                                            sx={{
                                                '&.Mui-checked': {
                                                    color: colors.primaryColor
                                                }
                                            }}
                                        />
                                    </ListItemIcon>
                                    <ListItemText primary={output.label} />
                                </ListItemButton>
                            </ListItem>
                        ))}
                    </List>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setShowOutputSelector(false)}>Done</Button>
                </DialogActions>
            </Dialog>

            {/* Board Type Selector Dialog */}
            <Dialog
                open={showBoardTypeSelector}
                onClose={() => setShowBoardTypeSelector(false)}
                maxWidth="sm"
                fullWidth
            >
                <DialogTitle sx={{
                    backgroundColor: colors.primaryColor,
                    color: colors.lightTextColor
                }}>
                    Select Required Board Types
                </DialogTitle>
                <DialogContent sx={{ pt: 2 }}>
                    <List sx={{ pt: 0 }}>
                        {availableBoardTypes.map(board => (
                            <ListItem key={board.value} disablePadding>
                                <ListItemButton onClick={() => handleToggleBoardType(board.value)} dense>
                                    <ListItemIcon>
                                        <Checkbox
                                            edge="start"
                                            checked={requiredBoardTypes.includes(board.value)}
                                            tabIndex={-1}
                                            disableRipple
                                            sx={{
                                                '&.Mui-checked': {
                                                    color: colors.primaryColor
                                                }
                                            }}
                                        />
                                    </ListItemIcon>
                                    <ListItemText primary={board.label} />
                                </ListItemButton>
                            </ListItem>
                        ))}
                    </List>
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setShowBoardTypeSelector(false)}>Done</Button>
                </DialogActions>
            </Dialog>
        </>
    );
}
