import { Popover } from '@mui/material';
import { ObserveState } from '../../utils/statemanager/ObserveState';
import { TooltipManager } from '../../utils/TooltipManager';

/**
 * Global tooltip display component
 * Renders tooltips managed by TooltipManager singleton
 * Should be placed once at the root level of the application
 */
export function TooltipDisplay() {
    return (
        <ObserveState
            key="global-tooltip-display"
            listenTo={TooltipManager.Instance}
            properties={['isOpen', 'tooltipContent', 'anchorPosition']}
            control={() => {
                const manager = TooltipManager.Instance;

                if (!manager.isOpen || !manager.anchorPosition) {
                    return null;
                }

                return (
                    <Popover
                        open={manager.isOpen}
                        anchorReference="anchorPosition"
                        anchorPosition={manager.anchorPosition}
                        onClose={() => manager.hideTooltip()}
                        disableRestoreFocus
                        disableAutoFocus
                        disableEnforceFocus
                        sx={{
                            pointerEvents: 'none',
                            '& .MuiPopover-paper': {
                                pointerEvents: 'auto',
                                maxWidth: '400px',
                                boxShadow: 3
                            }
                        }}
                        slotProps={{
                            paper: {
                                onMouseEnter: () => manager.keepTooltipOpen(),
                                onMouseLeave: () => manager.hideTooltip()
                            }
                        }}
                        transformOrigin={{
                            vertical: 'top',
                            horizontal: 'left'
                        }}
                    >
                        {manager.tooltipContent}
                    </Popover>
                );
            }}
        />
    );
}
