import { DataReloadEvent, DataReloadNotifier } from '../utils/DataReloadNotifier';
import { LogCategory, Logger } from '../utils/Logger';
import { StateManager } from '../utils/statemanager/StateManager';
import { IUserAction, UserActionRegistry } from '../utils/userActions';

/**
 * Singleton class to manage loaded actions for UI components
 * Uses StateManager for reactive updates when actions change
 */
export class ActionData {
    private static _instance: ActionData;

    private _allActions: IUserAction[] = [];
    private _actionsByCategory: Map<string, IUserAction[]> = new Map();
    private _isInitialized: boolean = false;

    private constructor() {
        // Start loading actions immediately
        this.loadActions();

        // Listen for data reload events to refresh actions
        DataReloadNotifier.Instance.addListener(DataReloadEvent.AllDataReloaded, async () => {
            Logger.Instance.log(LogCategory.DataManager, 'ActionData: Reloading actions after data reload');
            await this.refresh();
        });

        // Listen for user actions updates (e.g., when MDI/Flow is saved)
        DataReloadNotifier.Instance.addListener(DataReloadEvent.UserActionsUpdated, async () => {
            Logger.Instance.log(LogCategory.DataManager, 'ActionData: Reloading actions after user actions update');
            await this.refresh();
        });
    }

    public static get Instance(): ActionData {
        if (!ActionData._instance) {
            ActionData._instance = new ActionData();
        }
        return ActionData._instance;
    }

    /**
     * Whether actions have been loaded and initialized
     */
    public get isInitialized(): boolean {
        return this._isInitialized;
    }

    /**
     * Get all loaded actions
     */
    public get allActions(): IUserAction[] {
        return [...this._allActions];
    }

    /**
     * Get actions grouped by category
     */
    public get actionsByCategory(): Map<string, IUserAction[]> {
        return new Map(this._actionsByCategory);
    }

    /**
     * Get actions for a specific category
     */
    public getActionsForCategory(category: string): IUserAction[] {
        return this._actionsByCategory.get(category) || [];
    }

    /**
     * Get an action by ID
     */
    public getAction(actionId: string): IUserAction | undefined {
        return this._allActions.find(action => action.id === actionId);
    }

    /**
     * Load all actions from registry (async)
     * Called automatically on initialization and when actions change
     */
    public async loadActions(): Promise<void> {
        try {
            const registry = UserActionRegistry.Instance;

            // Load all actions
            const actions = await registry.getAllActions();
            this._allActions = actions;

            // Group by category
            const grouped = new Map<string, IUserAction[]>();
            for (const action of actions) {
                const existing = grouped.get(action.category) || [];
                existing.push(action);
                grouped.set(action.category, existing);
            }
            this._actionsByCategory = grouped;

            // Mark as initialized
            const wasInitialized = this._isInitialized;
            if (!this._isInitialized) {
                this._isInitialized = true;
            }

            // Always notify observers to ensure components that subscribe late get updates
            StateManager.propertyChanged(this, 'isInitialized');
            StateManager.propertyChanged(this, 'allActions');
            StateManager.propertyChanged(this, 'actionsByCategory');

            // Log only on first initialization
            if (!wasInitialized) {
                Logger.Instance.log(LogCategory.DataManager, `ActionData: Initialized with ${actions.length} actions`);
            }
        } catch (error) {
            Logger.Instance.logError(LogCategory.DataManager, 'ActionData: Failed to load actions:', error);
        }
    }

    /**
     * Reload actions from registry
     * Call this when MDI/Flows are saved or deleted
     */
    public async refresh(): Promise<void> {

        // Invalidate the registry cache
        UserActionRegistry.Instance.invalidateProgramStorageCache();

        // Reload
        await this.loadActions();
    }
}
