import { Component, ErrorInfo, ReactNode } from 'react';
import { ConfigurationData } from './data/ConfigurationData';
import { ConfigurationDataColors } from './data/ConfigurationDataColors';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error?: Error;
}

class ErrorBoundary extends Component<Props, State> {
  public state: State = {
    hasError: false,
  };

  public static getDerivedStateFromError(error: Error): State {
    return { hasError: true, error };
  }

  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('ErrorBoundary caught an error:', error, errorInfo);
  }

  public render() {
    const config = ConfigurationData.Instance;
    const colors = ConfigurationDataColors.Instance;
    if (this.state.hasError) {
      return (
        <div style={{ padding: '20px', color: colors.errorColor, fontSize: '18px' }}>
          <h1>Something went wrong</h1>
          <p>{this.state.error?.message || 'An unexpected error occurred'}</p>
          <pre style={{ backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor, padding: '10px', fontSize: '14px' }}>
            {this.state.error?.stack}
          </pre>
          <button onClick={() => window.location.reload()}>
            Reload Page
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
