import {
  Box,
  Paper,
  Popover,
  TextField,
  Tooltip,
  Typography
} from '@mui/material';
import React, { useState } from 'react';
import { ConfigurationDataColors } from '../../data/ConfigurationDataColors';

interface ColorPickerProps {
  label?: string;
  value: string;
  onChange: (color: string) => void;
  disabled?: boolean;
  size?: 'small' | 'medium' | 'large';
  showHexInput?: boolean;
}

export const ColorPicker: React.FC<ColorPickerProps> = ({
  label,
  value,
  onChange,
  disabled = false,
  size = 'medium',
  showHexInput = true
}) => {
  const [anchorEl, setAnchorEl] = useState<HTMLElement | null>(null);
  const [tempHex, setTempHex] = useState(value);

  const getSizeValues = () => {
    switch (size) {
      case 'small':
        return { width: 48, height: 24, fontSize: '0.75rem' }; // 2x width for small
      case 'large':
        return { width: 96, height: 48, fontSize: '1rem' }; // 2x width for large
      default:
        return { width: 64, height: 32, fontSize: '0.875rem' }; // 2x width for medium
    }
  };

  const { width, height, fontSize } = getSizeValues();

  const handleColorSquareClick = (event: React.MouseEvent<HTMLElement>) => {
    if (!disabled) {
      setAnchorEl(event.currentTarget);
      setTempHex(value);
    }
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleColorChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newColor = event.target.value;
    setTempHex(newColor);
    onChange(newColor);
  };

  const handleHexChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newHex = event.target.value;
    setTempHex(newHex);

    // Validate hex color format
    if (/^#[0-9A-F]{6}$/i.test(newHex) || /^#[0-9A-F]{3}$/i.test(newHex)) {
      onChange(newHex);
    }
  };

  const handleHexBlur = () => {
    // If invalid hex, revert to current value
    if (!/^#[0-9A-F]{6}$/i.test(tempHex) && !/^#[0-9A-F]{3}$/i.test(tempHex)) {
      setTempHex(value);
    }
  };

  const handlePresetClick = (presetColor: string) => {
    setTempHex(presetColor);
    onChange(presetColor);
  };

  const open = Boolean(anchorEl);
  const simulatorColors = ConfigurationDataColors.Instance.getAllSimulatorColors();
  const portalColors = ConfigurationDataColors.Instance.getAllPortalColors();

  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
      <Tooltip title={`Click to change color (${value})`} arrow>
        <Box
          onClick={handleColorSquareClick}
          sx={{
            width,
            height,
            backgroundColor: value,
            border: `2px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
            borderRadius: 1,
            cursor: disabled ? 'not-allowed' : 'pointer',
            transition: 'all 0.2s ease',
            opacity: disabled ? 0.5 : 1,
            '&:hover': disabled ? {} : {
              transform: 'scale(1.05)',
              boxShadow: ConfigurationDataColors.Instance.shadowColor
            }
          }}
        />
      </Tooltip>

      {label && (
        <Typography variant="body2" sx={{ fontSize }}>
          {label}
        </Typography>
      )}

      <Popover
        open={open}
        anchorEl={anchorEl}
        onClose={handleClose}
        anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'left',
        }}
        transformOrigin={{
          vertical: 'top',
          horizontal: 'left',
        }}
      >
        <Paper sx={{ p: 2, minWidth: 280, maxWidth: 400 }}>
          <Typography variant="subtitle2" gutterBottom>
            Choose Color
          </Typography>

          {/* Simulator Color Presets */}
          <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary" sx={{ mb: 1, display: 'block' }}>
              Simulator Colors
            </Typography>
            <Box sx={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: 0.5,
              maxHeight: 120,
              overflowY: 'auto',
              p: 0.5,
              border: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
              borderRadius: 1,
              backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor
            }}>
              {simulatorColors.map((color) => (
                <Tooltip key={color} title={color} arrow>
                  <Box
                    onClick={() => handlePresetClick(color)}
                    sx={{
                      width: 32,
                      height: 32,
                      backgroundColor: color,
                      border: value === color
                        ? `3px solid ${ConfigurationDataColors.Instance.primaryColor}`
                        : `1px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
                      borderRadius: 1,
                      cursor: 'pointer',
                      transition: 'all 0.2s ease',
                      '&:hover': {
                        transform: 'scale(1.15)',
                        boxShadow: 2,
                        zIndex: 1
                      }
                    }}
                  />
                </Tooltip>
              ))}
            </Box>
          </Box>

          {/* Portal/UI Color Presets */}
          <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary" sx={{ mb: 1, display: 'block' }}>
              Portal Colors
            </Typography>
            <Box sx={{
              display: 'flex',
              flexWrap: 'wrap',
              gap: 0.5,
              maxHeight: 120,
              overflowY: 'auto',
              p: 0.5,
              border: `1px solid ${ConfigurationDataColors.Instance.borderColor}`,
              borderRadius: 1,
              backgroundColor: ConfigurationDataColors.Instance.lightBackgroundColor
            }}>
              {portalColors.map((color) => (
                <Tooltip key={color} title={color} arrow>
                  <Box
                    onClick={() => handlePresetClick(color)}
                    sx={{
                      width: 32,
                      height: 32,
                      backgroundColor: color,
                      border: value === color
                        ? `3px solid ${ConfigurationDataColors.Instance.primaryColor}`
                        : `1px solid ${ConfigurationDataColors.Instance.secondaryBorderColor}`,
                      borderRadius: 1,
                      cursor: 'pointer',
                      transition: 'all 0.2s ease',
                      '&:hover': {
                        transform: 'scale(1.15)',
                        boxShadow: 2,
                        zIndex: 1
                      }
                    }}
                  />
                </Tooltip>
              ))}
            </Box>
          </Box>

          {/* Native color picker */}
          <Box sx={{ mb: 2 }}>
            <Typography variant="caption" color="text.secondary" sx={{ mb: 1, display: 'block' }}>
              Custom Color
            </Typography>
            <input
              type="color"
              value={value}
              onChange={handleColorChange}
              style={{
                width: '100%',
                height: 40,
                border: 'none',
                borderRadius: 4,
                cursor: 'pointer'
              }}
            />
          </Box>

          {/* Hex input */}
          {showHexInput && (
            <TextField
              fullWidth
              label="Hex Color"
              value={tempHex}
              onChange={handleHexChange}
              onBlur={handleHexBlur}
              size="small"
              placeholder="RRGGBB"
              inputProps={{
                style: { fontFamily: 'monospace' }
              }}
              helperText="Format: RRGGBB or RGB"
            />
          )}
        </Paper>
      </Popover>
    </Box>
  );
};
