import { Delete as DeleteIcon, Computer as MachineIcon, Warning as WarningIcon } from '@mui/icons-material';
import {
    Alert,
    Box,
    Button,
    Chip,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Divider,
    FormControl,
    IconButton,
    InputLabel,
    List,
    ListItem,
    ListItemIcon,
    ListItemText,
    MenuItem,
    Paper,
    Select,
    Typography
} from '@mui/material';
import { useEffect, useState } from 'react';
import { ConfigurationDataColors } from '../../../data/ConfigurationDataColors';
import { ConfigurationState } from '../../../data/ConfigurationState';
import { DataManager } from '../../../data/DataManager';
import { UserMessageQueue } from '../../../data/UserMessageQueue';
import { Machine } from '../../../machine/Machine';
import { LogCategory, Logger } from '../../../utils/Logger';

export function MachineManagerTab() {
    const colors = ConfigurationDataColors.Instance;

    const [machines, setMachines] = useState<string[]>([]);
    const [currentMachine, setCurrentMachine] = useState<string>('');
    const [loadingList, setLoadingList] = useState(false);

    // Delete dialog state
    const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
    const [machineToDelete, setMachineToDelete] = useState<string>('');
    const [switchToMachine, setSwitchToMachine] = useState<string>('');
    const [deleting, setDeleting] = useState(false);

    useEffect(() => {
        loadMachines();
    }, []);

    const loadMachines = async () => {
        try {
            setLoadingList(true);
            const names = await Machine.getInstance().setup.GetMachineNames();
            const current = await Machine.getInstance().setup.GetCurrentMachineName();
            setMachines(names);
            setCurrentMachine(current || '');
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to load machine names:', error);
            UserMessageQueue.Instance.addMessage('❌ Failed to load machine list');
        } finally {
            setLoadingList(false);
        }
    };

    const handleDeleteClick = (machineName: string) => {
        setMachineToDelete(machineName);
        // Pre-select a different machine to switch to if deleting the active one
        const others = machines.filter(m => m !== machineName);
        setSwitchToMachine(others[0] || '');
        setDeleteDialogOpen(true);
    };

    const isDeletingCurrentMachine = machineToDelete === currentMachine;
    const otherMachines = machines.filter(m => m !== machineToDelete);
    const canConfirm = !isDeletingCurrentMachine || (isDeletingCurrentMachine && switchToMachine !== '');

    const handleConfirmDelete = async () => {
        setDeleteDialogOpen(false);
        setDeleting(true);

        const operation = ConfigurationState.Instance.startLongRunningOperation(
            'Deleting Machine',
            `Deleting machine "${machineToDelete}"...`
        );

        try {
            await Machine.getInstance().setup.DeleteMachine(
                machineToDelete,
                isDeletingCurrentMachine ? switchToMachine : undefined
            );

            if (isDeletingCurrentMachine) {
                ConfigurationState.Instance.updateLongRunningOperationMessage('Reloading data for new machine...');
                await DataManager.Instance.reloadAllData();
            }

            // Refresh machine list
            const updatedNames = await Machine.getInstance().setup.GetMachineNames();
            const updatedCurrent = await Machine.getInstance().setup.GetCurrentMachineName();
            setMachines(updatedNames);
            setCurrentMachine(updatedCurrent || '');

            UserMessageQueue.Instance.addMessage(`✓ Machine "${machineToDelete}" deleted`);
        } catch (error) {
            Logger.Instance.logError(LogCategory.System, 'Failed to delete machine:', error);
            UserMessageQueue.Instance.addMessage(`❌ Failed to delete machine "${machineToDelete}"`);
            // Reload list to ensure consistent state
            await loadMachines();
        } finally {
            ConfigurationState.Instance.completeLongRunningOperation();
            setDeleting(false);
            setMachineToDelete('');
        }
    };

    const handleCancelDelete = () => {
        setDeleteDialogOpen(false);
        setMachineToDelete('');
        setSwitchToMachine('');
    };

    return (
        <Box>
            <Typography variant="h4" gutterBottom>Machine Manager</Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                Manage machine configurations stored on the backend. Deleting a machine removes all its
                data from the cloud (configs, jobs, G-code files) but does not affect local files.
            </Typography>

            <Paper sx={{ p: 3 }}>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
                    <Typography variant="h6">Available Machines</Typography>
                    <Button
                        variant="outlined"
                        size="small"
                        onClick={loadMachines}
                        disabled={loadingList || deleting}
                    >
                        Refresh
                    </Button>
                </Box>

                {machines.length === 0 && !loadingList && (
                    <Typography color="text.secondary" sx={{ py: 3, textAlign: 'center' }}>
                        No machines found
                    </Typography>
                )}

                <List disablePadding>
                    {machines.map((machineName, index) => {
                        const isActive = machineName === currentMachine;
                        return (
                            <Box key={machineName}>
                                {index > 0 && <Divider />}
                                <ListItem
                                    sx={{
                                        py: 1.5,
                                        backgroundColor: isActive ? `${colors.primaryColor}10` : undefined,
                                        borderLeft: isActive ? `4px solid ${colors.primaryColor}` : '4px solid transparent',
                                    }}
                                    secondaryAction={
                                        <IconButton
                                            edge="end"
                                            color="error"
                                            onClick={() => handleDeleteClick(machineName)}
                                            disabled={deleting || machines.length <= 1}
                                            title={machines.length <= 1 ? 'Cannot delete the only machine' : `Delete "${machineName}"`}
                                        >
                                            <DeleteIcon />
                                        </IconButton>
                                    }
                                >
                                    <ListItemIcon sx={{ minWidth: 40 }}>
                                        <MachineIcon sx={{ color: isActive ? colors.primaryColor : 'text.secondary' }} />
                                    </ListItemIcon>
                                    <ListItemText
                                        primary={
                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                <Typography variant="body1" fontWeight={isActive ? 600 : 400}>
                                                    {machineName}
                                                </Typography>
                                                {isActive && (
                                                    <Chip
                                                        label="Active"
                                                        size="small"
                                                        sx={{
                                                            backgroundColor: colors.primaryColor,
                                                            color: colors.lightTextColor,
                                                            height: 20,
                                                            fontSize: '0.7rem'
                                                        }}
                                                    />
                                                )}
                                            </Box>
                                        }
                                    />
                                </ListItem>
                            </Box>
                        );
                    })}
                </List>

                {machines.length <= 1 && machines.length > 0 && (
                    <Alert severity="info" sx={{ mt: 2 }}>
                        You must have at least one machine. Create another machine before deleting this one.
                    </Alert>
                )}
            </Paper>

            {/* Delete Confirmation Dialog */}
            <Dialog open={deleteDialogOpen} onClose={handleCancelDelete} maxWidth="sm" fullWidth>
                <DialogTitle sx={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 1,
                    backgroundColor: '#d32f2f',
                    color: 'white',
                    py: 2,
                    px: 3
                }}>
                    <WarningIcon />
                    Delete Machine
                </DialogTitle>

                <DialogContent>
                    <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', gap: 2 }}>
                        <Typography variant="body1">
                            Are you sure you want to delete <strong>"{machineToDelete}"</strong>?
                        </Typography>

                        <Alert severity="warning">
                            This will permanently delete all backend data for this machine — configurations,
                            jobs, and G-code files stored in the cloud. Local files are not affected.
                            This cannot be undone.
                        </Alert>

                        {isDeletingCurrentMachine && (
                            <>
                                <Alert severity="error">
                                    This is the currently active machine. You must select another machine to
                                    switch to before deleting it.
                                </Alert>

                                <FormControl fullWidth required error={switchToMachine === ''}>
                                    <InputLabel>Switch to Machine</InputLabel>
                                    <Select
                                        value={switchToMachine}
                                        onChange={(e) => setSwitchToMachine(e.target.value)}
                                        label="Switch to Machine"
                                    >
                                        {otherMachines.map(name => (
                                            <MenuItem key={name} value={name}>{name}</MenuItem>
                                        ))}
                                    </Select>
                                </FormControl>
                            </>
                        )}
                    </Box>
                </DialogContent>

                <DialogActions sx={{
                    p: 2,
                    gap: 1,
                    justifyContent: 'flex-end',
                    borderTop: `1px solid ${colors.borderColor}`
                }}>
                    <Button onClick={handleCancelDelete} variant="outlined">
                        Cancel
                    </Button>
                    <Button
                        onClick={handleConfirmDelete}
                        variant="contained"
                        color="error"
                        disabled={!canConfirm}
                        startIcon={<DeleteIcon />}
                    >
                        Delete Machine
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
}
